import React, { useState, useEffect, useRef } from 'react';
import { 
  collection, 
  query, 
  where, 
  getDocs, 
  addDoc, 
  deleteDoc,
  serverTimestamp, 
  orderBy,
  doc,
  updateDoc
} from 'firebase/firestore';
import { db } from '../firebase';
import { Course, Module, Lesson, User, ProfessorSubView } from '../types';
import { 
  Search, 
  Filter, 
  BookOpen, 
  Plus, 
  Info, 
  X, 
  ChevronRight, 
  Play, 
  Pause,
  Volume2,
  VolumeX,
  Maximize,
  FileText, 
  MoreVertical, 
  ArrowLeft, 
  Layout, 
  Trash2, 
  AlertTriangle, 
  Layers, 
  Eye, 
  Clock, 
  Download, 
  CheckCircle, 
  FileDown 
} from 'lucide-react';

interface ProfessorViewProps {
  user: User;
  activeSub: ProfessorSubView;
  setActiveSub: (view: ProfessorSubView) => void;
}

const ProfessorView: React.FC<ProfessorViewProps> = ({ user, activeSub, setActiveSub }) => {
  const [myCourses, setMyCourses] = useState<Course[]>([]);
  const [loading, setLoading] = useState(true);
  const [selectedCourse, setSelectedCourse] = useState<Course | null>(null);
  const [modules, setModules] = useState<Module[]>([]);
  const [lessonsByModule, setLessonsByModule] = useState<Record<string, Lesson[]>>({});
  const [openMenuId, setOpenMenuId] = useState<string | null>(null);

  // Modal States
  const [showCourseModal, setShowCourseModal] = useState(false);
  const [showModuleModal, setShowModuleModal] = useState(false);
  const [showLessonModal, setShowLessonModal] = useState(false);
  const [activeModuleId, setActiveModuleId] = useState<string | null>(null);

  // Preview States
  const [previewLesson, setPreviewLesson] = useState<Lesson | null>(null);
  const [countdown, setCountdown] = useState(15);
  const [isTimerFinished, setIsTimerFinished] = useState(false);
  const [isConcluded, setIsConcluded] = useState(false);

  // Custom Player States
  const [playerIsPlaying, setPlayerIsPlaying] = useState(false);
  const [playerVolume, setPlayerVolume] = useState(80);
  const [isMuted, setIsMuted] = useState(false);
  const iframeRef = useRef<HTMLIFrameElement>(null);
  const playerContainerRef = useRef<HTMLDivElement>(null);

  // Form States
  const [courseForm, setCourseForm] = useState({
    nome: '',
    descricao: '',
    capaUrl: '',
    cargaHoraria: '',
    publicoAlvo: 'Geral' as const
  });
  const [moduleForm, setModuleForm] = useState({ nome: '' });
  const [lessonForm, setLessonForm] = useState({
    titulo: '',
    videoUrl: '',
    materialUrl: ''
  });

  const fetchMyCourses = async () => {
    setLoading(true);
    try {
      const q = query(collection(db, 'cursos'), where('professorId', '==', user.uid), orderBy('createdAt', 'desc'));
      const querySnapshot = await getDocs(q);
      const fetched: Course[] = [];
      querySnapshot.forEach((doc) => {
        fetched.push({ id: doc.id, ...doc.data() } as Course);
      });
      setMyCourses(fetched);
    } catch (error) {
      console.error("Erro ao carregar seus cursos:", error);
    } finally {
      setLoading(false);
    }
  };

  const fetchModules = async (courseId: string) => {
    try {
      const q = query(collection(db, 'cursos', courseId, 'modulos'), orderBy('ordem', 'asc'));
      const querySnapshot = await getDocs(q);
      const fetched: Module[] = [];
      querySnapshot.forEach((doc) => {
        fetched.push({ id: doc.id, ...doc.data() } as Module);
      });
      setModules(fetched);

      for (const mod of fetched) {
        fetchLessons(courseId, mod.id);
      }
    } catch (error) {
      console.error("Erro ao carregar módulos:", error);
    }
  };

  const fetchLessons = async (courseId: string, moduleId: string) => {
    try {
      const q = query(collection(db, 'cursos', courseId, 'modulos', moduleId, 'aulas'), orderBy('ordem', 'asc'));
      const querySnapshot = await getDocs(q);
      const fetched: Lesson[] = [];
      querySnapshot.forEach((doc) => {
        fetched.push({ id: doc.id, ...doc.data() } as Lesson);
      });
      setLessonsByModule(prev => ({ ...prev, [moduleId]: fetched }));
    } catch (error) {
      console.error("Erro ao carregar aulas:", error);
    }
  };

  useEffect(() => {
    fetchMyCourses();
  }, [user.uid]);

  // SINCRONIZAÇÃO DA TRAVA (NÃO ALTERAR)
  useEffect(() => {
    let timer: number | undefined;

    if (previewLesson && countdown > 0 && !isConcluded) {
      timer = window.setInterval(() => {
        setCountdown((prev) => {
          if (prev <= 1) {
            setIsTimerFinished(true);
            if (timer) clearInterval(timer);
            return 0;
          }
          return prev - 1;
        });
      }, 1000);
    }

    return () => {
      if (timer) clearInterval(timer);
    };
  }, [previewLesson, countdown, isConcluded]);

  // PLAYER COMMANDS (NÃO ALTERAR)
  const sendPlayerCommand = (func: string, args: any[] = []) => {
    if (iframeRef.current && iframeRef.current.contentWindow) {
      iframeRef.current.contentWindow.postMessage(
        JSON.stringify({ event: 'command', func, args }), 
        '*'
      );
    }
  };

  const togglePlay = () => {
    if (playerIsPlaying) {
      sendPlayerCommand('pauseVideo');
    } else {
      sendPlayerCommand('playVideo');
    }
    setPlayerIsPlaying(!playerIsPlaying);
  };

  const toggleMute = () => {
    if (isMuted) {
      sendPlayerCommand('unMute');
      sendPlayerCommand('setVolume', [playerVolume]);
    } else {
      sendPlayerCommand('mute');
    }
    setIsMuted(!isMuted);
  };

  const handleVolumeChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const vol = parseInt(e.target.value);
    setPlayerVolume(vol);
    if (!isMuted) {
      sendPlayerCommand('setVolume', [vol]);
    }
  };

  const toggleFullscreen = () => {
    if (playerContainerRef.current) {
      if (!document.fullscreenElement) {
        playerContainerRef.current.requestFullscreen().catch(err => {
          console.error(`Erro ao ativar tela cheia: ${err.message}`);
        });
      } else {
        document.exitFullscreen();
      }
    }
  };

  const handleCreateCourse = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      await addDoc(collection(db, 'cursos'), {
        ...courseForm,
        professorId: user.uid,
        inscritos: 0,
        status: 'rascunho',
        createdAt: serverTimestamp()
      });
      setShowCourseModal(false);
      setCourseForm({ nome: '', descricao: '', capaUrl: '', cargaHoraria: '', publicoAlvo: 'Geral' });
      fetchMyCourses();
    } catch (error) {
      console.error("Erro ao criar curso:", error);
    }
  };

  const handleCreateModule = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedCourse) return;
    try {
      await addDoc(collection(db, 'cursos', selectedCourse.id, 'modulos'), {
        nome: moduleForm.nome,
        ordem: modules.length + 1,
        createdAt: serverTimestamp()
      });
      setShowModuleModal(false);
      setModuleForm({ nome: '' });
      fetchModules(selectedCourse.id);
    } catch (error) {
      console.error("Erro ao criar módulo:", error);
    }
  };

  const handleDeleteModule = async (moduleId: string) => {
    if (!selectedCourse) return;
    if (!confirm("Tem certeza que deseja excluir este módulo? Todas as aulas vinculadas serão perdidas no sistema.")) return;

    try {
      await deleteDoc(doc(db, 'cursos', selectedCourse.id, 'modulos', moduleId));
      fetchModules(selectedCourse.id);
    } catch (error) {
      console.error("Erro ao excluir módulo:", error);
    }
  };

  const handleCreateLesson = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedCourse || !activeModuleId) return;
    try {
      const currentLessonsCount = lessonsByModule[activeModuleId]?.length || 0;
      await addDoc(collection(db, 'cursos', selectedCourse.id, 'modulos', activeModuleId, 'aulas'), {
        ...lessonForm,
        ordem: currentLessonsCount + 1,
        createdAt: serverTimestamp()
      });
      setShowLessonModal(false);
      setLessonForm({ titulo: '', videoUrl: '', materialUrl: '' });
      fetchLessons(selectedCourse.id, activeModuleId);
    } catch (error) {
      console.error("Erro ao criar aula:", error);
    }
  };

  const handleDeleteLesson = async (moduleId: string, lessonId: string) => {
    if (!selectedCourse) return;
    if (!confirm("Excluir esta aula permanentemente?")) return;

    try {
      await deleteDoc(doc(db, 'cursos', selectedCourse.id, 'modulos', moduleId, 'aulas', lessonId));
      fetchLessons(selectedCourse.id, moduleId);
    } catch (error) {
      console.error("Erro ao excluir aula:", error);
    }
  };

  const openCourseDetail = (course: Course) => {
    setSelectedCourse(course);
    setActiveSub('modulos'); // SINCRONIZAÇÃO: Muda a aba ativa para 'módulos'
    fetchModules(course.id);
  };

  const openPreview = (lesson: Lesson) => {
    setCountdown(15);
    setIsTimerFinished(false);
    setIsConcluded(false);
    setPlayerIsPlaying(false);
    setPreviewLesson(lesson);
  };

  const closePreview = () => {
    setPreviewLesson(null);
    setIsTimerFinished(false);
    setIsConcluded(false);
    setCountdown(15);
    setPlayerIsPlaying(false);
  };

  const handleConcludeLesson = () => {
    if (!isTimerFinished) return;
    setIsConcluded(true);
  };

  const getEmbedUrl = (url: string) => {
    if (!url) return "";
    const ytRegex = /(?:https?:\/\/)?(?:www\.)?(?:youtube\.com\/(?:[^\/\n\s]+\/\S+\/|(?:v|e(?:mbed)?)\/|\S*?[?&]v=)|youtu\.be\/)([a-zA-Z0-9_-]{11})/;
    const ytMatch = url.match(ytRegex);
    if (ytMatch && ytMatch[1]) {
      return `https://www.youtube.com/embed/${ytMatch[1]}?modestbranding=1&rel=0&iv_load_policy=3&disablekb=1&controls=0&showinfo=0&enablejsapi=1&origin=${window.location.origin}`;
    }
    return url;
  };

  // RENDER DETALHES DO CURSO (MÓDULOS)
  if (activeSub === 'modulos' && selectedCourse) {
    return (
      <div className="space-y-6 animate-in fade-in duration-500">
        <header className="flex items-center justify-between gap-4">
          <div className="flex items-center gap-4">
            <button 
              onClick={() => { setSelectedCourse(null); setActiveSub('cursos'); }}
              className="flex items-center justify-center h-10 w-10 bg-white border border-slate-200 hover:bg-slate-50 rounded-xl text-slate-600 transition-all shadow-sm group"
              title="Voltar para Cursos"
            >
              <ArrowLeft size={20} className="group-hover:-translate-x-1 transition-transform" />
            </button>
            <div>
              <h1 className="text-2xl font-bold text-slate-900 leading-tight">{selectedCourse.nome}</h1>
              <div className="flex items-center gap-2 mt-0.5">
                <span className="text-slate-400 text-xs font-medium uppercase tracking-wider">Construtor de Conteúdo</span>
                <span className="h-1 w-1 rounded-full bg-slate-300"></span>
                <span className="text-indigo-600 text-xs font-bold uppercase tracking-wider">{selectedCourse.publicoAlvo}</span>
              </div>
            </div>
          </div>
          <button 
            onClick={() => setShowModuleModal(true)}
            className="hidden sm:flex items-center gap-2 bg-indigo-600 text-white px-5 py-2.5 rounded-xl text-sm font-bold hover:bg-indigo-700 transition-all shadow-lg shadow-indigo-600/20"
          >
            <Plus size={18} />
            Novo Módulo
          </button>
        </header>

        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
          <div className="lg:col-span-2 space-y-4">
            <div className="bg-white rounded-2xl border border-slate-200 shadow-sm overflow-hidden">
              <div className="px-6 py-4 border-b border-slate-100 flex items-center justify-between bg-slate-50/50">
                <div className="flex items-center gap-2">
                  <Layout size={16} className="text-slate-400" />
                  <h2 className="text-xs font-bold text-slate-800 uppercase tracking-widest">Matriz Curricular</h2>
                </div>
                <span className="text-[10px] font-bold text-slate-400">{modules.length} Módulos Total</span>
              </div>

              <div className="p-4 space-y-4">
                {modules.length === 0 ? (
                  <div className="p-16 text-center">
                    <div className="bg-slate-50 w-16 h-16 rounded-full flex items-center justify-center mx-auto mb-4 border border-slate-100">
                      <Layers size={24} className="text-slate-300" />
                    </div>
                    <p className="text-slate-500 font-medium text-sm">Este curso ainda não possui módulos.</p>
                  </div>
                ) : (
                  modules.map((mod) => (
                    <div key={mod.id} className="border border-slate-100 rounded-xl overflow-hidden bg-slate-50/30 group">
                      <div className="px-4 py-3 border-b border-slate-100 flex items-center justify-between bg-white group-hover:bg-slate-50/50 transition-colors">
                        <div className="flex items-center gap-3">
                          <span className="bg-slate-900 text-white w-6 h-6 rounded-lg flex items-center justify-center text-[10px] font-black">
                            {mod.ordem < 10 ? `0${mod.ordem}` : mod.ordem}
                          </span>
                          <h3 className="font-bold text-slate-800 text-sm tracking-tight">{mod.nome}</h3>
                        </div>
                        <div className="flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                          <button 
                            onClick={() => { setActiveModuleId(mod.id); setShowLessonModal(true); }}
                            className="p-1.5 text-indigo-600 hover:bg-indigo-50 rounded-lg transition-colors"
                            title="Adicionar Aula"
                          >
                            <Plus size={18} />
                          </button>
                          <button 
                            onClick={() => handleDeleteModule(mod.id)}
                            className="p-1.5 text-slate-400 hover:text-red-500 hover:bg-red-50 rounded-lg transition-colors"
                            title="Excluir Módulo"
                          >
                            <Trash2 size={18} />
                          </button>
                        </div>
                      </div>

                      <div className="p-2 space-y-1">
                        {lessonsByModule[mod.id]?.map((lesson) => (
                          <div key={lesson.id} className="flex items-center justify-between p-3 rounded-xl hover:bg-white hover:shadow-sm transition-all group/lesson bg-transparent">
                            <div className="flex items-center gap-4">
                              <div className="p-2 bg-white border border-slate-100 text-indigo-600 rounded-lg shadow-sm">
                                <Play size={12} fill="currentColor" />
                              </div>
                              <div>
                                <p className="text-sm font-semibold text-slate-700 leading-none">{lesson.titulo}</p>
                                <div className="flex items-center gap-3 mt-1.5">
                                  {lesson.videoUrl && (
                                    <span className="text-[10px] text-slate-400 flex items-center gap-1 bg-slate-100 px-1.5 py-0.5 rounded">
                                      <Play size={8} /> Vídeo
                                    </span>
                                  )}
                                  {lesson.materialUrl && (
                                    <span className="text-[10px] text-slate-400 flex items-center gap-1 bg-slate-100 px-1.5 py-0.5 rounded">
                                      <FileText size={8} /> Apoio
                                    </span>
                                  )}
                                </div>
                              </div>
                            </div>
                            <div className="flex items-center gap-1 opacity-0 group-hover/lesson:opacity-100 transition-all">
                              <button 
                                onClick={() => openPreview(lesson)}
                                className="p-1.5 text-indigo-600 hover:bg-indigo-50 rounded-lg transition-colors"
                                title="Pré-visualizar Aula"
                              >
                                <Eye size={16} />
                              </button>
                              <button 
                                onClick={() => handleDeleteLesson(mod.id, lesson.id)}
                                className="p-1.5 text-slate-300 hover:text-red-500 transition-all"
                                title="Excluir Aula"
                              >
                                <Trash2 size={14} />
                              </button>
                            </div>
                          </div>
                        ))}
                      </div>
                    </div>
                  ))
                )}
              </div>
            </div>
          </div>

          <div className="space-y-4">
            <div className="bg-white p-5 rounded-2xl border border-slate-200 shadow-sm sticky top-24">
              <div className="relative rounded-xl overflow-hidden mb-5 border border-slate-100 shadow-inner">
                <img 
                  src={selectedCourse.capaUrl || 'https://images.unsplash.com/photo-1504052434139-443c40c98408?w=800&auto=format&fit=crop&q=60'} 
                  alt="Capa"
                  className="w-full h-32 object-cover"
                />
              </div>
              <div className="space-y-4">
                <div className="flex items-center justify-between text-xs pb-3 border-b border-slate-50">
                  <span className="text-slate-500 font-bold uppercase tracking-tighter">Status</span>
                  <span className={`px-2 py-0.5 rounded text-[10px] font-black uppercase ${selectedCourse.status === 'ativo' ? 'bg-emerald-100 text-emerald-700' : 'bg-slate-100 text-slate-600'}`}>
                    {selectedCourse.status}
                  </span>
                </div>
                <div className="flex items-center justify-between text-xs">
                  <span className="text-slate-500 font-bold uppercase tracking-tighter">Carga Horária</span>
                  <span className="text-slate-900 font-black">{selectedCourse.cargaHoraria}</span>
                </div>
              </div>
            </div>
          </div>
        </div>

        {/* Modal Módulo */}
        {showModuleModal && (
          <div className="fixed inset-0 z-[110] flex items-center justify-center p-4 bg-slate-900/40 backdrop-blur-sm">
            <div className="bg-white w-full max-w-md rounded-2xl shadow-2xl overflow-hidden">
              <div className="p-4 border-b border-slate-100 flex items-center justify-between">
                <h3 className="font-bold text-slate-900">Novo Módulo Acadêmico</h3>
                <button onClick={() => setShowModuleModal(false)} className="text-slate-400 hover:text-slate-600"><X size={20} /></button>
              </div>
              <form onSubmit={handleCreateModule} className="p-6 space-y-4">
                <div className="space-y-1.5">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Título</label>
                  <input required autoFocus value={moduleForm.nome} onChange={e => setModuleForm({nome: e.target.value})} className="w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm outline-none" />
                </div>
                <button type="submit" className="w-full bg-indigo-600 text-white py-2.5 rounded-xl font-bold text-sm">Criar Módulo</button>
              </form>
            </div>
          </div>
        )}

        {showLessonModal && (
          <div className="fixed inset-0 z-[110] flex items-center justify-center p-4 bg-slate-900/40 backdrop-blur-sm">
            <div className="bg-white w-full max-w-lg rounded-2xl shadow-2xl overflow-hidden">
              <div className="p-4 border-b border-slate-100 flex items-center justify-between">
                <h3 className="font-bold text-slate-900">Adicionar Aula</h3>
                <button onClick={() => setShowLessonModal(false)} className="text-slate-400 hover:text-slate-600"><X size={20} /></button>
              </div>
              <form onSubmit={handleCreateLesson} className="p-6 space-y-4">
                <div className="space-y-1.5">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Título da Aula</label>
                  <input required autoFocus value={lessonForm.titulo} onChange={e => setLessonForm({...lessonForm, titulo: e.target.value})} className="w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm" />
                </div>
                <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                  <div className="space-y-1.5">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Link Vídeo</label>
                    <input value={lessonForm.videoUrl} onChange={e => setLessonForm({...lessonForm, videoUrl: e.target.value})} className="w-full px-4 py-2 bg-slate-50 border border-slate-200 rounded-xl text-sm" />
                  </div>
                  <div className="space-y-1.5">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Link Material</label>
                    <input value={lessonForm.materialUrl} onChange={e => setLessonForm({...lessonForm, materialUrl: e.target.value})} className="w-full px-4 py-2 bg-slate-50 border border-slate-200 rounded-xl text-sm" />
                  </div>
                </div>
                <button type="submit" className="w-full bg-indigo-600 text-white py-3 rounded-xl font-bold text-sm">Publicar Aula</button>
              </form>
            </div>
          </div>
        )}

        {/* Modal Preview - PLAYER REPROJETADO E BLINDADO (NÃO ALTERAR) */}
        {previewLesson && (
          <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 bg-slate-900/80 backdrop-blur-md animate-in fade-in duration-300">
            <div className="bg-white w-full max-w-6xl h-[90vh] rounded-3xl shadow-2xl overflow-hidden flex flex-col animate-in zoom-in-95 duration-200">
              <div className="p-5 border-b border-slate-100 flex items-center justify-between bg-white">
                <div className="flex items-center gap-3">
                  <div className="bg-indigo-600 p-2 rounded-xl text-white shadow-lg shadow-indigo-200">
                    <Eye size={18} />
                  </div>
                  <div>
                    <h3 className="font-bold text-slate-900 text-base leading-tight">Painel de Estudo Profissional: {previewLesson.titulo}</h3>
                    <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest">Experiência Blindada Customizada</p>
                  </div>
                </div>
                <button 
                  onClick={closePreview}
                  className="flex items-center gap-2 px-4 py-2 bg-slate-100 hover:bg-slate-200 rounded-xl text-slate-600 text-xs font-bold transition-colors"
                >
                  <X size={16} /> Fechar Aula
                </button>
              </div>

              <div className="flex-1 overflow-y-auto bg-slate-50/50 p-6 flex flex-col lg:flex-row gap-6">
                <div className="flex-[2] space-y-6 flex flex-col justify-center">
                  {previewLesson.videoUrl ? (
                    <div 
                      ref={playerContainerRef}
                      className="aspect-video bg-slate-900 rounded-2xl overflow-hidden shadow-2xl border-4 border-white relative group"
                    >
                      <iframe 
                        ref={iframeRef}
                        width="100%" 
                        height="100%" 
                        src={getEmbedUrl(previewLesson.videoUrl)} 
                        title="Video Player"
                        frameBorder="0" 
                        allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture" 
                        allowFullScreen
                        className="pointer-events-none"
                      ></iframe>

                      <div className="absolute top-0 left-0 w-full h-24 bg-transparent z-10 pointer-events-auto cursor-default"></div>
                      <div className="absolute bottom-0 left-0 w-full h-20 bg-transparent z-10 pointer-events-auto cursor-default"></div>

                      <div className="absolute inset-0 z-20 pointer-events-none flex flex-col justify-end">
                        {!playerIsPlaying && (
                          <div 
                            className="absolute inset-0 flex items-center justify-center bg-black/20 backdrop-blur-[2px] pointer-events-auto cursor-pointer group/center"
                            onClick={togglePlay}
                          >
                            <div className="w-20 h-20 bg-white/10 backdrop-blur-xl border border-white/20 rounded-full flex items-center justify-center text-white scale-100 group-hover/center:scale-110 transition-all shadow-2xl">
                              <Play size={40} fill="currentColor" />
                            </div>
                          </div>
                        )}

                        <div className="p-4 bg-gradient-to-t from-black/80 via-black/40 to-transparent opacity-0 group-hover:opacity-100 transition-opacity duration-300 pointer-events-auto">
                          <div className="flex items-center justify-between gap-6 px-4">
                            <div className="flex items-center gap-4">
                              <button 
                                onClick={togglePlay}
                                className="text-white hover:text-indigo-400 transition-colors"
                              >
                                {playerIsPlaying ? <Pause size={24} fill="currentColor" /> : <Play size={24} fill="currentColor" />}
                              </button>

                              <div className="flex items-center gap-3 group/vol">
                                <button onClick={toggleMute} className="text-white hover:text-indigo-400 transition-colors">
                                  {(isMuted || playerVolume === 0) ? <VolumeX size={20} /> : <Volume2 size={20} />}
                                </button>
                                <input 
                                  type="range" 
                                  min="0" 
                                  max="100" 
                                  value={isMuted ? 0 : playerVolume}
                                  onChange={handleVolumeChange}
                                  className="w-20 h-1.5 bg-white/20 rounded-full appearance-none cursor-pointer accent-indigo-500 hover:accent-indigo-400 transition-all"
                                />
                              </div>
                            </div>

                            <div className="flex items-center gap-4">
                              <span className="text-[10px] font-black text-white/40 uppercase tracking-widest hidden sm:block">🔒 Modo Escola Blindado</span>
                              <button 
                                onClick={toggleFullscreen}
                                className="text-white hover:text-indigo-400 transition-colors"
                              >
                                <Maximize size={20} />
                              </button>
                            </div>
                          </div>
                        </div>
                      </div>

                      <div className="absolute top-4 left-4 bg-slate-900/60 backdrop-blur-md px-3 py-1.5 rounded-xl text-[9px] text-white/80 font-black uppercase tracking-widest z-30 pointer-events-none border border-white/10 shadow-2xl flex items-center gap-2">
                        <div className="w-1.5 h-1.5 rounded-full bg-indigo-500 animate-pulse"></div>
                        Sistema Customizado Ativo
                      </div>
                    </div>
                  ) : (
                    <div className="aspect-video flex items-center justify-center p-20 border-2 border-dashed border-slate-200 rounded-3xl text-slate-400 italic bg-white">
                      <div className="text-center">
                        <Play size={48} className="mx-auto mb-4 opacity-20" />
                        <p>Conteúdo de vídeo indisponível.</p>
                      </div>
                    </div>
                  )}

                  <div className="p-6 bg-white rounded-2xl border border-slate-200 shadow-sm">
                    <h4 className="font-bold text-slate-900 mb-2 flex items-center gap-2">
                       <ShieldCheck size={18} className="text-indigo-600" />
                       Tecnologia de Foco Pedagógico
                    </h4>
                    <p className="text-sm text-slate-500 leading-relaxed">
                      Este player foi configurado para garantir que você absorva 100% do conteúdo sem interrupções ou distrações externas. O avanço manual do vídeo está desabilitado para preservar o fluxo de ensino estabelecido pelo professor.
                    </p>
                  </div>
                </div>

                <div className="flex-1 space-y-4">
                  <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm sticky top-0">
                    <h4 className="text-xs font-black text-slate-400 uppercase tracking-[0.2em] mb-4">Métrica de Retenção</h4>

                    <div className="space-y-6">
                      <div className={`p-4 rounded-xl border transition-all ${isConcluded ? 'bg-emerald-50 border-emerald-100' : 'bg-amber-50 border-amber-100'}`}>
                        <div className="flex items-center gap-3 mb-2">
                          {isConcluded ? (
                            <div className="bg-emerald-500 text-white p-1 rounded-full"><CheckCircle size={14} /></div>
                          ) : (
                            <Clock size={18} className="text-amber-600 animate-pulse" />
                          )}
                          <span className={`text-xs font-bold ${isConcluded ? 'text-emerald-700' : 'text-amber-700'}`}>
                            {isConcluded ? 'Acesso Validado' : 'Validação Ativa'}
                          </span>
                        </div>
                        <p className="text-[10px] text-slate-500 leading-relaxed font-medium">
                          {isConcluded 
                            ? 'O tempo mínimo de aula foi atingido. Você pode baixar seu material.' 
                            : 'Assista ao vídeo por completo. O sistema de monitoramento está validando sua permanência.'}
                        </p>
                      </div>

                      <div className="bg-slate-50 p-6 rounded-xl text-center border border-slate-100">
                        {(!isTimerFinished && !isConcluded) ? (
                          <div className="space-y-2">
                            <span className="text-4xl font-black text-slate-900 tabular-nums tracking-tighter">{countdown}s</span>
                            <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Cronômetro de Segurança</p>
                          </div>
                        ) : (
                          <div className="py-2">
                            <div className="flex items-center justify-center gap-2 text-emerald-600 mb-1">
                                <CheckCircle size={20} />
                                <span className="font-black text-sm uppercase tracking-wider">LMS Concluído</span>
                            </div>
                            <p className="text-[10px] text-slate-400 font-medium">Requisitos técnicos satisfeitos.</p>
                          </div>
                        )}
                      </div>

                      <div className="space-y-3">
                        <button 
                          disabled={!isTimerFinished || isConcluded}
                          onClick={handleConcludeLesson}
                          className={`w-full py-4 rounded-xl font-bold text-sm transition-all shadow-lg flex items-center justify-center gap-2 ${
                            isTimerFinished && !isConcluded
                              ? 'bg-slate-900 text-white shadow-slate-200 hover:bg-slate-800 active:scale-95' 
                              : isConcluded 
                                ? 'bg-emerald-100 text-emerald-700 shadow-none cursor-default border border-emerald-200'
                                : 'bg-slate-100 text-slate-400 cursor-not-allowed border border-slate-200 shadow-none'
                          }`}
                        >
                          {isConcluded ? (
                            <>
                                <CheckCircle size={16} />
                                Aula Concluída
                            </>
                          ) : countdown > 0 ? (
                            <span className="text-[11px] px-2 text-center leading-tight">
                              Liberação em {countdown}s
                            </span>
                          ) : (
                            'Confirmar Conclusão'
                          )}
                        </button>

                        {isConcluded && previewLesson.materialUrl && (
                          <a 
                            href={previewLesson.materialUrl}
                            target="_blank"
                            rel="noopener noreferrer"
                            className="w-full py-4 bg-indigo-600 text-white rounded-xl font-bold text-sm transition-all shadow-lg shadow-indigo-100 flex items-center justify-center gap-2 hover:bg-indigo-700 active:scale-95 animate-in slide-in-from-bottom duration-500"
                          >
                            <Download size={18} />
                            📥 Baixar Apoio (PDF)
                          </a>
                        )}
                      </div>
                    </div>

                    <div className="mt-8 pt-6 border-t border-slate-50 text-center">
                      <p className="text-[9px] text-slate-400 uppercase font-black tracking-widest italic">Escola Bíblica EAD 1.0</p>
                    </div>
                  </div>
                </div>
              </div>
            </div>
          </div>
        )}
      </div>
    );
  }

  // RENDER LISTA DE CURSOS
  return (
    <div className="space-y-6 animate-in fade-in duration-500">
      <header className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold text-slate-900 tracking-tight">Cursos & Matrículas</h1>
          <p className="text-slate-500 text-sm font-medium">Gestão direta de conteúdos pedagógicos.</p>
        </div>
        <button 
          onClick={() => setShowCourseModal(true)}
          className="flex items-center justify-center gap-2 bg-indigo-600 text-white px-5 py-2.5 rounded-xl text-sm font-bold hover:bg-indigo-700 transition-all shadow-lg"
        >
          <Plus size={18} />
          Cadastrar Novo Curso
        </button>
      </header>

      <div className="bg-white rounded-2xl border border-slate-200 shadow-sm min-h-[400px] flex flex-col overflow-hidden">
        <div className="p-4 border-b border-slate-100 flex flex-col sm:flex-row items-center justify-between gap-4 bg-slate-50/30">
          <div className="relative w-full max-w-xs">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={16} />
            <input 
              type="text" 
              placeholder="Localizar curso..." 
              className="w-full pl-10 pr-4 py-2 bg-white border border-slate-200 rounded-lg text-xs outline-none shadow-sm font-medium"
            />
          </div>
        </div>

        {loading ? (
          <div className="flex-1 flex items-center justify-center p-12">
            <div className="h-6 w-6 animate-spin rounded-full border-2 border-indigo-600 border-t-transparent"></div>
          </div>
        ) : myCourses.length > 0 ? (
          <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6 p-6">
            {myCourses.map(course => (
              <div 
                key={course.id} 
                onClick={() => openCourseDetail(course)}
                className="border border-slate-200 p-4 rounded-2xl hover:shadow-xl hover:border-indigo-400 transition-all cursor-pointer group bg-white flex flex-col relative overflow-hidden"
              >
                <div className="relative h-32 rounded-xl overflow-hidden mb-4 bg-slate-100 border border-slate-100">
                  <img src={course.capaUrl || 'https://images.unsplash.com/photo-1504052434139-443c40c98408?w=800&auto=format&fit=crop&q=60'} alt={course.nome} className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-700" />
                  <div className="absolute top-2 right-2 flex gap-1">
                    <span className={`px-2 py-0.5 rounded-full text-[9px] font-black uppercase ${course.status === 'ativo' ? 'bg-emerald-500 text-white' : 'bg-slate-700 text-white'}`}>{course.status}</span>
                  </div>
                </div>
                <h3 className="font-bold text-slate-900 text-sm mb-1 line-clamp-2">{course.nome}</h3>
                <div className="flex items-center gap-2 mb-4">
                  <span className="text-[9px] font-black uppercase tracking-widest px-2 py-0.5 bg-indigo-50 text-indigo-700 rounded-md">{course.publicoAlvo}</span>
                </div>
                {/* BOTÃO GERENCIAR - Ação Dupla: Seleciona e Muda Aba */}
                <div 
                  onClick={(e) => { e.stopPropagation(); openCourseDetail(course); }}
                  className="mt-auto flex items-center justify-between text-[10px] text-slate-400 font-black uppercase tracking-widest pt-4 border-t border-slate-50 group-hover:text-indigo-600 transition-colors"
                >
                  <div className="flex items-center gap-2">
                    <Layout size={12} className="text-slate-300 group-hover:text-indigo-500 transition-colors" />
                    <span>Gerenciar</span>
                  </div>
                  <ChevronRight size={14} className="group-hover:translate-x-1 transition-transform text-indigo-500" />
                </div>
              </div>
            ))}
          </div>
        ) : (
          <div className="flex-1 flex flex-col items-center justify-center p-16 opacity-50">
            <BookOpen size={48} className="mb-4 text-slate-300" />
            <h3 className="text-slate-900 font-bold">Nenhum curso sob sua gestão</h3>
          </div>
        )}
      </div>

      {/* Modal Criar Curso */}
      {showCourseModal && (
        <div className="fixed inset-0 z-[110] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm animate-in fade-in duration-300">
          <div className="bg-white w-full max-w-xl rounded-2xl shadow-2xl overflow-hidden animate-in zoom-in-95 duration-200">
            <div className="p-5 border-b border-slate-100 flex items-center justify-between">
              <h3 className="font-bold text-slate-900 text-lg">Criar Novo Currículo</h3>
              <button onClick={() => setShowCourseModal(false)} className="text-slate-400 hover:text-slate-600 p-2"><X size={20} /></button>
            </div>
            <form onSubmit={handleCreateCourse} className="p-6 space-y-6">
              <div className="space-y-4">
                <div className="space-y-1.5">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Título</label>
                  <input required autoFocus value={courseForm.nome} onChange={e => setCourseForm({...courseForm, nome: e.target.value})} placeholder="Título da Disciplina" className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl text-sm" />
                </div>
                <div className="grid grid-cols-2 gap-4">
                  <div className="space-y-1.5">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Carga Horária</label>
                    <input required value={courseForm.cargaHoraria} onChange={e => setCourseForm({...courseForm, cargaHoraria: e.target.value})} placeholder="40h" className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl text-sm" />
                  </div>
                  <div className="space-y-1.5">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Público</label>
                    <select value={courseForm.publicoAlvo} onChange={e => setCourseForm({...courseForm, publicoAlvo: e.target.value as any})} className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl text-sm">
                      <option value="Geral">Geral</option>
                      <option value="Líderes">Líderes</option>
                      <option value="Obreiros">Obreiros</option>
                    </select>
                  </div>
                </div>
                <div className="space-y-1.5">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Capa URL</label>
                  <input value={courseForm.capaUrl} onChange={e => setCourseForm({...courseForm, capaUrl: e.target.value})} className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl text-sm" />
                </div>
              </div>
              <button type="submit" className="w-full bg-slate-900 text-white py-3.5 rounded-xl font-bold text-sm">Criar e Iniciar Construtor</button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

// Helper component for shield icon
const ShieldCheck = ({ size, className }: { size: number, className: string }) => (
  <svg 
    width={size} 
    height={size} 
    viewBox="0 0 24 24" 
    fill="none" 
    stroke="currentColor" 
    strokeWidth="2" 
    strokeLinecap="round" 
    strokeLinejoin="round" 
    className={className}
  >
    <path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z" />
    <path d="m9 12 2 2 4-4" />
  </svg>
);

export default ProfessorView;

import React from 'react';

export type UserRole = 'diretor' | 'professor' | 'aluno';

export interface User {
  uid: string;
  email: string | null;
  displayName: string | null;
  role: UserRole;
  photoURL?: string;
}

export interface Course {
  id: string;
  nome: string;
  tema?: string;
  descricao?: string;
  descricaoLonga?: string;
  professorResponsavel?: string;
  capaUrl?: string;
  cargaHoraria: string;
  publicoAlvo: 'Geral' | 'Líderes' | 'Obreiros';
  professorId: string;
  inscritos: number;
  status: 'ativo' | 'rascunho';
  createdAt: any;
}

export interface Module {
  id: string;
  nome: string;
  ordem: number;
  courseId: string; // Ref to parent for global listing
  createdAt: any;
}

export interface Lesson {
  id: string;
  titulo: string;
  descricao?: string;
  videoUrl: string;
  materialUrl: string;
  ordem: number;
  createdAt: any;
}

export type MainView = 'dashboard' | 'professor' | 'alunos' | 'secretaria' | 'configuracoes';

export type ProfessorSubView = 
  | 'cursos' 
  | 'modulos' 
  | 'materiais' 
  | 'avaliacao' 
  | 'feedback' 
  | 'diario' 
  | 'relatorio' 
  | 'frequencia' 
  | 'live';

export interface NavItem {
  id: MainView;
  label: string;
  icon: React.ReactNode;
}

import React, { useState, useEffect, useRef } from 'react';
import { 
  collection, 
  query, 
  where, 
  getDocs, 
  addDoc, 
  deleteDoc,
  serverTimestamp, 
  orderBy,
  doc,
  getDoc,
  updateDoc
} from 'firebase/firestore';
import { db } from '../firebase';
import { Course, Module, Lesson, User, ProfessorSubView } from '../types';
import { 
  Search, 
  Filter, 
  BookOpen, 
  Plus, 
  Info, 
  X, 
  ChevronRight, 
  Play, 
  Pause,
  Volume2,
  VolumeX,
  Maximize,
  FileText, 
  MoreVertical, 
  ArrowLeft, 
  Layout, 
  Trash2, 
  AlertTriangle, 
  Layers, 
  Eye, 
  Clock, 
  Download, 
  CheckCircle, 
  Copy,
  Edit,
  GraduationCap,
  FileUp,
  ShieldCheck
} from 'lucide-react';

interface ProfessorViewProps {
  user: User;
  activeSub: ProfessorSubView;
  setActiveSub: (view: ProfessorSubView) => void;
}

const ProfessorView: React.FC<ProfessorViewProps> = ({ user, activeSub, setActiveSub }) => {
  const [myCourses, setMyCourses] = useState<Course[]>([]);
  const [loading, setLoading] = useState(true);
  const [selectedCourse, setSelectedCourse] = useState<Course | null>(null);
  const [modules, setModules] = useState<Module[]>([]);
  const [lessonsByModule, setLessonsByModule] = useState<Record<string, Lesson[]>>({});
  const [openMenuId, setOpenMenuId] = useState<string | null>(null);

  // Modal States
  const [showCourseModal, setShowCourseModal] = useState(false);
  const [showModuleModal, setShowModuleModal] = useState(false);
  const [showLessonModal, setShowLessonModal] = useState(false);
  const [activeModuleId, setActiveModuleId] = useState<string | null>(null);

  // Preview States
  const [previewLesson, setPreviewLesson] = useState<Lesson | null>(null);
  const [countdown, setCountdown] = useState(15);
  const [isTimerFinished, setIsTimerFinished] = useState(false);
  const [isConcluded, setIsConcluded] = useState(false);

  // Custom Player States
  const [playerIsPlaying, setPlayerIsPlaying] = useState(false);
  const [playerVolume, setPlayerVolume] = useState(80);
  const [isMuted, setIsMuted] = useState(false);
  const iframeRef = useRef<HTMLIFrameElement>(null);
  const playerContainerRef = useRef<HTMLDivElement>(null);

  // Form States
  const [courseForm, setCourseForm] = useState({
    nome: '',
    tema: '',
    descricao: '',
    descricaoLonga: '',
    professorResponsavel: user.displayName || '',
    capaUrl: '',
    cargaHoraria: '',
    publicoAlvo: 'Geral' as const
  });
  const [moduleForm, setModuleForm] = useState({ nome: '' });
  const [lessonForm, setLessonForm] = useState({
    titulo: '',
    descricao: '',
    videoUrl: '',
    materialUrl: ''
  });

  const fetchMyCourses = async () => {
    setLoading(true);
    try {
      const q = query(collection(db, 'cursos'), where('professorId', '==', user.uid), orderBy('createdAt', 'desc'));
      const querySnapshot = await getDocs(q);
      const fetched: Course[] = [];
      querySnapshot.forEach((doc) => {
        fetched.push({ id: doc.id, ...doc.data() } as Course);
      });
      setMyCourses(fetched);
    } catch (error) {
      console.error("Erro ao carregar seus cursos:", error);
    } finally {
      setLoading(false);
    }
  };

  const fetchModules = async (courseId: string) => {
    try {
      const q = query(collection(db, 'cursos', courseId, 'modulos'), orderBy('ordem', 'asc'));
      const querySnapshot = await getDocs(q);
      const fetched: Module[] = [];
      querySnapshot.forEach((doc) => {
        fetched.push({ id: doc.id, ...doc.data() } as Module);
      });
      setModules(fetched);

      for (const mod of fetched) {
        fetchLessons(courseId, mod.id);
      }
    } catch (error) {
      console.error("Erro ao carregar módulos:", error);
    }
  };

  const fetchLessons = async (courseId: string, moduleId: string) => {
    try {
      const q = query(collection(db, 'cursos', courseId, 'modulos', moduleId, 'aulas'), orderBy('ordem', 'asc'));
      const querySnapshot = await getDocs(q);
      const fetched: Lesson[] = [];
      querySnapshot.forEach((doc) => {
        fetched.push({ id: doc.id, ...doc.data() } as Lesson);
      });
      setLessonsByModule(prev => ({ ...prev, [moduleId]: fetched }));
    } catch (error) {
      console.error("Erro ao carregar aulas:", error);
    }
  };

  useEffect(() => {
    fetchMyCourses();
  }, [user.uid]);

  // SINCRONIZAÇÃO DA TRAVA (NÃO ALTERAR)
  useEffect(() => {
    let timer: number | undefined;

    if (previewLesson && countdown > 0 && !isConcluded) {
      timer = window.setInterval(() => {
        setCountdown((prev) => {
          if (prev <= 1) {
            setIsTimerFinished(true);
            if (timer) clearInterval(timer);
            return 0;
          }
          return prev - 1;
        });
      }, 1000);
    }

    return () => {
      if (timer) clearInterval(timer);
    };
  }, [previewLesson, countdown, isConcluded]);

  // PLAYER COMMANDS (NÃO ALTERAR)
  const sendPlayerCommand = (func: string, args: any[] = []) => {
    if (iframeRef.current && iframeRef.current.contentWindow) {
      iframeRef.current.contentWindow.postMessage(
        JSON.stringify({ event: 'command', func, args }), 
        '*'
      );
    }
  };

  const togglePlay = () => {
    if (playerIsPlaying) {
      sendPlayerCommand('pauseVideo');
    } else {
      sendPlayerCommand('playVideo');
    }
    setPlayerIsPlaying(!playerIsPlaying);
  };

  const toggleMute = () => {
    if (isMuted) {
      sendPlayerCommand('unMute');
      sendPlayerCommand('setVolume', [playerVolume]);
    } else {
      sendPlayerCommand('mute');
    }
    setIsMuted(!isMuted);
  };

  const handleVolumeChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const vol = parseInt(e.target.value);
    setPlayerVolume(vol);
    if (!isMuted) {
      sendPlayerCommand('setVolume', [vol]);
    }
  };

  const toggleFullscreen = () => {
    if (playerContainerRef.current) {
      if (!document.fullscreenElement) {
        playerContainerRef.current.requestFullscreen().catch(err => {
          console.error(`Erro ao ativar tela cheia: ${err.message}`);
        });
      } else {
        document.exitFullscreen();
      }
    }
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    if (file.size > 5 * 1024 * 1024) {
      alert("Erro: O arquivo é muito grande. O limite máximo permitido é de 5 MB.");
      e.target.value = "";
      return;
    }

    const reader = new FileReader();
    reader.onloadend = () => {
      setCourseForm(prev => ({ ...prev, capaUrl: reader.result as string }));
    };
    reader.readAsDataURL(file);
  };

  const handleCreateCourse = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      await addDoc(collection(db, 'cursos'), {
        ...courseForm,
        professorId: user.uid,
        inscritos: 0,
        status: 'rascunho',
        createdAt: serverTimestamp()
      });
      setShowCourseModal(false);
      setCourseForm({ 
        nome: '', tema: '', descricao: '', descricaoLonga: '', 
        professorResponsavel: user.displayName || '', capaUrl: '', 
        cargaHoraria: '', publicoAlvo: 'Geral' 
      });
      fetchMyCourses();
    } catch (error) {
      console.error("Erro ao criar curso:", error);
    }
  };

  const handleDeleteCourse = async (courseId: string) => {
    if (!confirm("Tem certeza que deseja excluir este curso e todo o seu conteúdo permanentemente?")) return;
    try {
      await deleteDoc(doc(db, 'cursos', courseId));
      fetchMyCourses();
      setOpenMenuId(null);
    } catch (error) { console.error(error); }
  };

  const handleDuplicateCourse = async (course: Course) => {
    try {
      const { id, ...data } = course;
      await addDoc(collection(db, 'cursos'), {
        ...data,
        nome: `${data.nome} (Cópia)`,
        createdAt: serverTimestamp(),
        inscritos: 0,
        status: 'rascunho'
      });
      fetchMyCourses();
      setOpenMenuId(null);
    } catch (error) { console.error(error); }
  };

  const handleCreateModule = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedCourse) return;
    try {
      await addDoc(collection(db, 'cursos', selectedCourse.id, 'modulos'), {
        nome: moduleForm.nome,
        ordem: modules.length + 1,
        courseId: selectedCourse.id,
        createdAt: serverTimestamp()
      });
      setShowModuleModal(false);
      setModuleForm({ nome: '' });
      fetchModules(selectedCourse.id);
    } catch (error) {
      console.error("Erro ao criar módulo:", error);
    }
  };

  const handleDeleteModule = async (moduleId: string) => {
    const targetCourseId = selectedCourse?.id || modules.find(m => m.id === moduleId)?.courseId;
    if (!targetCourseId) return;
    if (!confirm("Deseja excluir este módulo?")) return;

    try {
      await deleteDoc(doc(db, 'cursos', targetCourseId, 'modulos', moduleId));
      if (selectedCourse) fetchModules(selectedCourse.id);
      else fetchAllModules();
    } catch (error) { console.error(error); }
  };

  const handleDuplicateModule = async (mod: Module) => {
    try {
      const { id, ...data } = mod;
      await addDoc(collection(db, 'cursos', mod.courseId, 'modulos'), {
        ...data,
        nome: `${data.nome} (Cópia)`,
        ordem: modules.length + 1,
        createdAt: serverTimestamp()
      });
      if (selectedCourse) fetchModules(selectedCourse.id);
      else fetchAllModules();
    } catch (error) { console.error(error); }
  };

  const handleCreateLesson = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedCourse || !activeModuleId) return;
    try {
      const currentLessonsCount = lessonsByModule[activeModuleId]?.length || 0;
      await addDoc(collection(db, 'cursos', selectedCourse.id, 'modulos', activeModuleId, 'aulas'), {
        ...lessonForm,
        ordem: currentLessonsCount + 1,
        createdAt: serverTimestamp()
      });
      setShowLessonModal(false);
      setLessonForm({ titulo: '', descricao: '', videoUrl: '', materialUrl: '' });
      fetchLessons(selectedCourse.id, activeModuleId);
    } catch (error) {
      console.error("Erro ao criar aula:", error);
    }
  };

  const openCourseDetail = (course: Course) => {
    setSelectedCourse(course);
    setActiveSub('modulos');
    fetchModules(course.id);
  };

  const [allModulesByCourse, setAllModulesByCourse] = useState<Record<string, {course: Course, modules: Module[]}>>({});

  const fetchAllModules = async () => {
    setLoading(true);
    try {
      const grouped: Record<string, {course: Course, modules: Module[]}> = {};
      for (const course of myCourses) {
        const q = query(collection(db, 'cursos', course.id, 'modulos'), orderBy('ordem', 'asc'));
        const querySnapshot = await getDocs(q);
        const mods: Module[] = [];
        querySnapshot.forEach(d => mods.push({id: d.id, ...d.data()} as Module));
        grouped[course.id] = { course, modules: mods };
      }
      setAllModulesByCourse(grouped);
    } catch (error) { console.error(error); } finally { setLoading(false); }
  };

  useEffect(() => {
    if (activeSub === 'modulos' && !selectedCourse) {
      fetchAllModules();
    }
  }, [activeSub, selectedCourse, myCourses]);

  const openPreview = (lesson: Lesson) => {
    setCountdown(15);
    setIsTimerFinished(false);
    setIsConcluded(false);
    setPlayerIsPlaying(false);
    setPreviewLesson(lesson);
  };

  const closePreview = () => {
    setPreviewLesson(null);
    setIsTimerFinished(false);
    setIsConcluded(false);
    setCountdown(15);
    setPlayerIsPlaying(false);
  };

  const handleConcludeLesson = () => {
    if (!isTimerFinished) return;
    setIsConcluded(true);
  };

  const getEmbedUrl = (url: string) => {
    if (!url) return "";
    const ytRegex = /(?:https?:\/\/)?(?:www\.)?(?:youtube\.com\/(?:[^\/\n\s]+\/\S+\/|(?:v|e(?:mbed)?)\/|\S*?[?&]v=)|youtu\.be\/)([a-zA-Z0-9_-]{11})/;
    const ytMatch = url.match(ytRegex);
    if (ytMatch && ytMatch[1]) {
      return `https://www.youtube.com/embed/${ytMatch[1]}?modestbranding=1&rel=0&iv_load_policy=3&disablekb=1&controls=0&showinfo=0&enablejsapi=1&origin=${window.location.origin}`;
    }
    return url;
  };

  // RENDER: VISÃO GERAL DE MÓDULOS (Agrupado por Curso)
  if (activeSub === 'modulos' && !selectedCourse) {
    return (
      <div className="space-y-6 animate-in fade-in duration-500">
        <header>
          <h1 className="text-2xl font-bold text-slate-900 tracking-tight">Visão Geral dos Módulos</h1>
          <p className="text-slate-500 text-sm font-medium">Controle centralizado da estrutura curricular de todos os seus cursos.</p>
        </header>

        {loading ? (
          <div className="flex items-center justify-center p-20"><div className="h-8 w-8 animate-spin rounded-full border-4 border-indigo-600 border-t-transparent"></div></div>
        ) : Object.keys(allModulesByCourse).length === 0 ? (
          <div className="bg-white p-20 rounded-2xl border border-slate-200 text-center opacity-50">
            <Layers size={48} className="mx-auto mb-4 text-slate-300" />
            <p className="font-bold text-slate-900">Nenhum módulo encontrado</p>
          </div>
        ) : (
          <div className="space-y-8">
            {Object.values(allModulesByCourse).map(({ course, modules }) => (
              <div key={course.id} className="bg-white rounded-2xl border border-slate-200 shadow-sm overflow-hidden">
                <div className="px-6 py-4 border-b border-slate-100 flex items-center justify-between bg-slate-50/50">
                  <div className="flex items-center gap-3">
                    <div className="bg-indigo-600 text-white p-1.5 rounded-lg"><BookOpen size={16} /></div>
                    <h2 className="text-sm font-bold text-slate-800 uppercase tracking-widest">{course.nome}</h2>
                  </div>
                  <span className="text-[10px] font-bold text-slate-400 uppercase">{modules.length} Módulos</span>
                </div>
                <div className="overflow-x-auto">
                  <table className="w-full text-left">
                    <thead className="bg-slate-50/30 text-[10px] font-black text-slate-400 uppercase tracking-tighter border-b border-slate-100">
                      <tr>
                        <th className="px-6 py-3 w-16 text-center">Ordem</th>
                        <th className="px-6 py-3">Título do Módulo</th>
                        <th className="px-6 py-3">Data de Criação</th>
                        <th className="px-6 py-3 text-right">Ações Rápidas</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-100 text-sm">
                      {modules.map(mod => (
                        <tr key={mod.id} className="hover:bg-slate-50/50 transition-colors">
                          <td className="px-6 py-4 text-center font-bold text-slate-400">#{mod.ordem}</td>
                          <td className="px-6 py-4 font-semibold text-slate-900">{mod.nome}</td>
                          <td className="px-6 py-4 text-slate-500 text-xs">Ajustado via EAD 1.0</td>
                          <td className="px-6 py-4">
                            <div className="flex items-center justify-end gap-1">
                              <button onClick={() => openCourseDetail(course)} className="p-2 text-indigo-600 hover:bg-indigo-50 rounded-lg transition-colors" title="Visualizar como Aluno"><Eye size={16} /></button>
                              <button className="p-2 text-slate-400 hover:bg-slate-100 rounded-lg transition-colors" title="Editar"><Edit size={16} /></button>
                              <button onClick={() => handleDuplicateModule(mod)} className="p-2 text-slate-400 hover:bg-slate-100 rounded-lg transition-colors" title="Duplicar"><Copy size={16} /></button>
                              <button onClick={() => handleDeleteModule(mod.id)} className="p-2 text-red-400 hover:bg-red-50 rounded-lg transition-colors" title="Excluir"><Trash2 size={16} /></button>
                            </div>
                          </td>
                        </tr>
                      ))}
                      {modules.length === 0 && (
                        <tr><td colSpan={4} className="p-8 text-center text-slate-400 italic text-xs">Nenhum módulo cadastrado neste curso.</td></tr>
                      )}
                    </tbody>
                  </table>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>
    );
  }

  // RENDER: MATRIZ CURRICULAR (Específica do Curso)
  if (activeSub === 'modulos' && selectedCourse) {
    return (
      <div className="space-y-6 animate-in fade-in duration-500">
        <header className="flex items-center justify-between gap-4">
          <div className="flex items-center gap-4">
            <button 
              onClick={() => { setSelectedCourse(null); setActiveSub('cursos'); }}
              className="flex items-center justify-center h-10 w-10 bg-white border border-slate-200 hover:bg-slate-50 rounded-xl text-slate-600 transition-all shadow-sm group"
              title="Voltar para Cursos"
            >
              <ArrowLeft size={20} className="group-hover:-translate-x-1 transition-transform" />
            </button>
            <div>
              <h1 className="text-2xl font-bold text-slate-900 leading-tight">{selectedCourse.nome}</h1>
              <div className="flex items-center gap-2 mt-0.5">
                <span className="text-slate-400 text-xs font-medium uppercase tracking-wider">Métrica Pedagógica</span>
                <span className="h-1 w-1 rounded-full bg-slate-300"></span>
                <span className="text-indigo-600 text-xs font-bold uppercase tracking-wider">{selectedCourse.publicoAlvo}</span>
              </div>
            </div>
          </div>
          <button 
            onClick={() => setShowModuleModal(true)}
            className="hidden sm:flex items-center gap-2 bg-indigo-600 text-white px-5 py-2.5 rounded-xl text-sm font-bold hover:bg-indigo-700 transition-all shadow-lg shadow-indigo-600/20"
          >
            <Plus size={18} />
            Novo Módulo
          </button>
        </header>

        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
          <div className="lg:col-span-2 space-y-4">
            <div className="bg-white rounded-2xl border border-slate-200 shadow-sm overflow-hidden">
              <div className="px-6 py-4 border-b border-slate-100 flex items-center justify-between bg-slate-50/50">
                <div className="flex items-center gap-2">
                  <Layout size={16} className="text-slate-400" />
                  <h2 className="text-xs font-bold text-slate-800 uppercase tracking-widest">Matriz de Ensino</h2>
                </div>
                <span className="text-[10px] font-bold text-slate-400">{modules.length} Módulos Ativos</span>
              </div>

              <div className="p-4 space-y-4">
                {modules.length === 0 ? (
                  <div className="p-16 text-center opacity-50">
                    <Layers size={24} className="mx-auto mb-4 text-slate-300" />
                    <p className="text-slate-500 font-medium text-sm">Este curso ainda não possui módulos.</p>
                  </div>
                ) : (
                  modules.map((mod) => (
                    <div key={mod.id} className="border border-slate-100 rounded-xl overflow-hidden bg-slate-50/30 group">
                      <div className="px-4 py-3 border-b border-slate-100 flex items-center justify-between bg-white group-hover:bg-slate-50/50 transition-colors">
                        <div className="flex items-center gap-3">
                          <span className="bg-slate-900 text-white w-6 h-6 rounded-lg flex items-center justify-center text-[10px] font-black">
                            {mod.ordem < 10 ? `0${mod.ordem}` : mod.ordem}
                          </span>
                          <h3 className="font-bold text-slate-800 text-sm tracking-tight">{mod.nome}</h3>
                        </div>
                        <div className="flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                          <button onClick={() => { setActiveModuleId(mod.id); setShowLessonModal(true); }} className="p-1.5 text-indigo-600 hover:bg-indigo-50 rounded-lg transition-colors" title="Adicionar Aula"><Plus size={18} /></button>
                          <button onClick={() => handleDeleteModule(mod.id)} className="p-1.5 text-slate-400 hover:text-red-500 hover:bg-red-50 rounded-lg transition-colors" title="Excluir Módulo"><Trash2 size={18} /></button>
                        </div>
                      </div>

                      <div className="p-2 space-y-1">
                        {lessonsByModule[mod.id]?.map((lesson) => (
                          <div key={lesson.id} className="flex items-center justify-between p-3 rounded-xl hover:bg-white hover:shadow-sm transition-all group/lesson bg-transparent">
                            <div className="flex items-center gap-4">
                              <div className="p-2 bg-white border border-slate-100 text-indigo-600 rounded-lg shadow-sm"><Play size={12} fill="currentColor" /></div>
                              <div>
                                <p className="text-sm font-semibold text-slate-700 leading-none">{lesson.titulo}</p>
                                <div className="flex items-center gap-3 mt-1.5">
                                  {lesson.videoUrl && <span className="text-[10px] text-slate-400 flex items-center gap-1 bg-slate-100 px-1.5 py-0.5 rounded"><Play size={8} /> Vídeo</span>}
                                  {lesson.materialUrl && <span className="text-[10px] text-slate-400 flex items-center gap-1 bg-slate-100 px-1.5 py-0.5 rounded"><FileText size={8} /> Apoio</span>}
                                </div>
                              </div>
                            </div>
                            <div className="flex items-center gap-1 opacity-0 group-hover/lesson:opacity-100 transition-all">
                              <button onClick={() => openPreview(lesson)} className="p-1.5 text-indigo-600 hover:bg-indigo-50 rounded-lg transition-colors" title="Pré-visualizar"><Eye size={16} /></button>
                              <button className="p-1.5 text-slate-300 hover:text-red-500 transition-all" title="Excluir Aula"><Trash2 size={14} /></button>
                            </div>
                          </div>
                        ))}
                      </div>
                    </div>
                  ))
                )}
              </div>
            </div>
          </div>

          <div className="space-y-4">
            <div className="bg-white p-5 rounded-2xl border border-slate-200 shadow-sm sticky top-24">
              <div className="relative rounded-xl overflow-hidden mb-5 border border-slate-100 shadow-inner h-40 bg-slate-50">
                {selectedCourse.capaUrl ? (
                  <img src={selectedCourse.capaUrl} alt="Capa" className="w-full h-full object-cover" />
                ) : (
                  <div className="w-full h-full flex items-center justify-center text-slate-300"><FileText size={32} /></div>
                )}
              </div>
              <div className="space-y-4">
                <div className="flex items-center justify-between text-xs pb-3 border-b border-slate-50">
                  <span className="text-slate-500 font-bold uppercase tracking-tighter">Professor</span>
                  <span className="text-indigo-600 font-bold">{selectedCourse.professorResponsavel || 'Não definido'}</span>
                </div>
                <div className="flex items-center justify-between text-xs pb-3 border-b border-slate-50">
                  <span className="text-slate-500 font-bold uppercase tracking-tighter">Status</span>
                  <span className={`px-2 py-0.5 rounded text-[10px] font-black uppercase ${selectedCourse.status === 'ativo' ? 'bg-emerald-100 text-emerald-700' : 'bg-slate-100 text-slate-600'}`}>
                    {selectedCourse.status}
                  </span>
                </div>
                <div className="flex items-center justify-between text-xs">
                  <span className="text-slate-500 font-bold uppercase tracking-tighter">Carga Horária</span>
                  <span className="text-slate-900 font-black">{selectedCourse.cargaHoraria}</span>
                </div>
                {selectedCourse.descricaoLonga && (
                  <div className="pt-4 mt-4 border-t border-slate-50">
                    <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Ementa do Curso</p>
                    <p className="text-[11px] text-slate-500 leading-relaxed line-clamp-4">{selectedCourse.descricaoLonga}</p>
                  </div>
                )}
              </div>
            </div>
          </div>
        </div>

        {/* Modal Módulo */}
        {showModuleModal && (
          <div className="fixed inset-0 z-[110] flex items-center justify-center p-4 bg-slate-900/40 backdrop-blur-sm">
            <div className="bg-white w-full max-w-md rounded-2xl shadow-2xl overflow-hidden animate-in zoom-in-95 duration-200">
              <div className="p-4 border-b border-slate-100 flex items-center justify-between">
                <h3 className="font-bold text-slate-900">Novo Módulo Acadêmico</h3>
                <button onClick={() => setShowModuleModal(false)} className="text-slate-400 hover:text-slate-600 p-2"><X size={20} /></button>
              </div>
              <form onSubmit={handleCreateModule} className="p-6 space-y-4">
                <div className="space-y-1.5">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Título do Módulo</label>
                  <input required autoFocus value={moduleForm.nome} onChange={e => setModuleForm({nome: e.target.value})} className="w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm outline-none focus:ring-2 focus:ring-indigo-500 transition-all" />
                </div>
                <button type="submit" className="w-full bg-indigo-600 text-white py-3 rounded-xl font-bold text-sm shadow-lg shadow-indigo-100">Criar Módulo</button>
              </form>
            </div>
          </div>
        )}

        {/* Modal Aula */}
        {showLessonModal && (
          <div className="fixed inset-0 z-[110] flex items-center justify-center p-4 bg-slate-900/40 backdrop-blur-sm">
            <div className="bg-white w-full max-w-lg rounded-2xl shadow-2xl overflow-hidden animate-in zoom-in-95 duration-200">
              <div className="p-4 border-b border-slate-100 flex items-center justify-between">
                <h3 className="font-bold text-slate-900">Adicionar Aula à Unidade</h3>
                <button onClick={() => setShowLessonModal(false)} className="text-slate-400 hover:text-slate-600 p-2"><X size={20} /></button>
              </div>
              <form onSubmit={handleCreateLesson} className="p-6 space-y-4">
                <div className="space-y-1.5">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Título da Aula</label>
                  <input required autoFocus value={lessonForm.titulo} onChange={e => setLessonForm({...lessonForm, titulo: e.target.value})} className="w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm outline-none focus:ring-2 focus:ring-indigo-500" />
                </div>
                <div className="space-y-1.5">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Descrição / Resumo</label>
                  <textarea rows={2} value={lessonForm.descricao} onChange={e => setLessonForm({...lessonForm, descricao: e.target.value})} className="w-full px-4 py-2 bg-slate-50 border border-slate-200 rounded-xl text-sm outline-none resize-none focus:ring-2 focus:ring-indigo-500" placeholder="Breve introdução do conteúdo..."></textarea>
                </div>
                <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                  <div className="space-y-1.5">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">URL Vídeo (YT)</label>
                    <input value={lessonForm.videoUrl} onChange={e => setLessonForm({...lessonForm, videoUrl: e.target.value})} className="w-full px-4 py-2 bg-slate-50 border border-slate-200 rounded-xl text-sm outline-none focus:ring-2 focus:ring-indigo-500" />
                  </div>
                  <div className="space-y-1.5">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Link Material PDF</label>
                    <input value={lessonForm.materialUrl} onChange={e => setLessonForm({...lessonForm, materialUrl: e.target.value})} className="w-full px-4 py-2 bg-slate-50 border border-slate-200 rounded-xl text-sm outline-none focus:ring-2 focus:ring-indigo-500" />
                  </div>
                </div>
                <button type="submit" className="w-full bg-indigo-600 text-white py-3 rounded-xl font-bold text-sm shadow-lg shadow-indigo-100">Publicar Conteúdo</button>
              </form>
            </div>
          </div>
        )}

        {/* Modal Preview - PLAYER REPROJETADO E BLINDADO (NÃO ALTERAR ESTRUTURA) */}
        {previewLesson && (
          <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 bg-slate-900/80 backdrop-blur-md animate-in fade-in duration-300">
            <div className="bg-white w-full max-w-6xl h-[90vh] rounded-3xl shadow-2xl overflow-hidden flex flex-col animate-in zoom-in-95 duration-200">
              <div className="p-5 border-b border-slate-100 flex items-center justify-between bg-white">
                <div className="flex items-center gap-3">
                  <div className="bg-indigo-600 p-2 rounded-xl text-white shadow-lg shadow-indigo-200"><Eye size={18} /></div>
                  <div>
                    <h3 className="font-bold text-slate-900 text-base leading-tight">{previewLesson.titulo}</h3>
                    <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest">Ambiente de Ensino Blindado 1.0</p>
                  </div>
                </div>
                <button onClick={closePreview} className="flex items-center gap-2 px-4 py-2 bg-slate-100 hover:bg-slate-200 rounded-xl text-slate-600 text-xs font-bold transition-colors"><X size={16} /> Encerrar Aula</button>
              </div>

              <div className="flex-1 overflow-y-auto bg-slate-50/50 p-6 flex flex-col lg:flex-row gap-6">
                <div className="flex-[2] space-y-6">
                  {previewLesson.videoUrl ? (
                    <div ref={playerContainerRef} className="aspect-video bg-slate-900 rounded-2xl overflow-hidden shadow-2xl border-4 border-white relative group">
                      <iframe ref={iframeRef} width="100%" height="100%" src={getEmbedUrl(previewLesson.videoUrl)} title="Video Player" frameBorder="0" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture" allowFullScreen className="pointer-events-none"></iframe>
                      <div className="absolute top-0 left-0 w-full h-24 bg-transparent z-10 pointer-events-auto cursor-default"></div>
                      <div className="absolute bottom-0 left-0 w-full h-20 bg-transparent z-10 pointer-events-auto cursor-default"></div>
                      <div className="absolute inset-0 z-20 pointer-events-none flex flex-col justify-end">
                        {!playerIsPlaying && (
                          <div className="absolute inset-0 flex items-center justify-center bg-black/20 backdrop-blur-[2px] pointer-events-auto cursor-pointer group/center" onClick={togglePlay}>
                            <div className="w-20 h-20 bg-white/10 backdrop-blur-xl border border-white/20 rounded-full flex items-center justify-center text-white scale-100 group-hover/center:scale-110 transition-all shadow-2xl"><Play size={40} fill="currentColor" /></div>
                          </div>
                        )}
                        <div className="p-4 bg-gradient-to-t from-black/80 via-black/40 to-transparent opacity-0 group-hover:opacity-100 transition-opacity duration-300 pointer-events-auto">
                          <div className="flex items-center justify-between gap-6 px-4">
                            <div className="flex items-center gap-4">
                              <button onClick={togglePlay} className="text-white hover:text-indigo-400 transition-colors">{playerIsPlaying ? <Pause size={24} fill="currentColor" /> : <Play size={24} fill="currentColor" />}</button>
                              <div className="flex items-center gap-3 group/vol">
                                <button onClick={toggleMute} className="text-white hover:text-indigo-400 transition-colors">{(isMuted || playerVolume === 0) ? <VolumeX size={20} /> : <Volume2 size={20} />}</button>
                                <input type="range" min="0" max="100" value={isMuted ? 0 : playerVolume} onChange={handleVolumeChange} className="w-20 h-1.5 bg-white/20 rounded-full appearance-none cursor-pointer accent-indigo-500 hover:accent-indigo-400 transition-all" />
                              </div>
                            </div>
                            <div className="flex items-center gap-4">
                              <span className="text-[10px] font-black text-white/40 uppercase tracking-widest hidden sm:block">🔒 Escola Bíblica Blindada</span>
                              <button onClick={toggleFullscreen} className="text-white hover:text-indigo-400 transition-colors"><Maximize size={20} /></button>
                            </div>
                          </div>
                        </div>
                      </div>
                    </div>
                  ) : (
                    <div className="aspect-video flex items-center justify-center p-20 border-2 border-dashed border-slate-200 rounded-3xl text-slate-400 italic bg-white text-center"><p>Conteúdo em vídeo não configurado para esta aula.</p></div>
                  )}

                  {/* Descrição da Aula */}
                  <div className="p-8 bg-white rounded-3xl border border-slate-200 shadow-sm space-y-4">
                    <h4 className="text-lg font-bold text-slate-900 flex items-center gap-2"><FileText size={20} className="text-indigo-600" /> Sobre esta Aula</h4>
                    <p className="text-sm text-slate-600 leading-relaxed whitespace-pre-wrap">
                      {previewLesson.descricao || "Nenhuma descrição detalhada disponível para este conteúdo pedagógico no momento."}
                    </p>
                  </div>
                </div>

                <div className="flex-1 space-y-4">
                  <div className="bg-white p-6 rounded-3xl border border-slate-200 shadow-sm sticky top-0">
                    <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] mb-4">Progresso do Aluno</h4>
                    <div className="space-y-6">
                      <div className={`p-5 rounded-2xl border transition-all ${isConcluded ? 'bg-emerald-50 border-emerald-100' : 'bg-indigo-50 border-indigo-100'}`}>
                        <div className="flex items-center gap-3 mb-2">
                          {isConcluded ? (
                            <div className="bg-emerald-500 text-white p-1 rounded-full"><CheckCircle size={14} /></div>
                          ) : (
                            <Clock size={18} className="text-indigo-600 animate-pulse" />
                          )}
                          <span className={`text-xs font-bold ${isConcluded ? 'text-emerald-700' : 'text-indigo-700'}`}>
                            {isConcluded ? 'Presença Validada' : 'Acompanhamento Ativo'}
                          </span>
                        </div>
                        <p className="text-[10px] text-slate-500 leading-relaxed font-medium">
                          {isConcluded ? 'Certificado de conclusão desta unidade liberado.' : 'Permaneça na aula. O sistema validará seu engajamento em breve.'}
                        </p>
                      </div>

                      <div className="bg-slate-50 p-6 rounded-2xl text-center border border-slate-100">
                        {(!isTimerFinished && !isConcluded) ? (
                          <div className="space-y-1">
                            <span className="text-4xl font-black text-slate-900 tabular-nums tracking-tighter">{countdown}s</span>
                            <p className="text-[9px] font-bold text-slate-400 uppercase tracking-[0.3em]">Validação em Curso</p>
                          </div>
                        ) : (
                          <div className="py-2 flex flex-col items-center gap-1">
                            <div className="text-emerald-600 flex items-center gap-2"><CheckCircle size={20} /><span className="font-black text-sm uppercase">Foco Validado</span></div>
                            <p className="text-[10px] text-slate-400">Requisito técnico satisfeito.</p>
                          </div>
                        )}
                      </div>

                      <div className="space-y-3">
                        <button disabled={!isTimerFinished || isConcluded} onClick={handleConcludeLesson} className={`w-full py-4 rounded-2xl font-bold text-sm transition-all shadow-lg flex items-center justify-center gap-2 ${isTimerFinished && !isConcluded ? 'bg-slate-900 text-white shadow-slate-200 hover:bg-slate-800' : isConcluded ? 'bg-emerald-100 text-emerald-700 border border-emerald-200' : 'bg-slate-100 text-slate-400 border border-slate-200 shadow-none'}`}>
                          {isConcluded ? <><CheckCircle size={16} /> Aula Concluída</> : countdown > 0 ? <span className="text-[11px]">Validando Aula... ({countdown}s)</span> : 'Confirmar Conclusão'}
                        </button>
                        {isConcluded && previewLesson.materialUrl && (
                          <a href={previewLesson.materialUrl} target="_blank" rel="noopener noreferrer" className="w-full py-4 bg-indigo-600 text-white rounded-2xl font-bold text-sm transition-all shadow-lg shadow-indigo-100 flex items-center justify-center gap-2 hover:bg-indigo-700 animate-in slide-in-from-bottom duration-500"><Download size={18} /> Baixar PDF de Apoio</a>
                        )}
                      </div>
                    </div>
                    <div className="mt-8 pt-6 border-t border-slate-50 text-center"><p className="text-[9px] text-slate-400 uppercase font-black tracking-widest italic">LMS Pedagógico Igreja 1.0</p></div>
                  </div>
                </div>
              </div>
            </div>
          </div>
        )}
      </div>
    );
  }

  // RENDER: LISTA DE CURSOS (Dashboard Inicial)
  return (
    <div className="space-y-6 animate-in fade-in duration-500">
      <header className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold text-slate-900 tracking-tight">Gestão de Cursos</h1>
          <p className="text-slate-500 text-sm font-medium">Configure seus cursos, gerencie currículos e acompanhe alunos.</p>
        </div>
        <button onClick={() => setShowCourseModal(true)} className="flex items-center justify-center gap-2 bg-indigo-600 text-white px-5 py-3 rounded-xl text-sm font-bold hover:bg-indigo-700 transition-all shadow-lg shadow-indigo-100">
          <Plus size={18} /> Configurar Novo Curso
        </button>
      </header>

      <div className="bg-white rounded-2xl border border-slate-200 shadow-sm min-h-[400px] flex flex-col overflow-visible">
        <div className="p-4 border-b border-slate-100 flex flex-col sm:flex-row items-center justify-between gap-4 bg-slate-50/30">
          <div className="relative w-full max-w-xs">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={16} />
            <input type="text" placeholder="Filtrar curso..." className="w-full pl-10 pr-4 py-2.5 bg-white border border-slate-200 rounded-lg text-xs outline-none focus:ring-2 focus:ring-indigo-500 transition-all" />
          </div>
        </div>

        {loading ? (
          <div className="flex-1 flex items-center justify-center p-12"><div className="h-6 w-6 animate-spin rounded-full border-2 border-indigo-600 border-t-transparent"></div></div>
        ) : myCourses.length > 0 ? (
          <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6 p-6">
            {myCourses.map(course => (
              <div key={course.id} className="border border-slate-200 p-4 rounded-3xl hover:shadow-xl hover:border-indigo-400 transition-all group bg-white flex flex-col relative overflow-visible">
                {/* Menu de Ações do Curso */}
                <div className="absolute top-3 right-3 z-[40]">
                  <button onClick={(e) => { e.stopPropagation(); setOpenMenuId(openMenuId === course.id ? null : course.id); }} className="p-2 bg-white/90 backdrop-blur-sm rounded-xl border border-slate-200 text-slate-500 hover:text-indigo-600 shadow-sm transition-all"><MoreVertical size={16} /></button>
                  {openMenuId === course.id && (
                    <div className="absolute right-0 mt-2 w-40 bg-white rounded-2xl shadow-2xl border border-slate-100 z-[50] animate-in zoom-in-95 duration-100 overflow-hidden">
                      <button onClick={() => openCourseDetail(course)} className="w-full px-4 py-3 text-left text-xs font-bold text-slate-600 hover:bg-slate-50 hover:text-indigo-600 transition-colors flex items-center gap-2"><Edit size={14} /> Editar Estrutura</button>
                      <button onClick={() => handleDuplicateCourse(course)} className="w-full px-4 py-3 text-left text-xs font-bold text-slate-600 hover:bg-slate-50 hover:text-indigo-600 transition-colors flex items-center gap-2"><Copy size={14} /> Duplicar</button>
                      <button onClick={() => handleDeleteCourse(course.id)} className="w-full px-4 py-3 text-left text-xs font-bold text-red-500 hover:bg-red-50 transition-colors flex items-center gap-2"><Trash2 size={14} /> Excluir</button>
                    </div>
                  )}
                </div>

                <div onClick={() => openCourseDetail(course)} className="cursor-pointer">
                  <div className="relative h-40 rounded-2xl overflow-hidden mb-4 bg-slate-100 border border-slate-100">
                    {course.capaUrl ? <img src={course.capaUrl} alt={course.nome} className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-700" /> : <div className="w-full h-full flex items-center justify-center text-slate-200"><BookOpen size={48} /></div>}
                    <div className="absolute top-2 left-2 flex gap-1">
                      <span className={`px-2 py-0.5 rounded-lg text-[9px] font-black uppercase ${course.status === 'ativo' ? 'bg-emerald-500 text-white shadow-lg shadow-emerald-500/20' : 'bg-slate-700 text-white'}`}>{course.status}</span>
                    </div>
                  </div>
                  <h3 className="font-black text-slate-900 text-base mb-1 line-clamp-2 leading-tight">{course.nome}</h3>
                  <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest mb-3">{course.tema || 'Tema não definido'}</p>
                  <div className="flex items-center gap-2 mb-4">
                    <span className="text-[9px] font-black uppercase tracking-widest px-2 py-0.5 bg-indigo-50 text-indigo-700 rounded-md border border-indigo-100">{course.publicoAlvo}</span>
                    <span className="text-[9px] font-black uppercase tracking-widest px-2 py-0.5 bg-slate-50 text-slate-500 rounded-md border border-slate-100">{course.cargaHoraria}</span>
                  </div>
                  <div className="mt-auto flex items-center justify-between text-[10px] text-slate-400 font-black uppercase tracking-[0.2em] pt-4 border-t border-slate-50 group-hover:text-indigo-600 transition-colors">
                    <div className="flex items-center gap-2"><Layout size={12} /><span>Gerenciar Matriz</span></div>
                    <ChevronRight size={14} className="group-hover:translate-x-1 transition-transform" />
                  </div>
                </div>
              </div>
            ))}
          </div>
        ) : (
          <div className="flex-1 flex flex-col items-center justify-center p-20 opacity-50"><BookOpen size={48} className="mb-4 text-slate-300" /><h3 className="text-slate-900 font-bold uppercase tracking-widest text-xs">Aguardando seu primeiro curso...</h3></div>
        )}
      </div>

      {/* Modal: Configurar Novo Curso */}
      {showCourseModal && (
        <div className="fixed inset-0 z-[110] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm animate-in fade-in duration-300">
          <div className="bg-white w-full max-w-2xl rounded-3xl shadow-2xl overflow-hidden animate-in zoom-in-95 duration-200 max-h-[90vh] flex flex-col">
            <div className="p-6 border-b border-slate-100 flex items-center justify-between bg-slate-50/30">
              <div className="flex items-center gap-3">
                <div className="bg-indigo-600 p-2 rounded-xl text-white shadow-lg shadow-indigo-100"><GraduationCap size={20} /></div>
                <div>
                  <h3 className="font-bold text-slate-900 text-lg">Configurar Novo Curso</h3>
                  <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest">Definição Estrutural Pedagógica</p>
                </div>
              </div>
              <button onClick={() => setShowCourseModal(false)} className="text-slate-400 hover:text-slate-600 p-2"><X size={20} /></button>
            </div>
            <form onSubmit={handleCreateCourse} className="p-8 space-y-6 overflow-y-auto">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className="space-y-4">
                  <div className="space-y-1.5">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Título do Curso</label>
                    <input required autoFocus value={courseForm.nome} onChange={e => setCourseForm({...courseForm, nome: e.target.value})} placeholder="Ex: Teologia Sistemática" className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-2xl text-sm outline-none focus:ring-2 focus:ring-indigo-500" />
                  </div>
                  <div className="space-y-1.5">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Professor Responsável</label>
                    <input required value={courseForm.professorResponsavel} onChange={e => setCourseForm({...courseForm, professorResponsavel: e.target.value})} className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-2xl text-sm outline-none focus:ring-2 focus:ring-indigo-500" />
                  </div>
                  <div className="grid grid-cols-2 gap-4">
                    <div className="space-y-1.5">
                      <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Carga Horária</label>
                      <input required value={courseForm.cargaHoraria} onChange={e => setCourseForm({...courseForm, cargaHoraria: e.target.value})} placeholder="Ex: 40h" className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-2xl text-sm outline-none focus:ring-2 focus:ring-indigo-500" />
                    </div>
                    <div className="space-y-1.5">
                      <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Público</label>
                      <select value={courseForm.publicoAlvo} onChange={e => setCourseForm({...courseForm, publicoAlvo: e.target.value as any})} className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-2xl text-sm outline-none focus:ring-2 focus:ring-indigo-500">
                        <option value="Geral">Geral</option>
                        <option value="Líderes">Líderes</option>
                        <option value="Obreiros">Obreiros</option>
                      </select>
                    </div>
                  </div>
                </div>
                <div className="space-y-4">
                  <div className="space-y-1.5">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Tema Principal</label>
                    <input value={courseForm.tema} onChange={e => setCourseForm({...courseForm, tema: e.target.value})} placeholder="Ex: História da Igreja" className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-2xl text-sm outline-none focus:ring-2 focus:ring-indigo-500" />
                  </div>
                  <div className="space-y-1.5">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Upload da Capa (Max 5MB)</label>
                    <div className="relative h-32 w-full bg-slate-50 border-2 border-dashed border-slate-200 rounded-2xl flex flex-col items-center justify-center p-4 hover:border-indigo-400 transition-all cursor-pointer">
                      <input type="file" accept="image/*" onChange={handleFileUpload} className="absolute inset-0 opacity-0 cursor-pointer" />
                      {courseForm.capaUrl ? (
                        <img src={courseForm.capaUrl} className="h-full w-full object-cover rounded-xl" />
                      ) : (
                        <>
                          <FileUp size={24} className="text-slate-400 mb-2" />
                          <span className="text-[10px] font-bold text-slate-400 uppercase">Clique para selecionar</span>
                        </>
                      )}
                    </div>
                  </div>
                </div>
              </div>
              <div className="space-y-1.5">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Descrição Longa (Ementa)</label>
                <textarea rows={3} value={courseForm.descricaoLonga} onChange={e => setCourseForm({...courseForm, descricaoLonga: e.target.value})} placeholder="Detalhe os objetivos e o cronograma do curso..." className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-2xl text-sm outline-none focus:ring-2 focus:ring-indigo-500 resize-none"></textarea>
              </div>
              <button type="submit" className="w-full bg-slate-900 text-white py-4 rounded-2xl font-black text-sm uppercase tracking-[0.2em] shadow-xl hover:bg-slate-800 transition-all active:scale-95">Finalizar Configuração</button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

// Helper component for shield icon
const ShieldCheck = ({ size, className }: { size: number, className: string }) => (
  <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className={className}>
    <path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z" /><path d="m9 12 2 2 4-4" />
  </svg>
);

export default ProfessorView;

import React from 'react';

export type UserRole = 'diretor' | 'professor' | 'aluno';

export interface User {
  uid: string;
  email: string | null;
  displayName: string | null;
  role: UserRole;
  photoURL?: string;
}

export interface Course {
  id: string;
  nome: string;
  tema?: string;
  descricao?: string;
  descricaoLonga?: string;
  professorResponsavel?: string;
  capaUrl?: string;
  cargaHoraria: string;
  publicoAlvo: 'Geral' | 'Líderes' | 'Obreiros';
  professorId: string;
  inscritos: number;
  status: 'ativo' | 'rascunho';
  createdAt: any;
}

export interface Module {
  id: string;
  nome: string;
  ordem: number;
  courseId: string;
  createdAt: any;
}

export interface Lesson {
  id: string;
  titulo: string;
  descricao?: string;
  videoUrl: string;
  materialUrl: string;
  ordem: number;
  createdAt: any;
}

export type MainView = 'dashboard' | 'professor' | 'alunos' | 'secretaria' | 'configuracoes';

export type ProfessorSubView = 
  | 'cursos' 
  | 'modulos' 
  | 'materiais' 
  | 'avaliacao' 
  | 'feedback' 
  | 'diario' 
  | 'relatorio' 
  | 'frequencia' 
  | 'live';

export interface NavItem {
  id: MainView;
  label: string;
  icon: React.ReactNode;
}

import React, { useState, useEffect, useRef } from 'react';
import { 
  collection, 
  query, 
  where, 
  getDocs, 
  addDoc, 
  deleteDoc,
  serverTimestamp, 
  orderBy,
  doc,
  getDoc,
  updateDoc
} from 'firebase/firestore';
import { db } from '../firebase';
import { Course, Module, Lesson, User, ProfessorSubView } from '../types';
import { 
  Search, 
  Filter, 
  BookOpen, 
  Plus, 
  Info, 
  X, 
  ChevronRight, 
  Play, 
  Pause,
  Volume2,
  VolumeX,
  Maximize,
  FileText, 
  MoreVertical, 
  ArrowLeft, 
  Layout, 
  Trash2, 
  AlertTriangle, 
  Layers, 
  Eye, 
  Clock, 
  Download, 
  CheckCircle, 
  Copy,
  Edit,
  GraduationCap,
  FileUp,
  ShieldCheck
} from 'lucide-react';

interface ProfessorViewProps {
  user: User;
  activeSub: ProfessorSubView;
  setActiveSub: (view: ProfessorSubView) => void;
}

const ProfessorView: React.FC<ProfessorViewProps> = ({ user, activeSub, setActiveSub }) => {
  const [myCourses, setMyCourses] = useState<Course[]>([]);
  const [loading, setLoading] = useState(true);
  const [selectedCourse, setSelectedCourse] = useState<Course | null>(null);
  const [modules, setModules] = useState<Module[]>([]);
  const [lessonsByModule, setLessonsByModule] = useState<Record<string, Lesson[]>>({});
  const [allModulesByCourse, setAllModulesByCourse] = useState<Record<string, {course: Course, modules: Module[]}>>({});
  const [openMenuId, setOpenMenuId] = useState<string | null>(null);

  // Modal States
  const [showCourseModal, setShowCourseModal] = useState(false);
  const [showModuleModal, setShowModuleModal] = useState(false);
  const [showLessonModal, setShowLessonModal] = useState(false);
  const [activeModuleId, setActiveModuleId] = useState<string | null>(null);

  // Preview States
  const [previewLesson, setPreviewLesson] = useState<Lesson | null>(null);
  const [countdown, setCountdown] = useState(15);
  const [isTimerFinished, setIsTimerFinished] = useState(false);
  const [isConcluded, setIsConcluded] = useState(false);

  // Custom Player States
  const [playerIsPlaying, setPlayerIsPlaying] = useState(false);
  const [playerVolume, setPlayerVolume] = useState(80);
  const [isMuted, setIsMuted] = useState(false);
  const iframeRef = useRef<HTMLIFrameElement>(null);
  const playerContainerRef = useRef<HTMLDivElement>(null);

  // Form States
  const [courseForm, setCourseForm] = useState({
    nome: '',
    tema: '',
    descricaoLonga: '',
    professorResponsavel: user.displayName || '',
    capaUrl: '',
    cargaHoraria: '',
    publicoAlvo: 'Geral' as const
  });
  const [moduleForm, setModuleForm] = useState({ nome: '' });
  const [lessonForm, setLessonForm] = useState({
    titulo: '',
    descricao: '',
    videoUrl: '',
    materialUrl: ''
  });

  const fetchMyCourses = async () => {
    setLoading(true);
    try {
      const q = query(collection(db, 'cursos'), where('professorId', '==', user.uid), orderBy('createdAt', 'desc'));
      const querySnapshot = await getDocs(q);
      const fetched: Course[] = [];
      querySnapshot.forEach((doc) => {
        fetched.push({ id: doc.id, ...doc.data() } as Course);
      });
      setMyCourses(fetched);
    } catch (error) {
      console.error("Erro ao carregar cursos:", error);
    } finally {
      setLoading(false);
    }
  };

  const fetchModules = async (courseId: string) => {
    try {
      const q = query(collection(db, 'cursos', courseId, 'modulos'), orderBy('ordem', 'asc'));
      const querySnapshot = await getDocs(q);
      const fetched: Module[] = [];
      querySnapshot.forEach((doc) => {
        fetched.push({ id: doc.id, ...doc.data(), courseId } as Module);
      });
      setModules(fetched);
      for (const mod of fetched) {
        fetchLessons(courseId, mod.id);
      }
    } catch (error) {
      console.error("Erro ao carregar módulos:", error);
    }
  };

  const fetchAllModules = async () => {
    setLoading(true);
    try {
      const grouped: Record<string, {course: Course, modules: Module[]}> = {};
      for (const course of myCourses) {
        const q = query(collection(db, 'cursos', course.id, 'modulos'), orderBy('ordem', 'asc'));
        const querySnapshot = await getDocs(q);
        const mods: Module[] = [];
        querySnapshot.forEach(d => mods.push({id: d.id, ...d.data(), courseId: course.id} as Module));
        grouped[course.id] = { course, modules: mods };
      }
      setAllModulesByCourse(grouped);
    } catch (error) { console.error(error); } finally { setLoading(false); }
  };

  const fetchLessons = async (courseId: string, moduleId: string) => {
    try {
      const q = query(collection(db, 'cursos', courseId, 'modulos', moduleId, 'aulas'), orderBy('ordem', 'asc'));
      const querySnapshot = await getDocs(q);
      const fetched: Lesson[] = [];
      querySnapshot.forEach((doc) => {
        fetched.push({ id: doc.id, ...doc.data() } as Lesson);
      });
      setLessonsByModule(prev => ({ ...prev, [moduleId]: fetched }));
    } catch (error) {
      console.error("Erro ao carregar aulas:", error);
    }
  };

  useEffect(() => {
    fetchMyCourses();
  }, [user.uid]);

  useEffect(() => {
    if (activeSub === 'modulos' && !selectedCourse) {
      fetchAllModules();
    }
  }, [activeSub, selectedCourse, myCourses]);

  // Video Security Lock Logic (Preserved)
  useEffect(() => {
    let timer: number | undefined;
    if (previewLesson && countdown > 0 && !isConcluded) {
      timer = window.setInterval(() => {
        setCountdown((prev) => {
          if (prev <= 1) {
            setIsTimerFinished(true);
            if (timer) clearInterval(timer);
            return 0;
          }
          return prev - 1;
        });
      }, 1000);
    }
    return () => { if (timer) clearInterval(timer); };
  }, [previewLesson, countdown, isConcluded]);

  // Video Commands Logic (Preserved)
  const sendPlayerCommand = (func: string, args: any[] = []) => {
    if (iframeRef.current && iframeRef.current.contentWindow) {
      iframeRef.current.contentWindow.postMessage(JSON.stringify({ event: 'command', func, args }), '*');
    }
  };

  const togglePlay = () => {
    if (playerIsPlaying) sendPlayerCommand('pauseVideo');
    else sendPlayerCommand('playVideo');
    setPlayerIsPlaying(!playerIsPlaying);
  };

  const toggleMute = () => {
    if (isMuted) { sendPlayerCommand('unMute'); sendPlayerCommand('setVolume', [playerVolume]); }
    else sendPlayerCommand('mute');
    setIsMuted(!isMuted);
  };

  const handleVolumeChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const vol = parseInt(e.target.value);
    setPlayerVolume(vol);
    if (!isMuted) sendPlayerCommand('setVolume', [vol]);
  };

  const toggleFullscreen = () => {
    if (playerContainerRef.current) {
      if (!document.fullscreenElement) playerContainerRef.current.requestFullscreen();
      else document.exitFullscreen();
    }
  };

  // Course & Module Actions
  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    if (file.size > 5 * 1024 * 1024) {
      alert("Arquivo excede 5MB. Reduza a imagem para continuar.");
      e.target.value = "";
      return;
    }
    const reader = new FileReader();
    reader.onloadend = () => setCourseForm(prev => ({ ...prev, capaUrl: reader.result as string }));
    reader.readAsDataURL(file);
  };

  const handleCreateCourse = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      await addDoc(collection(db, 'cursos'), {
        ...courseForm,
        professorId: user.uid,
        inscritos: 0,
        status: 'rascunho',
        createdAt: serverTimestamp()
      });
      setShowCourseModal(false);
      fetchMyCourses();
    } catch (error) { console.error(error); }
  };

  const handleDeleteCourse = async (courseId: string) => {
    if (!confirm("Excluir curso e todo o conteúdo vinculado?")) return;
    try {
      await deleteDoc(doc(db, 'cursos', courseId));
      fetchMyCourses();
      setOpenMenuId(null);
    } catch (error) { console.error(error); }
  };

  const handleDuplicateCourse = async (course: Course) => {
    try {
      const { id, ...data } = course;
      await addDoc(collection(db, 'cursos'), {
        ...data,
        nome: `${data.nome} (Cópia)`,
        createdAt: serverTimestamp(),
        inscritos: 0,
        status: 'rascunho'
      });
      fetchMyCourses();
      setOpenMenuId(null);
    } catch (error) { console.error(error); }
  };

  const handleCreateModule = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedCourse) return;
    try {
      await addDoc(collection(db, 'cursos', selectedCourse.id, 'modulos'), {
        nome: moduleForm.nome,
        ordem: modules.length + 1,
        courseId: selectedCourse.id,
        createdAt: serverTimestamp()
      });
      setShowModuleModal(false);
      setModuleForm({ nome: '' });
      fetchModules(selectedCourse.id);
    } catch (error) { console.error(error); }
  };

  const handleDeleteModule = async (moduleId: string, courseId: string) => {
    if (!confirm("Excluir este módulo permanentemente?")) return;
    try {
      await deleteDoc(doc(db, 'cursos', courseId, 'modulos', moduleId));
      if (selectedCourse) fetchModules(selectedCourse.id);
      else fetchAllModules();
    } catch (error) { console.error(error); }
  };

  const handleDuplicateModule = async (mod: Module) => {
    try {
      const { id, ...data } = mod;
      await addDoc(collection(db, 'cursos', mod.courseId, 'modulos'), {
        ...data,
        nome: `${data.nome} (Cópia)`,
        ordem: modules.length + 1,
        createdAt: serverTimestamp()
      });
      if (selectedCourse) fetchModules(selectedCourse.id);
      else fetchAllModules();
    } catch (error) { console.error(error); }
  };

  const handleCreateLesson = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedCourse || !activeModuleId) return;
    try {
      const count = lessonsByModule[activeModuleId]?.length || 0;
      await addDoc(collection(db, 'cursos', selectedCourse.id, 'modulos', activeModuleId, 'aulas'), {
        ...lessonForm,
        ordem: count + 1,
        createdAt: serverTimestamp()
      });
      setShowLessonModal(false);
      setLessonForm({ titulo: '', descricao: '', videoUrl: '', materialUrl: '' });
      fetchLessons(selectedCourse.id, activeModuleId);
    } catch (error) { console.error(error); }
  };

  const openCourseDetail = (course: Course) => {
    setSelectedCourse(course);
    setActiveSub('modulos');
    fetchModules(course.id);
  };

  const openPreview = (lesson: Lesson) => {
    setCountdown(15);
    setIsTimerFinished(false);
    setIsConcluded(false);
    setPlayerIsPlaying(false);
    setPreviewLesson(lesson);
  };

  const getEmbedUrl = (url: string) => {
    if (!url) return "";
    const ytRegex = /(?:https?:\/\/)?(?:www\.)?(?:youtube\.com\/(?:[^\/\n\s]+\/\S+\/|(?:v|e(?:mbed)?)\/|\S*?[?&]v=)|youtu\.be\/)([a-zA-Z0-9_-]{11})/;
    const ytMatch = url.match(ytRegex);
    if (ytMatch && ytMatch[1]) {
      return `https://www.youtube.com/embed/${ytMatch[1]}?modestbranding=1&rel=0&iv_load_policy=3&disablekb=1&controls=0&showinfo=0&enablejsapi=1&origin=${window.location.origin}`;
    }
    return url;
  };

  // UI: Grouped Modules View
  if (activeSub === 'modulos' && !selectedCourse) {
    return (
      <div className="space-y-6 animate-in fade-in duration-500">
        <header>
          <h1 className="text-2xl font-bold text-slate-900 tracking-tight">Módulos da Instituição</h1>
          <p className="text-slate-500 text-sm font-medium">Controle granular da estrutura acadêmica global.</p>
        </header>

        {loading ? (
          <div className="flex items-center justify-center p-20"><div className="h-8 w-8 animate-spin rounded-full border-4 border-indigo-600 border-t-transparent"></div></div>
        ) : Object.keys(allModulesByCourse).length === 0 ? (
          <div className="bg-white p-20 rounded-2xl border border-slate-200 text-center opacity-50">
            <Layers size={48} className="mx-auto mb-4 text-slate-300" />
            <p className="font-bold text-slate-900">Aguardando definição curricular...</p>
          </div>
        ) : (
          <div className="space-y-8">
            {Object.values(allModulesByCourse).map(({ course, modules }) => (
              <div key={course.id} className="bg-white rounded-2xl border border-slate-200 shadow-sm overflow-hidden">
                <div className="px-6 py-4 border-b border-slate-100 flex items-center justify-between bg-slate-50/50">
                  <div className="flex items-center gap-3">
                    <div className="bg-indigo-600 text-white p-1.5 rounded-lg"><BookOpen size={16} /></div>
                    <h2 className="text-sm font-bold text-slate-800 uppercase tracking-widest">{course.nome}</h2>
                  </div>
                  <span className="text-[10px] font-bold text-slate-400 uppercase">{modules.length} Módulos</span>
                </div>
                <div className="overflow-x-auto">
                  <table className="w-full text-left">
                    <thead className="bg-slate-50 text-[10px] font-black text-slate-400 uppercase tracking-tighter border-b border-slate-100">
                      <tr>
                        <th className="px-6 py-3 w-16">Ord.</th>
                        <th className="px-6 py-3">Módulo</th>
                        <th className="px-6 py-3 text-right">Ações de Gestão</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-100 text-sm">
                      {modules.map(mod => (
                        <tr key={mod.id} className="hover:bg-slate-50/50 transition-colors">
                          <td className="px-6 py-4 text-slate-400 font-bold">#{mod.ordem}</td>
                          <td className="px-6 py-4 font-semibold text-slate-900">{mod.nome}</td>
                          <td className="px-6 py-4">
                            <div className="flex items-center justify-end gap-1">
                              <button onClick={() => openCourseDetail(course)} className="p-2 text-indigo-600 hover:bg-indigo-50 rounded-lg transition-colors" title="Visualizar Matriz"><Eye size={16} /></button>
                              <button onClick={() => handleDuplicateModule(mod)} className="p-2 text-slate-400 hover:bg-slate-100 rounded-lg transition-colors" title="Duplicar"><Copy size={16} /></button>
                              <button onClick={() => handleDeleteModule(mod.id, course.id)} className="p-2 text-red-400 hover:bg-red-50 rounded-lg transition-colors" title="Excluir"><Trash2 size={16} /></button>
                            </div>
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>
    );
  }

  // UI: Course Matrix Detail
  if (activeSub === 'modulos' && selectedCourse) {
    return (
      <div className="space-y-6 animate-in fade-in duration-500">
        <header className="flex items-center justify-between gap-4">
          <div className="flex items-center gap-4">
            <button onClick={() => { setSelectedCourse(null); setActiveSub('cursos'); }} className="h-10 w-10 bg-white border border-slate-200 rounded-xl flex items-center justify-center text-slate-600 hover:bg-slate-50 transition-all shadow-sm"><ArrowLeft size={20} /></button>
            <div>
              <h1 className="text-2xl font-bold text-slate-900">{selectedCourse.nome}</h1>
              <p className="text-slate-500 text-sm font-medium">{selectedCourse.tema}</p>
            </div>
          </div>
          <button onClick={() => setShowModuleModal(true)} className="flex items-center gap-2 bg-indigo-600 text-white px-5 py-2.5 rounded-xl text-sm font-bold hover:bg-indigo-700 shadow-lg shadow-indigo-100">
            <Plus size={18} /> Novo Módulo
          </button>
        </header>

        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
          <div className="lg:col-span-2 space-y-4">
            <div className="bg-white rounded-2xl border border-slate-200 shadow-sm overflow-hidden">
              <div className="px-6 py-4 border-b border-slate-100 bg-slate-50/50"><h2 className="text-xs font-bold text-slate-800 uppercase tracking-widest">Estrutura Curricular</h2></div>
              <div className="p-4 space-y-4">
                {modules.map(mod => (
                  <div key={mod.id} className="border border-slate-100 rounded-xl overflow-hidden group">
                    <div className="px-4 py-3 border-b border-slate-100 flex items-center justify-between bg-white">
                      <h3 className="font-bold text-slate-800 text-sm">Módulo {mod.ordem}: {mod.nome}</h3>
                      <div className="flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                        <button onClick={() => { setActiveModuleId(mod.id); setShowLessonModal(true); }} className="p-1.5 text-indigo-600 hover:bg-indigo-50 rounded-lg"><Plus size={18} /></button>
                        <button onClick={() => handleDeleteModule(mod.id, selectedCourse.id)} className="p-1.5 text-slate-400 hover:text-red-500"><Trash2 size={18} /></button>
                      </div>
                    </div>
                    <div className="p-2 space-y-1">
                      {lessonsByModule[mod.id]?.map(lesson => (
                        <div key={lesson.id} className="flex items-center justify-between p-3 rounded-xl hover:bg-slate-50 transition-all group/lesson">
                          <div className="flex items-center gap-4">
                            <div className="p-2 bg-white border border-slate-100 text-indigo-600 rounded-lg"><Play size={12} fill="currentColor" /></div>
                            <span className="text-sm font-semibold text-slate-700">{lesson.titulo}</span>
                          </div>
                          <button onClick={() => openPreview(lesson)} className="p-1.5 text-indigo-600 hover:bg-indigo-50 rounded-lg opacity-0 group-hover/lesson:opacity-100 transition-all"><Eye size={16} /></button>
                        </div>
                      ))}
                    </div>
                  </div>
                ))}
              </div>
            </div>
          </div>
          <div className="bg-white p-5 rounded-2xl border border-slate-200 shadow-sm h-fit sticky top-24">
             <div className="aspect-video rounded-xl overflow-hidden mb-4 bg-slate-50 border border-slate-100">
               {selectedCourse.capaUrl ? <img src={selectedCourse.capaUrl} className="w-full h-full object-cover" /> : <div className="h-full flex items-center justify-center text-slate-200"><BookOpen size={48} /></div>}
             </div>
             <div className="space-y-4 text-xs">
                <div className="flex justify-between border-b border-slate-50 pb-2"><span className="text-slate-400 font-bold uppercase">Professor</span><span className="font-black text-slate-900">{selectedCourse.professorResponsavel}</span></div>
                <div className="flex justify-between border-b border-slate-50 pb-2"><span className="text-slate-400 font-bold uppercase">Carga</span><span className="font-black text-slate-900">{selectedCourse.cargaHoraria}</span></div>
                <div className="flex justify-between"><span className="text-slate-400 font-bold uppercase">Público</span><span className="font-black text-indigo-600">{selectedCourse.publicoAlvo}</span></div>
                {selectedCourse.descricaoLonga && <div className="pt-4 mt-4 border-t border-slate-100"><p className="text-slate-400 font-bold uppercase mb-2">Ementa</p><p className="text-slate-600 leading-relaxed italic">{selectedCourse.descricaoLonga}</p></div>}
             </div>
          </div>
        </div>

        {/* Modal Module/Lesson (Simplified for context) */}
        {showModuleModal && (
          <div className="fixed inset-0 z-[110] flex items-center justify-center p-4 bg-slate-900/40 backdrop-blur-sm">
            <div className="bg-white w-full max-w-md rounded-2xl shadow-2xl p-6">
              <h3 className="font-bold text-slate-900 mb-4">Novo Módulo</h3>
              <form onSubmit={handleCreateModule} className="space-y-4">
                <input required autoFocus value={moduleForm.nome} onChange={e => setModuleForm({nome: e.target.value})} placeholder="Título do Módulo" className="w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm" />
                <button type="submit" className="w-full bg-indigo-600 text-white py-3 rounded-xl font-bold text-sm">Criar Módulo</button>
              </form>
            </div>
          </div>
        )}

        {showLessonModal && (
          <div className="fixed inset-0 z-[110] flex items-center justify-center p-4 bg-slate-900/40 backdrop-blur-sm">
            <div className="bg-white w-full max-w-lg rounded-2xl shadow-2xl p-6">
              <h3 className="font-bold text-slate-900 mb-4">Adicionar Aula</h3>
              <form onSubmit={handleCreateLesson} className="space-y-4">
                <input required value={lessonForm.titulo} onChange={e => setLessonForm({...lessonForm, titulo: e.target.value})} placeholder="Título da Aula" className="w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm" />
                <textarea rows={2} value={lessonForm.descricao} onChange={e => setLessonForm({...lessonForm, descricao: e.target.value})} placeholder="Descrição/Resumo pedagógico" className="w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm resize-none"></textarea>
                <div className="grid grid-cols-2 gap-4">
                  <input value={lessonForm.videoUrl} onChange={e => setLessonForm({...lessonForm, videoUrl: e.target.value})} placeholder="URL YouTube" className="w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm" />
                  <input value={lessonForm.materialUrl} onChange={e => setLessonForm({...lessonForm, materialUrl: e.target.value})} placeholder="URL Material PDF" className="w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm" />
                </div>
                <button type="submit" className="w-full bg-indigo-600 text-white py-3 rounded-xl font-bold text-sm">Publicar Aula</button>
              </form>
            </div>
          </div>
        )}

        {/* Preview Modal: Pedagogical Layout (Security Lock Preserved) */}
        {previewLesson && (
          <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 bg-slate-900/80 backdrop-blur-md">
            <div className="bg-white w-full max-w-6xl h-[90vh] rounded-3xl shadow-2xl overflow-hidden flex flex-col">
              <div className="p-5 border-b border-slate-100 flex items-center justify-between bg-white">
                <div className="flex items-center gap-3"><div className="bg-indigo-600 p-2 rounded-xl text-white shadow-lg shadow-indigo-200"><Eye size={18} /></div><h3 className="font-bold text-slate-900">{previewLesson.titulo}</h3></div>
                <button onClick={() => setPreviewLesson(null)} className="px-4 py-2 bg-slate-100 hover:bg-slate-200 rounded-xl text-slate-600 text-xs font-bold transition-colors">Encerrar Aula</button>
              </div>

              <div className="flex-1 overflow-y-auto bg-slate-50/50 p-6 flex flex-col lg:flex-row gap-6">
                <div className="flex-[2] space-y-6">
                  {/* Player Container - Locked UI (NÃO ALTERAR) */}
                  <div ref={playerContainerRef} className="aspect-video bg-slate-900 rounded-2xl overflow-hidden shadow-2xl border-4 border-white relative group">
                    <iframe ref={iframeRef} width="100%" height="100%" src={getEmbedUrl(previewLesson.videoUrl)} frameBorder="0" allow="accelerometer; autoplay; encrypted-media; gyroscope" className="pointer-events-none"></iframe>
                    <div className="absolute inset-0 z-20 pointer-events-none flex flex-col justify-end">
                      {!playerIsPlaying && (
                        <div className="absolute inset-0 flex items-center justify-center bg-black/20 pointer-events-auto cursor-pointer" onClick={togglePlay}>
                          <div className="w-20 h-20 bg-white/10 backdrop-blur-xl border border-white/20 rounded-full flex items-center justify-center text-white"><Play size={40} fill="currentColor" /></div>
                        </div>
                      )}
                      <div className="p-4 bg-gradient-to-t from-black/80 to-transparent opacity-0 group-hover:opacity-100 transition-opacity pointer-events-auto">
                        <div className="flex items-center justify-between gap-6 px-4">
                          <div className="flex items-center gap-4">
                            <button onClick={togglePlay} className="text-white hover:text-indigo-400">{playerIsPlaying ? <Pause size={24} fill="currentColor" /> : <Play size={24} fill="currentColor" />}</button>
                            <div className="flex items-center gap-3"><button onClick={toggleMute} className="text-white">{(isMuted || playerVolume === 0) ? <VolumeX size={20} /> : <Volume2 size={20} />}</button><input type="range" min="0" max="100" value={isMuted ? 0 : playerVolume} onChange={handleVolumeChange} className="w-20 h-1.5 bg-white/20 rounded-full appearance-none accent-indigo-500" /></div>
                          </div>
                          <button onClick={toggleFullscreen} className="text-white hover:text-indigo-400"><Maximize size={20} /></button>
                        </div>
                      </div>
                    </div>
                  </div>
                  {/* New Pedagogical Description Layout */}
                  <div className="p-8 bg-white rounded-3xl border border-slate-200 shadow-sm space-y-3">
                    <h4 className="text-lg font-bold text-slate-900 flex items-center gap-2"><FileText size={20} className="text-indigo-600" /> Sobre esta Aula</h4>
                    <p className="text-sm text-slate-600 leading-relaxed whitespace-pre-wrap">{previewLesson.descricao || "Descrição não detalhada para este conteúdo pedagógico."}</p>
                  </div>
                </div>

                <div className="flex-1 space-y-4">
                  <div className="bg-white p-6 rounded-3xl border border-slate-200 shadow-sm h-fit">
                    <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-4">Engajamento da Turma</h4>
                    <div className="space-y-6">
                       <div className={`p-5 rounded-2xl border transition-all ${isConcluded ? 'bg-emerald-50 border-emerald-100' : 'bg-indigo-50 border-indigo-100'}`}>
                          <div className="flex items-center gap-3 mb-2"><Clock size={18} className={isConcluded ? 'text-emerald-600' : 'text-indigo-600 animate-pulse'} /><span className="text-xs font-bold">{isConcluded ? 'Engajamento Validado' : 'Acompanhamento Ativo'}</span></div>
                          <p className="text-[10px] text-slate-500">Mantenha o foco. O sistema validará sua presença ao final do cronômetro pedagógico.</p>
                       </div>
                       <div className="bg-slate-50 p-6 rounded-2xl text-center border border-slate-100">
                          {(!isTimerFinished && !isConcluded) ? (
                            <div className="space-y-1"><span className="text-4xl font-black text-slate-900 tabular-nums">{countdown}s</span><p className="text-[9px] font-bold text-slate-400 uppercase tracking-widest">Tempo para Conclusão</p></div>
                          ) : (
                            <div className="py-2 text-emerald-600 flex flex-col items-center gap-1"><CheckCircle size={24} /><span className="text-xs font-black uppercase">Requisito Satisfeito</span></div>
                          )}
                       </div>
                       <button disabled={!isTimerFinished || isConcluded} onClick={handleConcludeLesson} className={`w-full py-4 rounded-2xl font-bold text-sm shadow-lg ${isTimerFinished && !isConcluded ? 'bg-slate-900 text-white' : isConcluded ? 'bg-emerald-100 text-emerald-700' : 'bg-slate-100 text-slate-400 cursor-not-allowed'}`}>
                          {isConcluded ? 'Aula Concluída' : countdown > 0 ? `Aguarde ${countdown}s` : 'Confirmar Conclusão'}
                       </button>
                    </div>
                  </div>
                </div>
              </div>
            </div>
          </div>
        )}
      </div>
    );
  }

  // UI: Dashboard Courses List
  return (
    <div className="space-y-6 animate-in fade-in duration-500">
      <header className="flex flex-col sm:flex-row items-center justify-between gap-4">
        <div><h1 className="text-2xl font-bold text-slate-900 tracking-tight">Gestão Pedagógica</h1><p className="text-slate-500 text-sm font-medium">Controle de cursos, matrículas e matriz curricular.</p></div>
        <button onClick={() => setShowCourseModal(true)} className="flex items-center gap-2 bg-indigo-600 text-white px-5 py-3 rounded-xl text-sm font-bold hover:bg-indigo-700 transition-all shadow-lg shadow-indigo-100"><Plus size={18} /> Configurar Novo Curso</button>
      </header>

      <div className="bg-white rounded-2xl border border-slate-200 shadow-sm min-h-[400px] flex flex-col overflow-visible">
        <div className="p-4 border-b border-slate-100 flex items-center justify-between bg-slate-50/30">
          <div className="relative w-full max-w-xs"><Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={16} /><input type="text" placeholder="Localizar curso..." className="w-full pl-10 pr-4 py-2.5 bg-white border border-slate-200 rounded-lg text-xs" /></div>
        </div>

        {loading ? (
          <div className="flex-1 flex items-center justify-center"><div className="h-6 w-6 animate-spin rounded-full border-2 border-indigo-600 border-t-transparent"></div></div>
        ) : (
          <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6 p-6">
            {myCourses.map(course => (
              <div key={course.id} onClick={() => openCourseDetail(course)} className="border border-slate-200 p-4 rounded-3xl hover:shadow-xl hover:border-indigo-400 transition-all cursor-pointer group flex flex-col relative overflow-visible bg-white">
                <div className="absolute top-3 right-3 z-40">
                  <button onClick={(e) => { e.stopPropagation(); setOpenMenuId(openMenuId === course.id ? null : course.id); }} className="p-2 bg-white/90 backdrop-blur-sm rounded-xl border border-slate-200 text-slate-500"><MoreVertical size={16} /></button>
                  {openMenuId === course.id && (
                    <div className="absolute right-0 mt-2 w-40 bg-white rounded-2xl shadow-2xl border border-slate-100 z-50 overflow-hidden text-xs font-bold">
                      <button onClick={(e) => {e.stopPropagation(); handleDuplicateCourse(course)}} className="w-full px-4 py-3 text-left hover:bg-slate-50 flex items-center gap-2"><Copy size={14} /> Duplicar</button>
                      <button onClick={(e) => {e.stopPropagation(); handleDeleteCourse(course.id)}} className="w-full px-4 py-3 text-left hover:bg-red-50 text-red-500 flex items-center gap-2"><Trash2 size={14} /> Excluir</button>
                    </div>
                  )}
                </div>
                <div className="relative h-40 rounded-2xl overflow-hidden mb-4 bg-slate-50 border border-slate-100">
                  {course.capaUrl ? <img src={course.capaUrl} className="w-full h-full object-cover group-hover:scale-105 transition-all duration-700" /> : <div className="h-full flex items-center justify-center text-slate-200"><BookOpen size={48} /></div>}
                  <div className="absolute top-2 left-2"><span className={`px-2 py-0.5 rounded-lg text-[9px] font-black uppercase ${course.status === 'ativo' ? 'bg-emerald-500 text-white' : 'bg-slate-700 text-white'}`}>{course.status}</span></div>
                </div>
                <h3 className="font-black text-slate-900 text-base leading-tight mb-1">{course.nome}</h3>
                <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest mb-3">{course.tema || 'Sem tema definido'}</p>
                <div className="mt-auto pt-4 border-t border-slate-50 flex items-center justify-between text-[10px] text-slate-400 font-black uppercase tracking-widest group-hover:text-indigo-600 transition-colors">
                  <div className="flex items-center gap-2"><Layout size={12} /><span>Gerenciar Matriz</span></div>
                  <ChevronRight size={14} className="group-hover:translate-x-1 transition-all" />
                </div>
              </div>
            ))}
          </div>
        )}
      </div>

      {/* Modal: Configurar Novo Curso (Robust) */}
      {showCourseModal && (
        <div className="fixed inset-0 z-[110] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm">
          <div className="bg-white w-full max-w-2xl rounded-3xl shadow-2xl overflow-hidden flex flex-col max-h-[90vh]">
            <div className="p-6 border-b border-slate-100 flex items-center justify-between bg-slate-50/30">
              <div className="flex items-center gap-3"><div className="bg-indigo-600 p-2 rounded-xl text-white"><GraduationCap size={20} /></div><h3 className="font-bold text-slate-900">Configurar Novo Curso</h3></div>
              <button onClick={() => setShowCourseModal(false)} className="text-slate-400 hover:text-slate-600"><X size={20} /></button>
            </div>
            <form onSubmit={handleCreateCourse} className="p-8 space-y-6 overflow-y-auto">
              <div className="grid grid-cols-2 gap-6">
                <div className="space-y-4">
                  <div className="space-y-1"><label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Título do Curso</label><input required autoFocus value={courseForm.nome} onChange={e => setCourseForm({...courseForm, nome: e.target.value})} className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-2xl text-sm outline-none focus:ring-2 focus:ring-indigo-500" /></div>
                  <div className="space-y-1"><label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Professor Responsável</label><input required value={courseForm.professorResponsavel} onChange={e => setCourseForm({...courseForm, professorResponsavel: e.target.value})} className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-2xl text-sm outline-none focus:ring-2 focus:ring-indigo-500" /></div>
                  <div className="grid grid-cols-2 gap-4">
                    <div className="space-y-1"><label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Carga</label><input required value={courseForm.cargaHoraria} onChange={e => setCourseForm({...courseForm, cargaHoraria: e.target.value})} placeholder="Ex: 40h" className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-2xl text-sm outline-none" /></div>
                    <div className="space-y-1"><label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Público</label><select value={courseForm.publicoAlvo} onChange={e => setCourseForm({...courseForm, publicoAlvo: e.target.value as any})} className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-2xl text-sm"><option value="Geral">Geral</option><option value="Líderes">Líderes</option><option value="Obreiros">Obreiros</option></select></div>
                  </div>
                </div>
                <div className="space-y-4">
                  <div className="space-y-1"><label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Tema Principal</label><input value={courseForm.tema} onChange={e => setCourseForm({...courseForm, tema: e.target.value})} placeholder="Ex: Teologia Bíblica" className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-2xl text-sm outline-none" /></div>
                  <div className="space-y-1">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Upload da Capa (Max 5MB)</label>
                    <div className="relative h-32 w-full bg-slate-50 border-2 border-dashed border-slate-200 rounded-2xl flex flex-col items-center justify-center p-4 hover:border-indigo-400 cursor-pointer">
                      <input type="file" accept="image/*" onChange={handleFileUpload} className="absolute inset-0 opacity-0 cursor-pointer" />
                      {courseForm.capaUrl ? <img src={courseForm.capaUrl} className="h-full w-full object-cover rounded-xl" /> : <><FileUp size={24} className="text-slate-400 mb-2" /><span className="text-[9px] font-bold text-slate-400 uppercase">Selecionar Imagem</span></>}
                    </div>
                  </div>
                </div>
              </div>
              <div className="space-y-1"><label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Ementa do Curso (Descrição Longa)</label><textarea rows={3} value={courseForm.descricaoLonga} onChange={e => setCourseForm({...courseForm, descricaoLonga: e.target.value})} className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-2xl text-sm outline-none resize-none"></textarea></div>
              <button type="submit" className="w-full bg-slate-900 text-white py-4 rounded-2xl font-black text-sm uppercase tracking-widest hover:bg-slate-800 transition-all active:scale-95">Finalizar Configuração</button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default ProfessorView;

import React, { useState, useEffect, useRef } from 'react';
import { 
  collection, 
  query, 
  where, 
  getDocs, 
  addDoc, 
  deleteDoc,
  serverTimestamp, 
  orderBy,
  doc,
  getDoc,
  updateDoc
} from 'firebase/firestore';
import { db } from '../firebase';
import { Course, Module, Lesson, User, ProfessorSubView } from '../types';
import { 
  Search, 
  Filter, 
  BookOpen, 
  Plus, 
  Info, 
  X, 
  ChevronRight, 
  Play, 
  Pause,
  Volume2,
  VolumeX,
  Maximize,
  FileText, 
  MoreVertical, 
  ArrowLeft, 
  Layout, 
  Trash2, 
  AlertTriangle, 
  Layers, 
  Eye, 
  Clock, 
  Download, 
  CheckCircle, 
  Copy,
  Edit,
  GraduationCap,
  FileUp,
  ShieldCheck
} from 'lucide-react';

interface ProfessorViewProps {
  user: User;
  activeSub: ProfessorSubView;
  setActiveSub: (view: ProfessorSubView) => void;
}

const ProfessorView: React.FC<ProfessorViewProps> = ({ user, activeSub, setActiveSub }) => {
  const [myCourses, setMyCourses] = useState<Course[]>([]);
  const [loading, setLoading] = useState(true);
  const [selectedCourse, setSelectedCourse] = useState<Course | null>(null);
  const [modules, setModules] = useState<Module[]>([]);
  const [lessonsByModule, setLessonsByModule] = useState<Record<string, Lesson[]>>({});
  const [allModulesByCourse, setAllModulesByCourse] = useState<Record<string, {course: Course, modules: Module[]}>>({});
  const [openMenuId, setOpenMenuId] = useState<string | null>(null);

  // Modal States
  const [showCourseModal, setShowCourseModal] = useState(false);
  const [showModuleModal, setShowModuleModal] = useState(false);
  const [showLessonModal, setShowLessonModal] = useState(false);
  const [activeModuleId, setActiveModuleId] = useState<string | null>(null);

  // Preview States
  const [previewLesson, setPreviewLesson] = useState<Lesson | null>(null);
  const [countdown, setCountdown] = useState(15);
  const [isTimerFinished, setIsTimerFinished] = useState(false);
  const [isConcluded, setIsConcluded] = useState(false);

  // Custom Player States
  const [playerIsPlaying, setPlayerIsPlaying] = useState(false);
  const [playerVolume, setPlayerVolume] = useState(80);
  const [isMuted, setIsMuted] = useState(false);
  const iframeRef = useRef<HTMLIFrameElement>(null);
  const playerContainerRef = useRef<HTMLDivElement>(null);

  // Form States
  const [courseForm, setCourseForm] = useState({
    nome: '',
    tema: '',
    descricaoLonga: '',
    professorResponsavel: user.displayName || '',
    capaUrl: '',
    cargaHoraria: '',
    publicoAlvo: 'Geral' as const
  });
  const [moduleForm, setModuleForm] = useState({ nome: '' });
  const [lessonForm, setLessonForm] = useState({
    titulo: '',
    descricao: '',
    videoUrl: '',
    materialUrl: ''
  });

  const fetchMyCourses = async () => {
    setLoading(true);
    try {
      const q = query(collection(db, 'cursos'), where('professorId', '==', user.uid), orderBy('createdAt', 'desc'));
      const querySnapshot = await getDocs(q);
      const fetched: Course[] = [];
      querySnapshot.forEach((doc) => {
        fetched.push({ id: doc.id, ...doc.data() } as Course);
      });
      setMyCourses(fetched);
    } catch (error) {
      console.error("Erro ao carregar cursos:", error);
    } finally {
      setLoading(false);
    }
  };

  const fetchModules = async (courseId: string) => {
    try {
      const q = query(collection(db, 'cursos', courseId, 'modulos'), orderBy('ordem', 'asc'));
      const querySnapshot = await getDocs(q);
      const fetched: Module[] = [];
      querySnapshot.forEach((doc) => {
        fetched.push({ id: doc.id, ...doc.data(), courseId } as Module);
      });
      setModules(fetched);
      for (const mod of fetched) {
        fetchLessons(courseId, mod.id);
      }
    } catch (error) {
      console.error("Erro ao carregar módulos:", error);
    }
  };

  const fetchAllModules = async () => {
    setLoading(true);
    try {
      const grouped: Record<string, {course: Course, modules: Module[]}> = {};
      for (const course of myCourses) {
        const q = query(collection(db, 'cursos', course.id, 'modulos'), orderBy('ordem', 'asc'));
        const querySnapshot = await getDocs(q);
        const mods: Module[] = [];
        querySnapshot.forEach(d => mods.push({id: d.id, ...d.data(), courseId: course.id} as Module));
        grouped[course.id] = { course, modules: mods };
      }
      setAllModulesByCourse(grouped);
    } catch (error) { console.error(error); } finally { setLoading(false); }
  };

  const fetchLessons = async (courseId: string, moduleId: string) => {
    try {
      const q = query(collection(db, 'cursos', courseId, 'modulos', moduleId, 'aulas'), orderBy('ordem', 'asc'));
      const querySnapshot = await getDocs(q);
      const fetched: Lesson[] = [];
      querySnapshot.forEach((doc) => {
        fetched.push({ id: doc.id, ...doc.data() } as Lesson);
      });
      setLessonsByModule(prev => ({ ...prev, [moduleId]: fetched }));
    } catch (error) {
      console.error("Erro ao carregar aulas:", error);
    }
  };

  useEffect(() => {
    fetchMyCourses();
  }, [user.uid]);

  useEffect(() => {
    if (activeSub === 'modulos' && !selectedCourse) {
      fetchAllModules();
    }
  }, [activeSub, selectedCourse, myCourses]);

  // Video Security Lock Logic (Preserved)
  useEffect(() => {
    let timer: number | undefined;
    if (previewLesson && countdown > 0 && !isConcluded) {
      timer = window.setInterval(() => {
        setCountdown((prev) => {
          if (prev <= 1) {
            setIsTimerFinished(true);
            if (timer) clearInterval(timer);
            return 0;
          }
          return prev - 1;
        });
      }, 1000);
    }
    return () => { if (timer) clearInterval(timer); };
  }, [previewLesson, countdown, isConcluded]);

  // Video Commands Logic (Preserved)
  const sendPlayerCommand = (func: string, args: any[] = []) => {
    if (iframeRef.current && iframeRef.current.contentWindow) {
      iframeRef.current.contentWindow.postMessage(JSON.stringify({ event: 'command', func, args }), '*');
    }
  };

  const togglePlay = () => {
    if (playerIsPlaying) sendPlayerCommand('pauseVideo');
    else sendPlayerCommand('playVideo');
    setPlayerIsPlaying(!playerIsPlaying);
  };

  const toggleMute = () => {
    if (isMuted) { sendPlayerCommand('unMute'); sendPlayerCommand('setVolume', [playerVolume]); }
    else sendPlayerCommand('mute');
    setIsMuted(!isMuted);
  };

  const handleVolumeChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const vol = parseInt(e.target.value);
    setPlayerVolume(vol);
    if (!isMuted) sendPlayerCommand('setVolume', [vol]);
  };

  const toggleFullscreen = () => {
    if (playerContainerRef.current) {
      if (!document.fullscreenElement) playerContainerRef.current.requestFullscreen();
      else document.exitFullscreen();
    }
  };

  // Course & Module Actions
  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    if (file.size > 5 * 1024 * 1024) {
      alert("Arquivo excede 5MB. Reduza a imagem para continuar.");
      e.target.value = "";
      return;
    }
    const reader = new FileReader();
    reader.onloadend = () => setCourseForm(prev => ({ ...prev, capaUrl: reader.result as string }));
    reader.readAsDataURL(file);
  };

  const handleCreateCourse = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      await addDoc(collection(db, 'cursos'), {
        ...courseForm,
        professorId: user.uid,
        inscritos: 0,
        status: 'rascunho',
        createdAt: serverTimestamp()
      });
      setShowCourseModal(false);
      fetchMyCourses();
    } catch (error) { console.error(error); }
  };

  const handleDeleteCourse = async (courseId: string) => {
    if (!confirm("Excluir curso e todo o conteúdo vinculado?")) return;
    try {
      await deleteDoc(doc(db, 'cursos', courseId));
      fetchMyCourses();
      setOpenMenuId(null);
    } catch (error) { console.error(error); }
  };

  const handleDuplicateCourse = async (course: Course) => {
    try {
      const { id, ...data } = course;
      await addDoc(collection(db, 'cursos'), {
        ...data,
        nome: `${data.nome} (Cópia)`,
        createdAt: serverTimestamp(),
        inscritos: 0,
        status: 'rascunho'
      });
      fetchMyCourses();
      setOpenMenuId(null);
    } catch (error) { console.error(error); }
  };

  const handleCreateModule = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedCourse) return;
    try {
      await addDoc(collection(db, 'cursos', selectedCourse.id, 'modulos'), {
        nome: moduleForm.nome,
        ordem: modules.length + 1,
        courseId: selectedCourse.id,
        createdAt: serverTimestamp()
      });
      setShowModuleModal(false);
      setModuleForm({ nome: '' });
      fetchModules(selectedCourse.id);
    } catch (error) { console.error(error); }
  };

  const handleDeleteModule = async (moduleId: string, courseId: string) => {
    if (!confirm("Excluir este módulo permanentemente?")) return;
    try {
      await deleteDoc(doc(db, 'cursos', courseId, 'modulos', moduleId));
      if (selectedCourse) fetchModules(selectedCourse.id);
      else fetchAllModules();
    } catch (error) { console.error(error); }
  };

  const handleDuplicateModule = async (mod: Module) => {
    try {
      const { id, ...data } = mod;
      await addDoc(collection(db, 'cursos', mod.courseId, 'modulos'), {
        ...data,
        nome: `${data.nome} (Cópia)`,
        ordem: modules.length + 1,
        createdAt: serverTimestamp()
      });
      if (selectedCourse) fetchModules(selectedCourse.id);
      else fetchAllModules();
    } catch (error) { console.error(error); }
  };

  const handleCreateLesson = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedCourse || !activeModuleId) return;
    try {
      const count = lessonsByModule[activeModuleId]?.length || 0;
      await addDoc(collection(db, 'cursos', selectedCourse.id, 'modulos', activeModuleId, 'aulas'), {
        ...lessonForm,
        ordem: count + 1,
        createdAt: serverTimestamp()
      });
      setShowLessonModal(false);
      setLessonForm({ titulo: '', descricao: '', videoUrl: '', materialUrl: '' });
      fetchLessons(selectedCourse.id, activeModuleId);
    } catch (error) { console.error(error); }
  };

  const openCourseDetail = (course: Course) => {
    setSelectedCourse(course);
    setActiveSub('modulos');
    fetchModules(course.id);
  };

  const openPreview = (lesson: Lesson) => {
    setCountdown(15);
    setIsTimerFinished(false);
    setIsConcluded(false);
    setPlayerIsPlaying(false);
    setPreviewLesson(lesson);
  };

  // Added missing handleConcludeLesson function
  const handleConcludeLesson = () => {
    setIsConcluded(true);
  };

  const getEmbedUrl = (url: string) => {
    if (!url) return "";
    const ytRegex = /(?:https?:\/\/)?(?:www\.)?(?:youtube\.com\/(?:[^\/\n\s]+\/\S+\/|(?:v|e(?:mbed)?)\/|\S*?[?&]v=)|youtu\.be\/)([a-zA-Z0-9_-]{11})/;
    const ytMatch = url.match(ytRegex);
    if (ytMatch && ytMatch[1]) {
      return `https://www.youtube.com/embed/${ytMatch[1]}?modestbranding=1&rel=0&iv_load_policy=3&disablekb=1&controls=0&showinfo=0&enablejsapi=1&origin=${window.location.origin}`;
    }
    return url;
  };

  // UI: Grouped Modules View
  if (activeSub === 'modulos' && !selectedCourse) {
    return (
      <div className="space-y-6 animate-in fade-in duration-500">
        <header>
          <h1 className="text-2xl font-bold text-slate-900 tracking-tight">Módulos da Instituição</h1>
          <p className="text-slate-500 text-sm font-medium">Controle granular da estrutura acadêmica global.</p>
        </header>

        {loading ? (
          <div className="flex items-center justify-center p-20"><div className="h-8 w-8 animate-spin rounded-full border-4 border-indigo-600 border-t-transparent"></div></div>
        ) : Object.keys(allModulesByCourse).length === 0 ? (
          <div className="bg-white p-20 rounded-2xl border border-slate-200 text-center opacity-50">
            <Layers size={48} className="mx-auto mb-4 text-slate-300" />
            <p className="font-bold text-slate-900">Aguardando definição curricular...</p>
          </div>
        ) : (
          <div className="space-y-8">
            {Object.values(allModulesByCourse).map(({ course, modules }) => (
              <div key={course.id} className="bg-white rounded-2xl border border-slate-200 shadow-sm overflow-hidden">
                <div className="px-6 py-4 border-b border-slate-100 flex items-center justify-between bg-slate-50/50">
                  <div className="flex items-center gap-3">
                    <div className="bg-indigo-600 text-white p-1.5 rounded-lg"><BookOpen size={16} /></div>
                    <h2 className="text-sm font-bold text-slate-800 uppercase tracking-widest">{course.nome}</h2>
                  </div>
                  <span className="text-[10px] font-bold text-slate-400 uppercase">{modules.length} Módulos</span>
                </div>
                <div className="overflow-x-auto">
                  <table className="w-full text-left">
                    <thead className="bg-slate-50 text-[10px] font-black text-slate-400 uppercase tracking-tighter border-b border-slate-100">
                      <tr>
                        <th className="px-6 py-3 w-16">Ord.</th>
                        <th className="px-6 py-3">Módulo</th>
                        <th className="px-6 py-3 text-right">Ações de Gestão</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-100 text-sm">
                      {modules.map(mod => (
                        <tr key={mod.id} className="hover:bg-slate-50/50 transition-colors">
                          <td className="px-6 py-4 text-slate-400 font-bold">#{mod.ordem}</td>
                          <td className="px-6 py-4 font-semibold text-slate-900">{mod.nome}</td>
                          <td className="px-6 py-4">
                            <div className="flex items-center justify-end gap-1">
                              <button onClick={() => openCourseDetail(course)} className="p-2 text-indigo-600 hover:bg-indigo-50 rounded-lg transition-colors" title="Visualizar Matriz"><Eye size={16} /></button>
                              <button onClick={() => handleDuplicateModule(mod)} className="p-2 text-slate-400 hover:bg-slate-100 rounded-lg transition-colors" title="Duplicar"><Copy size={16} /></button>
                              <button onClick={() => handleDeleteModule(mod.id, course.id)} className="p-2 text-red-400 hover:bg-red-50 rounded-lg transition-colors" title="Excluir"><Trash2 size={16} /></button>
                            </div>
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>
    );
  }

  // UI: Course Matrix Detail
  if (activeSub === 'modulos' && selectedCourse) {
    return (
      <div className="space-y-6 animate-in fade-in duration-500">
        <header className="flex items-center justify-between gap-4">
          <div className="flex items-center gap-4">
            <button onClick={() => { setSelectedCourse(null); setActiveSub('cursos'); }} className="h-10 w-10 bg-white border border-slate-200 rounded-xl flex items-center justify-center text-slate-600 hover:bg-slate-50 transition-all shadow-sm"><ArrowLeft size={20} /></button>
            <div>
              <h1 className="text-2xl font-bold text-slate-900">{selectedCourse.nome}</h1>
              <p className="text-slate-500 text-sm font-medium">{selectedCourse.tema}</p>
            </div>
          </div>
          <button onClick={() => setShowModuleModal(true)} className="flex items-center gap-2 bg-indigo-600 text-white px-5 py-2.5 rounded-xl text-sm font-bold hover:bg-indigo-700 shadow-lg shadow-indigo-100">
            <Plus size={18} /> Novo Módulo
          </button>
