                        </div>
                        <p className="text-[10px] text-slate-500 leading-relaxed font-medium">
                          {isConcluded 
                            ? 'Excelente! Você completou os requisitos desta aula.' 
                            : 'Falta pouco! Assista ao conteúdo completo para liberar sua confirmação de presença.'}
                        </p>
                      </div>

                      <div className="bg-slate-50 p-6 rounded-2xl text-center border border-slate-100">
                        {(!isTimerFinished && !isConcluded) ? (
                          <div className="space-y-2">
                            <span className="text-4xl font-black text-slate-900 tabular-nums tracking-tighter">{countdown}s</span>
                            <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Tempo para Validar</p>
                          </div>
