        <button 
          onClick={() => setShowCourseModal(true)}
          className="flex items-center justify-center gap-2 bg-indigo-600 text-white px-5 py-2.5 rounded-xl text-sm font-bold hover:bg-indigo-700 transition-all shadow-lg"
        >
          <Plus size={18} />
          Configurar Novo Curso
        </button>
      </header>

      <div className="bg-white rounded-2xl border border-slate-200 shadow-sm min-h-[400px] flex flex-col overflow-hidden">
