              <div className="pt-2">
                <button 
                  type="submit" 
                  className="w-full bg-slate-900 text-white py-4 rounded-2xl font-black text-sm uppercase tracking-[0.2em] shadow-xl shadow-slate-200 hover:bg-slate-800 transition-all active:scale-[0.98]"
                >
                  Finalizar e Criar Curso
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default ProfessorView;

import React from 'react';

export type UserRole = 'diretor' | 'professor' | 'aluno';

export interface User {
  uid: string;
  email: string | null;
  displayName: string | null;
  role: UserRole;
  photoURL?: string;
}

export interface Course {
  id: string;
  nome: string;
  tema?: string;
  descricao?: string;
  descricaoLonga?: string;
  professorResponsavel?: string;
  capaUrl?: string;
  cargaHoraria: string;
  publicoAlvo: 'Geral' | 'Líderes' | 'Obreiros';
  professorId: string;
  inscritos: number;
  status: 'ativo' | 'rascunho';
  createdAt: any;
}

export interface Module {
  id: string;
  nome: string;
  ordem: number;
  courseId: string;
  createdAt: any;
}

export interface Lesson {
  id: string;
  titulo: string;
  descricao?: string;
  videoUrl: string;
  materialUrl: string;
  ordem: number;
  createdAt: any;
}

export type MainView = 'dashboard' | 'professor' | 'alunos' | 'secretaria' | 'configuracoes';

export type ProfessorSubView = 
  | 'cursos' 
  | 'modulos' 
  | 'materiais' 
  | 'avaliacao' 
  | 'feedback' 
  | 'diario' 
  | 'relatorio' 
  | 'frequencia' 
  | 'live';

export interface NavItem {
  id: MainView;
  label: string;
  icon: React.ReactNode;
}

import React, { useState, useEffect, useRef } from 'react';
import { 
  collection, 
  query, 
  where, 
  getDocs, 
  addDoc, 
  deleteDoc,
  serverTimestamp, 
  orderBy,
  doc,
  getDoc,
  updateDoc
} from 'firebase/firestore';
import { db } from '../firebase';
import { Course, Module, Lesson, User, ProfessorSubView } from '../types';
import { 
  Search, 
  Filter, 
  BookOpen, 
  Plus, 
  Info, 
  X, 
  ChevronRight, 
  Play, 
  Pause,
  Volume2,
  VolumeX,
  Maximize,
  FileText, 
  MoreVertical, 
  ArrowLeft, 
  Layout, 
  Trash2, 
  AlertTriangle, 
  Layers, 
  Eye, 
  Clock, 
  Download, 
  CheckCircle, 
  Copy,
  Edit,
  GraduationCap,
  FileUp,
  ShieldCheck
} from 'lucide-react';

interface ProfessorViewProps {
  user: User;
  activeSub: ProfessorSubView;
  setActiveSub: (view: ProfessorSubView) => void;
}

const ProfessorView: React.FC<ProfessorViewProps> = ({ user, activeSub, setActiveSub }) => {
  const [myCourses, setMyCourses] = useState<Course[]>([]);
  const [loading, setLoading] = useState(true);
  const [selectedCourse, setSelectedCourse] = useState<Course | null>(null);
  const [modules, setModules] = useState<Module[]>([]);
  const [lessonsByModule, setLessonsByModule] = useState<Record<string, Lesson[]>>({});
  const [allModulesGrouped, setAllModulesGrouped] = useState<Record<string, { course: Course, modules: Module[] }>>({});
  const [openMenuId, setOpenMenuId] = useState<string | null>(null);

  // Modal States
  const [showCourseModal, setShowCourseModal] = useState(false);
  const [showModuleModal, setShowModuleModal] = useState(false);
  const [showLessonModal, setShowLessonModal] = useState(false);
  const [activeModuleId, setActiveModuleId] = useState<string | null>(null);

  // Preview States
  const [previewLesson, setPreviewLesson] = useState<Lesson | null>(null);
  const [countdown, setCountdown] = useState(15);
  const [isTimerFinished, setIsTimerFinished] = useState(false);
  const [isConcluded, setIsConcluded] = useState(false);

  // Custom Player States
  const [playerIsPlaying, setPlayerIsPlaying] = useState(false);
  const [playerVolume, setPlayerVolume] = useState(80);
  const [isMuted, setIsMuted] = useState(false);
  const iframeRef = useRef<HTMLIFrameElement>(null);
  const playerContainerRef = useRef<HTMLDivElement>(null);

  // Form States
  const [courseForm, setCourseForm] = useState({
    nome: '',
    tema: '',
    professorResponsavel: user.displayName || '',
    descricaoLonga: '',
    capaUrl: '',
    cargaHoraria: '',
    publicoAlvo: 'Geral' as const
  });
  const [moduleForm, setModuleForm] = useState({ nome: '' });
  const [lessonForm, setLessonForm] = useState({
    titulo: '',
    descricao: '',
    videoUrl: '',
    materialUrl: ''
  });

  const fetchMyCourses = async () => {
    setLoading(true);
    try {
      const q = query(collection(db, 'cursos'), where('professorId', '==', user.uid), orderBy('createdAt', 'desc'));
      const querySnapshot = await getDocs(q);
      const fetched: Course[] = [];
      querySnapshot.forEach((doc) => {
        fetched.push({ id: doc.id, ...doc.data() } as Course);
      });
      setMyCourses(fetched);
    } catch (error) {
      console.error("Erro ao carregar seus cursos:", error);
    } finally {
      setLoading(false);
    }
  };

  const fetchModulesForCourse = async (courseId: string) => {
    const q = query(collection(db, 'cursos', courseId, 'modulos'), orderBy('ordem', 'asc'));
    const querySnapshot = await getDocs(q);
    const fetched: Module[] = [];
    querySnapshot.forEach((doc) => {
      fetched.push({ id: doc.id, ...doc.data(), courseId } as Module);
    });
    return fetched;
  };

  const fetchAllModulesGrouped = async () => {
    setLoading(true);
    try {
      const grouped: Record<string, { course: Course, modules: Module[] }> = {};
      for (const course of myCourses) {
        const mods = await fetchModulesForCourse(course.id);
        grouped[course.id] = { course, modules: mods };
      }
      setAllModulesGrouped(grouped);
    } catch (error) {
      console.error("Erro ao agrupar módulos:", error);
    } finally {
      setLoading(false);
    }
  };

  const fetchLessons = async (courseId: string, moduleId: string) => {
    try {
      const q = query(collection(db, 'cursos', courseId, 'modulos', moduleId, 'aulas'), orderBy('ordem', 'asc'));
      const querySnapshot = await getDocs(q);
      const fetched: Lesson[] = [];
      querySnapshot.forEach((doc) => {
        fetched.push({ id: doc.id, ...doc.data() } as Lesson);
      });
      setLessonsByModule(prev => ({ ...prev, [moduleId]: fetched }));
    } catch (error) {
      console.error("Erro ao carregar aulas:", error);
    }
  };

  useEffect(() => {
    fetchMyCourses();
  }, [user.uid]);

  useEffect(() => {
    if (activeSub === 'modulos' && !selectedCourse) {
      fetchAllModulesGrouped();
    }
  }, [activeSub, selectedCourse, myCourses]);

  // PRESERVE: 15s LOCK LOGIC
  useEffect(() => {
    let timer: number | undefined;
    if (previewLesson && countdown > 0 && !isConcluded) {
      timer = window.setInterval(() => {
        setCountdown((prev) => {
          if (prev <= 1) {
            setIsTimerFinished(true);
            if (timer) clearInterval(timer);
            return 0;
          }
          return prev - 1;
        });
      }, 1000);
    }
    return () => { if (timer) clearInterval(timer); };
  }, [previewLesson, countdown, isConcluded]);

  // PRESERVE: PLAYER COMMANDS
  const sendPlayerCommand = (func: string, args: any[] = []) => {
    if (iframeRef.current && iframeRef.current.contentWindow) {
      iframeRef.current.contentWindow.postMessage(
        JSON.stringify({ event: 'command', func, args }), 
        '*'
      );
    }
  };

  const togglePlay = () => {
    if (playerIsPlaying) sendPlayerCommand('pauseVideo');
    else sendPlayerCommand('playVideo');
    setPlayerIsPlaying(!playerIsPlaying);
  };

  const toggleMute = () => {
    if (isMuted) {
      sendPlayerCommand('unMute');
      sendPlayerCommand('setVolume', [playerVolume]);
    } else {
      sendPlayerCommand('mute');
    }
    setIsMuted(!isMuted);
  };

  const handleVolumeChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const vol = parseInt(e.target.value);
    setPlayerVolume(vol);
    if (!isMuted) sendPlayerCommand('setVolume', [vol]);
  };

  const toggleFullscreen = () => {
    if (playerContainerRef.current) {
      if (!document.fullscreenElement) playerContainerRef.current.requestFullscreen();
      else document.exitFullscreen();
    }
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    if (file.size > 5 * 1024 * 1024) {
      alert("A imagem de capa não pode exceder 5 MB.");
      e.target.value = '';
      return;
    }
    const reader = new FileReader();
    reader.onloadend = () => {
      setCourseForm(prev => ({ ...prev, capaUrl: reader.result as string }));
    };
    reader.readAsDataURL(file);
  };

  const handleCreateCourse = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      await addDoc(collection(db, 'cursos'), {
        ...courseForm,
        professorId: user.uid,
        inscritos: 0,
        status: 'rascunho',
        createdAt: serverTimestamp()
      });
      setShowCourseModal(false);
      fetchMyCourses();
    } catch (error) { console.error(error); }
  };

  const handleDeleteCourse = async (courseId: string) => {
    if (!confirm("Tem certeza que deseja excluir o curso inteiro?")) return;
    try {
      await deleteDoc(doc(db, 'cursos', courseId));
      setMyCourses(prev => prev.filter(c => c.id !== courseId));
      setOpenMenuId(null);
    } catch (error) { console.error(error); }
  };

  const handleDuplicateCourse = async (course: Course) => {
    try {
      const { id, ...data } = course;
      await addDoc(collection(db, 'cursos'), {
        ...data,
        nome: `${data.nome} (Cópia)`,
        createdAt: serverTimestamp()
      });
      fetchMyCourses();
      setOpenMenuId(null);
    } catch (error) { console.error(error); }
  };

  const handleDeleteModule = async (courseId: string, moduleId: string) => {
    if (!confirm("Excluir este módulo?")) return;
    try {
      await deleteDoc(doc(db, 'cursos', courseId, 'modulos', moduleId));
      if (selectedCourse) {
        setModules(prev => prev.filter(m => m.id !== moduleId));
      } else {
        fetchAllModulesGrouped();
      }
    } catch (error) { console.error(error); }
  };

  const handleDuplicateModule = async (mod: Module) => {
    try {
      const { id, ...data } = mod;
      await addDoc(collection(db, 'cursos', mod.courseId, 'modulos'), {
        ...data,
        nome: `${data.nome} (Cópia)`,
        ordem: (mod.ordem || 0) + 1,
        createdAt: serverTimestamp()
      });
      if (selectedCourse) {
        const mods = await fetchModulesForCourse(selectedCourse.id);
        setModules(mods);
      } else {
        fetchAllModulesGrouped();
      }
    } catch (error) { console.error(error); }
  };

  const handleCreateModule = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedCourse) return;
    try {
      await addDoc(collection(db, 'cursos', selectedCourse.id, 'modulos'), {
        nome: moduleForm.nome,
        ordem: modules.length + 1,
        createdAt: serverTimestamp()
      });
      setShowModuleModal(false);
      setModuleForm({ nome: '' });
      const mods = await fetchModulesForCourse(selectedCourse.id);
      setModules(mods);
    } catch (error) { console.error(error); }
  };

  const handleCreateLesson = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedCourse || !activeModuleId) return;
    try {
      await addDoc(collection(db, 'cursos', selectedCourse.id, 'modulos', activeModuleId, 'aulas'), {
        ...lessonForm,
        ordem: (lessonsByModule[activeModuleId]?.length || 0) + 1,
        createdAt: serverTimestamp()
      });
      setShowLessonModal(false);
      setLessonForm({ titulo: '', descricao: '', videoUrl: '', materialUrl: '' });
      fetchLessons(selectedCourse.id, activeModuleId);
    } catch (error) { console.error(error); }
  };

  const openCourseDetail = async (course: Course) => {
    setSelectedCourse(course);
    setActiveSub('modulos');
    const mods = await fetchModulesForCourse(course.id);
    setModules(mods);
    for (const mod of mods) {
      fetchLessons(course.id, mod.id);
    }
  };

  const openPreview = (lesson: Lesson) => {
    setCountdown(15);
    setIsTimerFinished(false);
    setIsConcluded(false);
    setPlayerIsPlaying(false);
    setPreviewLesson(lesson);
  };

  const getEmbedUrl = (url: string) => {
    if (!url) return "";
    const ytRegex = /(?:https?:\/\/)?(?:www\.)?(?:youtube\.com\/(?:[^\/\n\s]+\/\S+\/|(?:v|e(?:mbed)?)\/|\S*?[?&]v=)|youtu\.be\/)([a-zA-Z0-9_-]{11})/;
    const ytMatch = url.match(ytRegex);
    if (ytMatch && ytMatch[1]) {
      return `https://www.youtube.com/embed/${ytMatch[1]}?modestbranding=1&rel=0&iv_load_policy=3&disablekb=1&controls=0&showinfo=0&enablejsapi=1&origin=${window.location.origin}`;
    }
    return url;
  };

  // NEW: Grouped Modules View
  if (activeSub === 'modulos' && !selectedCourse) {
    return (
      <div className="space-y-6 animate-in fade-in duration-500">
        <header>
          <h1 className="text-2xl font-bold text-slate-900 tracking-tight">Visão Geral dos Módulos</h1>
          <p className="text-slate-500 text-sm">Estrutura curricular organizada por curso.</p>
        </header>

        {loading ? (
          <div className="flex items-center justify-center p-20"><div className="h-8 w-8 animate-spin rounded-full border-4 border-indigo-600 border-t-transparent"></div></div>
        ) : Object.keys(allModulesGrouped).length === 0 ? (
          <div className="bg-white p-20 rounded-2xl border border-slate-200 text-center opacity-50">
            <Layers size={48} className="mx-auto mb-4 text-slate-300" />
            <p className="font-bold text-slate-900">Nenhum módulo encontrado</p>
          </div>
        ) : (
          <div className="space-y-8">
            {Object.values(allModulesGrouped).map(({ course, modules }) => (
              <div key={course.id} className="bg-white rounded-2xl border border-slate-200 shadow-sm overflow-hidden">
                <div className="px-6 py-4 border-b border-slate-100 flex items-center justify-between bg-slate-50/50">
                  <div className="flex items-center gap-3">
                    <BookOpen size={16} className="text-indigo-600" />
                    <h2 className="text-sm font-bold text-slate-800 uppercase tracking-widest">{course.nome}</h2>
                  </div>
                  <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">{modules.length} Módulos</span>
                </div>
                <div className="overflow-x-auto">
                  <table className="w-full text-left">
                    <thead className="bg-slate-50/30 text-[10px] font-black text-slate-400 uppercase tracking-tighter border-b border-slate-100">
                      <tr>
                        <th className="px-6 py-3">Nome do Módulo</th>
                        <th className="px-6 py-3">Ordem</th>
                        <th className="px-6 py-3 text-right">Ações</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-100 text-sm">
                      {modules.map(mod => (
                        <tr key={mod.id} className="hover:bg-slate-50/50 transition-colors">
                          <td className="px-6 py-4 font-semibold text-slate-900">{mod.nome}</td>
                          <td className="px-6 py-4 text-slate-500">Unidade {mod.ordem}</td>
                          <td className="px-6 py-4">
                            <div className="flex items-center justify-end gap-1">
                              <button onClick={() => openCourseDetail(course)} className="p-2 text-indigo-600 hover:bg-indigo-50 rounded-lg transition-colors" title="Ver Matriz"><Eye size={16} /></button>
                              <button className="p-2 text-slate-400 hover:bg-slate-100 rounded-lg transition-colors" title="Editar"><Edit size={16} /></button>
                              <button onClick={() => handleDuplicateModule(mod)} className="p-2 text-slate-400 hover:bg-slate-100 rounded-lg transition-colors" title="Duplicar"><Copy size={16} /></button>
                              <button onClick={() => handleDeleteModule(course.id, mod.id)} className="p-2 text-red-500 hover:bg-red-50 rounded-lg transition-colors" title="Excluir"><Trash2 size={16} /></button>
                            </div>
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>
    );
  }

  // PRESERVE: Course Detail View
  if (activeSub === 'modulos' && selectedCourse) {
    return (
      <div className="space-y-6 animate-in fade-in duration-500">
        <header className="flex items-center justify-between gap-4">
          <div className="flex items-center gap-4">
            <button onClick={() => { setSelectedCourse(null); setActiveSub('cursos'); }} className="h-10 w-10 bg-white border border-slate-200 hover:bg-slate-50 rounded-xl text-slate-600 transition-all shadow-sm flex items-center justify-center"><ArrowLeft size={20} /></button>
            <div>
              <h1 className="text-2xl font-bold text-slate-900 leading-tight">{selectedCourse.nome}</h1>
              <p className="text-slate-500 text-sm">{selectedCourse.tema}</p>
            </div>
          </div>
          <button onClick={() => setShowModuleModal(true)} className="flex items-center gap-2 bg-indigo-600 text-white px-5 py-2.5 rounded-xl text-sm font-bold hover:bg-indigo-700 shadow-lg shadow-indigo-100"><Plus size={18} /> Novo Módulo</button>
        </header>

        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
          <div className="lg:col-span-2 space-y-4">
            <div className="bg-white rounded-2xl border border-slate-200 shadow-sm overflow-hidden">
              <div className="px-6 py-4 border-b border-slate-100 flex items-center justify-between bg-slate-50/50">
                <h2 className="text-xs font-bold text-slate-800 uppercase tracking-widest">Estrutura Curricular</h2>
                <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">{modules.length} Módulos</span>
              </div>
              <div className="p-4 space-y-4">
                {modules.map((mod) => (
                  <div key={mod.id} className="border border-slate-100 rounded-xl overflow-hidden group">
                    <div className="px-4 py-3 border-b border-slate-100 flex items-center justify-between bg-white group-hover:bg-slate-50/50 transition-colors">
                      <h3 className="font-bold text-slate-800 text-sm">Módulo {mod.ordem}: {mod.nome}</h3>
                      <div className="flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                        <button onClick={() => { setActiveModuleId(mod.id); setShowLessonModal(true); }} className="p-1.5 text-indigo-600 hover:bg-indigo-50 rounded-lg transition-colors"><Plus size={18} /></button>
                        <button onClick={() => handleDeleteModule(selectedCourse.id, mod.id)} className="p-1.5 text-red-400 hover:bg-red-50 rounded-lg transition-colors"><Trash2 size={18} /></button>
                      </div>
                    </div>
                    <div className="p-2 space-y-1">
                      {lessonsByModule[mod.id]?.map((lesson) => (
                        <div key={lesson.id} className="flex items-center justify-between p-3 rounded-xl hover:bg-slate-50 transition-all group/lesson">
                          <div className="flex items-center gap-4">
                            <div className="p-2 bg-white border border-slate-100 text-indigo-600 rounded-lg"><Play size={12} fill="currentColor" /></div>
                            <span className="text-sm font-semibold text-slate-700">{lesson.titulo}</span>
                          </div>
                          <button onClick={() => openPreview(lesson)} className="p-1.5 text-indigo-600 hover:bg-indigo-50 rounded-lg opacity-0 group-hover/lesson:opacity-100 transition-all"><Eye size={16} /></button>
                        </div>
                      ))}
                    </div>
                  </div>
                ))}
              </div>
            </div>
          </div>

          <div className="bg-white p-5 rounded-2xl border border-slate-200 shadow-sm sticky top-24 h-fit">
            <img src={selectedCourse.capaUrl || 'https://images.unsplash.com/photo-1504052434139-443c40c98408?w=800'} className="w-full h-40 object-cover rounded-xl mb-4 border border-slate-100 shadow-sm" />
            <div className="space-y-3">
              <div className="flex justify-between border-b pb-2"><span className="text-[10px] text-slate-400 uppercase font-black">Professor</span><span className="text-xs font-bold">{selectedCourse.professorResponsavel}</span></div>
              <div className="flex justify-between border-b pb-2"><span className="text-[10px] text-slate-400 uppercase font-black">Carga</span><span className="text-xs font-bold">{selectedCourse.cargaHoraria}</span></div>
              <div className="flex justify-between border-b pb-2"><span className="text-[10px] text-slate-400 uppercase font-black">Público</span><span className="text-xs font-bold">{selectedCourse.publicoAlvo}</span></div>
              <p className="text-[11px] text-slate-500 leading-relaxed italic">{selectedCourse.descricaoLonga}</p>
            </div>
          </div>
        </div>

        {/* Modal Module */}
        {showModuleModal && (
          <div className="fixed inset-0 z-[110] flex items-center justify-center p-4 bg-slate-900/40 backdrop-blur-sm">
            <div className="bg-white w-full max-w-md rounded-2xl shadow-2xl p-6">
              <h3 className="font-bold text-slate-900 mb-4">Novo Módulo</h3>
              <form onSubmit={handleCreateModule} className="space-y-4">
                <input required autoFocus value={moduleForm.nome} onChange={e => setModuleForm({nome: e.target.value})} placeholder="Título do Módulo" className="w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm" />
                <button type="submit" className="w-full bg-indigo-600 text-white py-2.5 rounded-xl font-bold text-sm">Criar Módulo</button>
              </form>
            </div>
          </div>
        )}

        {/* Modal Lesson */}
        {showLessonModal && (
          <div className="fixed inset-0 z-[110] flex items-center justify-center p-4 bg-slate-900/40 backdrop-blur-sm">
            <div className="bg-white w-full max-w-lg rounded-2xl shadow-2xl p-6">
              <h3 className="font-bold text-slate-900 mb-4">Adicionar Aula</h3>
              <form onSubmit={handleCreateLesson} className="space-y-4">
                <input required value={lessonForm.titulo} onChange={e => setLessonForm({...lessonForm, titulo: e.target.value})} placeholder="Título da Aula" className="w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm" />
                <textarea value={lessonForm.descricao} onChange={e => setLessonForm({...lessonForm, descricao: e.target.value})} placeholder="Descrição Pedagógica" className="w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm resize-none" rows={3}></textarea>
                <div className="grid grid-cols-2 gap-4">
                  <input value={lessonForm.videoUrl} onChange={e => setLessonForm({...lessonForm, videoUrl: e.target.value})} placeholder="URL YouTube" className="w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm" />
                  <input value={lessonForm.materialUrl} onChange={e => setLessonForm({...lessonForm, materialUrl: e.target.value})} placeholder="Material PDF" className="w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm" />
                </div>
                <button type="submit" className="w-full bg-indigo-600 text-white py-3 rounded-xl font-bold text-sm">Publicar Conteúdo</button>
              </form>
            </div>
          </div>
        )}

        {/* Pedagogical Preview Modal */}
        {previewLesson && (
          <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 bg-slate-900/80 backdrop-blur-md animate-in fade-in duration-300">
            <div className="bg-white w-full max-w-6xl h-[90vh] rounded-3xl shadow-2xl overflow-hidden flex flex-col animate-in zoom-in-95 duration-200">
              <div className="p-5 border-b border-slate-100 flex items-center justify-between bg-white">
                <div className="flex items-center gap-3">
                  <div className="bg-indigo-600 p-2 rounded-xl text-white shadow-lg shadow-indigo-200"><Eye size={18} /></div>
                  <h3 className="font-bold text-slate-900 text-base">{previewLesson.titulo}</h3>
                </div>
                <button onClick={() => setPreviewLesson(null)} className="px-4 py-2 bg-slate-100 hover:bg-slate-200 rounded-xl text-slate-600 text-xs font-bold transition-colors">Sair da Aula</button>
              </div>

              <div className="flex-1 overflow-y-auto bg-slate-50/50 p-6 flex flex-col lg:flex-row gap-6">
                <div className="flex-[2] space-y-6">
                  {/* Player Container (Security Preserved) */}
                  <div ref={playerContainerRef} className="aspect-video bg-slate-900 rounded-2xl overflow-hidden shadow-2xl border-4 border-white relative group">
                    <iframe ref={iframeRef} width="100%" height="100%" src={getEmbedUrl(previewLesson.videoUrl)} title="Video Player" frameBorder="0" allow="accelerometer; autoplay; encrypted-media; gyroscope" className="pointer-events-none"></iframe>
                    <div className="absolute inset-0 z-20 pointer-events-none flex flex-col justify-end">
                      {!playerIsPlaying && (
                        <div className="absolute inset-0 flex items-center justify-center bg-black/20 pointer-events-auto cursor-pointer" onClick={togglePlay}>
                          <div className="w-20 h-20 bg-white/10 backdrop-blur-xl border border-white/20 rounded-full flex items-center justify-center text-white transition-all shadow-2xl"><Play size={40} fill="currentColor" /></div>
                        </div>
                      )}
                      <div className="p-4 bg-gradient-to-t from-black/80 to-transparent opacity-0 group-hover:opacity-100 transition-opacity pointer-events-auto">
                        <div className="flex items-center justify-between gap-6 px-4">
                          <div className="flex items-center gap-4">
                            <button onClick={togglePlay} className="text-white hover:text-indigo-400 transition-colors">{playerIsPlaying ? <Pause size={24} fill="currentColor" /> : <Play size={24} fill="currentColor" />}</button>
                            <div className="flex items-center gap-3 group/vol">
                              <button onClick={toggleMute} className="text-white hover:text-indigo-400 transition-colors">{(isMuted || playerVolume === 0) ? <VolumeX size={20} /> : <Volume2 size={20} />}</button>
                              <input type="range" min="0" max="100" value={isMuted ? 0 : playerVolume} onChange={handleVolumeChange} className="w-20 h-1.5 bg-white/20 rounded-full appearance-none cursor-pointer accent-indigo-500 hover:accent-indigo-400 transition-all" />
                            </div>
                          </div>
                          <button onClick={toggleFullscreen} className="text-white hover:text-indigo-400 transition-colors"><Maximize size={20} /></button>
                        </div>
                      </div>
                    </div>
                  </div>

                  {/* Pedagogical Description Area */}
                  <div className="p-8 bg-white rounded-3xl border border-slate-200 shadow-sm space-y-4">
                    <h4 className="text-lg font-bold text-slate-900 flex items-center gap-2"><FileText size={20} className="text-indigo-600" /> Descrição da Aula</h4>
                    <p className="text-sm text-slate-600 leading-relaxed whitespace-pre-wrap">{previewLesson.descricao || "Nenhuma descrição detalhada disponível."}</p>
                  </div>
                </div>

                <div className="flex-1 space-y-4">
                  <div className="bg-white p-6 rounded-3xl border border-slate-200 shadow-sm h-fit">
                    <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-4">Seu Progresso</h4>
                    <div className="space-y-6">
                      <div className={`p-4 rounded-xl border transition-all ${isConcluded ? 'bg-emerald-50 border-emerald-100' : 'bg-indigo-50 border-indigo-100'}`}>
                        <div className="flex items-center gap-3 mb-2">
                          {isConcluded ? <CheckCircle size={18} className="text-emerald-600" /> : <Clock size={18} className="text-indigo-600 animate-pulse" />}
                          <span className={`text-xs font-bold ${isConcluded ? 'text-emerald-700' : 'text-indigo-700'}`}>{isConcluded ? 'Aula Concluída' : 'Engajamento Ativo'}</span>
                        </div>
                        <p className="text-[10px] text-slate-500 leading-relaxed">Assista ao vídeo por completo. O sistema validará sua presença ao final do cronômetro.</p>
                      </div>

                      <div className="bg-slate-50 p-6 rounded-2xl text-center border border-slate-100">
                        {(!isTimerFinished && !isConcluded) ? (
                          <div className="space-y-1"><span className="text-4xl font-black text-slate-900 tabular-nums">{countdown}s</span><p className="text-[9px] font-bold text-slate-400 uppercase tracking-widest">Validação Pedagógica</p></div>
                        ) : (
                          <div className="py-2 flex flex-col items-center gap-1 text-emerald-600"><CheckCircle size={24} /><span className="text-xs font-black uppercase">Requisito Satisfeito</span></div>
                        )}
                      </div>

                      <button disabled={!isTimerFinished || isConcluded} onClick={() => setIsConcluded(true)} className={`w-full py-4 rounded-xl font-bold text-sm transition-all shadow-lg ${isTimerFinished && !isConcluded ? 'bg-slate-900 text-white' : isConcluded ? 'bg-emerald-100 text-emerald-700' : 'bg-slate-100 text-slate-400 cursor-not-allowed'}`}>
                        {isConcluded ? 'Concluído' : countdown > 0 ? `Aguarde ${countdown}s` : 'Confirmar Presença'}
                      </button>
                    </div>
                  </div>
                </div>
              </div>
            </div>
          </div>
        )}
      </div>
    );
  }

  // Dashboard Courses View
  return (
    <div className="space-y-6 animate-in fade-in duration-500">
      <header className="flex flex-col sm:flex-row items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold text-slate-900 tracking-tight">Gestão de Cursos</h1>
          <p className="text-slate-500 text-sm font-medium">Configure novos currículos e acompanhe o progresso acadêmico.</p>
        </div>
        <button onClick={() => setShowCourseModal(true)} className="flex items-center gap-2 bg-indigo-600 text-white px-5 py-3 rounded-xl text-sm font-bold hover:bg-indigo-700 transition-all shadow-lg shadow-indigo-100"><Plus size={18} /> Configurar Novo Curso</button>
      </header>

      {/* Course Cards Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {loading ? (
          <div className="col-span-full py-20 flex justify-center"><div className="h-6 w-6 animate-spin rounded-full border-2 border-indigo-600 border-t-transparent"></div></div>
        ) : myCourses.map(course => (
          <div key={course.id} onClick={() => openCourseDetail(course)} className="bg-white border border-slate-200 rounded-3xl overflow-hidden hover:shadow-xl hover:border-indigo-200 transition-all group cursor-pointer flex flex-col relative overflow-visible">
            {/* Action Buttons Overlay */}
            <div className="absolute top-3 right-3 z-50">
              <button onClick={(e) => { e.stopPropagation(); setOpenMenuId(openMenuId === course.id ? null : course.id); }} className="p-2 bg-white/90 backdrop-blur-sm rounded-xl border border-slate-200 text-slate-500 hover:text-indigo-600 shadow-sm transition-all"><MoreVertical size={16} /></button>
              {openMenuId === course.id && (
                <div className="absolute right-0 mt-2 w-40 bg-white rounded-2xl shadow-2xl border border-slate-100 z-50 animate-in zoom-in-95 duration-100 overflow-hidden text-xs font-bold">
                  <button onClick={(e) => { e.stopPropagation(); handleDuplicateCourse(course); }} className="w-full px-4 py-3 text-left hover:bg-slate-50 flex items-center gap-2"><Copy size={14} /> Duplicar</button>
                  <button onClick={(e) => { e.stopPropagation(); handleDeleteCourse(course.id); }} className="w-full px-4 py-3 text-left hover:bg-red-50 text-red-500 flex items-center gap-2"><Trash2 size={14} /> Excluir</button>
                </div>
              )}
            </div>

            <div className="h-40 overflow-hidden bg-slate-100 border-b border-slate-100 relative">
              {course.capaUrl ? <img src={course.capaUrl} className="w-full h-full object-cover transition-transform group-hover:scale-105" /> : <div className="h-full flex items-center justify-center text-slate-200"><BookOpen size={48} /></div>}
              <div className="absolute top-2 left-2 flex gap-1"><span className={`px-2 py-0.5 rounded-lg text-[9px] font-black uppercase ${course.status === 'ativo' ? 'bg-emerald-500 text-white shadow-lg shadow-emerald-500/20' : 'bg-slate-700 text-white'}`}>{course.status}</span></div>
            </div>
            <div className="p-5 flex-1 flex flex-col">
              <h3 className="font-black text-slate-900 text-base mb-1 group-hover:text-indigo-600 transition-colors leading-tight line-clamp-2">{course.nome}</h3>
              <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest mb-3">{course.tema || 'Geral'}</p>
              <div className="flex items-center gap-2 mb-4">
                <span className="text-[9px] font-black uppercase tracking-widest px-2 py-1 bg-indigo-50 text-indigo-700 rounded-md border border-indigo-100">{course.publicoAlvo}</span>
                <span className="text-[9px] font-black uppercase tracking-widest px-2 py-1 bg-slate-50 text-slate-500 rounded-md border border-slate-100">{course.cargaHoraria}</span>
              </div>
              <div className="mt-auto pt-4 border-t border-slate-50 flex items-center justify-between text-[10px] text-slate-400 font-black uppercase tracking-[0.2em]">
                <div className="flex items-center gap-2"><Layout size={12} /><span>Ver Matriz</span></div>
                <ChevronRight size={14} className="group-hover:translate-x-1 transition-transform" />
              </div>
            </div>
          </div>
        ))}
      </div>

      {/* Advanced Course Modal */}
      {showCourseModal && (
        <div className="fixed inset-0 z-[110] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm animate-in fade-in duration-300">
          <div className="bg-white w-full max-w-2xl rounded-3xl shadow-2xl overflow-hidden animate-in zoom-in-95 duration-200 flex flex-col max-h-[90vh]">
            <div className="p-6 border-b border-slate-100 flex items-center justify-between bg-slate-50/30">
              <div className="flex items-center gap-3">
                <div className="bg-indigo-600 p-2.5 rounded-xl text-white"><GraduationCap size={20} /></div>
                <div><h3 className="font-bold text-slate-900 text-lg">Configurar Novo Curso</h3><p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest">Definição do Currículo Acadêmico</p></div>
              </div>
              <button onClick={() => setShowCourseModal(false)} className="text-slate-400 hover:text-slate-600 p-2"><X size={20} /></button>
            </div>

            <form onSubmit={handleCreateCourse} className="p-8 space-y-6 overflow-y-auto">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className="space-y-4">
                  <div className="space-y-1"><label className="text-[10px] font-black text-slate-400 uppercase ml-1">Título do Curso</label><input required autoFocus value={courseForm.nome} onChange={e => setCourseForm({...courseForm, nome: e.target.value})} placeholder="Ex: Teologia Sistemática" className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-2xl text-sm" /></div>
                  <div className="space-y-1"><label className="text-[10px] font-black text-slate-400 uppercase ml-1">Professor Responsável</label><input required value={courseForm.professorResponsavel} onChange={e => setCourseForm({...courseForm, professorResponsavel: e.target.value})} className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-2xl text-sm" /></div>
                  <div className="grid grid-cols-2 gap-4">
                    <div className="space-y-1"><label className="text-[10px] font-black text-slate-400 uppercase ml-1">Carga Horária</label><input required value={courseForm.cargaHoraria} onChange={e => setCourseForm({...courseForm, cargaHoraria: e.target.value})} placeholder="40h" className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-2xl text-sm" /></div>
                    <div className="space-y-1"><label className="text-[10px] font-black text-slate-400 uppercase ml-1">Público</label><select value={courseForm.publicoAlvo} onChange={e => setCourseForm({...courseForm, publicoAlvo: e.target.value as any})} className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-2xl text-sm"><option value="Geral">Geral</option><option value="Líderes">Líderes</option><option value="Obreiros">Obreiros</option></select></div>
                  </div>
                </div>
                <div className="space-y-4">
                  <div className="space-y-1"><label className="text-[10px] font-black text-slate-400 uppercase ml-1">Tema / Categoria</label><input value={courseForm.tema} onChange={e => setCourseForm({...courseForm, tema: e.target.value})} placeholder="Ex: História da Igreja" className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-2xl text-sm" /></div>
                  <div className="space-y-1">
                    <label className="text-[10px] font-black text-slate-400 uppercase ml-1">Capa (Max 5MB)</label>
                    <div className="relative h-32 w-full bg-slate-50 border-2 border-dashed border-slate-200 rounded-2xl flex flex-col items-center justify-center hover:border-indigo-400 transition-all cursor-pointer">
                      <input type="file" accept="image/*" onChange={handleFileUpload} className="absolute inset-0 opacity-0 cursor-pointer" />
                      {courseForm.capaUrl ? <img src={courseForm.capaUrl} className="w-full h-full object-cover rounded-2xl" /> : <><FileUp size={24} className="text-slate-300" /><span className="text-[10px] font-bold text-slate-400 uppercase">Selecionar Imagem</span></>}
                    </div>
                  </div>
                </div>
              </div>
              <div className="space-y-1"><label className="text-[10px] font-black text-slate-400 uppercase ml-1">Descrição Longa (Ementa)</label><textarea rows={3} value={courseForm.descricaoLonga} onChange={e => setCourseForm({...courseForm, descricaoLonga: e.target.value})} className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-2xl text-sm resize-none" placeholder="Detalhes dos objetivos do curso..."></textarea></div>
              <button type="submit" className="w-full bg-slate-900 text-white py-4 rounded-2xl font-black text-sm uppercase tracking-widest shadow-xl">Finalizar e Criar Curso</button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default ProfessorView;

import React, { useState, useEffect, useRef } from 'react';
import { 
  collection, 
  query, 
  where, 
  getDocs, 
  addDoc, 
  deleteDoc,
  serverTimestamp, 
  orderBy,
  doc,
  updateDoc
} from 'firebase/firestore';
import { db } from '../firebase';
import { Course, Module, Lesson, User, ProfessorSubView } from '../types';
import { 
  Search, 
  Filter, 
  BookOpen, 
  Plus, 
  Info, 
  X, 
  ChevronRight, 
  Play, 
  Pause,
  Volume2,
  VolumeX,
  Maximize,
  FileText, 
  MoreVertical, 
  ArrowLeft, 
  Layout, 
  Trash2, 
  AlertTriangle, 
  Layers, 
  Eye, 
  Clock, 
  Download, 
  CheckCircle, 
  Copy,
  Edit,
  GraduationCap,
  FileUp,
  ShieldCheck
} from 'lucide-react';

interface ProfessorViewProps {
  user: User;
  activeSub: ProfessorSubView;
  setActiveSub: (view: ProfessorSubView) => void;
}

const ProfessorView: React.FC<ProfessorViewProps> = ({ user, activeSub, setActiveSub }) => {
  const [myCourses, setMyCourses] = useState<Course[]>([]);
  const [loading, setLoading] = useState(true);
  const [selectedCourse, setSelectedCourse] = useState<Course | null>(null);
  const [modules, setModules] = useState<Module[]>([]);
  const [lessonsByModule, setLessonsByModule] = useState<Record<string, Lesson[]>>({});
  const [allModulesGrouped, setAllModulesGrouped] = useState<Record<string, { course: Course, modules: Module[] }>>({});
  const [openMenuId, setOpenMenuId] = useState<string | null>(null);

  // Modal States
  const [showCourseModal, setShowCourseModal] = useState(false);
  const [showModuleModal, setShowModuleModal] = useState(false);
  const [showLessonModal, setShowLessonModal] = useState(false);
  const [activeModuleId, setActiveModuleId] = useState<string | null>(null);

  // Preview States
  const [previewLesson, setPreviewLesson] = useState<Lesson | null>(null);
  const [countdown, setCountdown] = useState(15);
  const [isTimerFinished, setIsTimerFinished] = useState(false);
  const [isConcluded, setIsConcluded] = useState(false);

  // Custom Player States
  const [playerIsPlaying, setPlayerIsPlaying] = useState(false);
  const [playerVolume, setPlayerVolume] = useState(80);
  const [isMuted, setIsMuted] = useState(false);
  const iframeRef = useRef<HTMLIFrameElement>(null);
  const playerContainerRef = useRef<HTMLDivElement>(null);

  // Form States
  const [courseForm, setCourseForm] = useState({
    nome: '',
    tema: '',
    professorResponsavel: user.displayName || '',
    descricaoLonga: '',
    capaUrl: '',
    cargaHoraria: '',
    publicoAlvo: 'Geral' as const
  });
  const [moduleForm, setModuleForm] = useState({ nome: '' });
  const [lessonForm, setLessonForm] = useState({
    titulo: '',
    descricao: '',
    videoUrl: '',
    materialUrl: ''
  });

  const fetchMyCourses = async () => {
    setLoading(true);
    try {
      const q = query(collection(db, 'cursos'), where('professorId', '==', user.uid), orderBy('createdAt', 'desc'));
      const querySnapshot = await getDocs(q);
      const fetched: Course[] = [];
      querySnapshot.forEach((doc) => {
        fetched.push({ id: doc.id, ...doc.data() } as Course);
      });
      setMyCourses(fetched);
    } catch (error) {
      console.error("Erro ao carregar seus cursos:", error);
    } finally {
      setLoading(false);
    }
  };

  const fetchModulesForCourse = async (courseId: string) => {
    const q = query(collection(db, 'cursos', courseId, 'modulos'), orderBy('ordem', 'asc'));
    const querySnapshot = await getDocs(q);
    const fetched: Module[] = [];
    querySnapshot.forEach((doc) => {
      fetched.push({ id: doc.id, ...doc.data(), courseId } as Module);
    });
    return fetched;
  };

  const fetchAllModulesGrouped = async () => {
    setLoading(true);
    try {
      const grouped: Record<string, { course: Course, modules: Module[] }> = {};
      for (const course of myCourses) {
        const mods = await fetchModulesForCourse(course.id);
        grouped[course.id] = { course, modules: mods };
      }
      setAllModulesGrouped(grouped);
    } catch (error) {
      console.error("Erro ao agrupar módulos:", error);
    } finally {
      setLoading(false);
    }
  };

  const fetchLessons = async (courseId: string, moduleId: string) => {
    try {
      const q = query(collection(db, 'cursos', courseId, 'modulos', moduleId, 'aulas'), orderBy('ordem', 'asc'));
      const querySnapshot = await getDocs(q);
      const fetched: Lesson[] = [];
      querySnapshot.forEach((doc) => {
        fetched.push({ id: doc.id, ...doc.data() } as Lesson);
      });
      setLessonsByModule(prev => ({ ...prev, [moduleId]: fetched }));
    } catch (error) {
      console.error("Erro ao carregar aulas:", error);
    }
  };

  useEffect(() => {
    fetchMyCourses();
  }, [user.uid]);

  useEffect(() => {
    if (activeSub === 'modulos' && !selectedCourse) {
      fetchAllModulesGrouped();
    }
  }, [activeSub, selectedCourse, myCourses]);

  // PRESERVE: 15s LOCK LOGIC
  useEffect(() => {
    let timer: number | undefined;
    if (previewLesson && countdown > 0 && !isConcluded) {
      timer = window.setInterval(() => {
        setCountdown((prev) => {
          if (prev <= 1) {
            setIsTimerFinished(true);
            if (timer) clearInterval(timer);
            return 0;
          }
          return prev - 1;
        });
      }, 1000);
    }
    return () => { if (timer) clearInterval(timer); };
  }, [previewLesson, countdown, isConcluded]);

  // PRESERVE: PLAYER COMMANDS
  const sendPlayerCommand = (func: string, args: any[] = []) => {
    if (iframeRef.current && iframeRef.current.contentWindow) {
      iframeRef.current.contentWindow.postMessage(
        JSON.stringify({ event: 'command', func, args }), 
        '*'
      );
    }
  };

  const togglePlay = () => {
    if (playerIsPlaying) sendPlayerCommand('pauseVideo');
    else sendPlayerCommand('playVideo');
    setPlayerIsPlaying(!playerIsPlaying);
  };

  const toggleMute = () => {
    if (isMuted) {
      sendPlayerCommand('unMute');
      sendPlayerCommand('setVolume', [playerVolume]);
    } else {
      sendPlayerCommand('mute');
    }
    setIsMuted(!isMuted);
  };

  const handleVolumeChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const vol = parseInt(e.target.value);
    setPlayerVolume(vol);
    if (!isMuted) sendPlayerCommand('setVolume', [vol]);
  };

  const toggleFullscreen = () => {
    if (playerContainerRef.current) {
      if (!document.fullscreenElement) playerContainerRef.current.requestFullscreen();
      else document.exitFullscreen();
    }
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    if (file.size > 5 * 1024 * 1024) {
      alert("A imagem de capa não pode exceder 5 MB.");
      e.target.value = '';
      return;
    }
    const reader = new FileReader();
    reader.onloadend = () => {
      setCourseForm(prev => ({ ...prev, capaUrl: reader.result as string }));
    };
    reader.readAsDataURL(file);
  };

  const handleCreateCourse = async (e: React.FormEvent) => {
    e.preventDefault();
    console.log('Iniciando criação de curso...', courseForm);

    try {
      setLoading(true);
      const courseData = {
        ...courseForm,
        professorId: user.uid,
        inscritos: 0,
        status: 'rascunho',
        createdAt: serverTimestamp()
      };

      await addDoc(collection(db, 'cursos'), courseData);
      console.log('Curso criado com sucesso!');

      // Reset form
      setCourseForm({
        nome: '',
        tema: '',
        professorResponsavel: user.displayName || '',
        descricaoLonga: '',
        capaUrl: '',
        cargaHoraria: '',
        publicoAlvo: 'Geral'
      });

      setShowCourseModal(false);
      await fetchMyCourses();
    } catch (error) {
      console.error("Erro crítico ao criar curso:", error);
      alert("Houve um erro ao salvar o curso. Verifique sua conexão.");
    } finally {
      setLoading(false);
    }
  };

  const handleDeleteCourse = async (courseId: string) => {
    if (!confirm("Tem certeza que deseja excluir o curso inteiro?")) return;
    try {
      await deleteDoc(doc(db, 'cursos', courseId));
      setMyCourses(prev => prev.filter(c => c.id !== courseId));
      setOpenMenuId(null);
    } catch (error) { console.error(error); }
  };

  const handleDuplicateCourse = async (course: Course) => {
    try {
      const { id, ...data } = course;
      await addDoc(collection(db, 'cursos'), {
        ...data,
        nome: `${data.nome} (Cópia)`,
        createdAt: serverTimestamp()
      });
      fetchMyCourses();
      setOpenMenuId(null);
    } catch (error) { console.error(error); }
  };

  const handleDeleteModule = async (courseId: string, moduleId: string) => {
    if (!confirm("Excluir este módulo?")) return;
    try {
      await deleteDoc(doc(db, 'cursos', courseId, 'modulos', moduleId));
      if (selectedCourse) {
        setModules(prev => prev.filter(m => m.id !== moduleId));
      } else {
        fetchAllModulesGrouped();
      }
    } catch (error) { console.error(error); }
  };

  const handleDuplicateModule = async (mod: Module) => {
    try {
      const { id, ...data } = mod;
      await addDoc(collection(db, 'cursos', mod.courseId, 'modulos'), {
        ...data,
        nome: `${data.nome} (Cópia)`,
        ordem: (mod.ordem || 0) + 1,
        createdAt: serverTimestamp()
      });
      if (selectedCourse) {
        const mods = await fetchModulesForCourse(selectedCourse.id);
        setModules(mods);
      } else {
        fetchAllModulesGrouped();
      }
    } catch (error) { console.error(error); }
  };

  const handleCreateModule = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedCourse) return;
    try {
      await addDoc(collection(db, 'cursos', selectedCourse.id, 'modulos'), {
        nome: moduleForm.nome,
        ordem: modules.length + 1,
        createdAt: serverTimestamp()
      });
      setShowModuleModal(false);
      setModuleForm({ nome: '' });
      const mods = await fetchModulesForCourse(selectedCourse.id);
      setModules(mods);
    } catch (error) { console.error(error); }
  };

  const handleCreateLesson = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedCourse || !activeModuleId) return;
    try {
      await addDoc(collection(db, 'cursos', selectedCourse.id, 'modulos', activeModuleId, 'aulas'), {
        ...lessonForm,
        ordem: (lessonsByModule[activeModuleId]?.length || 0) + 1,
        createdAt: serverTimestamp()
      });
      setShowLessonModal(false);
      setLessonForm({ titulo: '', descricao: '', videoUrl: '', materialUrl: '' });
      fetchLessons(selectedCourse.id, activeModuleId);
    } catch (error) { console.error(error); }
  };

  const openCourseDetail = async (course: Course) => {
    setSelectedCourse(course);
    setActiveSub('modulos');
    const mods = await fetchModulesForCourse(course.id);
    setModules(mods);
    for (const mod of mods) {
      fetchLessons(course.id, mod.id);
    }
  };

  const openPreview = (lesson: Lesson) => {
    setCountdown(15);
    setIsTimerFinished(false);
    setIsConcluded(false);
    setPlayerIsPlaying(false);
    setPreviewLesson(lesson);
  };

  const getEmbedUrl = (url: string) => {
    if (!url) return "";
    const ytRegex = /(?:https?:\/\/)?(?:www\.)?(?:youtube\.com\/(?:[^\/\n\s]+\/\S+\/|(?:v|e(?:mbed)?)\/|\S*?[?&]v=)|youtu\.be\/)([a-zA-Z0-9_-]{11})/;
    const ytMatch = url.match(ytRegex);
    if (ytMatch && ytMatch[1]) {
      return `https://www.youtube.com/embed/${ytMatch[1]}?modestbranding=1&rel=0&iv_load_policy=3&disablekb=1&controls=0&showinfo=0&enablejsapi=1&origin=${window.location.origin}`;
    }
    return url;
  };

  // NEW: Grouped Modules View
  if (activeSub === 'modulos' && !selectedCourse) {
    return (
      <div className="space-y-6 animate-in fade-in duration-500">
        <header>
          <h1 className="text-2xl font-bold text-slate-900 tracking-tight">Visão Geral dos Módulos</h1>
          <p className="text-slate-500 text-sm">Estrutura curricular organizada por curso.</p>
        </header>

        {loading ? (
          <div className="flex items-center justify-center p-20"><div className="h-8 w-8 animate-spin rounded-full border-4 border-indigo-600 border-t-transparent"></div></div>
