                              <button className="p-2 text-slate-400 hover:bg-slate-100 rounded-lg transition-colors" title="Editar"><Edit size={16} /></button>
                              <button onClick={() => handleDuplicateModule(mod)} className="p-2 text-slate-400 hover:bg-slate-100 rounded-lg transition-colors" title="Duplicar"><Copy size={16} /></button>
                              <button onClick={() => handleDeleteModule(course.id, mod.id)} className="p-2 text-red-500 hover:bg-red-50 rounded-lg transition-colors" title="Excluir"><Trash2 size={16} /></button>
                            </div>
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>
    );
  }

  // PRESERVE: Course Detail View
  if (activeSub === 'modulos' && selectedCourse) {
    return (
      <div className="space-y-6 animate-in fade-in duration-500">
        <header className="flex items-center justify-between gap-4">
          <div className="flex items-center gap-4">
            <button onClick={() => { setSelectedCourse(null); setActiveSub('cursos'); }} className="h-10 w-10 bg-white border border-slate-200 hover:bg-slate-50 rounded-xl text-slate-600 transition-all shadow-sm flex items-center justify-center"><ArrowLeft size={20} /></button>
            <div>
              <h1 className="text-2xl font-bold text-slate-900 leading-tight">{selectedCourse.nome}</h1>
              <p className="text-slate-500 text-sm">{selectedCourse.tema}</p>
            </div>
          </div>
          <button onClick={() => setShowModuleModal(true)} className="flex items-center gap-2 bg-indigo-600 text-white px-5 py-2.5 rounded-xl text-sm font-bold hover:bg-indigo-700 shadow-lg shadow-indigo-100"><Plus size={18} /> Novo Módulo</button>
        </header>

        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
          <div className="lg:col-span-2 space-y-4">
