                  </div>
                </div>
                <div className="space-y-4">
                  <div className="space-y-1"><label className="text-[10px] font-black text-slate-400 uppercase ml-1">Tema / Categoria</label><input value={courseForm.tema} onChange={e => setCourseForm({...courseForm, tema: e.target.value})} placeholder="Ex: História da Igreja" className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-2xl text-sm outline-none" /></div>
                  <div className="space-y-1">
                    <label className="text-[10px] font-black text-slate-400 uppercase ml-1">Capa (Max 5MB)</label>
                    <div className="relative h-32 w-full bg-slate-50 border-2 border-dashed border-slate-200 rounded-2xl flex flex-col items-center justify-center hover:border-indigo-400 transition-all cursor-pointer">
                      <input type="file" accept="image/*" onChange={handleFileUpload} className="absolute inset-0 opacity-0 cursor-pointer" />
                      {courseForm.capaUrl ? <img src={courseForm.capaUrl} className="w-full h-full object-cover rounded-2xl" /> : <><FileUp size={24} className="text-slate-300" /><span className="text-[10px] font-bold text-slate-400 uppercase">Selecionar Imagem</span></>}
                    </div>
                  </div>
                </div>
              </div>
              <div className="space-y-1"><label className="text-[10px] font-black text-slate-400 uppercase ml-1">Descrição Longa (Ementa)</label><textarea rows={3} value={courseForm.descricaoLonga} onChange={e => setCourseForm({...courseForm, descricaoLonga: e.target.value})} className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-2xl text-sm resize-none outline-none" placeholder="Detalhes dos objetivos do curso..."></textarea></div>
              <button 
                type="submit" 
                disabled={loading}
                className={`w-full bg-slate-900 text-white py-4 rounded-2xl font-black text-sm uppercase tracking-widest shadow-xl transition-all ${loading ? 'opacity-50 cursor-not-allowed' : 'hover:bg-slate-800 active:scale-95'}`}
              >
                {loading ? 'Salvando...' : 'Finalizar e Criar Curso'}
              </button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

