                  <h3 className="font-bold text-slate-900 text-base">{previewLesson.titulo}</h3>
                </div>
                <button onClick={() => setPreviewLesson(null)} className="px-4 py-2 bg-slate-100 hover:bg-slate-200 rounded-xl text-slate-600 text-xs font-bold transition-colors">Sair da Revisão</button>
