            <form onSubmit={handleCreateCourse} className="p-8 space-y-6 overflow-y-auto">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className="space-y-4">
                  <div className="space-y-1"><label className="text-[10px] font-black text-slate-400 uppercase ml-1">Título do Curso</label><input required autoFocus value={courseForm.nome} onChange={e => setCourseForm({...courseForm, nome: e.target.value})} placeholder="Ex: Teologia Sistemática" className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-2xl text-sm outline-none" /></div>
                  <div className="space-y-1"><label className="text-[10px] font-black text-slate-400 uppercase ml-1">Professor Responsável</label><input required value={courseForm.professorResponsavel} onChange={e => setCourseForm({...courseForm, professorResponsavel: e.target.value})} className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-2xl text-sm outline-none" /></div>
                  <div className="grid grid-cols-2 gap-4">
                    <div className="space-y-1"><label className="text-[10px] font-black text-slate-400 uppercase ml-1">Carga Horária</label><input required value={courseForm.cargaHoraria} onChange={e => setCourseForm({...courseForm, cargaHoraria: e.target.value})} placeholder="40h" className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-2xl text-sm outline-none" /></div>
                    <div className="space-y-1"><label className="text-[10px] font-black text-slate-400 uppercase ml-1">Público</label><select value={courseForm.publicoAlvo} onChange={e => setCourseForm({...courseForm, publicoAlvo: e.target.value as any})} className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-2xl text-sm outline-none"><option value="Geral">Geral</option><option value="Líderes">Líderes</option><option value="Obreiros">Obreiros</option></select></div>
                  </div>
                </div>
                <div className="space-y-4">
                  <div className="space-y-1"><label className="text-[10px] font-black text-slate-400 uppercase ml-1">Tema / Categoria</label><input value={courseForm.tema} onChange={e => setCourseForm({...courseForm, tema: e.target.value})} placeholder="Ex: História da Igreja" className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-2xl text-sm outline-none" /></div>
                  <div className="space-y-1">
                    <label className="text-[10px] font-black text-slate-400 uppercase ml-1">Capa (Max 5MB)</label>
                    <div className="relative h-32 w-full bg-slate-50 border-2 border-dashed border-slate-200 rounded-2xl flex flex-col items-center justify-center hover:border-indigo-400 transition-all cursor-pointer">
                      <input type="file" accept="image/*" onChange={handleFileUpload} className="absolute inset-0 opacity-0 cursor-pointer" />
                      {courseForm.capaUrl ? <img src={courseForm.capaUrl} className="w-full h-full object-cover rounded-2xl" /> : <><FileUp size={24} className="text-slate-300" /><span className="text-[10px] font-bold text-slate-400 uppercase">Selecionar Imagem</span></>}
                    </div>
                  </div>
                </div>
              </div>
              <div className="space-y-1"><label className="text-[10px] font-black text-slate-400 uppercase ml-1">Descrição Longa (Ementa)</label><textarea rows={3} value={courseForm.descricaoLonga} onChange={e => setCourseForm({...courseForm, descricaoLonga: e.target.value})} className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-2xl text-sm resize-none outline-none" placeholder="Detalhes dos objetivos do curso..."></textarea></div>
              <button 
                type="submit" 
                disabled={loading}
                className={`w-full bg-slate-900 text-white py-4 rounded-2xl font-black text-sm uppercase tracking-widest shadow-xl transition-all ${loading ? 'opacity-50 cursor-not-allowed' : 'hover:bg-slate-800 active:scale-95'}`}
              >
                {loading ? 'Salvando...' : 'Finalizar e Criar Curso'}
              </button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default ProfessorView;

import React from 'react';

export type UserRole = 'diretor' | 'professor' | 'aluno';

export interface User {
  uid: string;
  email: string | null;
  displayName: string | null;
  role: UserRole;
  photoURL?: string;
}

export interface Course {
  id: string;
  nome: string;
  tema?: string;
  descricao?: string;
  descricaoLonga?: string;
  professorResponsavel?: string;
  capaUrl?: string;
  cargaHoraria: string;
  publicoAlvo: 'Geral' | 'Líderes' | 'Obreiros';
  professorId: string;
  inscritos: number;
  status: 'ativo' | 'rascunho';
  geraCertificado: boolean;
  createdAt: any;
}

export interface Module {
  id: string;
  nome: string;
  ordem: number;
  courseId: string;
  createdAt: any;
}

export interface Lesson {
  id: string;
  titulo: string;
  descricao?: string;
  videoUrl: string;
  materialUrl: string;
  ordem: number;
  createdAt: any;
}

export type MainView = 'dashboard' | 'professor' | 'alunos' | 'secretaria' | 'configuracoes';

export type ProfessorSubView = 
  | 'cursos' 
  | 'modulos' 
  | 'materiais' 
  | 'avaliacao' 
  | 'feedback' 
  | 'diario' 
  | 'relatorio' 
  | 'frequencia' 
  | 'live';

export interface NavItem {
  id: MainView;
  label: string;
  icon: React.ReactNode;
}

import React, { useState, useEffect, useRef } from 'react';
import { 
  collection, 
  query, 
  where, 
  getDocs, 
  addDoc, 
  deleteDoc,
  serverTimestamp, 
  orderBy,
  doc,
  updateDoc
} from 'firebase/firestore';
import { db } from '../firebase';
import { Course, Module, Lesson, User, ProfessorSubView } from '../types';
import { 
  Search, 
  Filter, 
  BookOpen, 
  Plus, 
  Info, 
  X, 
  ChevronRight, 
  Play, 
  Pause, 
  Volume2, 
  VolumeX, 
  Maximize, 
  FileText, 
  MoreVertical, 
  ArrowLeft, 
  Layout, 
  Trash2, 
  AlertTriangle, 
  Layers, 
  Eye, 
  Clock, 
  Download, 
  CheckCircle, 
  Copy, 
  Edit, 
  GraduationCap, 
  FileUp, 
  ShieldCheck,
  FileDown,
  Settings
} from 'lucide-react';

interface ProfessorViewProps {
  user: User;
  activeSub: ProfessorSubView;
  setActiveSub: (view: ProfessorSubView) => void;
}

const ProfessorView: React.FC<ProfessorViewProps> = ({ user, activeSub, setActiveSub }) => {
  const [myCourses, setMyCourses] = useState<Course[]>([]);
  const [loading, setLoading] = useState(true);
  const [selectedCourse, setSelectedCourse] = useState<Course | null>(null);
  const [modules, setModules] = useState<Module[]>([]);
  const [lessonsByModule, setLessonsByModule] = useState<Record<string, Lesson[]>>({});
  const [allModulesGrouped, setAllModulesGrouped] = useState<Record<string, { course: Course, modules: Module[] }>>({});
  const [openMenuId, setOpenMenuId] = useState<string | null>(null);

  // Modal States
  const [showCourseModal, setShowCourseModal] = useState(false);
  const [isEditingCourse, setIsEditingCourse] = useState(false);
  const [showModuleModal, setShowModuleModal] = useState(false);
  const [showEditModuleModal, setShowEditModuleModal] = useState(false);
  const [showLessonModal, setShowLessonModal] = useState(false);
  const [isEditingLesson, setIsEditingLesson] = useState(false);
  const [activeModuleId, setActiveModuleId] = useState<string | null>(null);
  const [editingModule, setEditingModule] = useState<Module | null>(null);
  const [editingLessonId, setEditingLessonId] = useState<string | null>(null);

  // Preview States
  const [previewLesson, setPreviewLesson] = useState<Lesson | null>(null);
  const [countdown, setCountdown] = useState(15);
  const [isTimerFinished, setIsTimerFinished] = useState(false);
  const [isConcluded, setIsConcluded] = useState(false);

  // Custom Player States
  const [playerIsPlaying, setPlayerIsPlaying] = useState(false);
  const [playerVolume, setPlayerVolume] = useState(80);
  const [isMuted, setIsMuted] = useState(false);
  const iframeRef = useRef<HTMLIFrameElement>(null);
  const playerContainerRef = useRef<HTMLDivElement>(null);

  // Form States
  const [courseForm, setCourseForm] = useState({
    nome: '',
    tema: '',
    professorResponsavel: user.displayName || '',
    descricaoLonga: '',
    capaUrl: '',
    cargaHoraria: '',
    publicoAlvo: 'Geral' as const,
    geraCertificado: false
  });
  const [moduleForm, setModuleForm] = useState({ nome: '' });
  const [lessonForm, setLessonForm] = useState({
    titulo: '',
    descricao: '',
    videoUrl: '',
    materialUrl: ''
  });

  const fetchMyCourses = async () => {
    setLoading(true);
    try {
      const q = query(collection(db, 'cursos'), where('professorId', '==', user.uid), orderBy('createdAt', 'desc'));
      const querySnapshot = await getDocs(q);
      const fetched: Course[] = [];
      querySnapshot.forEach((doc) => {
        fetched.push({ id: doc.id, ...doc.data() } as Course);
      });
      setMyCourses(fetched);
    } catch (error) {
      console.error("Erro ao carregar seus cursos:", error);
    } finally {
      setLoading(false);
    }
  };

  const fetchModulesForCourse = async (courseId: string) => {
    const q = query(collection(db, 'cursos', courseId, 'modulos'), orderBy('ordem', 'asc'));
    const querySnapshot = await getDocs(q);
    const fetched: Module[] = [];
    querySnapshot.forEach((doc) => {
      fetched.push({ id: doc.id, ...doc.data(), courseId } as Module);
    });
    return fetched;
  };

  const fetchAllModulesGrouped = async () => {
    setLoading(true);
    try {
      const grouped: Record<string, { course: Course, modules: Module[] }> = {};
      for (const course of myCourses) {
        const mods = await fetchModulesForCourse(course.id);
        grouped[course.id] = { course, modules: mods };
      }
      setAllModulesGrouped(grouped);
    } catch (error) {
      console.error("Erro ao agrupar módulos:", error);
    } finally {
      setLoading(false);
    }
  };

  const fetchLessons = async (courseId: string, moduleId: string) => {
    try {
      const q = query(collection(db, 'cursos', courseId, 'modulos', moduleId, 'aulas'), orderBy('ordem', 'asc'));
      const querySnapshot = await getDocs(q);
      const fetched: Lesson[] = [];
      querySnapshot.forEach((doc) => {
        fetched.push({ id: doc.id, ...doc.data() } as Lesson);
      });
      setLessonsByModule(prev => ({ ...prev, [moduleId]: fetched }));
    } catch (error) {
      console.error("Erro ao carregar aulas:", error);
    }
  };

  useEffect(() => {
    fetchMyCourses();
  }, [user.uid]);

  useEffect(() => {
    if (activeSub === 'modulos' && !selectedCourse) {
      fetchAllModulesGrouped();
    }
  }, [activeSub, selectedCourse, myCourses]);

  // PRESERVE: 15s LOCK LOGIC (BYPASS FOR PROFESSOR IN BUILDER MODE)
  useEffect(() => {
    let timer: number | undefined;
    // Bypass: Se estivermos no construtor de cursos, o timer já começa finalizado
    if (selectedCourse) {
      setIsTimerFinished(true);
      setCountdown(0);
      return;
    }

    if (previewLesson && countdown > 0 && !isConcluded) {
      timer = window.setInterval(() => {
        setCountdown((prev) => {
          if (prev <= 1) {
            setIsTimerFinished(true);
            if (timer) clearInterval(timer);
            return 0;
          }
          return prev - 1;
        });
      }, 1000);
    }
    return () => { if (timer) clearInterval(timer); };
  }, [previewLesson, countdown, isConcluded, selectedCourse]);

  // PRESERVE: PLAYER COMMANDS
  const sendPlayerCommand = (func: string, args: any[] = []) => {
    if (iframeRef.current && iframeRef.current.contentWindow) {
      iframeRef.current.contentWindow.postMessage(
        JSON.stringify({ event: 'command', func, args }), 
        '*'
      );
    }
  };

  const togglePlay = () => {
    if (playerIsPlaying) sendPlayerCommand('pauseVideo');
    else sendPlayerCommand('playVideo');
    setPlayerIsPlaying(!playerIsPlaying);
  };

  const toggleMute = () => {
    if (isMuted) {
      sendPlayerCommand('unMute');
      sendPlayerCommand('setVolume', [playerVolume]);
    } else {
      sendPlayerCommand('mute');
    }
    setIsMuted(!isMuted);
  };

  const handleVolumeChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const vol = parseInt(e.target.value);
    setPlayerVolume(vol);
    if (!isMuted) sendPlayerCommand('setVolume', [vol]);
  };

  const toggleFullscreen = () => {
    if (playerContainerRef.current) {
      if (!document.fullscreenElement) playerContainerRef.current.requestFullscreen();
      else document.exitFullscreen();
    }
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    if (file.size > 5 * 1024 * 1024) {
      alert("A imagem de capa não pode exceder 5 MB.");
      e.target.value = '';
      return;
    }
    const reader = new FileReader();
    reader.onloadend = () => {
      setCourseForm(prev => ({ ...prev, capaUrl: reader.result as string }));
    };
    reader.readAsDataURL(file);
  };

  const handleSaveCourse = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      setLoading(true);
      if (isEditingCourse && selectedCourse) {
        const courseRef = doc(db, 'cursos', selectedCourse.id);
        await updateDoc(courseRef, { ...courseForm });
        // Atualiza o estado do curso selecionado
        setSelectedCourse({ ...selectedCourse, ...courseForm });
      } else {
        await addDoc(collection(db, 'cursos'), {
          ...courseForm,
          professorId: user.uid,
          inscritos: 0,
          status: 'rascunho',
          createdAt: serverTimestamp()
        });
      }

      setShowCourseModal(false);
      setIsEditingCourse(false);
      setCourseForm({
        nome: '',
        tema: '',
        professorResponsavel: user.displayName || '',
        descricaoLonga: '',
        capaUrl: '',
        cargaHoraria: '',
        publicoAlvo: 'Geral',
        geraCertificado: false
      });
      await fetchMyCourses();
    } catch (error) {
      console.error("Erro ao salvar curso:", error);
    } finally {
      setLoading(false);
    }
  };

  const handleEditCourseInfo = () => {
    if (!selectedCourse) return;
    setCourseForm({
      nome: selectedCourse.nome,
      tema: selectedCourse.tema || '',
      professorResponsavel: selectedCourse.professorResponsavel || '',
      descricaoLonga: selectedCourse.descricaoLonga || '',
      capaUrl: selectedCourse.capaUrl || '',
      cargaHoraria: selectedCourse.cargaHoraria,
      publicoAlvo: selectedCourse.publicoAlvo,
      geraCertificado: selectedCourse.geraCertificado || false
    });
    setIsEditingCourse(true);
    setShowCourseModal(true);
  };

  const handleDeleteCourse = async (courseId: string) => {
    if (!confirm("Tem certeza que deseja excluir o curso inteiro?")) return;
    try {
      await deleteDoc(doc(db, 'cursos', courseId));
      setMyCourses(prev => prev.filter(c => c.id !== courseId));
      setOpenMenuId(null);
    } catch (error) { console.error(error); }
  };

  const handleDuplicateCourse = async (course: Course) => {
    try {
      const { id, ...data } = course;
      await addDoc(collection(db, 'cursos'), {
        ...data,
        nome: `${data.nome} (Cópia)`,
        createdAt: serverTimestamp()
      });
      fetchMyCourses();
      setOpenMenuId(null);
    } catch (error) { console.error(error); }
  };

  const handleDeleteModule = async (courseId: string, moduleId: string) => {
    if (!confirm("Excluir este módulo?")) return;
    try {
      await deleteDoc(doc(db, 'cursos', courseId, 'modulos', moduleId));
      if (selectedCourse) {
        setModules(prev => prev.filter(m => m.id !== moduleId));
      } else {
        fetchAllModulesGrouped();
      }
    } catch (error) { console.error(error); }
  };

  const handleDuplicateModule = async (mod: Module) => {
    try {
      const { id, ...data } = mod;
      await addDoc(collection(db, 'cursos', mod.courseId, 'modulos'), {
        ...data,
        nome: `${data.nome} (Cópia)`,
        ordem: (mod.ordem || 0) + 1,
        createdAt: serverTimestamp()
      });
      if (selectedCourse) {
        const mods = await fetchModulesForCourse(selectedCourse.id);
        setModules(mods);
      } else {
        fetchAllModulesGrouped();
      }
    } catch (error) { console.error(error); }
  };

  const handleCreateModule = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedCourse) return;
    try {
      await addDoc(collection(db, 'cursos', selectedCourse.id, 'modulos'), {
        nome: moduleForm.nome,
        ordem: modules.length + 1,
        createdAt: serverTimestamp()
      });
      setShowModuleModal(false);
      setModuleForm({ nome: '' });
      const mods = await fetchModulesForCourse(selectedCourse.id);
      setModules(mods);
    } catch (error) { console.error(error); }
  };

  const handleEditModule = (mod: Module) => {
    setEditingModule(mod);
    setModuleForm({ nome: mod.nome });
    setShowEditModuleModal(true);
  };

  const handleUpdateModule = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingModule) return;
    try {
      const modRef = doc(db, 'cursos', editingModule.courseId, 'modulos', editingModule.id);
      await updateDoc(modRef, { nome: moduleForm.nome });
      setShowEditModuleModal(false);
      setEditingModule(null);
      setModuleForm({ nome: '' });
      if (selectedCourse) {
        const mods = await fetchModulesForCourse(selectedCourse.id);
        setModules(mods);
      } else {
        fetchAllModulesGrouped();
      }
    } catch (error) {
      console.error("Erro ao atualizar módulo:", error);
    }
  };

  const handleSaveLesson = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedCourse || !activeModuleId) return;

    try {
      if (isEditingLesson && editingLessonId) {
        const lessonRef = doc(db, 'cursos', selectedCourse.id, 'modulos', activeModuleId, 'aulas', editingLessonId);
        await updateDoc(lessonRef, { ...lessonForm });
