  const getEmbedUrl = (url: string) => {
    if (!url) return "";
    const ytRegex = /(?:https?:\/\/)?(?:www\.)?(?:youtube\.com\/(?:[^\/\n\s]+\/\S+\/|(?:v|e(?:mbed)?)\/|\S*?[?&]v=)|youtu\.be\/)([a-zA-Z0-9_-]{11})/;
    const ytMatch = url.match(ytRegex);
    if (ytMatch && ytMatch[1]) {
      // enablejsapi=1 é necessário para os comandos postMessage
      return `https://www.youtube.com/embed/${ytMatch[1]}?modestbranding=1&rel=0&iv_load_policy=3&disablekb=1&controls=${selectedCourse ? '1' : '0'}&showinfo=0&enablejsapi=1&origin=${window.location.origin}`;
    }
    return url;
