                <textarea value={lessonForm.descricao} onChange={e => setLessonForm({...lessonForm, descricao: e.target.value})} placeholder="Descrição Pedagógica" className="w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm resize-none" rows={3}></textarea>
                <div className="grid grid-cols-2 gap-4">
                  <input value={lessonForm.videoUrl} onChange={e => setLessonForm({...lessonForm, videoUrl: e.target.value})} placeholder="URL YouTube" className="w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm" />
                  <input value={lessonForm.materialUrl} onChange={e => setLessonForm({...lessonForm, materialUrl: e.target.value})} placeholder="Material PDF" className="w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm" />
                </div>
                <div className="flex gap-3">
                  <button type="button" onClick={() => { setShowLessonModal(false); setIsEditingLesson(false); setEditingLessonId(null); setLessonForm({titulo:'', descricao:'', videoUrl:'', materialUrl:''}); }} className="flex-1 px-4 py-3 border border-slate-200 text-slate-600 rounded-xl font-bold text-sm">Cancelar</button>
                  <button type="submit" className="flex-1 bg-indigo-600 text-white py-3 rounded-xl font-bold text-sm">
                    {isEditingLesson ? 'Salvar Alterações' : 'Publicar Conteúdo'}
