                        </div>
                        <p className="text-[10px] text-slate-500 leading-relaxed">
                          {selectedCourse ? 'Navegação e conclusão liberadas para conferência técnica do professor.' : 'A conclusão é liberada apenas após o cronômetro interno completar 5 minutos.'}
                        </p>
                      </div>

                      <div className="bg-slate-50 p-6 rounded-2xl text-center border border-slate-100">
                        {(!selectedCourse && isPlaying) ? ( // Apenas mostra o cronômetro para aluno, enquanto assiste
                          <div className="py-2 flex flex-col items-center gap-1 text-slate-900 font-bold uppercase text-2xl tracking-widest">
                            {Math.floor(timeLeft / 60).toString().padStart(2, '0')}:{(timeLeft % 60).toString().padStart(2, '0')}
                            <span className="text-[10px] text-slate-500">Tempo Restante</span>
                          </div>
                        ) : (
                          isConcluded ? (
                            <div className="py-2 flex flex-col items-center gap-1 text-emerald-600 font-bold uppercase text-[10px] tracking-widest animate-in zoom-in duration-300"><CheckCircle size={24} />Métricas Completas</div>
                          ) : (
                            <div className="py-2 flex flex-col items-center gap-1 text-slate-400 font-bold uppercase text-[10px] tracking-widest"><Play size={24} />Aguardando Play</div>
                          )
