      if (isEditingCourse && editingCourseId) {
        const courseRef = doc(db, 'cursos', editingCourseId);
        await updateDoc(courseRef, { ...courseForm });

        if (selectedCourse?.id === editingCourseId) {
          setSelectedCourse({ ...selectedCourse, ...courseForm });
        }
      } else {
        await addDoc(collection(db, 'cursos'), {
          ...courseForm,
          professorId: user.uid,
          inscritos: 0,
          status: 'rascunho',
          createdAt: serverTimestamp()
        });
      }

      handleCloseCourseModal();
      await fetchMyCourses();
    } catch (error) {
      console.error("Erro ao salvar curso:", error);
    } finally {
      setLoading(false);
    }
  };

