                  <div className="space-y-1"><label className="text-[10px] font-black text-slate-400 uppercase ml-1">Docente Responsável</label><input required value={courseForm.professorResponsavel} onChange={e => setCourseForm({...courseForm, professorResponsavel: e.target.value})} className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-2xl text-sm outline-none focus:ring-2 focus:ring-indigo-500" /></div>
                  <div className="grid grid-cols-2 gap-4">
                    <div className="space-y-1"><label className="text-[10px] font-black text-slate-400 uppercase ml-1">Carga Horária</label><input required value={courseForm.cargaHoraria} onChange={e => setCourseForm({...courseForm, cargaHoraria: e.target.value})} placeholder="40h" className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-2xl text-sm outline-none focus:ring-2 focus:ring-indigo-500" /></div>
                    <div className="space-y-1"><label className="text-[10px] font-black text-slate-400 uppercase ml-1">Público</label><select value={courseForm.publicoAlvo} onChange={e => setCourseForm({...courseForm, publicoAlvo: e.target.value as any})} className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-2xl text-sm outline-none focus:ring-2 focus:ring-indigo-500"><option value="Geral">Geral</option><option value="Líderes">Líderes</option><option value="Obreiros">Obreiros</option></select></div>
                  </div>
                </div>
                <div className="space-y-4">
                  <div className="space-y-1"><label className="text-[10px] font-black text-slate-400 uppercase ml-1">Tema / Categoria</label><input value={courseForm.tema} onChange={e => setCourseForm({...courseForm, tema: e.target.value})} placeholder="Ex: História da Igreja" className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-2xl text-sm outline-none focus:ring-2 focus:ring-indigo-500" /></div>
                  <div className="space-y-1">
                    <label className="text-[10px] font-black text-slate-400 uppercase ml-1">Capa (Max 5MB)</label>
                    <div className="relative h-32 w-full bg-slate-50 border-2 border-dashed border-slate-200 rounded-2xl flex flex-col items-center justify-center hover:border-indigo-400 transition-all cursor-pointer">
                      <input type="file" accept="image/*" onChange={handleFileUpload} className="absolute inset-0 opacity-0 cursor-pointer" />
                      {courseForm.capaUrl ? <img src={courseForm.capaUrl} className="w-full h-full object-cover rounded-2xl" /> : <><FileUp size={24} className="text-slate-300" /><span className="text-[10px] font-bold text-slate-400 uppercase">Enviar Imagem</span></>}
                    </div>
                  </div>
                </div>
              </div>

              <div className="flex items-center gap-3 p-4 bg-slate-50 rounded-2xl border border-slate-200 shadow-inner">
                <input 
                  type="checkbox" 
                  id="geraCertificado" 
                  checked={courseForm.geraCertificado} 
                  onChange={e => setCourseForm({...courseForm, geraCertificado: e.target.checked})}
                  className="w-5 h-5 rounded border-slate-300 text-indigo-600 focus:ring-indigo-500 cursor-pointer" 
                />
                <label htmlFor="geraCertificado" className="text-xs font-bold text-slate-700 cursor-pointer select-none">Este curso emite certificado de conclusão automático ao final? (Sim/Não)</label>
              </div>

              <div className="space-y-1"><label className="text-[10px] font-black text-slate-400 uppercase ml-1">Ementa Completa</label><textarea rows={3} value={courseForm.descricaoLonga} onChange={e => setCourseForm({...courseForm, descricaoLonga: e.target.value})} className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-2xl text-sm resize-none outline-none focus:ring-2 focus:ring-indigo-500" placeholder="Descreva os objetivos principais do curso..."></textarea></div>

              <div className="flex gap-3 pt-4">
                <button type="button" onClick={handleCloseCourseModal} className="flex-1 px-4 py-4 border border-slate-200 text-slate-600 rounded-2xl font-bold text-sm hover:bg-slate-50 transition-all">Descartar</button>
                <button 
                  type="submit" 
                  disabled={loading}
                  className={`flex-[2] bg-slate-900 text-white py-4 rounded-2xl font-black text-sm uppercase tracking-widest shadow-xl transition-all ${loading ? 'opacity-50 cursor-not-allowed' : 'hover:bg-slate-800 active:scale-95'}`}
                >
                  {loading ? 'Processando...' : (isEditingCourse ? 'Salvar Alterações' : 'Criar Curso')}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default ProfessorView;

import React, { useState, useEffect, useRef } from 'react';
import { 
  collection, 
  query, 
  where, 
  getDocs, 
  addDoc, 
  deleteDoc,
  serverTimestamp, 
  orderBy,
  doc,
  updateDoc
} from 'firebase/firestore';
import { db } from '../firebase';
import { Course, Module, Lesson, User, ProfessorSubView } from '../types';
import { 
  BookOpen, 
  Plus, 
  X, 
  ChevronRight, 
  Play, 
  Pause, 
  Volume2, 
  VolumeX, 
  Maximize, 
  FileText, 
  MoreVertical, 
  ArrowLeft, 
  Layout, 
  Trash2, 
  Layers, 
  Eye, 
  CheckCircle, 
  Copy, 
  Edit, 
  GraduationCap, 
  FileUp, 
  ShieldCheck,
  FileDown,
  Settings,
  Lock // Adicionado ícone de cadeado
} from 'lucide-react';

// Declaração global para a API do YouTube
declare global {
  interface Window {
    YT: any;
    onYouTubeIframeAPIReady: () => void;
    _onYouTubeIframeAPIReadyHandlers: Function[]; // Adiciona a fila de handlers
  }
}

interface ProfessorViewProps {
  user: User;
  activeSub: ProfessorSubView;
  setActiveSub: (view: ProfessorSubView) => void;
}

const ProfessorView: React.FC<ProfessorViewProps> = ({ user, activeSub, setActiveSub }) => {
  const [myCourses, setMyCourses] = useState<Course[]>([]);
  const [loading, setLoading] = useState(true);
  const [selectedCourse, setSelectedCourse] = useState<Course | null>(null);
  const [modules, setModules] = useState<Module[]>([]);
  const [lessonsByModule, setLessonsByModule] = useState<Record<string, Lesson[]>>({});
  const [allModulesGrouped, setAllModulesGrouped] = useState<Record<string, { course: Course, modules: Module[] }>>({});
  const [openMenuId, setOpenMenuId] = useState<string | null>(null);

  // Modal States
  const [showCourseModal, setShowCourseModal] = useState(false);
  const [isEditingCourse, setIsEditingCourse] = useState(false);
  const [editingCourseId, setEditingCourseId] = useState<string | null>(null);

  const [showModuleModal, setShowModuleModal] = useState(false);
  const [showEditModuleModal, setShowEditModuleModal] = useState(false);
  const [showLessonModal, setShowLessonModal] = useState(false);
  const [isEditingLesson, setIsEditingLesson] = useState(false);
  const [activeModuleId, setActiveModuleId] = useState<string | null>(null);
  const [editingModule, setEditingModule] = useState<Module | null>(null);
  const [editingLessonId, setEditingLessonId] = useState<string | null>(null);

  // Preview States
  const [previewLesson, setPreviewLesson] = useState<Lesson | null>(null);
  const [isConcluded, setIsConcluded] = useState(false); 
  const [isPlaying, setIsPlaying] = useState(false); // True se o player está montado e o usuário clicou play no cover
  const [playerState, setPlayerState] = useState<number | null>(null); // YT.PlayerState
  const [timeLeft, setTimeLeft] = useState(300); // 5 minutos = 300 segundos
  const timerIntervalRef = useRef<number | null>(null); // Ref para o intervalo do cronômetro
  const [showWelcomeModal, setShowWelcomeModal] = useState(false); // Novo estado para o modal de boas-vindas
  const [youtubeApiReady, setYoutubeApiReady] = useState(false); // Estado para rastrear se a API do YouTube está pronta
  const [showCompletionModal, setShowCompletionModal] = useState(false); // Novo estado para o modal de conclusão da aula

  // Custom Player States
  const [ytPlayer, setYtPlayer] = useState<any>(null); // State para a instância do YT.Player
  const [playerVolume, setPlayerVolume] = useState(80);
  const [isMuted, setIsMuted] = useState(false);
  const iframeRef = useRef<HTMLIFrameElement>(null); // Ref for the iframe element
  const playerContainerRef = useRef<HTMLDivElement>(null); // Ref for the overall player container div

  // Form States
  const [courseForm, setCourseForm] = useState({
    nome: '',
    tema: '',
    professorResponsavel: user.displayName || '',
    descricaoLonga: '',
    capaUrl: '',
    cargaHoraria: '',
    publicoAlvo: 'Geral' as const,
    geraCertificado: false
  });
  const [moduleForm, setModuleForm] = useState({ nome: '' });
  const [lessonForm, setLessonForm] = useState({
    titulo: '',
    descricao: '',
    videoUrl: '',
    materialUrl: ''
  });

  const fetchMyCourses = async () => {
    setLoading(true);
    try {
      const q = query(collection(db, 'cursos'), where('professorId', '==', user.uid), orderBy('createdAt', 'desc'));
      const querySnapshot = await getDocs(q);
      const fetched: Course[] = [];
      querySnapshot.forEach((doc) => {
        fetched.push({ id: doc.id, ...doc.data() } as Course);
      });
      setMyCourses(fetched);
    } catch (error) {
      console.error("Erro ao carregar cursos:", error);
    } finally {
      setLoading(false);
    }
  };

  const fetchModulesForCourse = async (courseId: string) => {
    const q = query(collection(db, 'cursos', courseId, 'modulos'), orderBy('ordem', 'asc'));
    const querySnapshot = await getDocs(q);
    const fetched: Module[] = [];
    querySnapshot.forEach((doc) => {
      fetched.push({ id: doc.id, ...doc.data(), courseId } as Module);
    });
    return fetched;
  };

  const fetchAllModulesGrouped = async () => {
    setLoading(true);
    try {
      const grouped: Record<string, { course: Course, modules: Module[] }> = {};
      for (const course of myCourses) {
        const mods = await fetchModulesForCourse(course.id);
        grouped[course.id] = { course, modules: mods };
      }
      setAllModulesGrouped(grouped);
    } catch (error) {
      console.error("Erro ao agrupar módulos:", error);
    } finally {
      setLoading(false);
    }
  };

  const fetchLessons = async (courseId: string, moduleId: string) => {
    try {
      const q = query(collection(db, 'cursos', courseId, 'modulos', moduleId, 'aulas'), orderBy('ordem', 'asc'));
      const querySnapshot = await getDocs(q);
      const fetched: Lesson[] = [];
      querySnapshot.forEach((doc) => {
        fetched.push({ id: doc.id, ...doc.data() } as Lesson);
      });
      setLessonsByModule(prev => ({ ...prev, [moduleId]: fetched }));
    } catch (error) {
      console.error("Erro ao carregar aulas:", error);
    }
  };

  useEffect(() => {
    fetchMyCourses();
  }, [user.uid]);

  // Carrega módulos agrupados apenas quando na aba 'modulos'
  useEffect(() => {
    if (activeSub === 'modulos') {
      fetchAllModulesGrouped();
    }
  }, [activeSub, myCourses]);

  // Effect 1: Load YouTube API script and manage global callback
  useEffect(() => {
    if (typeof window === 'undefined') return;

    const loadScript = () => {
      if (!document.getElementById('youtube-iframe-api-script')) {
        const tag = document.createElement('script');
        tag.src = 'https://www.youtube.com/iframe_api';
        tag.id = 'youtube-iframe-api-script';
        tag.async = true; // Make script loading non-blocking
        const firstScriptTag = document.getElementsByTagName('script')[0];
        if (firstScriptTag && firstScriptTag.parentNode) {
          firstScriptTag.parentNode.insertBefore(tag, firstScriptTag);
        } else {
          document.head.appendChild(tag); // Fallback if no script tag found
        }
      }
    };

    // Ensure _onYouTubeIframeAPIReadyHandlers queue exists and manage window.onYouTubeIframeAPIReady
    if (!(window as any)._onYouTubeIframeAPIReadyHandlers) {
      (window as any)._onYouTubeIframeAPIReadyHandlers = [];
      const originalYTReady = window.onYouTubeIframeAPIReady; // Store original if it exists
      window.onYouTubeIframeAPIReady = () => {
        originalYTReady?.(); // Call original if it existed
        (window as any)._onYouTubeIframeAPIReadyHandlers.forEach((handler: Function) => handler());
      };
    }

    // Add our component's handler to the queue
    const componentReadyHandler = () => {
      setYoutubeApiReady(true);
    };
    (window as any)._onYouTubeIframeAPIReadyHandlers.push(componentReadyHandler);

    // If the API is already loaded (e.g., script cached, or a previous component loaded it)
    if (window.YT && window.YT.Player) {
      setYoutubeApiReady(true);
    } else {
      loadScript();
    }

    return () => {
      // Cleanup: remove our handler from the queue when component unmounts
      (window as any)._onYouTubeIframeAPIReadyHandlers = (window as any)._onYouTubeIframeAPIReadyHandlers.filter(
        (handler: Function) => handler !== componentReadyHandler
      );
    };
  }, []); // Empty dependency array means it runs once on mount

  // Effect 2: Manage YouTube Player instance
  useEffect(() => {
    // Conditions to create player: lesson, API ready, modal closed, and iframe ref ready
    const shouldCreatePlayer = previewLesson && youtubeApiReady && !showWelcomeModal && iframeRef.current;

    // Clean up existing player if conditions change or component unmounts
    const cleanupPlayer = () => {
      if (ytPlayer) {
        ytPlayer.destroy();
        setYtPlayer(null);
      }
    };

    if (shouldCreatePlayer) {
      const videoId = getYouTubeVideoId(previewLesson.videoUrl);
      if (!videoId) {
        console.warn("Invalid YouTube video URL provided. Cannot create player.");
        cleanupPlayer(); // Ensure player is cleaned up even on invalid URL
        return;
      }

      // If player needs to be re-created, destroy existing one first
      if (ytPlayer) {
        cleanupPlayer();
      }

      const newPlayer = new window.YT.Player(iframeRef.current, {
        videoId: videoId,
        playerVars: {
          modestbranding: 1, rel: 0, iv_load_policy: 3, disablekb: 1,
          controls: selectedCourse ? 1 : 0, showinfo: 0, enablejsapi: 1,
          origin: window.location.origin,
          autoplay: isPlaying ? 1 : 0, // Autoplay only if user initiated (isPlaying is true)
          mute: isPlaying ? 0 : 1,     // Mute initially if not playing to allow autoplay
        },
        events: {
          onReady: onPlayerReady,
          onStateChange: onPlayerStateChange,
        },
      });
      setYtPlayer(newPlayer);
    } else {
      // If conditions for player creation are not met, ensure it's destroyed
      cleanupPlayer();
    }

    // Additional cleanup for non-player related states when previewLesson is gone
    if (!previewLesson) {
      setIsConcluded(false);
      setIsPlaying(false);
      setPlayerState(null);
      if (timerIntervalRef.current) {
        clearInterval(timerIntervalRef.current);
        timerIntervalRef.current = null;
      }
    }

    return cleanupPlayer; // Cleanup on unmount or re-run
  }, [
    previewLesson,
    youtubeApiReady, // Player depends on API readiness
    showWelcomeModal, // Player depends on welcome modal state
    isPlaying, // Player autoplay param depends on this
    selectedCourse // Player controls param depends on this
  ]);

  // Lógica do Cronômetro de 5 minutos (Resiliente)
  useEffect(() => {
    // Cronômetro só para aluno, quando o player está tocando E o tempo não acabou
    const isPlayingForStudent = !selectedCourse && playerState === window.YT?.PlayerState?.PLAYING; // Safeguard here too

    if (isPlayingForStudent && timeLeft > 0) {
      if (!timerIntervalRef.current) { // Se o timer não está ativo, inicia
        timerIntervalRef.current = window.setInterval(() => {
          setTimeLeft(prevTime => {
            if (prevTime <= 1) {
              if (timerIntervalRef.current) {
                clearInterval(timerIntervalRef.current);
                timerIntervalRef.current = null;
              }
              setIsConcluded(true); // Aula concluída para o aluno
              if (!showCompletionModal) { // Exibe o modal de conclusão
                setShowCompletionModal(true);
              }
              return 0;
            }
            return prevTime - 1;
          });
        }, 1000);
      }
    } else if (timerIntervalRef.current) { // Se não está tocando ou tempo esgotado, para o timer
      clearInterval(timerIntervalRef.current);
      timerIntervalRef.current = null;
    }

    return () => { // Cleanup do timer ao desmontar ou mudar dependências
      if (timerIntervalRef.current) {
        clearInterval(timerIntervalRef.current);
        timerIntervalRef.current = null;
      }
    };
  }, [playerState, timeLeft, selectedCourse, showCompletionModal]);


  const getYouTubeVideoId = (url: string) => {
    const ytRegex = /(?:https?:\/\/)?(?:www\.)?(?:youtube\.com\/(?:[^\/\n\s]+\/\S+\/|(?:v|e(?:mbed)?)\/|\S*?[?&]v=)|youtu\.be\/)([a-zA-Z0-9_-]{11})/;
    const ytMatch = url.match(ytRegex);
    return ytMatch && ytMatch[1];
  };

  const onPlayerReady = (event: any) => {
    // Força a qualidade máxima disponível
    const availableQualities = event.target.getAvailableQualityLevels();
    if (availableQualities.includes('hd1080')) {
      event.target.setPlaybackQuality('hd1080');
    } else if (availableQualities.includes('highres')) {
      event.target.setPlaybackQuality('highres');
    } else if (availableQualities.includes('large')) { // Fallback para 720p
      event.target.setPlaybackQuality('large');
    } else {
      event.target.setPlaybackQuality('high'); // Fallback geral
    }

    // Configura o volume inicial e o estado mudo
    event.target.setVolume(playerVolume);
    if (isMuted) event.target.mute();
    else event.target.unMute();

    // Se o player for inicializado com isPlaying true, ele deve tocar
    if (isPlaying && event.target.getPlayerState() !== window.YT.PlayerState.PLAYING) {
      event.target.playVideo();
    }
  };

  const onPlayerStateChange = (event: any) => {
    // Safeguard: Ensure window.YT.PlayerState is available
    if (!window.YT || !window.YT.PlayerState) {
      console.warn("YouTube API PlayerState not available. Skipping state change handling.");
      return;
    }

    setPlayerState(event.data);
    if (event.data === window.YT.PlayerState.ENDED) {
      if (!selectedCourse) { 
        setIsConcluded(true); 
        if (!showCompletionModal) setShowCompletionModal(true);
      }
      setIsPlaying(false); // Retorna à capa ou estado "parado"
    } else if (event.data === window.YT.PlayerState.PAUSED) {
      setIsPlaying(false); // Se pausar, o overlay de play reaparece
    } else if (event.data === window.YT.PlayerState.PLAYING) {
      setIsPlaying(true); // Se estiver tocando, o overlay de play desaparece
    }
  };

  // Funções de controle do player customizado
  const togglePlay = () => {
    // Safeguard: Ensure ytPlayer and window.YT.PlayerState are available
    if (!ytPlayer || !window.YT || !window.YT.PlayerState) { 
      // If no player or API not ready, this is the initial click on the cover/welcome modal
      setIsPlaying(true); // This will trigger the player to mount/autoplay
      setShowWelcomeModal(false); // Ensure welcome modal is closed
      return;
    }

    // If player exists and API is ready
    if (ytPlayer.getPlayerState() === window.YT.PlayerState.PLAYING) {
      ytPlayer.pauseVideo();
      // state will be updated via onPlayerStateChange
    } else {
      ytPlayer.playVideo();
      // state will be updated via onPlayerStateChange
    }
  };

  const toggleMute = () => {
    // Safeguard
    if (!ytPlayer || !window.YT || !window.YT.PlayerState) return; 
    if (isMuted) {
      ytPlayer.unMute();
      ytPlayer.setVolume(playerVolume);
    } else {
      ytPlayer.mute();
    }
    setIsMuted(prev => !prev);
  };

  const handleVolumeChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const vol = parseInt(e.target.value);
    setPlayerVolume(vol);
    // Safeguard
    if (ytPlayer && !isMuted && window.YT && window.YT.PlayerState) { 
      ytPlayer.setVolume(vol);
    }
  };

  const toggleFullscreen = () => {
    if (playerContainerRef.current) {
      if (!document.fullscreenElement) playerContainerRef.current.requestFullscreen();
      else document.exitFullscreen();
    }
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    if (file.size > 5 * 1024 * 1024) {
      alert("A imagem de capa não pode exceder 5 MB.");
      e.target.value = '';
      return;
    }
    const reader = new FileReader();
    reader.onloadend = () => {
      setCourseForm(prev => ({ ...prev, capaUrl: reader.result as string }));
    };
    reader.readAsDataURL(file);
  };

  const handleSaveCourse = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      setLoading(true);
      if (isEditingCourse && editingCourseId) {
        const courseRef = doc(db, 'cursos', editingCourseId);
        await updateDoc(courseRef, { ...courseForm });

        if (selectedCourse?.id === editingCourseId) {
          setSelectedCourse({ ...selectedCourse, ...courseForm });
        }
      } else {
        await addDoc(collection(db, 'cursos'), {
          ...courseForm,
          professorId: user.uid,
          inscritos: 0,
          status: 'rascunho',
          createdAt: serverTimestamp()
        });
      }

      handleCloseCourseModal();
      await fetchMyCourses();
    } catch (error) {
      console.error("Erro ao salvar curso:", error);
    } finally {
      setLoading(false);
    }
  };

  const handleEditCourseInfo = (course: Course) => {
    setCourseForm({
      nome: course.nome,
      tema: course.tema || '',
      professorResponsavel: course.professorResponsavel || '',
      descricaoLonga: course.descricaoLonga || '',
      capaUrl: course.capaUrl || '',
      cargaHoraria: course.cargaHoraria,
      publicoAlvo: course.publicoAlvo,
      geraCertificado: course.geraCertificado || false
    });
    setEditingCourseId(course.id);
    setIsEditingCourse(true);
    setShowCourseModal(true);
    setOpenMenuId(null); // Fecha qualquer menu de contexto
  };

  const handleCloseCourseModal = () => {
    setShowCourseModal(false);
    setIsEditingCourse(false);
    setEditingCourseId(null);
    setCourseForm({ // Reseta o formulário
      nome: '',
      tema: '',
      professorResponsavel: user.displayName || '',
      descricaoLonga: '',
      capaUrl: '',
      cargaHoraria: '',
      publicoAlvo: 'Geral',
      geraCertificado: false
    });
  };

  const handleDeleteCourse = async (courseId: string) => {
    if (!confirm("Tem certeza que deseja excluir o curso inteiro?")) return;
    try {
      await deleteDoc(doc(db, 'cursos', courseId));
      setMyCourses(prev => prev.filter(c => c.id !== courseId));
      setOpenMenuId(null);
    } catch (error) { console.error(error); }
  };

  const handleDuplicateCourse = async (course: Course) => {
    try {
      const { id, ...data } = course;
      await addDoc(collection(db, 'cursos'), {
        ...data,
        nome: `${data.nome} (Cópia)`,
        createdAt: serverTimestamp()
      });
      fetchMyCourses();
      setOpenMenuId(null);
    } catch (error) { console.error(error); }
  };

  const handleDeleteModule = async (courseId: string, moduleId: string) => {
    if (!confirm("Excluir este módulo?")) return;
    try {
      await deleteDoc(doc(db, 'cursos', courseId, 'modulos', moduleId));
      if (selectedCourse) {
        setModules(prev => prev.filter(m => m.id !== moduleId));
      } else {
        fetchAllModulesGrouped();
      }
    } catch (error) { console.error(error); }
  };

  const handleDuplicateModule = async (mod: Module) => {
    try {
      const { id, ...data } = mod;
      await addDoc(collection(db, 'cursos', mod.courseId, 'modulos'), {
        ...data,
        nome: `${data.nome} (Cópia)`,
        ordem: (mod.ordem || 0) + 1,
        createdAt: serverTimestamp()
      });
      if (selectedCourse) {
        const mods = await fetchModulesForCourse(selectedCourse.id);
        setModules(mods);
      } else {
        fetchAllModulesGrouped();
      }
    } catch (error) { console.error(error); }
  };

  const handleCreateModule = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedCourse) return;
    try {
      await addDoc(collection(db, 'cursos', selectedCourse.id, 'modulos'), {
        nome: moduleForm.nome,
        ordem: modules.length + 1,
        createdAt: serverTimestamp()
      });
      setShowModuleModal(false);
      setModuleForm({ nome: '' });
      const mods = await fetchModulesForCourse(selectedCourse.id);
      setModules(mods);
    }
    catch (error) { console.error(error); }
  };

  const handleEditModule = (mod: Module) => {
    setEditingModule(mod);
    setModuleForm({ nome: mod.nome });
    setShowEditModuleModal(true);
  };

  const handleUpdateModule = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingModule) return;
    try {
      const modRef = doc(db, 'cursos', editingModule.courseId, 'modulos', editingModule.id);
      await updateDoc(modRef, { nome: moduleForm.nome });
      setShowEditModuleModal(false);
      setEditingModule(null);
      setModuleForm({ nome: '' });
      if (selectedCourse) {
        const mods = await fetchModulesForCourse(selectedCourse.id);
        setModules(mods);
      } else {
        fetchAllModulesGrouped();
      }
    } catch (error) {
      console.error("Erro ao atualizar módulo:", error);
    }
  };

  const handleSaveLesson = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedCourse || !activeModuleId) return;

    try {
      if (isEditingLesson && editingLessonId) {
        const lessonRef = doc(db, 'cursos', selectedCourse.id, 'modulos', activeModuleId, 'aulas', editingLessonId);
        await updateDoc(lessonRef, { ...lessonForm });
      } else {
        await addDoc(collection(db, 'cursos', selectedCourse.id, 'modulos', activeModuleId, 'aulas'), {
          ...lessonForm,
          ordem: (lessonsByModule[activeModuleId]?.length || 0) + 1,
          createdAt: serverTimestamp()
        });
      }

      setShowLessonModal(false);
      setIsEditingLesson(false);
      setEditingLessonId(null);
      setLessonForm({ titulo: '', descricao: '', videoUrl: '', materialUrl: '' });
      fetchLessons(selectedCourse.id, activeModuleId);

      if (previewLesson && previewLesson.id === editingLessonId) {
        setPreviewLesson(null);
      }
    } catch (error) { console.error(error); }
  };

  const handleDeleteLesson = async (moduleId: string, lessonId: string) => {
    if (!selectedCourse) return;
    if (!confirm("Tem certeza que deseja DESTRUIR esta aula permanentemente?")) return;
    try {
      await deleteDoc(doc(db, 'cursos', selectedCourse.id, 'modulos', moduleId, 'aulas', lessonId));
      fetchLessons(selectedCourse.id, moduleId);
      if (previewLesson?.id === lessonId) setPreviewLesson(null);
    } catch (error) { console.error(error); }
  };

  const handleEditLesson = (lesson: Lesson, moduleId: string) => {
    setActiveModuleId(moduleId);
    setLessonForm({
      titulo: lesson.titulo,
      descricao: lesson.descricao || '',
      videoUrl: lesson.videoUrl,
      materialUrl: lesson.materialUrl
    });
    setEditingLessonId(lesson.id);
    setIsEditingLesson(true);
    setShowLessonModal(true);
  };

  const openCourseDetail = async (course: Course) => {
    setSelectedCourse(course);
    const mods = await fetchModulesForCourse(course.id);
    setModules(mods);
    for (const mod of mods) {
      fetchLessons(course.id, mod.id);
    }
  };

  const openPreview = (lesson: Lesson, moduleId: string) => {
    setActiveModuleId(moduleId);
    setPreviewLesson(lesson);
    setIsPlaying(false); // Sempre começa com a capa/modal
    setPlayerState(null); // Reseta o estado do player
    setTimeLeft(300); // Reseta o cronômetro
    setIsConcluded(!!selectedCourse); // Professor: isConcluded é true por padrão. Aluno: false.
    setShowWelcomeModal(!selectedCourse); // Aluno: Mostra o modal de boas-vindas. Professor: Ignora.
    setShowCompletionModal(false); // Garante que o modal de conclusão não esteja aberto
  };

  const handleNextLesson = () => {
    if (!previewLesson || !activeModuleId || !selectedCourse) return;

    const currentModuleIndex = modules.findIndex(mod => mod.id === activeModuleId);
    if (currentModuleIndex === -1) return;

    const currentModuleLessons = lessonsByModule[activeModuleId] || [];
    const currentLessonIndex = currentModuleLessons.findIndex(
      (lesson: Lesson) => lesson.id === previewLesson.id
    );

    if (currentLessonIndex !== -1 && currentLessonIndex < currentModuleLessons.length - 1) {
      // Há próxima aula no módulo atual
      const nextLesson = currentModuleLessons[currentLessonIndex + 1];
      openPreview(nextLesson, activeModuleId);
    } else if (currentModuleIndex < modules.length - 1) {
      // Última aula do módulo atual, tenta o próximo módulo
      const nextModule = modules[currentModuleIndex + 1];
      const nextModuleLessons = lessonsByModule[nextModule.id] || [];
      if (nextModuleLessons.length > 0) {
        openPreview(nextModuleLessons[0], nextModule.id); // Primeira aula do próximo módulo
      } else {
        // Próximo módulo vazio, retorna ao painel do curso
        setPreviewLesson(null);
        setSelectedCourse(selectedCourse); // Para forçar o re-render se o curso já estiver selecionado
      }
    } else {
      // Última aula do último módulo, retorna ao painel do curso
      setPreviewLesson(null);
      setSelectedCourse(selectedCourse);
    }
    setShowCompletionModal(false); // Fecha o modal após navegar
  };

  const handleReturnToDashboard = () => {
    setPreviewLesson(null);
    setShowCompletionModal(false); // Fecha o modal
    // Não precisa de setActiveView('dashboard') se já estiver no construtor
  };


  // VISTA: VISÃO GERAL DE MÓDULOS (Sidebar independente)
  if (activeSub === 'modulos') {
    return (
      <div className="space-y-6 animate-in fade-in duration-500">
        <header className="flex items-center justify-between">
          <div>
            <h1 className="text-2xl font-bold text-slate-900 tracking-tight">Gestão Global de Módulos</h1>
            <p className="text-slate-500 text-sm">Organização da matriz curricular de todos os cursos ativos.</p>
          </div>
          {selectedCourse && (
            <button onClick={() => setActiveSub('cursos')} className="flex items-center gap-2 bg-white border border-slate-200 text-slate-600 px-4 py-2 rounded-xl text-sm font-bold hover:bg-slate-50 shadow-sm transition-all">
              <ArrowLeft size={18} /> Voltar ao Construtor
            </button>
          )}
        </header>

        {loading ? (
          <div className="flex items-center justify-center p-20"><div className="h-8 w-8 animate-spin rounded-full border-4 border-indigo-600 border-t-transparent"></div></div>
        ) : Object.keys(allModulesGrouped).length === 0 ? (
          <div className="bg-white p-20 rounded-2xl border border-slate-200 text-center opacity-50">
            <Layers size={48} className="mx-auto mb-4 text-slate-300" />
            <p className="font-bold text-slate-900">Nenhum módulo encontrado</p>
          </div>
        ) : (
          <div className="space-y-8">
            {Object.values(allModulesGrouped).map(({ course, modules }) => (
              <div key={course.id} className="bg-white rounded-2xl border border-slate-200 shadow-sm overflow-hidden">
                <div className="px-6 py-4 border-b border-slate-100 flex items-center justify-between bg-slate-50/50">
                  <div className="flex items-center gap-3">
                    <BookOpen size={16} className="text-indigo-600" />
                    <h2 className="text-sm font-bold text-slate-800 uppercase tracking-widest">{course.nome}</h2>
                  </div>
                  <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">{modules.length} Módulos</span>
                </div>
                <div className="overflow-x-auto">
                  <table className="w-full text-left">
                    <thead className="bg-slate-50/30 text-[10px] font-black text-slate-400 uppercase tracking-tighter border-b border-slate-100">
                      <tr>
                        <th className="px-6 py-3">Nome do Módulo</th>
                        <th className="px-6 py-3">Ordem</th>
                        <th className="px-6 py-3 text-right">Ações</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-100 text-sm">
                      {modules.map(mod => (
                        <tr key={mod.id} className="hover:bg-slate-50/50 transition-colors">
                          <td className="px-6 py-4 font-semibold text-slate-900">{mod.nome}</td>
                          <td className="px-6 py-4 text-slate-500">Unidade {mod.ordem}</td>
                          <td className="px-6 py-4">
                            <div className="flex items-center justify-end gap-1">
                              <button onClick={() => { setActiveSub('cursos'); openCourseDetail(course); }} className="p-2 text-indigo-600 hover:bg-indigo-50 rounded-lg transition-colors" title="Abrir no Construtor"><Layout size={16} /></button>
                              <button onClick={() => handleEditModule(mod)} className="p-2 text-slate-400 hover:bg-slate-100 rounded-lg transition-colors" title="Editar"><Edit size={16} /></button>
                              <button onClick={() => handleDeleteModule(course.id, mod.id)} className="p-2 text-red-500 hover:bg-red-50 rounded-lg transition-colors" title="Excluir"><Trash2 size={16} /></button>
                            </div>
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              </div>
            ))}
          </div>
        )}

        {showEditModuleModal && (
          <div className="fixed inset-0 z-[110] flex items-center justify-center p-4 bg-slate-900/40 backdrop-blur-sm">
            <div className="bg-white w-full max-w-md rounded-2xl shadow-2xl p-6">
              <h3 className="font-bold text-slate-900 mb-4">Editar Módulo</h3>
              <form onSubmit={handleUpdateModule} className="space-y-4">
                <input required autoFocus value={moduleForm.nome} onChange={e => setModuleForm({nome: e.target.value})} placeholder="Título do Módulo" className="w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm outline-none" />
                <div className="flex gap-3">
                  <button type="button" onClick={() => { setShowEditModuleModal(false); setEditingModule(null); setModuleForm({nome:''}); }} className="flex-1 px-4 py-2.5 border border-slate-200 text-slate-600 rounded-xl font-bold text-sm">Cancelar</button>
                  <button type="submit" className="flex-1 bg-indigo-600 text-white py-2.5 rounded-xl font-bold text-sm shadow-lg shadow-indigo-100">Salvar Alterações</button>
                </div>
              </form>
            </div>
          </div>
        )}
      </div>
    );
  }

  // VISTA: CONSTRUTOR DE CURSO
  if (activeSub === 'cursos' && selectedCourse) {
    return (
      <div className="space-y-6 animate-in fade-in duration-500">
        <header className="flex items-center justify-between gap-4">
          <div className="flex items-center gap-4">
            <button onClick={() => setSelectedCourse(null)} className="h-10 w-10 bg-white border border-slate-200 hover:bg-slate-50 rounded-xl text-slate-600 transition-all shadow-sm flex items-center justify-center"><ArrowLeft size={20} /></button>
            <div>
              <h1 className="text-2xl font-bold text-slate-900 leading-tight">{selectedCourse.nome}</h1>
              <div className="flex items-center gap-3 mt-1">
                <span className="text-slate-500 text-sm">{selectedCourse.tema}</span>
                {selectedCourse.geraCertificado && (
                  <span className="flex items-center gap-1 bg-emerald-100 text-emerald-700 text-[9px] font-black uppercase px-2 py-0.5 rounded-md">
                    <CheckCircle size={10} /> Emite Certificado
                  </span>
                )}
              </div>
            </div>
          </div>
          <div className="flex items-center gap-2">
            {/* REMOVIDO: Botão "Editar Info do Curso" do header do construtor */}
            <button onClick={() => setShowModuleModal(true)} className="flex items-center gap-2 bg-indigo-600 text-white px-5 py-2.5 rounded-xl text-sm font-bold hover:bg-indigo-700 shadow-lg shadow-indigo-100"><Plus size={18} /> Novo Módulo</button>
          </div>
        </header>

        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
          <div className="lg:col-span-2 space-y-4">
            <div className="bg-white rounded-2xl border border-slate-200 shadow-sm overflow-hidden">
              <div className="px-6 py-4 border-b border-slate-100 flex items-center justify-between bg-slate-50/50">
                <h2 className="text-xs font-bold text-slate-800 uppercase tracking-widest">Estrutura Curricular</h2>
                <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">{modules.length} Módulos</span>
              </div>
              <div className="p-4 space-y-4">
                {modules.map((mod) => (
                  <div key={mod.id} className="border border-slate-100 rounded-xl overflow-hidden group bg-slate-50/20">
                    <div className="px-4 py-3 border-b border-slate-100 flex items-center justify-between bg-white group-hover:bg-slate-50/50 transition-colors">
                      <h3 className="font-bold text-slate-800 text-sm">Unidade {mod.ordem}: {mod.nome}</h3>
                      <div className="flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                        <button onClick={() => { setActiveModuleId(mod.id); setIsEditingLesson(false); setEditingLessonId(null); setLessonForm({titulo:'', descricao:'', videoUrl:'', materialUrl:''}); setShowLessonModal(true); }} className="p-1.5 text-indigo-600 hover:bg-indigo-50 rounded-lg transition-colors" title="Adicionar Aula"><Plus size={18} /></button>
                        <button onClick={() => handleEditModule(mod)} className="p-1.5 text-slate-400 hover:bg-slate-50 rounded-lg transition-colors" title="Editar Módulo"><Edit size={18} /></button>
                        <button onClick={() => handleDeleteModule(selectedCourse.id, mod.id)} className="p-1.5 text-red-400 hover:bg-red-50 rounded-lg transition-colors" title="Excluir Módulo"><Trash2 size={18} /></button>
                      </div>
                    </div>
                    <div className="p-2 space-y-1">
                      {lessonsByModule[mod.id]?.map((lesson) => (
                        <div key={lesson.id} className="flex items-center justify-between p-3 rounded-xl hover:bg-white hover:shadow-sm transition-all group/lesson bg-transparent">
                          <div className="flex items-center gap-4">
                            <div className="p-2 bg-white border border-slate-100 text-indigo-600 rounded-lg"><Play size={12} fill="currentColor" /></div>
                            <span className="text-sm font-semibold text-slate-700">{lesson.titulo}</span>
                          </div>
                          <div className="flex items-center gap-1 opacity-0 group-hover/lesson:opacity-100 transition-all">
                            <button onClick={() => openPreview(lesson, mod.id)} className="p-1.5 text-indigo-600 hover:bg-indigo-50 rounded-lg transition-colors" title="Preview Blindado (Simulação Aluno)"><Eye size={16} /></button>
                            <button onClick={() => handleEditLesson(lesson, mod.id)} className="p-1.5 text-slate-400 hover:bg-slate-100 rounded-lg transition-colors" title="Editar Aula"><Edit size={16} /></button>
                            <button onClick={() => handleDeleteLesson(mod.id, lesson.id)} className="p-1.5 text-red-400 hover:bg-red-50 rounded-lg transition-colors" title="Excluir Aula"><Trash2 size={16} /></button>
                          </div>
                        </div>
                      ))}
                    </div>
                  </div>
                ))}
              </div>
            </div>
          </div>

          <div className="bg-white p-5 rounded-2xl border border-slate-200 shadow-sm sticky top-24 h-fit">
            <img src={selectedCourse.capaUrl || 'https://images.unsplash.com/photo-1504052434139-443c40c98408?w=800'} className="w-full h-40 object-cover rounded-xl mb-4 border border-slate-100 shadow-sm" />
            <div className="space-y-3">
              <div className="flex justify-between border-b pb-2"><span className="text-[10px] text-slate-400 uppercase font-black">Professor</span><span className="text-xs font-bold">{selectedCourse.professorResponsavel}</span></div>
              <div className="flex justify-between border-b pb-2"><span className="text-[10px] text-slate-400 uppercase font-black">Carga Horária</span><span className="text-xs font-bold">{selectedCourse.cargaHoraria}</span></div>
              <div className="flex justify-between border-b pb-2"><span className="text-[10px] text-slate-400 uppercase font-black">Público Alvo</span><span className="text-xs font-bold">{selectedCourse.publicoAlvo}</span></div>
              <p className="text-[11px] text-slate-500 leading-relaxed italic">{selectedCourse.descricaoLonga}</p>
            </div>
          </div>
        </div>

        {/* MODAL: NOVA AULA / EDIÇÃO DE AULA */}
        {showLessonModal && (
          <div className="fixed inset-0 z-[120] flex items-center justify-center p-4 bg-slate-900/40 backdrop-blur-sm">
            <div className="bg-white w-full max-w-lg rounded-2xl shadow-2xl p-6">
              <h3 className="font-bold text-slate-900 mb-4">{isEditingLesson ? 'Editar Aula' : 'Adicionar Aula'}</h3>
              <form onSubmit={handleSaveLesson} className="space-y-4">
                <input required value={lessonForm.titulo} onChange={e => setLessonForm({...lessonForm, titulo: e.target.value})} placeholder="Título da Aula" className="w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm" />
                <textarea value={lessonForm.descricao} onChange={e => setLessonForm({...lessonForm, descricao: e.target.value})} placeholder="Descrição Pedagógica" className="w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm resize-none outline-none" rows={3}></textarea>
                <div className="grid grid-cols-2 gap-4">
                  <input value={lessonForm.videoUrl} onChange={e => setLessonForm({...lessonForm, videoUrl: e.target.value})} placeholder="URL YouTube" className="w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm outline-none" />
                  <input value={lessonForm.materialUrl} onChange={e => setLessonForm({...lessonForm, materialUrl: e.target.value})} placeholder="Link do PDF" className="w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm outline-none" />
                </div>
                <div className="flex gap-3">
                  <button type="button" onClick={() => { setShowLessonModal(false); setIsEditingLesson(false); setEditingLessonId(null); setLessonForm({titulo:'', descricao:'', videoUrl:'', materialUrl:''}); }} className="flex-1 px-4 py-3 border border-slate-200 text-slate-600 rounded-xl font-bold text-sm">Cancelar</button>
                  <button type="submit" className="flex-1 bg-indigo-600 text-white py-3 rounded-xl font-bold text-sm shadow-lg shadow-indigo-100">
                    {isEditingLesson ? 'Salvar Alterações' : 'Publicar Conteúdo'}
                  </button>
                </div>
              </form>
            </div>
          </div>
        )}
      </div>
    );
  }

  // REPRODUTOR DE AULA (STREAMING VIEW) - Substitui o modal fixo anterior
  if (previewLesson && selectedCourse) { // Mostra esta view apenas se há uma aula em preview E um curso selecionado
    return (
      <div className="fixed inset-0 z-[100] bg-slate-900/95 backdrop-blur-md animate-in fade-in duration-300 overflow-y-auto">
        <div className="max-w-[1440px] mx-auto p-4 md:p-6 lg:p-8 flex flex-col h-full">
          <header className="flex items-center justify-between mb-6 pb-4 border-b border-slate-800">
            <div className="flex items-center gap-4">
              <button onClick={() => setPreviewLesson(null)} className="h-10 w-10 bg-slate-800 border border-slate-700 hover:bg-slate-700 rounded-xl text-slate-300 transition-all shadow-sm flex items-center justify-center"><ArrowLeft size={20} /></button>
              <div>
                <h1 className="text-xl font-bold text-white leading-tight">{selectedCourse.nome}</h1>
                <p className="text-slate-400 text-sm mt-0.5">Construtor de Cursos</p>
              </div>
            </div>
            <button onClick={() => setPreviewLesson(null)} className="px-4 py-2 bg-slate-800 hover:bg-slate-700 rounded-xl text-slate-300 text-xs font-bold transition-colors">Fechar Preview</button>
          </header>

          <div className="flex-1 grid grid-cols-1 lg:grid-cols-4 gap-6">
            {/* Coluna Principal: Player de Vídeo e Detalhes da Aula */}
            <div className="lg:col-span-3 space-y-6">
              {/* MODAL DE BOAS-VINDAS PARA ALUNOS */}
              {showWelcomeModal && !selectedCourse ? (
                <div className="aspect-video bg-indigo-700 rounded-3xl overflow-hidden shadow-2xl border-4 border-white relative flex items-center justify-center text-center p-8 animate-in zoom-in duration-300">
                  <button onClick={() => setShowWelcomeModal(false)} className="absolute top-4 right-4 text-white hover:text-indigo-200"><X size={24} /></button>
                  <div className="relative z-10 space-y-6 max-w-lg">
                    <p className="text-white text-xl font-semibold leading-relaxed">
                      Bem-vindo à aula! Para uma melhor experiência, procure um ambiente tranquilo, use fones de ouvido e coloque-se em uma posição confortável.
                    </p>
                    <button 
                      onClick={() => setShowWelcomeModal(false)} 
                      className="px-8 py-4 bg-emerald-500 text-white rounded-full text-lg font-bold shadow-lg shadow-emerald-500/30 hover:bg-emerald-600 transition-all active:scale-95 flex items-center justify-center gap-3 mx-auto"
                    >
                      <Play size={24} fill="currentColor" /> Entendi! Começar Aula
                    </button>
                  </div>
                  <div className="absolute inset-0 bg-gradient-to-br from-indigo-800 to-purple-900 opacity-80"></div>
                  <BookOpen size={160} className="absolute text-white/5 opacity-50" />
                </div>
              ) : (
                /* CONTAINER DO PLAYER: Blindagem com Overlay de Segurança para Aluno, Livre para Professor */
                <div ref={playerContainerRef} className="aspect-video bg-slate-900 rounded-3xl overflow-hidden shadow-2xl border-4 border-white/5 relative group">

                  {/* Iframe do vídeo (agora com API do YouTube) */}
                  {/* Renderiza o iframe APENAS se o modal de boas-vindas estiver fechado */}
                  {(!showWelcomeModal && youtubeApiReady) && ( // Ensure API is ready
                    <iframe 
                      ref={iframeRef} 
                      width="100%" 
                      height="100%" 
                      title="Video Player" 
                      frameBorder="0" 
                      allow="accelerometer; autoplay; encrypted-media; gyroscope; picture-in-picture" 
                      allowFullScreen
                      // Professor pode interagir nativamente, Aluno não pode interagir com o iframe
                      className={selectedCourse ? "pointer-events-auto" : "pointer-events-none"} 
                    ></iframe>
                  )}

                  {/* CAPA (THUMBNAIL) COM BOTÃO DE PLAY */}
                  {(!isPlaying && !showWelcomeModal && youtubeApiReady) && ( // Ensure API is ready to show thumbnail
                    <div 
                      className="absolute inset-0 z-10 bg-black/60 flex items-center justify-center pointer-events-auto cursor-pointer"
                      onClick={togglePlay} // Clica na capa -> Inicia o play
                    >
                      <img 
                        src={`https://img.youtube.com/vi/${getYouTubeVideoId(previewLesson.videoUrl)}/sddefault.jpg`} 
                        alt="Video Thumbnail" 
                        className="absolute inset-0 w-full h-full object-cover opacity-50"
                      />
                      <div className="relative z-10 w-20 h-20 bg-white/20 backdrop-blur-xl border border-white/30 rounded-full flex items-center justify-center text-white transition-all shadow-2xl hover:scale-110 active:scale-95">
                        <Play size={40} fill="currentColor" />
                      </div>
                    </div>
                  )}

                  <div className="absolute inset-0 z-20 pointer-events-none flex flex-col justify-end">
                    {/* CONTROLES CUSTOMIZADOS DO ALUNO: Visíveis apenas para Aluno e quando o player está tocando/pausado */}
                    {!selectedCourse && !showWelcomeModal && (
                      <div className="p-4 bg-gradient-to-t from-black/80 to-transparent opacity-0 group-hover:opacity-100 transition-opacity pointer-events-auto">
                        <div className="flex items-center justify-between gap-6 px-4">
                          <div className="flex items-center gap-4">
                            <button onClick={togglePlay} className="text-white hover:text-indigo-400 transition-colors">
                              {playerState === window.YT?.PlayerState?.PLAYING ? <Pause size={24} fill="currentColor" /> : <Play size={24} fill="currentColor" />}
                            </button>
                            <div className="flex items-center gap-3 group/vol">
                              <button onClick={toggleMute} className="text-white hover:text-indigo-400 transition-colors">{(isMuted || playerVolume === 0) ? <VolumeX size={20} /> : <Volume2 size={20} />}</button>
                              <input type="range" min="0" max="100" value={isMuted ? 0 : playerVolume} onChange={handleVolumeChange} className="w-20 h-1.5 bg-white/20 rounded-full appearance-none cursor-pointer accent-indigo-500 hover:accent-indigo-400 transition-all" />
                            </div>
                          </div>
                          <button onClick={toggleFullscreen} className="text-white hover:text-indigo-400 transition-colors"><Maximize size={20} /></button>
                        </div>
                      </div>
                    )}
                  </div>
                </div>
              )}

              {/* Informações da Aula */}
              <div className="p-8 bg-slate-800 rounded-3xl shadow-lg border border-slate-700 space-y-4">
                <h2 className="text-3xl font-extrabold text-white leading-tight">{previewLesson.titulo}</h2>
                <p className="text-sm text-slate-300 leading-relaxed whitespace-pre-wrap">{previewLesson.descricao || "Nenhuma descrição detalhada disponível para este tópico."}</p>

                {/* Botão de download do PDF - visível apenas quando concluído (para aluno) ou para professor */}
                {((isConcluded || selectedCourse) && previewLesson.materialUrl && !showWelcomeModal) && (
                  <a 
                    href={previewLesson.materialUrl} 
                    target="_blank" 
                    rel="noopener noreferrer" 
                    className="inline-flex items-center justify-center gap-2 mt-4 px-6 py-3 bg-indigo-600 text-white rounded-xl font-bold text-sm transition-all shadow-lg shadow-indigo-500/30 hover:bg-indigo-700 animate-in slide-in-from-bottom duration-300"
                  >
                    <FileDown size={18} />
                    Baixar Material em PDF
                  </a>
                )}
              </div>
            </div>

            {/* Coluna Lateral: Playlist e Métricas */}
            <div className="lg:col-span-1 space-y-6">
              <div className="bg-slate-800 p-6 rounded-3xl shadow-lg border border-slate-700 h-[calc(100vh-14rem)] overflow-y-auto">
                <h3 className="text-lg font-bold text-indigo-400 uppercase tracking-widest mb-6">Playlist do Curso</h3>

                {modules.map(mod => (
                  <div key={mod.id} className="mb-6 last:mb-0">
                    <h4 className="font-bold text-lg text-white mb-3 flex items-center gap-2">
                      <Layers size={18} className="text-indigo-400" /> Unidade {mod.ordem}: {mod.nome}
                    </h4>
                    <div className="space-y-2">
                      {lessonsByModule[mod.id]?.map(lesson => {
                        const isCurrent = previewLesson?.id === lesson.id;
                        const isUnlocked = selectedCourse || isConcluded; // Simplificado para fins de exemplo

                        return (
                          <button
                            key={lesson.id}
                            onClick={() => openPreview(lesson, mod.id)}
                            className={`flex items-center justify-between w-full p-3 rounded-xl transition-all ${
                              isCurrent 
                                ? 'bg-indigo-600 text-white shadow-md' 
                                : 'bg-slate-700 text-slate-300 hover:bg-slate-600'
                            }`}
                          >
                            <span className="flex items-center gap-3 text-sm font-medium">
                              {isCurrent ? <Play size={16} fill="currentColor" /> : (
                                isUnlocked ? <CheckCircle size={16} className="text-emerald-400" /> : <Lock size={16} className="text-slate-500" />
                              )}
                              {lesson.titulo}
                            </span>
                            {!isCurrent && <ChevronRight size={16} className="text-slate-400" />}
                          </button>
                        );
                      })}
                    </div>
                  </div>
                ))}
              </div>

              {/* Métricas Pedagógicas - Visível apenas para o aluno */}
              {!selectedCourse && (
                <div className="bg-slate-800 p-6 rounded-3xl shadow-lg border border-slate-700 text-center">
                  <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-4">Seu Progresso</h4>
                  <div className="py-2 flex flex-col items-center gap-1 text-slate-100 font-bold uppercase text-2xl tracking-widest">
                    {Math.floor(timeLeft / 60).toString().padStart(2, '0')}:{(timeLeft % 60).toString().padStart(2, '0')}
                    <span className="text-[10px] text-slate-500">Tempo Restante de Reprodução</span>
                  </div>
                </div>
              )}
            </div>
          </div>
        </div>

        {/* MODAL DE CONCLUSÃO DA AULA */}
        {showCompletionModal && !selectedCourse && (
          <div className="fixed inset-0 z-[210] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm animate-in fade-in duration-300">
            <div className="bg-white w-full max-w-md rounded-2xl shadow-2xl p-6 text-center animate-in zoom-in-95 duration-200">
              <CheckCircle size={48} className="text-emerald-500 mx-auto mb-4" />
              <h3 className="font-bold text-slate-900 text-xl mb-2">Aula Concluída!</h3>
              <p className="text-slate-600 text-sm mb-6">Parabéns! Você concluiu os requisitos mínimos para esta aula. O que deseja fazer a seguir?</p>

              <div className="flex flex-col gap-3">
                <button 
                  onClick={handleNextLesson} 
                  className="flex items-center justify-center gap-2 px-6 py-3 bg-indigo-600 text-white rounded-xl font-bold text-sm shadow-lg shadow-indigo-100 hover:bg-indigo-700 transition-all active:scale-95"
                >
                  <ChevronRight size={18} /> Próxima Aula
                </button>
                <button 
                  onClick={handleReturnToDashboard} 
                  className="flex items-center justify-center gap-2 px-6 py-3 border border-slate-200 text-slate-600 rounded-xl font-bold text-sm hover:bg-slate-50 transition-all"
                >
                  <BookOpen size={18} /> Voltar ao Painel do Curso
                </button>
              </div>
            </div>
          </div>
        )}
      </div>
    );
  }

  // VISTA: DASHBOARD / GRADE DE CURSOS
  return (
    <div className="space-y-6 animate-in fade-in duration-500">
      <header className="flex flex-col sm:flex-row items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold text-slate-900 tracking-tight">Portal do Professor</h1>
          <p className="text-slate-500 text-sm font-medium">Gestão acadêmica e configuração de cursos EAD.</p>
        </div>
        <button onClick={() => { setIsEditingCourse(false); setEditingCourseId(null); setCourseForm({ nome: '', tema: '', professorResponsavel: user.displayName || '', descricaoLonga: '', capaUrl: '', cargaHoraria: '', publicoAlvo: 'Geral', geraCertificado: false }); setShowCourseModal(true); }} className="flex items-center gap-2 bg-indigo-600 text-white px-5 py-3 rounded-xl text-sm font-bold hover:bg-indigo-700 transition-all shadow-lg shadow-indigo-100"><Plus size={18} /> Novo Curso</button>
      </header>

      <div className="grid grid-cols-1 md:grid-cols-3 xl:grid-cols-6 gap-4">
        {loading ? (
          <div className="col-span-full py-20 flex justify-center"><div className="h-6 w-6 animate-spin rounded-full border-2 border-indigo-600 border-t-transparent"></div></div>
        ) : myCourses.map(course => (
          <div key={course.id} onClick={() => openCourseDetail(course)} className="bg-white border border-slate-200 rounded-2xl overflow-hidden hover:shadow-xl hover:border-indigo-200 transition-all group cursor-pointer flex flex-col relative overflow-visible">
            <div className="absolute top-2 right-2 z-50">
              <button onClick={(e) => { e.stopPropagation(); setOpenMenuId(openMenuId === course.id ? null : course.id); }} className="p-1.5 bg-white/90 backdrop-blur-sm rounded-lg border border-slate-200 text-slate-500 hover:text-indigo-600 shadow-sm transition-all"><MoreVertical size={14} /></button>
              {openMenuId === course.id && (
                <div className="absolute right-0 mt-1 w-32 bg-white rounded-xl shadow-2xl border border-slate-100 z-50 animate-in zoom-in-95 duration-100 overflow-hidden text-[10px] font-bold">
                  <button onClick={(e) => { e.stopPropagation(); handleEditCourseInfo(course); }} className="w-full px-3 py-2 text-left hover:bg-slate-50 flex items-center gap-2 transition-colors"><Edit size={12} /> Editar Info</button>
                  <button onClick={(e) => { e.stopPropagation(); handleDuplicateCourse(course); }} className="w-full px-3 py-2 text-left hover:bg-slate-50 flex items-center gap-2 transition-colors"><Copy size={12} /> Duplicar</button>
                  <button onClick={(e) => { e.stopPropagation(); handleDeleteCourse(course.id); }} className="w-full px-3 py-2 text-left hover:bg-red-50 text-red-500 flex items-center gap-2 transition-colors"><Trash2 size={12} /> Excluir</button>
                </div>
              )}
            </div>

            <div className="h-24 overflow-hidden bg-slate-100 border-b border-slate-100 relative">
              {course.capaUrl ? <img src={course.capaUrl} className="w-full h-full object-cover transition-transform group-hover:scale-105" /> : <div className="h-full flex items-center justify-center text-slate-200"><BookOpen size={32} /></div>}
              <div className="absolute top-1 left-1 flex gap-1"><span className={`px-1.5 py-0.5 rounded text-[8px] font-black uppercase shadow-sm ${course.status === 'ativo' ? 'bg-emerald-500 text-white' : 'bg-slate-700 text-white'}`}>{course.status}</span></div>
            </div>
            <div className="p-3 flex-1 flex flex-col">
              <h3 className="font-bold text-slate-900 text-xs mb-1 group-hover:text-indigo-600 transition-colors leading-tight line-clamp-2">{course.nome}</h3>
              <p className="text-[8px] text-slate-400 font-bold uppercase tracking-widest mb-2">{course.tema || 'Geral'}</p>
              <div className="mt-auto pt-2 border-t border-slate-50 flex items-center justify-between text-[8px] text-slate-400 font-black uppercase tracking-widest">
                <div className="flex items-center gap-1"><Layout size={10} /><span>Ver Matriz</span></div>
                <ChevronRight size={10} className="group-hover:translate-x-0.5 transition-transform" />
              </div>
            </div>
          </div>
        ))}
      </div>

      {showCourseModal && (
        <div className="fixed inset-0 z-[250] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm animate-in fade-in duration-300">
          <div className="bg-white w-full max-w-2xl rounded-3xl shadow-2xl overflow-hidden animate-in zoom-in-95 duration-200 flex flex-col max-h-[90vh]">
            <div className="p-6 border-b border-slate-100 flex items-center justify-between bg-slate-50/30">
              <div className="flex items-center gap-3">
                <div className="bg-indigo-600 p-2.5 rounded-xl text-white shadow-lg shadow-indigo-100"><GraduationCap size={20} /></div>
                <div><h3 className="font-bold text-slate-900 text-lg">{isEditingCourse ? 'Editar Informações do Curso' : 'Configurar Novo Curso'}</h3><p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest">Currículo e Ementa Acadêmica</p></div>
              </div>
              <button onClick={handleCloseCourseModal} className="text-slate-400 hover:text-slate-600 p-2"><X size={20} /></button>
            </div>

            <form onSubmit={handleSaveCourse} className="p-8 space-y-6 overflow-y-auto">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className="space-y-4">
                  <div className="space-y-1"><label className="text-[10px] font-black text-slate-400 uppercase ml-1">Título do Curso</label><input required autoFocus value={courseForm.nome} onChange={e => setCourseForm({...courseForm, nome: e.target.value})} placeholder="Ex: Teologia Sistemática" className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-2xl text-sm outline-none focus:ring-2 focus:ring-indigo-500" /></div>
                  <div className="space-y-1"><label className="text-[10px] font-black text-slate-400 uppercase ml-1">Docente Responsável</label><input required value={courseForm.professorResponsavel} onChange={e => setCourseForm({...courseForm, professorResponsavel: e.target.value})} className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-2xl text-sm outline-none focus:ring-2 focus:ring-indigo-500" /></div>
                  <div className="grid grid-cols-2 gap-4">
                    <div className="space-y-1"><label className="text-[10px] font-black text-slate-400 uppercase ml-1">Carga Horária</label><input required value={courseForm.cargaHoraria} onChange={e => setCourseForm({...courseForm, cargaHoraria: e.target.value})} placeholder="40h" className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-2xl text-sm outline-none focus:ring-2 focus:ring-indigo-500" /></div>
                    <div className="space-y-1"><label className="text-[10px] font-black text-slate-400 uppercase ml-1">Público</label><select value={courseForm.publicoAlvo} onChange={e => setCourseForm({...courseForm, publicoAlvo: e.target.value as any})} className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-2xl text-sm outline-none focus:ring-2 focus:ring-indigo-500"><option value="Geral">Geral</option><option value="Líderes">Líderes</option><option value="Obreiros">Obreiros</option></select></div>
                  </div>
                </div>
                <div className="space-y-4">
                  <div className="space-y-1"><label className="text-[10px] font-black text-slate-400 uppercase ml-1">Tema / Categoria</label><input value={courseForm.tema} onChange={e => setCourseForm({...courseForm, tema: e.target.value})} placeholder="Ex: História da Igreja" className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-2xl text-sm outline-none focus:ring-2 focus:ring-indigo-500" /></div>
                  <div className="space-y-1">
                    <label className="text-[10px] font-black text-slate-400 uppercase ml-1">Capa (Max 5MB)</label>
                    <div className="relative h-32 w-full bg-slate-50 border-2 border-dashed border-slate-200 rounded-2xl flex flex-col items-center justify-center hover:border-indigo-400 transition-all cursor-pointer">
                      <input type="file" accept="image/*" onChange={handleFileUpload} className="absolute inset-0 opacity-0 cursor-pointer" />
                      {courseForm.capaUrl ? <img src={courseForm.capaUrl} className="w-full h-full object-cover rounded-2xl" /> : <><FileUp size={24} className="text-slate-300" /><span className="text-[10px] font-bold text-slate-400 uppercase">Enviar Imagem</span></>}
                    </div>
                  </div>
                </div>
              </div>

              <div className="flex items-center gap-3 p-4 bg-slate-50 rounded-2xl border border-slate-200 shadow-inner">
                <input 
                  type="checkbox" 
                  id="geraCertificado" 
                  checked={courseForm.geraCertificado} 
                  onChange={e => setCourseForm({...courseForm, geraCertificado: e.target.checked})}
                  className="w-5 h-5 rounded border-slate-300 text-indigo-600 focus:ring-indigo-500 cursor-pointer" 
                />
                <label htmlFor="geraCertificado" className="text-xs font-bold text-slate-700 cursor-pointer select-none">Este curso emite certificado de conclusão automático ao final? (Sim/Não)</label>
              </div>

              <div className="space-y-1"><label className="text-[10px] font-black text-slate-400 uppercase ml-1">Ementa Completa</label><textarea rows={3} value={courseForm.descricaoLonga} onChange={e => setCourseForm({...courseForm, descricaoLonga: e.target.value})} className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-2xl text-sm resize-none outline-none focus:ring-2 focus:ring-indigo-500" placeholder="Descreva os objetivos principais do curso..."></textarea></div>

              <div className="flex gap-3 pt-4">
                <button type="button" onClick={handleCloseCourseModal} className="flex-1 px-4 py-4 border border-slate-200 text-slate-600 rounded-2xl font-bold text-sm hover:bg-slate-50 transition-all">Descartar</button>
                <button 
                  type="submit" 
                  disabled={loading}
                  className={`flex-[2] bg-slate-900 text-white py-4 rounded-2xl font-black text-sm uppercase tracking-widest shadow-xl transition-all ${loading ? 'opacity-50 cursor-not-allowed' : 'hover:bg-slate-800 active:scale-95'}`}
                >
                  {loading ? 'Processando...' : (isEditingCourse ? 'Salvar Alterações' : 'Criar Curso')}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default ProfessorView;

import React, { useState, useEffect, useRef } from 'react';
import { 
  collection, 
  query, 
  where, 
  getDocs, 
  addDoc, 
  deleteDoc,
  serverTimestamp, 
  orderBy,
  doc,
  updateDoc
} from 'firebase/firestore';
import { db } from '../firebase';
import { Course, Module, Lesson, User, ProfessorSubView } from '../types';
import { 
  BookOpen, 
  Plus, 
  X, 
  ChevronRight, 
  Play, 
  Pause, 
  Volume2, 
  VolumeX, 
  Maximize, 
  FileText, 
  MoreVertical, 
  ArrowLeft, 
  Layout, 
  Trash2, 
  Layers, 
  Eye, 
  CheckCircle, 
  Copy, 
  Edit, 
  GraduationCap, 
  FileUp, 
  ShieldCheck,
  FileDown,
  Settings,
  Lock // Adicionado ícone de cadeado
} from 'lucide-react';

// Declaração global para a API do YouTube
declare global {
  interface Window {
    YT: any;
    onYouTubeIframeAPIReady: () => void;
    _onYouTubeIframeAPIReadyHandlers: Function[]; // Adiciona a fila de handlers
  }
}

interface ProfessorViewProps {
  user: User;
  activeSub: ProfessorSubView;
  setActiveSub: (view: ProfessorSubView) => void;
}

const ProfessorView: React.FC<ProfessorViewProps> = ({ user, activeSub, setActiveSub }) => {
  const [myCourses, setMyCourses] = useState<Course[]>([]);
  const [loading, setLoading] = useState(true);
  const [selectedCourse, setSelectedCourse] = useState<Course | null>(null);
  const [modules, setModules] = useState<Module[]>([]);
  const [lessonsByModule, setLessonsByModule] = useState<Record<string, Lesson[]>>({});
  const [allModulesGrouped, setAllModulesGrouped] = useState<Record<string, { course: Course, modules: Module[] }>>({});
  const [openMenuId, setOpenMenuId] = useState<string | null>(null);

  // Modal States
  const [showCourseModal, setShowCourseModal] = useState(false);
  const [isEditingCourse, setIsEditingCourse] = useState(false);
  const [editingCourseId, setEditingCourseId] = useState<string | null>(null);

  const [showModuleModal, setShowModuleModal] = useState(false);
  const [showEditModuleModal, setShowEditModuleModal] = useState(false);
  const [showLessonModal, setShowLessonModal] = useState(false);
  const [isEditingLesson, setIsEditingLesson] = useState(false);
  const [activeModuleId, setActiveModuleId] = useState<string | null>(null);
  const [editingModule, setEditingModule] = useState<Module | null>(null);
  const [editingLessonId, setEditingLessonId] = useState<string | null>(null);

  // Preview States
  const [previewLesson, setPreviewLesson] = useState<Lesson | null>(null);
  const [isConcluded, setIsConcluded] = useState(false); 
  const [isPlaying, setIsPlaying] = useState(false); // True se o player está montado e o usuário clicou play no cover
  const [playerState, setPlayerState] = useState<number | null>(null); // YT.PlayerState
  const [timeLeft, setTimeLeft] = useState(300); // 5 minutos = 300 segundos
  const timerIntervalRef = useRef<number | null>(null); // Ref para o intervalo do cronômetro
  const [showWelcomeModal, setShowWelcomeModal] = useState(false); // Novo estado para o modal de boas-vindas
  const [youtubeApiReady, setYoutubeApiReady] = useState(false); // Estado para rastrear se a API do YouTube está pronta
  const [showCompletionModal, setShowCompletionModal] = useState(false); // Novo estado para o modal de conclusão da aula

  // Custom Player States
  const [ytPlayer, setYtPlayer] = useState<any>(null); // State para a instância do YT.Player
  const [playerVolume, setPlayerVolume] = useState(80);
  const [isMuted, setIsMuted] = useState(false);
  const iframeRef = useRef<HTMLIFrameElement>(null); // Ref for the iframe element
  const playerContainerRef = useRef<HTMLDivElement>(null); // Ref for the overall player container div

  // Form States
  const [courseForm, setCourseForm] = useState({
    nome: '',
    tema: '',
    professorResponsavel: user.displayName || '',
    descricaoLonga: '',
    capaUrl: '',
    cargaHoraria: '',
    publicoAlvo: 'Geral' as const,
    geraCertificado: false
  });
  const [moduleForm, setModuleForm] = useState({ nome: '' });
  const [lessonForm, setLessonForm] = useState({
    titulo: '',
    descricao: '',
    videoUrl: '',
    materialUrl: ''
  });

  const fetchMyCourses = async () => {
    setLoading(true);
    try {
      const q = query(collection(db, 'cursos'), where('professorId', '==', user.uid), orderBy('createdAt', 'desc'));
      const querySnapshot = await getDocs(q);
      const fetched: Course[] = [];
      querySnapshot.forEach((doc) => {
        fetched.push({ id: doc.id, ...doc.data() } as Course);
      });
      setMyCourses(fetched);
    } catch (error) {
      console.error("Erro ao carregar cursos:", error);
    } finally {
      setLoading(false);
    }
  };

  const fetchModulesForCourse = async (courseId: string) => {
    const q = query(collection(db, 'cursos', courseId, 'modulos'), orderBy('ordem', 'asc'));
    const querySnapshot = await getDocs(q);
    const fetched: Module[] = [];
    querySnapshot.forEach((doc) => {
      fetched.push({ id: doc.id, ...doc.data(), courseId } as Module);
    });
    return fetched;
  };

  const fetchAllModulesGrouped = async () => {
    setLoading(true);
    try {
      const grouped: Record<string, { course: Course, modules: Module[] }> = {};
      for (const course of myCourses) {
        const mods = await fetchModulesForCourse(course.id);
        grouped[course.id] = { course, modules: mods };
      }
      setAllModulesGrouped(grouped);
    } catch (error) {
      console.error("Erro ao agrupar módulos:", error);
    } finally {
      setLoading(false);
    }
  };

  const fetchLessons = async (courseId: string, moduleId: string) => {
    try {
      const q = query(collection(db, 'cursos', courseId, 'modulos', moduleId, 'aulas'), orderBy('ordem', 'asc'));
      const querySnapshot = await getDocs(q);
      const fetched: Lesson[] = [];
      querySnapshot.forEach((doc) => {
        fetched.push({ id: doc.id, ...doc.data() } as Lesson);
      });
      setLessonsByModule(prev => ({ ...prev, [moduleId]: fetched }));
    } catch (error) {
      console.error("Erro ao carregar aulas:", error);
    }
  };

  useEffect(() => {
    fetchMyCourses();
  }, [user.uid]);

  // Carrega módulos agrupados apenas quando na aba 'modulos'
  useEffect(() => {
    if (activeSub === 'modulos') {
      fetchAllModulesGrouped();
    }
  }, [activeSub, myCourses]);

  // Effect 1: Load YouTube API script and manage global callback
  useEffect(() => {
    if (typeof window === 'undefined') return;

    const loadScript = () => {
      if (!document.getElementById('youtube-iframe-api-script')) {
        const tag = document.createElement('script');
        tag.src = 'https://www.youtube.com/iframe_api';
        tag.id = 'youtube-iframe-api-script';
        tag.async = true; // Make script loading non-blocking
        const firstScriptTag = document.getElementsByTagName('script')[0];
        if (firstScriptTag && firstScriptTag.parentNode) {
          firstScriptTag.parentNode.insertBefore(tag, firstScriptTag);
        } else {
          document.head.appendChild(tag); // Fallback if no script tag found
        }
      }
    };

    // Ensure _onYouTubeIframeAPIReadyHandlers queue exists and manage window.onYouTubeIframeAPIReady
    if (!(window as any)._onYouTubeIframeAPIReadyHandlers) {
      (window as any)._onYouTubeIframeAPIReadyHandlers = [];
      const originalYTReady = window.onYouTubeIframeAPIReady; // Store original if it exists
      window.onYouTubeIframeAPIReady = () => {
        originalYTReady?.(); // Call original if it existed
        (window as any)._onYouTubeIframeAPIReadyHandlers.forEach((handler: Function) => handler());
      };
    }

    // Add our component's handler to the queue
    const componentReadyHandler = () => {
      setYoutubeApiReady(true);
    };
    (window as any)._onYouTubeIframeAPIReadyHandlers.push(componentReadyHandler);

    // If the API is already loaded (e.g., script cached, or a previous component loaded it)
    if (window.YT && window.YT.Player) {
      setYoutubeApiReady(true);
    } else {
      loadScript();
    }

    return () => {
      // Cleanup: remove our handler from the queue when component unmounts
      (window as any)._onYouTubeIframeAPIReadyHandlers = (window as any)._onYouTubeIframeAPIReadyHandlers.filter(
        (handler: Function) => handler !== componentReadyHandler
      );
    };
  }, []); // Empty dependency array means it runs once on mount

  // Effect 2: Manage YouTube Player instance
  useEffect(() => {
    // Conditions to create player: lesson, API ready, modal closed, and iframe ref ready
    const shouldCreatePlayer = previewLesson && youtubeApiReady && !showWelcomeModal && iframeRef.current;

    // Clean up existing player if conditions change or component unmounts
    const cleanupPlayer = () => {
      if (ytPlayer) {
        ytPlayer.destroy();
        setYtPlayer(null);
      }
    };

    if (shouldCreatePlayer) {
      const videoId = getYouTubeVideoId(previewLesson.videoUrl);
      if (!videoId) {
        console.warn("Invalid YouTube video URL provided. Cannot create player.");
        cleanupPlayer(); // Ensure player is cleaned up even on invalid URL
        return;
      }

      // If player needs to be re-created, destroy existing one first
      if (ytPlayer) {
        cleanupPlayer();
      }

      const newPlayer = new window.YT.Player(iframeRef.current, {
        videoId: videoId,
        playerVars: {
          modestbranding: 1, rel: 0, iv_load_policy: 3, disablekb: 1,
          controls: selectedCourse ? 1 : 0, showinfo: 0, enablejsapi: 1,
          origin: window.location.origin,
          autoplay: isPlaying ? 1 : 0, // Autoplay only if user initiated (isPlaying is true)
          mute: isPlaying ? 0 : 1,     // Mute initially if not playing to allow autoplay
        },
        events: {
          onReady: onPlayerReady,
          onStateChange: onPlayerStateChange,
        },
      });
      setYtPlayer(newPlayer);
    } else {
      // If conditions for player creation are not met, ensure it's destroyed
      cleanupPlayer();
    }

    // Additional cleanup for non-player related states when previewLesson is gone
    if (!previewLesson) {
      setIsConcluded(false);
      setIsPlaying(false);
      setPlayerState(null);
      if (timerIntervalRef.current) {
        clearInterval(timerIntervalRef.current);
        timerIntervalRef.current = null;
      }
    }

    return cleanupPlayer; // Cleanup on unmount or re-run
  }, [
    previewLesson,
    youtubeApiReady, // Player depends on API readiness
    showWelcomeModal, // Player depends on welcome modal state
    isPlaying, // Player autoplay param depends on this
    selectedCourse // Player controls param depends on this
  ]);

  // Lógica do Cronômetro de 5 minutos (Resiliente)
  useEffect(() => {
    // Cronômetro só para aluno, quando o player está tocando E o tempo não acabou
    const isPlayingForStudent = !selectedCourse && playerState === window.YT?.PlayerState?.PLAYING; // Safeguard here too

    if (isPlayingForStudent && timeLeft > 0) {
      if (!timerIntervalRef.current) { // Se o timer não está ativo, inicia
        timerIntervalRef.current = window.setInterval(() => {
          setTimeLeft(prevTime => {
            if (prevTime <= 1) {
              if (timerIntervalRef.current) {
                clearInterval(timerIntervalRef.current);
                timerIntervalRef.current = null;
              }
              setIsConcluded(true); // Aula concluída para o aluno
              if (!showCompletionModal) { // Exibe o modal de conclusão
                setShowCompletionModal(true);
              }
              return 0;
            }
            return prevTime - 1;
          });
        }, 1000);
      }
    } else if (timerIntervalRef.current) { // Se não está tocando ou tempo esgotado, para o timer
      clearInterval(timerIntervalRef.current);
      timerIntervalRef.current = null;
    }

    return () => { // Cleanup do timer ao desmontar ou mudar dependências
      if (timerIntervalRef.current) {
        clearInterval(timerIntervalRef.current);
        timerIntervalRef.current = null;
      }
    };
  }, [playerState, timeLeft, selectedCourse, showCompletionModal]);


  const getYouTubeVideoId = (url: string) => {
    const ytRegex = /(?:https?:\/\/)?(?:www\.)?(?:youtube\.com\/(?:[^\/\n\s]+\/\S+\/|(?:v|e(?:mbed)?)\/|\S*?[?&]v=)|youtu\.be\/)([a-zA-Z0-9_-]{11})/;
    const ytMatch = url.match(ytRegex);
    return ytMatch && ytMatch[1];
  };

  const onPlayerReady = (event: any) => {
    // Força a qualidade máxima disponível
    const availableQualities = event.target.getAvailableQualityLevels();
    if (availableQualities.includes('hd1080')) {
      event.target.setPlaybackQuality('hd1080');
    } else if (availableQualities.includes('highres')) {
      event.target.setPlaybackQuality('highres');
    } else if (availableQualities.includes('large')) { // Fallback para 720p
      event.target.setPlaybackQuality('large');
    } else {
      event.target.setPlaybackQuality('high'); // Fallback geral
    }

    // Configura o volume inicial e o estado mudo
    event.target.setVolume(playerVolume);
    if (isMuted) event.target.mute();
    else event.target.unMute();

    // Se o player for inicializado com isPlaying true, ele deve tocar
    if (isPlaying && event.target.getPlayerState() !== window.YT.PlayerState.PLAYING) {
      event.target.playVideo();
    }
  };

  const onPlayerStateChange = (event: any) => {
    // Safeguard: Ensure window.YT.PlayerState is available
    if (!window.YT || !window.YT.PlayerState) {
      console.warn("YouTube API PlayerState not available. Skipping state change handling.");
      return;
    }

    setPlayerState(event.data);
    if (event.data === window.YT.PlayerState.ENDED) {
      if (!selectedCourse) { 
        setIsConcluded(true); 
        if (!showCompletionModal) setShowCompletionModal(true);
      }
      setIsPlaying(false); // Retorna à capa ou estado "parado"
    } else if (event.data === window.YT.PlayerState.PAUSED) {
      setIsPlaying(false); // Se pausar, o overlay de play reaparece
    } else if (event.data === window.YT.PlayerState.PLAYING) {
      setIsPlaying(true); // Se estiver tocando, o overlay de play desaparece
    }
  };

  // Funções de controle do player customizado
  const togglePlay = () => {
    // Safeguard: Ensure ytPlayer and window.YT.PlayerState are available
    if (!ytPlayer || !window.YT || !window.YT.PlayerState) { 
      // If no player or API not ready, this is the initial click on the cover/welcome modal
      setIsPlaying(true); // This will trigger the player to mount/autoplay
      setShowWelcomeModal(false); // Ensure welcome modal is closed
      return;
    }

    // If player exists and API is ready
    if (ytPlayer.getPlayerState() === window.YT.PlayerState.PLAYING) {
      ytPlayer.pauseVideo();
      // state will be updated via onPlayerStateChange
    } else {
      ytPlayer.playVideo();
      // state will be updated via onPlayerStateChange
    }
  };

  const toggleMute = () => {
    // Safeguard
    if (!ytPlayer || !window.YT || !window.YT.PlayerState) return; 
    if (isMuted) {
      ytPlayer.unMute();
      ytPlayer.setVolume(playerVolume);
    } else {
      ytPlayer.mute();
    }
    setIsMuted(prev => !prev);
  };

  const handleVolumeChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const vol = parseInt(e.target.value);
    setPlayerVolume(vol);
    // Safeguard
    if (ytPlayer && !isMuted && window.YT && window.YT.PlayerState) { 
      ytPlayer.setVolume(vol);
    }
  };

  const toggleFullscreen = () => {
    if (playerContainerRef.current) {
      if (!document.fullscreenElement) playerContainerRef.current.requestFullscreen();
      else document.exitFullscreen();
    }
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    if (file.size > 5 * 1024 * 1024) {
      alert("A imagem de capa não pode exceder 5 MB.");
      e.target.value = '';
      return;
    }
    const reader = new FileReader();
    reader.onloadend = () => {
      setCourseForm(prev => ({ ...prev, capaUrl: reader.result as string }));
    };
    reader.readAsDataURL(file);
  };

  const handleSaveCourse = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      setLoading(true);
      if (isEditingCourse && editingCourseId) {
        const courseRef = doc(db, 'cursos', editingCourseId);
        await updateDoc(courseRef, { ...courseForm });

        if (selectedCourse?.id === editingCourseId) {
          setSelectedCourse({ ...selectedCourse, ...courseForm });
        }
      } else {
        await addDoc(collection(db, 'cursos'), {
          ...courseForm,
          professorId: user.uid,
          inscritos: 0,
          status: 'rascunho',
          createdAt: serverTimestamp()
        });
      }

      handleCloseCourseModal();
      await fetchMyCourses();
    } catch (error) {
      console.error("Erro ao salvar curso:", error);
    } finally {
      setLoading(false);
    }
  };

  const handleEditCourseInfo = (course: Course) => {
    setCourseForm({
      nome: course.nome,
      tema: course.tema || '',
      professorResponsavel: course.professorResponsavel || '',
      descricaoLonga: course.descricaoLonga || '',
      capaUrl: course.capaUrl || '',
      cargaHoraria: course.cargaHoraria,
      publicoAlvo: course.publicoAlvo,
      geraCertificado: course.geraCertificado || false
    });
    setEditingCourseId(course.id);
    setIsEditingCourse(true);
    setShowCourseModal(true);
    setOpenMenuId(null); // Fecha qualquer menu de contexto
  };

  const handleCloseCourseModal = () => {
    setShowCourseModal(false);
    setIsEditingCourse(false);
    setEditingCourseId(null);
    setCourseForm({ // Reseta o formulário
      nome: '',
      tema: '',
      professorResponsavel: user.displayName || '',
      descricaoLonga: '',
      capaUrl: '',
      cargaHoraria: '',
      publicoAlvo: 'Geral',
      geraCertificado: false
    });
  };

  const handleDeleteCourse = async (courseId: string) => {
    if (!confirm("Tem certeza que deseja excluir o curso inteiro?")) return;
    try {
      await deleteDoc(doc(db, 'cursos', courseId));
      setMyCourses(prev => prev.filter(c => c.id !== courseId));
      setOpenMenuId(null);
    } catch (error) { console.error(error); }
  };

  const handleDuplicateCourse = async (course: Course) => {
    try {
      const { id, ...data } = course;
      await addDoc(collection(db, 'cursos'), {
        ...data,
        nome: `${data.nome} (Cópia)`,
        createdAt: serverTimestamp()
      });
      fetchMyCourses();
      setOpenMenuId(null);
    } catch (error) { console.error(error); }
  };

  const handleDeleteModule = async (courseId: string, moduleId: string) => {
    if (!confirm("Excluir este módulo?")) return;
    try {
      await deleteDoc(doc(db, 'cursos', courseId, 'modulos', moduleId));
      if (selectedCourse) {
        setModules(prev => prev.filter(m => m.id !== moduleId));
      } else {
        fetchAllModulesGrouped();
      }
    } catch (error) { console.error(error); }
  };

  const handleDuplicateModule = async (mod: Module) => {
    try {
      const { id, ...data } = mod;
      await addDoc(collection(db, 'cursos', mod.courseId, 'modulos'), {
        ...data,
        nome: `${data.nome} (Cópia)`,
        ordem: (mod.ordem || 0) + 1,
        createdAt: serverTimestamp()
      });
      if (selectedCourse) {
        const mods = await fetchModulesForCourse(selectedCourse.id);
        setModules(mods);
      } else {
        fetchAllModulesGrouped();
      }
    } catch (error) { console.error(error); }
  };

  const handleCreateModule = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedCourse) return;
    try {
      await addDoc(collection(db, 'cursos', selectedCourse.id, 'modulos'), {
        nome: moduleForm.nome,
        ordem: modules.length + 1,
        createdAt: serverTimestamp()
      });
      setShowModuleModal(false);
      setModuleForm({ nome: '' });
      const mods = await fetchModulesForCourse(selectedCourse.id);
      setModules(mods);
    }
    catch (error) { console.error(error); }
  };

  const handleEditModule = (mod: Module) => {
    setEditingModule(mod);
    setModuleForm({ nome: mod.nome });
    setShowEditModuleModal(true);
  };

  const handleUpdateModule = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingModule) return;
    try {
      const modRef = doc(db, 'cursos', editingModule.courseId, 'modulos', editingModule.id);
      await updateDoc(modRef, { nome: moduleForm.nome });
      setShowEditModuleModal(false);
      setEditingModule(null);
      setModuleForm({ nome: '' });
      if (selectedCourse) {
        const mods = await fetchModulesForCourse(selectedCourse.id);
        setModules(mods);
      } else {
        fetchAllModulesGrouped();
      }
    } catch (error) {
      console.error("Erro ao atualizar módulo:", error);
    }
  };

  const handleSaveLesson = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedCourse || !activeModuleId) return;

    try {
      if (isEditingLesson && editingLessonId) {
        const lessonRef = doc(db, 'cursos', selectedCourse.id, 'modulos', activeModuleId, 'aulas', editingLessonId);
        await updateDoc(lessonRef, { ...lessonForm });
      } else {
        await addDoc(collection(db, 'cursos', selectedCourse.id, 'modulos', activeModuleId, 'aulas'), {
          ...lessonForm,
          ordem: (lessonsByModule[activeModuleId]?.length || 0) + 1,
          createdAt: serverTimestamp()
        });
      }

      setShowLessonModal(false);
      setIsEditingLesson(false);
      setEditingLessonId(null);
      setLessonForm({ titulo: '', descricao: '', videoUrl: '', materialUrl: '' });
      fetchLessons(selectedCourse.id, activeModuleId);

      if (previewLesson && previewLesson.id === editingLessonId) {
        setPreviewLesson(null);
      }
    } catch (error) { console.error(error); }
  };

  const handleDeleteLesson = async (moduleId: string, lessonId: string) => {
    if (!selectedCourse) return;
    if (!confirm("Tem certeza que deseja DESTRUIR esta aula permanentemente?")) return;
    try {
      await deleteDoc(doc(db, 'cursos', selectedCourse.id, 'modulos', moduleId, 'aulas', lessonId));
      fetchLessons(selectedCourse.id, moduleId);
      if (previewLesson?.id === lessonId) setPreviewLesson(null);
    } catch (error) { console.error(error); }
  };

  const handleEditLesson = (lesson: Lesson, moduleId: string) => {
    setActiveModuleId(moduleId);
    setLessonForm({
      titulo: lesson.titulo,
      descricao: lesson.descricao || '',
      videoUrl: lesson.videoUrl,
      materialUrl: lesson.materialUrl
    });
    setEditingLessonId(lesson.id);
    setIsEditingLesson(true);
    setShowLessonModal(true);
  };

  const openCourseDetail = async (course: Course) => {
    setSelectedCourse(course);
    const mods = await fetchModulesForCourse(course.id);
    setModules(mods);
    for (const mod of mods) {
      fetchLessons(course.id, mod.id);
    }
  };

  const openPreview = (lesson: Lesson, moduleId: string) => {
    setActiveModuleId(moduleId);
    setPreviewLesson(lesson);
    setIsPlaying(false); // Sempre começa com a capa/modal
    setPlayerState(null); // Reseta o estado do player
    setTimeLeft(300); // Reseta o cronômetro
    setIsConcluded(!!selectedCourse); // Professor: isConcluded é true por padrão. Aluno: false.
    setShowWelcomeModal(!selectedCourse); // Aluno: Mostra o modal de boas-vindas. Professor: Ignora.
    setShowCompletionModal(false); // Garante que o modal de conclusão não esteja aberto
  };

  const handleNextLesson = () => {
    if (!previewLesson || !activeModuleId || !selectedCourse) return;

    const currentModuleIndex = modules.findIndex(mod => mod.id === activeModuleId);
    if (currentModuleIndex === -1) return;

    const currentModuleLessons = lessonsByModule[activeModuleId] || [];
    const currentLessonIndex = currentModuleLessons.findIndex(
      (lesson: Lesson) => lesson.id === previewLesson.id
    );

    if (currentLessonIndex !== -1 && currentLessonIndex < currentModuleLessons.length - 1) {
      // Há próxima aula no módulo atual
      const nextLesson = currentModuleLessons[currentLessonIndex + 1];
      openPreview(nextLesson, activeModuleId);
    } else if (currentModuleIndex < modules.length - 1) {
      // Última aula do módulo atual, tenta o próximo módulo
      const nextModule = modules[currentModuleIndex + 1];
      const nextModuleLessons = lessonsByModule[nextModule.id] || [];
      if (nextModuleLessons.length > 0) {
        openPreview(nextModuleLessons[0], nextModule.id); // Primeira aula do próximo módulo
      } else {
        // Próximo módulo vazio, retorna ao painel do curso
        setPreviewLesson(null);
        setSelectedCourse(selectedCourse); // Para forçar o re-render se o curso já estiver selecionado
      }
    } else {
      // Última aula do último módulo, retorna ao painel do curso
      setPreviewLesson(null);
      setSelectedCourse(selectedCourse);
    }
    setShowCompletionModal(false); // Fecha o modal após navegar
  };

  const handleReturnToDashboard = () => {
    setPreviewLesson(null);
    setShowCompletionModal(false); // Fecha o modal
    // Não precisa de setActiveView('dashboard') se já estiver no construtor
  };


  // REPRODUTOR DE AULA (STREAMING VIEW) - Mostra esta view apenas se há uma aula em preview E um curso selecionado
  // ESTA É A PRIMEIRA CONDIÇÃO PARA GARANTIR QUE SEMPRE SEJA RENDERIZADA QUANDO ATIVA
  if (previewLesson && selectedCourse) { 
    return (
      <div className="fixed inset-0 z-[100] bg-slate-900/95 backdrop-blur-md animate-in fade-in duration-300 overflow-y-auto">
        <div className="max-w-[1440px] mx-auto p-4 md:p-6 lg:p-8 flex flex-col h-full">
          <header className="flex items-center justify-between mb-6 pb-4 border-b border-slate-800">
            <div className="flex items-center gap-4">
              <button onClick={() => setPreviewLesson(null)} className="h-10 w-10 bg-slate-800 border border-slate-700 hover:bg-slate-700 rounded-xl text-slate-300 transition-all shadow-sm flex items-center justify-center"><ArrowLeft size={20} /></button>
              <div>
                <h1 className="text-xl font-bold text-white leading-tight">{selectedCourse.nome}</h1>
                <p className="text-slate-400 text-sm mt-0.5">Construtor de Cursos</p>
              </div>
            </div>
            <button onClick={() => setPreviewLesson(null)} className="px-4 py-2 bg-slate-800 hover:bg-slate-700 rounded-xl text-slate-300 text-xs font-bold transition-colors">Fechar Preview</button>
          </header>

          <div className="flex-1 grid grid-cols-1 lg:grid-cols-4 gap-6">
            {/* Coluna Principal: Player de Vídeo e Detalhes da Aula */}
            <div className="lg:col-span-3 space-y-6">
              {/* MODAL DE BOAS-VINDAS PARA ALUNOS */}
              {showWelcomeModal && !selectedCourse ? (
                <div className="aspect-video bg-indigo-700 rounded-3xl overflow-hidden shadow-2xl border-4 border-white relative flex items-center justify-center text-center p-8 animate-in zoom-in duration-300">
                  <button onClick={() => setShowWelcomeModal(false)} className="absolute top-4 right-4 text-white hover:text-indigo-200"><X size={24} /></button>
                  <div className="relative z-10 space-y-6 max-w-lg">
                    <p className="text-white text-xl font-semibold leading-relaxed">
                      Bem-vindo à aula! Para uma melhor experiência, procure um ambiente tranquilo, use fones de ouvido e coloque-se em uma posição confortável.
                    </p>
                    <button 
                      onClick={() => setShowWelcomeModal(false)} 
                      className="px-8 py-4 bg-emerald-500 text-white rounded-full text-lg font-bold shadow-lg shadow-emerald-500/30 hover:bg-emerald-600 transition-all active:scale-95 flex items-center justify-center gap-3 mx-auto"
                    >
                      <Play size={24} fill="currentColor" /> Entendi! Começar Aula
                    </button>
                  </div>
                  <div className="absolute inset-0 bg-gradient-to-br from-indigo-800 to-purple-900 opacity-80"></div>
                  <BookOpen size={160} className="absolute text-white/5 opacity-50" />
                </div>
              ) : (
                /* CONTAINER DO PLAYER: Blindagem com Overlay de Segurança para Aluno, Livre para Professor */
                <div ref={playerContainerRef} className="aspect-video bg-slate-900 rounded-3xl overflow-hidden shadow-2xl border-4 border-white/5 relative group">

                  {/* Iframe do vídeo (agora com API do YouTube) */}
                  {/* Renderiza o iframe APENAS se o modal de boas-vindas estiver fechado */}
                  {(!showWelcomeModal && youtubeApiReady) && ( // Ensure API is ready
                    <iframe 
                      ref={iframeRef} 
                      width="100%" 
                      height="100%" 
                      title="Video Player" 
                      frameBorder="0" 
                      allow="accelerometer; autoplay; encrypted-media; gyroscope; picture-in-picture" 
                      allowFullScreen
                      // Professor pode interagir nativamente, Aluno não pode interagir com o iframe
                      className={selectedCourse ? "pointer-events-auto" : "pointer-events-none"} 
                    ></iframe>
                  )}

                  {/* CAPA (THUMBNAIL) COM BOTÃO DE PLAY */}
                  {(!isPlaying && !showWelcomeModal && youtubeApiReady) && ( // Ensure API is ready to show thumbnail
                    <div 
                      className="absolute inset-0 z-10 bg-black/60 flex items-center justify-center pointer-events-auto cursor-pointer"
                      onClick={togglePlay} // Clica na capa -> Inicia o play
                    >
                      <img 
                        src={`https://img.youtube.com/vi/${getYouTubeVideoId(previewLesson.videoUrl)}/sddefault.jpg`} 
                        alt="Video Thumbnail" 
                        className="absolute inset-0 w-full h-full object-cover opacity-50"
                      />
                      <div className="relative z-10 w-20 h-20 bg-white/20 backdrop-blur-xl border border-white/30 rounded-full flex items-center justify-center text-white transition-all shadow-2xl hover:scale-110 active:scale-95">
                        <Play size={40} fill="currentColor" />
                      </div>
                    </div>
                  )}

                  <div className="absolute inset-0 z-20 pointer-events-none flex flex-col justify-end">
                    {/* CONTROLES CUSTOMIZADOS DO ALUNO: Visíveis apenas para Aluno e quando o player está tocando/pausado */}
                    {!selectedCourse && !showWelcomeModal && (
                      <div className="p-4 bg-gradient-to-t from-black/80 to-transparent opacity-0 group-hover:opacity-100 transition-opacity pointer-events-auto">
                        <div className="flex items-center justify-between gap-6 px-4">
                          <div className="flex items-center gap-4">
                            <button onClick={togglePlay} className="text-white hover:text-indigo-400 transition-colors">
                              {playerState === window.YT?.PlayerState?.PLAYING ? <Pause size={24} fill="currentColor" /> : <Play size={24} fill="currentColor" />}
                            </button>
                            <div className="flex items-center gap-3 group/vol">
                              <button onClick={toggleMute} className="text-white hover:text-indigo-400 transition-colors">{(isMuted || playerVolume === 0) ? <VolumeX size={20} /> : <Volume2 size={20} />}</button>
                              <input type="range" min="0" max="100" value={isMuted ? 0 : playerVolume} onChange={handleVolumeChange} className="w-20 h-1.5 bg-white/20 rounded-full appearance-none cursor-pointer accent-indigo-500 hover:accent-indigo-400 transition-all" />
                            </div>
                          </div>
                          <button onClick={toggleFullscreen} className="text-white hover:text-indigo-400 transition-colors"><Maximize size={20} /></button>
                        </div>
                      </div>
                    )}
                  </div>
                </div>
              )}

              {/* Informações da Aula */}
              <div className="p-8 bg-slate-800 rounded-3xl shadow-lg border border-slate-700 space-y-4">
                <h2 className="text-3xl font-extrabold text-white leading-tight">{previewLesson.titulo}</h2>
                <p className="text-sm text-slate-300 leading-relaxed whitespace-pre-wrap">{previewLesson.descricao || "Nenhuma descrição detalhada disponível para este tópico."}</p>

                {/* Botão de download do PDF - visível apenas quando concluído (para aluno) ou para professor */}
                {((isConcluded || selectedCourse) && previewLesson.materialUrl && !showWelcomeModal) && (
                  <a 
                    href={previewLesson.materialUrl} 
                    target="_blank" 
                    rel="noopener noreferrer" 
                    className="inline-flex items-center justify-center gap-2 mt-4 px-6 py-3 bg-indigo-600 text-white rounded-xl font-bold text-sm transition-all shadow-lg shadow-indigo-500/30 hover:bg-indigo-700 animate-in slide-in-from-bottom duration-300"
                  >
                    <FileDown size={18} />
                    Baixar Material em PDF
                  </a>
                )}
              </div>
            </div>

            {/* Coluna Lateral: Playlist e Métricas */}
            <div className="lg:col-span-1 space-y-6">
              <div className="bg-slate-800 p-6 rounded-3xl shadow-lg border border-slate-700 h-[calc(100vh-14rem)] overflow-y-auto">
                <h3 className="text-lg font-bold text-indigo-400 uppercase tracking-widest mb-6">Playlist do Curso</h3>

                {modules.map(mod => (
                  <div key={mod.id} className="mb-6 last:mb-0">
                    <h4 className="font-bold text-lg text-white mb-3 flex items-center gap-2">
                      <Layers size={18} className="text-indigo-400" /> Unidade {mod.ordem}: {mod.nome}
                    </h4>
                    <div className="space-y-2">
                      {lessonsByModule[mod.id]?.map(lesson => {
                        const isCurrent = previewLesson?.id === lesson.id;
                        const isUnlocked = selectedCourse || isConcluded; // Simplificado para fins de exemplo

                        return (
                          <button
                            key={lesson.id}
                            onClick={() => openPreview(lesson, mod.id)}
                            className={`flex items-center justify-between w-full p-3 rounded-xl transition-all ${
                              isCurrent 
                                ? 'bg-indigo-600 text-white shadow-md' 
                                : 'bg-slate-700 text-slate-300 hover:bg-slate-600'
                            }`}
                          >
                            <span className="flex items-center gap-3 text-sm font-medium">
                              {isCurrent ? <Play size={16} fill="currentColor" /> : (
                                isUnlocked ? <CheckCircle size={16} className="text-emerald-400" /> : <Lock size={16} className="text-slate-500" />
                              )}
                              {lesson.titulo}
                            </span>
                            {!isCurrent && <ChevronRight size={16} className="text-slate-400" />}
                          </button>
                        );
                      })}
                    </div>
                  </div>
                ))}
              </div>

              {/* Métricas Pedagógicas - Visível apenas para o aluno */}
              {!selectedCourse && (
                <div className="bg-slate-800 p-6 rounded-3xl shadow-lg border border-slate-700 text-center">
                  <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-4">Seu Progresso</h4>
                  <div className="py-2 flex flex-col items-center gap-1 text-slate-100 font-bold uppercase text-2xl tracking-widest">
                    {Math.floor(timeLeft / 60).toString().padStart(2, '0')}:{(timeLeft % 60).toString().padStart(2, '0')}
                    <span className="text-[10px] text-slate-500">Tempo Restante de Reprodução</span>
                  </div>
                </div>
              )}
            </div>
          </div>
        </div>

        {/* MODAL DE CONCLUSÃO DA AULA */}
        {showCompletionModal && !selectedCourse && (
          <div className="fixed inset-0 z-[210] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm animate-in fade-in duration-300">
            <div className="bg-white w-full max-w-md rounded-2xl shadow-2xl p-6 text-center animate-in zoom-in-95 duration-200">
              <CheckCircle size={48} className="text-emerald-500 mx-auto mb-4" />
              <h3 className="font-bold text-slate-900 text-xl mb-2">Aula Concluída!</h3>
              <p className="text-slate-600 text-sm mb-6">Parabéns! Você concluiu os requisitos mínimos para esta aula. O que deseja fazer a seguir?</p>

              <div className="flex flex-col gap-3">
                <button 
                  onClick={handleNextLesson} 
                  className="flex items-center justify-center gap-2 px-6 py-3 bg-indigo-600 text-white rounded-xl font-bold text-sm shadow-lg shadow-indigo-100 hover:bg-indigo-700 transition-all active:scale-95"
                >
                  <ChevronRight size={18} /> Próxima Aula
                </button>
                <button 
                  onClick={handleReturnToDashboard} 
                  className="flex items-center justify-center gap-2 px-6 py-3 border border-slate-200 text-slate-600 rounded-xl font-bold text-sm hover:bg-slate-50 transition-all"
                >
                  <BookOpen size={18} /> Voltar ao Painel do Curso
                </button>
              </div>
            </div>
          </div>
        )}
      </div>
    );
  }


  // VISTA: VISÃO GERAL DE MÓDULOS (Sidebar independente)
  if (activeSub === 'modulos') {
    return (
      <div className="space-y-6 animate-in fade-in duration-500">
        <header className="flex items-center justify-between">
          <div>
            <h1 className="text-2xl font-bold text-slate-900 tracking-tight">Gestão Global de Módulos</h1>
            <p className="text-slate-500 text-sm">Organização da matriz curricular de todos os cursos ativos.</p>
          </div>
          {selectedCourse && (
            <button onClick={() => setActiveSub('cursos')} className="flex items-center gap-2 bg-white border border-slate-200 text-slate-600 px-4 py-2 rounded-xl text-sm font-bold hover:bg-slate-50 shadow-sm transition-all">
              <ArrowLeft size={18} /> Voltar ao Construtor
            </button>
          )}
        </header>

        {loading ? (
          <div className="flex items-center justify-center p-20"><div className="h-8 w-8 animate-spin rounded-full border-4 border-indigo-600 border-t-transparent"></div></div>
        ) : Object.keys(allModulesGrouped).length === 0 ? (
          <div className="bg-white p-20 rounded-2xl border border-slate-200 text-center opacity-50">
            <Layers size={48} className="mx-auto mb-4 text-slate-300" />
            <p className="font-bold text-slate-900">Nenhum módulo encontrado</p>
          </div>
        ) : (
          <div className="space-y-8">
            {Object.values(allModulesGrouped).map(({ course, modules }) => (
              <div key={course.id} className="bg-white rounded-2xl border border-slate-200 shadow-sm overflow-hidden">
                <div className="px-6 py-4 border-b border-slate-100 flex items-center justify-between bg-slate-50/50">
                  <div className="flex items-center gap-3">
                    <BookOpen size={16} className="text-indigo-600" />
                    <h2 className="text-sm font-bold text-slate-800 uppercase tracking-widest">{course.nome}</h2>
                  </div>
                  <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">{modules.length} Módulos</span>
                </div>
                <div className="overflow-x-auto">
                  <table className="w-full text-left">
                    <thead className="bg-slate-50/30 text-[10px] font-black text-slate-400 uppercase tracking-tighter border-b border-slate-100">
                      <tr>
                        <th className="px-6 py-3">Nome do Módulo</th>
                        <th className="px-6 py-3">Ordem</th>
                        <th className="px-6 py-3 text-right">Ações</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-100 text-sm">
                      {modules.map(mod => (
                        <tr key={mod.id} className="hover:bg-slate-50/50 transition-colors">
                          <td className="px-6 py-4 font-semibold text-slate-900">{mod.nome}</td>
                          <td className="px-6 py-4 text-slate-500">Unidade {mod.ordem}</td>
                          <td className="px-6 py-4">
                            <div className="flex items-center justify-end gap-1">
                              <button onClick={() => { setActiveSub('cursos'); openCourseDetail(course); }} className="p-2 text-indigo-600 hover:bg-indigo-50 rounded-lg transition-colors" title="Abrir no Construtor"><Layout size={16} /></button>
                              <button onClick={() => handleEditModule(mod)} className="p-2 text-slate-400 hover:bg-slate-100 rounded-lg transition-colors" title="Editar"><Edit size={16} /></button>
                              <button onClick={() => handleDeleteModule(course.id, mod.id)} className="p-2 text-red-500 hover:bg-red-50 rounded-lg transition-colors" title="Excluir"><Trash2 size={16} /></button>
                            </div>
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              </div>
            ))}
          </div>
        )}

        {showEditModuleModal && (
          <div className="fixed inset-0 z-[110] flex items-center justify-center p-4 bg-slate-900/40 backdrop-blur-sm">
            <div className="bg-white w-full max-w-md rounded-2xl shadow-2xl p-6">
              <h3 className="font-bold text-slate-900 mb-4">Editar Módulo</h3>
              <form onSubmit={handleUpdateModule} className="space-y-4">
                <input required autoFocus value={moduleForm.nome} onChange={e => setModuleForm({nome: e.target.value})} placeholder="Título do Módulo" className="w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm outline-none" />
                <div className="flex gap-3">
                  <button type="button" onClick={() => { setShowEditModuleModal(false); setEditingModule(null); setModuleForm({nome:''}); }} className="flex-1 px-4 py-2.5 border border-slate-200 text-slate-600 rounded-xl font-bold text-sm">Cancelar</button>
                  <button type="submit" className="flex-1 bg-indigo-600 text-white py-2.5 rounded-xl font-bold text-sm shadow-lg shadow-indigo-100">Salvar Alterações</button>
                </div>
              </form>
            </div>
          </div>
        )}
      </div>
    );
  }

  // VISTA: CONSTRUTOR DE CURSO
  if (activeSub === 'cursos' && selectedCourse) {
    return (
      <div className="space-y-6 animate-in fade-in duration-500">
        <header className="flex items-center justify-between gap-4">
          <div className="flex items-center gap-4">
            <button onClick={() => setSelectedCourse(null)} className="h-10 w-10 bg-white border border-slate-200 hover:bg-slate-50 rounded-xl text-slate-600 transition-all shadow-sm flex items-center justify-center"><ArrowLeft size={20} /></button>
            <div>
              <h1 className="text-2xl font-bold text-slate-900 leading-tight">{selectedCourse.nome}</h1>
              <div className="flex items-center gap-3 mt-1">
                <span className="text-slate-500 text-sm">{selectedCourse.tema}</span>
                {selectedCourse.geraCertificado && (
                  <span className="flex items-center gap-1 bg-emerald-100 text-emerald-700 text-[9px] font-black uppercase px-2 py-0.5 rounded-md">
                    <CheckCircle size={10} /> Emite Certificado
                  </span>
                )}
              </div>
            </div>
