                  </div>
                </div>
                <div className="space-y-4">
                  <div className="space-y-1"><label className="text-[10px] font-black text-slate-400 uppercase ml-1">Tema / Categoria</label><input value={courseForm.tema} onChange={e => setCourseForm({...courseForm, tema: e.target.value})} placeholder="Ex: História da Igreja" className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-2xl text-sm outline-none focus:ring-2 focus:ring-indigo-500" /></div>
                  <div className="space-y-1">
                    <label className="text-[10px] font-black text-slate-400 uppercase ml-1">Capa (Max 5MB)</label>
                    <div className="relative h-32 w-full bg-slate-50 border-2 border-dashed border-slate-200 rounded-2xl flex flex-col items-center justify-center hover:border-indigo-400 transition-all cursor-pointer">
                      <input type="file" accept="image/*" onChange={handleFileUpload} className="absolute inset-0 opacity-0 cursor-pointer" />
                      {courseForm.capaUrl ? <img src={courseForm.capaUrl} className="w-full h-full object-cover rounded-2xl" /> : <><FileUp size={24} className="text-slate-300" /><span className="text-[10px] font-bold text-slate-400 uppercase">Enviar Imagem</span></>}
                    </div>
                  </div>
                </div>
              </div>

              <div className="flex items-center gap-3 p-4 bg-slate-50 rounded-2xl border border-slate-200 shadow-inner">
                <input 
                  type="checkbox" 
                  id="geraCertificado" 
                  checked={courseForm.geraCertificado} 
                  onChange={e => setCourseForm({...courseForm, geraCertificado: e.target.checked})}
                  className="w-5 h-5 rounded border-slate-300 text-indigo-600 focus:ring-indigo-500 cursor-pointer" 
                />
                <label htmlFor="geraCertificado" className="text-xs font-bold text-slate-700 cursor-pointer select-none">Este curso emite certificado de conclusão automático ao final? (Sim/Não)</label>
              </div>

              <div className="space-y-1"><label className="text-[10px] font-black text-slate-400 uppercase ml-1">Ementa Completa</label><textarea rows={3} value={courseForm.descricaoLonga} onChange={e => setCourseForm({...courseForm, descricaoLonga: e.target.value})} className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-2xl text-sm resize-none outline-none focus:ring-2 focus:ring-indigo-500" placeholder="Descreva os objetivos principais do curso..."></textarea></div>

              <div className="flex gap-3 pt-4">
                <button type="button" onClick={handleCloseCourseModal} className="flex-1 px-4 py-4 border border-slate-200 text-slate-600 rounded-2xl font-bold text-sm hover:bg-slate-50 transition-all">Descartar</button>
                <button 
                  type="submit" 
                  disabled={loading}
                  className={`flex-[2] bg-slate-900 text-white py-4 rounded-2xl font-black text-sm uppercase tracking-widest shadow-xl transition-all ${loading ? 'opacity-50 cursor-not-allowed' : 'hover:bg-slate-800 active:scale-95'}`}
                >
                  {loading ? 'Processando...' : (isEditingCourse ? 'Salvar Alterações' : 'Criar Curso')}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

