            </div>

            <form onSubmit={handleSaveCourse} className="p-8 space-y-6 overflow-y-auto">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className="space-y-4">
                  <div className="space-y-1"><label className="text-[10px] font-black text-slate-400 uppercase ml-1">Título do Curso</label><input required autoFocus value={courseForm.nome} onChange={e => setCourseForm({...courseForm, nome: e.target.value})} placeholder="Ex: Teologia Sistemática" className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-2xl text-sm outline-none focus:ring-2 focus:ring-indigo-500" /></div>
                  <div className="space-y-1"><label className="text-[10px] font-black text-slate-400 uppercase ml-1">Docente Responsável</label><input required value={courseForm.professorResponsavel} onChange={e => setCourseForm({...courseForm, professorResponsavel: e.target.value})} className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-2xl text-sm outline-none focus:ring-2 focus:ring-indigo-500" /></div>
                  <div className="grid grid-cols-2 gap-4">
                    <div className="space-y-1"><label className="text-[10px] font-black text-slate-400 uppercase ml-1">Carga Horária</label><input required value={courseForm.cargaHoraria} onChange={e => setCourseForm({...courseForm, cargaHoraria: e.target.value})} placeholder="40h" className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-2xl text-sm outline-none focus:ring-2 focus:ring-indigo-500" /></div>
                    <div className="space-y-1"><label className="text-[10px] font-black text-slate-400 uppercase ml-1">Público</label><select value={courseForm.publicoAlvo} onChange={e => setCourseForm({...courseForm, publicoAlvo: e.target.value as any})} className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-2xl text-sm outline-none focus:ring-2 focus:ring-indigo-500"><option value="Geral">Geral</option><option value="Líderes">Líderes</option><option value="Obreiros">Obreiros</option></select></div>
                  </div>
                </div>
                <div className="space-y-4">
                  <div className="space-y-1"><label className="text-[10px] font-black text-slate-400 uppercase ml-1">Tema / Categoria</label><input value={courseForm.tema} onChange={e => setCourseForm({...courseForm, tema: e.target.value})} placeholder="Ex: História da Igreja" className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-2xl text-sm outline-none focus:ring-2 focus:ring-indigo-500" /></div>
                  <div className="space-y-1">
                    <label className="text-[10px] font-black text-slate-400 uppercase ml-1">Capa (Max 5MB)</label>
                    <div className="relative h-32 w-full bg-slate-50 border-2 border-dashed border-slate-200 rounded-2xl flex flex-col items-center justify-center hover:border-indigo-400 transition-all cursor-pointer">
                      <input type="file" accept="image/*" onChange={handleFileUpload} className="absolute inset-0 opacity-0 cursor-pointer" />
                      {courseForm.capaUrl ? <img src={courseForm.capaUrl} className="w-full h-full object-cover rounded-2xl" /> : <><FileUp size={24} className="text-slate-300" /><span className="text-[10px] font-bold text-slate-400 uppercase">Enviar Imagem</span></>}
                    </div>
                  </div>
                </div>
              </div>

              <div className="flex items-center gap-3 p-4 bg-slate-50 rounded-2xl border border-slate-200 shadow-inner">
                <input 
                  type="checkbox" 
                  id="geraCertificado" 
                  checked={courseForm.geraCertificado} 
                  onChange={e => setCourseForm({...courseForm, geraCertificado: e.target.checked})}
                  className="w-5 h-5 rounded border-slate-300 text-indigo-600 focus:ring-indigo-500 cursor-pointer" 
                />
                <label htmlFor="geraCertificado" className="text-xs font-bold text-slate-700 cursor-pointer select-none">Este curso emite certificado de conclusão automático ao final? (Sim/Não)</label>
              </div>

              <div className="space-y-1"><label className="text-[10px] font-black text-slate-400 uppercase ml-1">Ementa Completa</label><textarea rows={3} value={courseForm.descricaoLonga} onChange={e => setCourseForm({...courseForm, descricaoLonga: e.target.value})} className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-2xl text-sm resize-none outline-none focus:ring-2 focus:ring-indigo-500" placeholder="Descreva os objetivos principais do curso..."></textarea></div>

              <div className="flex gap-3 pt-4">
                <button type="button" onClick={handleCloseCourseModal} className="flex-1 px-4 py-4 border border-slate-200 text-slate-600 rounded-2xl font-bold text-sm hover:bg-slate-50 transition-all">Descartar</button>
                <button 
                  type="submit" 
                  disabled={loading}
                  className={`flex-[2] bg-slate-900 text-white py-4 rounded-2xl font-black text-sm uppercase tracking-widest shadow-xl transition-all ${loading ? 'opacity-50 cursor-not-allowed' : 'hover:bg-slate-800 active:scale-95'}`}
                >
                  {loading ? 'Processando...' : (currentEditingModule ? 'Salvar Alterações' : 'Criar Curso')}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* MODAL: NOVO/EDITAR MÓDULO (Unified and moved outside activeSub conditionals) */}
      {showModuleFormModal && (
        <div className="fixed inset-0 z-[220] flex items-center justify-center p-4 bg-slate-900/40 backdrop-blur-sm">
          <div className="bg-white w-full max-w-md rounded-2xl shadow-2xl p-6">
            <h3 className="font-bold text-slate-900 mb-4">
              {currentEditingModule ? 'Editar Módulo' : 'Criar Novo Módulo'}
            </h3>
            <form onSubmit={handleSaveModule} className="space-y-4">
              <input 
                required autoFocus 
                value={moduleForm.nome} 
                onChange={e => setModuleForm({nome: e.target.value})} 
                placeholder="Título do Módulo" 
                className="w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm outline-none" 
              />
              <div className="flex gap-3">
                <button 
                  type="button" 
                  onClick={() => { setShowModuleFormModal(false); setModuleForm({nome:''}); setCurrentEditingModule(null); }} 
                  className="flex-1 px-4 py-2.5 border border-slate-200 text-slate-600 rounded-xl font-bold text-sm"
                >
                  Cancelar
                </button>
                <button 
                  type="submit" 
                  className="flex-1 bg-indigo-600 text-white py-2.5 rounded-xl font-bold text-sm shadow-lg shadow-indigo-100"
                >
                  {currentEditingModule ? 'Salvar Alterações' : 'Criar Módulo'}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* MODAL: NOVA AULA / EDIÇÃO DE AULA */}
      {showLessonModal && (
        <div className="fixed inset-0 z-[220] flex items-center justify-center p-4 bg-slate-900/40 backdrop-blur-sm">
          <div className="bg-white w-full max-w-lg rounded-2xl shadow-2xl p-6">
            <h3 className="font-bold text-slate-900 mb-4">{isEditingLesson ? 'Editar Aula' : 'Adicionar Aula'}</h3>
            <form onSubmit={handleSaveLesson} className="space-y-4">
              <input required value={lessonForm.titulo} onChange={e => setLessonForm({...lessonForm, titulo: e.target.value})} placeholder="Título da Aula" className="w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm" />
              <textarea value={lessonForm.descricao} onChange={e => setLessonForm({...lessonForm, descricao: e.target.value})} placeholder="Descrição Pedagógica" className="w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm resize-none outline-none" rows={3}></textarea>
              <div className="grid grid-cols-2 gap-4">
                <input value={lessonForm.videoUrl} onChange={e => setLessonForm({...lessonForm, videoUrl: e.target.value})} placeholder="URL YouTube" className="w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm outline-none" />
                <input value={lessonForm.materialUrl} onChange={e => setLessonForm({...lessonForm, materialUrl: e.target.value})} placeholder="Link do PDF" className="w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm outline-none" />
              </div>
              <div className="flex gap-3">
                <button type="button" onClick={() => { setShowLessonModal(false); setIsEditingLesson(false); setEditingLessonId(null); setLessonForm({titulo:'', descricao:'', videoUrl:'', materialUrl:''}); }} className="flex-1 px-4 py-3 border border-slate-200 text-slate-600 rounded-xl font-bold text-sm">Cancelar</button>
                <button type="submit" className="flex-1 bg-indigo-600 text-white py-3 rounded-xl font-bold text-sm shadow-lg shadow-indigo-100">
                  {isEditingLesson ? 'Salvar Alterações' : 'Publicar Conteúdo'}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default ProfessorView;

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { 
  collection, 
  query, 
  where, 
  getDocs, 
  addDoc, 
  deleteDoc,
  serverTimestamp, 
  orderBy,
  doc,
  updateDoc,
  getDoc,
  arrayUnion // Importado arrayUnion para atualizar arrays no Firestore
} from 'firebase/firestore';
import { db } from '../firebase';
import { Course, Module, Lesson, User, ProfessorSubView } from '../types';
import { 
  BookOpen, 
  Plus, 
  X, 
  ChevronRight, 
  Play, 
  Pause, 
  Volume2, 
  VolumeX, 
  Maximize, 
  MoreVertical, 
  ArrowLeft, 
  Layout, 
  Trash2, 
  Layers, 
  Eye, 
  CheckCircle, 
  Copy, 
  Edit, 
  GraduationCap, 
  FileUp, 
  FileDown,
  Lock 
} from 'lucide-react';

interface ProfessorViewProps {
  user: User;
  activeSub: ProfessorSubView;
  setActiveSub: (view: ProfessorSubView) => void;
}

const ProfessorView: React.FC<ProfessorViewProps> = ({ user, activeSub, setActiveSub }) => {
  const [myCourses, setMyCourses] = useState<Course[]>([]);
  const [loading, setLoading] = useState(true);
  const [selectedCourse, setSelectedCourse] = useState<Course | null>(null);
  const [modules, setModules] = useState<Module[]>([]);
  const [lessonsByModule, setLessonsByModule] = useState<Record<string, Lesson[]>>({});
  const [allModulesGrouped, setAllModulesGrouped] = useState<Record<string, { course: Course, modules: Module[] }>>({});
  const [openMenuId, setOpenMenuId] = useState<string | null>(null); // Manter estado do menu de contexto

  // Modal States
  const [showCourseModal, setShowCourseModal] = useState(false);
  const [isEditingCourse, setIsEditingCourse] = useState(false);
  const [editingCourseId, setEditingCourseId] = useState<string | null>(null);

  const [showModuleFormModal, setShowModuleFormModal] = useState(false); // Unified module form modal
  const [showLessonModal, setShowLessonModal] = useState(false);
  const [isEditingLesson, setIsEditingLesson] = useState(false);
  const [activeModuleId, setActiveModuleId] = useState<string | null>(null);
  const [currentEditingModule, setCurrentEditingModule] = useState<Module | null>(null); // Module being edited
  const [editingLessonId, setEditingLessonId] = useState<string | null>(null);

  // Preview States (Aula em modo cinema)
  const [previewLesson, setPreviewLesson] = useState<Lesson | null>(null);
  const [isConcluded, setIsConcluded] = useState(false); // Aula atual concluída na simulação
  const [isPlaying, setIsPlaying] = useState(false); // Player está "tocando" (autoplay no iframe)
  const [timeLeft, setTimeLeft] = useState(300); // 5 minutos = 300 segundos
  const timerIntervalRef = useRef<number | null>(null);
  const [showWelcomeModal, setShowWelcomeModal] = useState(false);
  const [showCompletionModal, setShowCompletionModal] = useState(false);

  // New state for student simulation mode. FALSE means Professor has full control.
  const [isStudentSimulationMode, setIsStudentSimulationMode] = useState(false);
  // New state for certificate unlock in simulation
  const [isCertificateUnlocked, setIsCertificateUnlocked] = useState(false);
  // New state to store completed lessons IDs for the simulated student
  const [completedLessonIds, setCompletedLessonIds] = useState<Set<string>>(new Set());
  // Total number of lessons in the current course
  const [totalLessons, setTotalLessons] = useState(0);


  // Player UI states (para controles visuais, interagem com o iframe via postMessage)
  const [playerVolume, setPlayerVolume] = useState(80); 
  const [isMuted, setIsMuted] = useState(false); 
  const iframeRef = useRef<HTMLIFrameElement>(null); 
  const playerContainerRef = useRef<HTMLDivElement>(null); 

  // Form States
  const [courseForm, setCourseForm] = useState({
    nome: '', tema: '', professorResponsavel: user.displayName || '',
    descricaoLonga: '', capaUrl: '', cargaHoraria: '',
    publicoAlvo: 'Geral' as const, geraCertificado: false
  });
  const [moduleForm, setModuleForm] = useState({ nome: '' });
  const [lessonForm, setLessonForm] = useState({
    titulo: '', descricao: '', videoUrl: '', materialUrl: ''
  });

  // --- Funções de Fetching de Dados ---
  const fetchMyCourses = async () => {
    setLoading(true);
    try {
      const q = query(collection(db, 'cursos'), where('professorId', '==', user.uid), orderBy('createdAt', 'desc'));
      const querySnapshot = await getDocs(q);
      const fetched: Course[] = [];
      querySnapshot.forEach((doc) => {
        fetched.push({ id: doc.id, ...doc.data() } as Course);
      });
      setMyCourses(fetched);
    } catch (error) {
      console.error("Erro ao carregar cursos:", error);
    } finally {
      setLoading(false);
    }
  };

  const fetchModulesForCourse = async (courseId: string) => {
    const q = query(collection(db, 'cursos', courseId, 'modulos'), orderBy('ordem', 'asc'));
    const querySnapshot = await getDocs(q);
    const fetched: Module[] = [];
    querySnapshot.forEach((doc) => {
      fetched.push({ id: doc.id, ...doc.data(), courseId } as Module);
    });
    return fetched;
  };

  const fetchAllModulesGrouped = async () => {
    setLoading(true);
    try {
      const grouped: Record<string, { course: Course, modules: Module[] }> = {};
      for (const course of myCourses) {
        const mods = await fetchModulesForCourse(course.id);
        grouped[course.id] = { course, modules: mods };
      }
      setAllModulesGrouped(grouped);
    } catch (error) {
      console.error("Erro ao agrupar módulos:", error);
    } finally {
      setLoading(false);
    }
  };

  const fetchLessons = async (courseId: string, moduleId: string) => {
    try {
      const q = query(collection(db, 'cursos', courseId, 'modulos', moduleId, 'aulas'), orderBy('ordem', 'asc'));
      const querySnapshot = await getDocs(q);
      const fetched: Lesson[] = [];
      querySnapshot.forEach((doc) => {
        fetched.push({ id: doc.id, ...doc.data() } as Lesson);
      });
      setLessonsByModule(prev => ({ ...prev, [moduleId]: fetched }));
    } catch (error) {
      console.error("Erro ao carregar aulas:", error);
    }
  };

  // --- Funções de Persistência REAL (Simulada para o professor) ---
  const fetchCompletedLessons = useCallback(async (studentId: string, courseId: string) => {
    if (!studentId || !courseId) return new Set<string>();
    try {
      // Em um ambiente real de aluno, buscaria as aulas concluídas
      // Para a simulação, vamos persistir no localStorage para demonstrar o comportamento
      const key = `completed_lessons_sim_${studentId}_${courseId}`;
      const stored = localStorage.getItem(key);
      return new Set(stored ? JSON.parse(stored) : []);

      /* CÓDIGO REAL DE FIRESTORE (APENAS EXEMPLO)
      const userDocRef = doc(db, 'users', studentId);
      const userDocSnap = await getDoc(userDocRef);
      if (userDocSnap.exists()) {
        const userData = userDocSnap.data();
        const completed = userData?.aulasConcluidas || []; // 'aulasConcluidas' é um array de lesson IDs no doc do user
        return new Set<string>(completed);
      }
      */
    } catch (error) {
      console.error("Erro ao buscar aulas concluídas do aluno (simulação):", error);
    }
    return new Set<string>();
  }, []);

  const updateCompletedLesson = useCallback(async (studentId: string, lessonId: string) => {
    if (!studentId || !lessonId) return;
    try {
      // Para a simulação, atualiza o localStorage
      const key = `completed_lessons_sim_${studentId}_${selectedCourse?.id}`;
      const currentCompleted = await fetchCompletedLessons(studentId, selectedCourse?.id || '');
      if (!currentCompleted.has(lessonId)) {
        currentCompleted.add(lessonId);
        localStorage.setItem(key, JSON.stringify(Array.from(currentCompleted)));
        console.log(`Simulação (localStorage): Aula ${lessonId} marcada como concluída para o aluno ${studentId}`);
        setCompletedLessonIds(currentCompleted); // Atualiza o estado local
      }

      /* CÓDIGO REAL DE FIRESTORE (APENAS EXEMPLO)
      const userDocRef = doc(db, 'users', studentId);
      await updateDoc(userDocRef, {
        aulasConcluidas: arrayUnion(lessonId)
      });
      console.log(`Firestore: Aula ${lessonId} marcada como concluída para o aluno ${studentId}`);
      setCompletedLessonIds(prev => new Set(prev).add(lessonId)); // Atualiza o estado local
      */
    } catch (error) {
      console.error("Erro ao atualizar aula concluída no Firestore (simulação):", error);
    }
  }, [fetchCompletedLessons, selectedCourse?.id]);

  // --- Effects ---
  useEffect(() => {
    fetchMyCourses();
  }, [user.uid]);

  useEffect(() => {
    if (activeSub === 'modulos') {
      fetchAllModulesGrouped();
    }
  }, [activeSub, myCourses]);

  // Calcula o total de aulas no curso para a lógica do certificado
  useEffect(() => {
    if (selectedCourse && modules.length > 0) {
      let count = 0;
      for (const mod of modules) {
        count += (lessonsByModule[mod.id]?.length || 0);
      }
      setTotalLessons(count);
    } else {
      setTotalLessons(0);
    }
  }, [selectedCourse, modules, lessonsByModule]);

  // Lógica do Cronômetro de 5 minutos (TOTALMENTE INDEPENDENTE DO YOUTUBE)
  useEffect(() => {
    // O timer só roda no modo de simulação de aluno, se a aula está em preview,
    // o modal de boas-vindas foi fechado e o vídeo está "tocando".
    const shouldStartTimer = isStudentSimulationMode && previewLesson && !showWelcomeModal && isPlaying;

    if (shouldStartTimer && timeLeft > 0) {
      if (!timerIntervalRef.current) {
        timerIntervalRef.current = window.setInterval(async () => {
          setTimeLeft(prevTime => {
            if (prevTime <= 1) {
              if (timerIntervalRef.current) {
                clearInterval(timerIntervalRef.current);
                timerIntervalRef.current = null;
              }
              setIsConcluded(true); // Aula concluída na simulação

              // Dispara a persistência no DB (ou simulação de persistência)
              if (user.uid && previewLesson?.id) {
                updateCompletedLesson(user.uid, previewLesson.id);
              }

              if (!showCompletionModal) {
                setShowCompletionModal(true);
              }
              return 0;
            }
            return prevTime - 1;
          });
        }, 1000);
      }
    } else if (timerIntervalRef.current) {
      clearInterval(timerIntervalRef.current);
      timerIntervalRef.current = null;
    }

    return () => {
      if (timerIntervalRef.current) {
        clearInterval(timerIntervalRef.current);
        timerIntervalRef.current = null;
      }
    };
  }, [previewLesson, isStudentSimulationMode, showWelcomeModal, isPlaying, timeLeft, showCompletionModal, user.uid, previewLesson?.id, updateCompletedLesson]);

  // Lógica de Desbloqueio de Certificado (para Simulação de Professor)
  useEffect(() => {
    if (selectedCourse?.geraCertificado && isStudentSimulationMode && totalLessons > 0) {
      setIsCertificateUnlocked(completedLessonIds.size >= totalLessons);
    } else {
      setIsCertificateUnlocked(false);
    }
  }, [selectedCourse?.geraCertificado, isStudentSimulationMode, completedLessonIds, totalLessons]);

  // Carrega as aulas concluídas ao entrar no modo de preview para um curso
  useEffect(() => {
    if (selectedCourse && user.uid) {
      // Sempre tenta buscar aulas concluídas, mas o comportamento (restrições)
      // só é aplicado se `isStudentSimulationMode` for true.
      fetchCompletedLessons(user.uid, selectedCourse.id).then(setCompletedLessonIds);
    } else {
      setCompletedLessonIds(new Set()); // Reseta ao sair da simulação
    }
  }, [selectedCourse, user.uid, fetchCompletedLessons]);

  const getYouTubeVideoId = (url: string) => {
    const ytRegex = /(?:https?:\/\/)?(?:www\.)?(?:youtube\.com\/(?:[^\/\n\s]+\/\S+\/|(?:v|e(?:mbed)?)\/|\S*?[?&]v=)|youtu\.be\/)([a-zA-Z0-9_-]{11})/;
    const ytMatch = url.match(ytRegex);
    return ytMatch && ytMatch[1];
  };

  // --- Funções de Controle do Player via postMessage ---
  const sendPlayerCommand = useCallback((command: string, args: any = '') => {
    if (iframeRef.current && iframeRef.current.contentWindow) {
      iframeRef.current.contentWindow.postMessage(
        JSON.stringify({
          event: 'command',
          func: command,
          args: args,
        }),
        '*'
      );
    }
  }, []);

  const togglePlay = () => {
    if (isPlaying) {
      sendPlayerCommand('pauseVideo');
      setIsPlaying(false);
    } else {
      sendPlayerCommand('playVideo');
      setIsPlaying(true);
      setShowWelcomeModal(false); // Fecha o modal de boas-vindas ao iniciar o play
    }
  };

  const toggleMute = () => {
    if (isMuted) {
      sendPlayerCommand('unMute');
    } else {
      sendPlayerCommand('mute');
    }
    setIsMuted(prev => !prev);
  };

  const handleVolumeChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const vol = parseInt(e.target.value);
    setPlayerVolume(vol);
    if (vol === 0) {
      if (!isMuted) sendPlayerCommand('mute');
      setIsMuted(true);
    } else {
      if (isMuted) sendPlayerCommand('unMute');
      sendPlayerCommand('setVolume', [vol]); // Define o volume via postMessage
      setIsMuted(false);
    }
  };

  const toggleFullscreen = () => {
    if (playerContainerRef.current) {
      if (!document.fullscreenElement) playerContainerRef.current.requestFullscreen();
      else document.exitFullscreen();
    }
  };

  // --- Funções de Gerenciamento de Cursos, Módulos e Aulas (CRUD) ---
  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    if (file.size > 5 * 1024 * 1024) { // Max 5MB
      alert("A imagem de capa não pode exceder 5 MB.");
      e.target.value = '';
      return;
    }
    const reader = new FileReader();
    reader.onloadend = () => {
      setCourseForm(prev => ({ ...prev, capaUrl: reader.result as string }));
    };
    reader.readAsDataURL(file);
  };

  const handleSaveCourse = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      setLoading(true);
      if (isEditingCourse && editingCourseId) {
        const courseRef = doc(db, 'cursos', editingCourseId);
        await updateDoc(courseRef, { ...courseForm });
        if (selectedCourse?.id === editingCourseId) {
          setSelectedCourse({ ...selectedCourse, ...courseForm });
        }
      } else {
        await addDoc(collection(db, 'cursos'), {
          ...courseForm, professorId: user.uid, inscritos: 0,
          status: 'rascunho', createdAt: serverTimestamp()
        });
      }
      handleCloseCourseModal();
      await fetchMyCourses();
    } catch (error) {
      console.error("Erro ao salvar curso:", error);
    } finally { setLoading(false); }
  };

  const handleEditCourseInfo = (course: Course) => {
    setCourseForm({
      nome: course.nome, tema: course.tema || '', professorResponsavel: course.professorResponsavel || '',
      descricaoLonga: course.descricaoLonga || '', capaUrl: course.capaUrl || '',
      cargaHoraria: course.cargaHoraria, publicoAlvo: course.publicoAlvo,
      geraCertificado: course.geraCertificado || false
    });
    setEditingCourseId(course.id);
    setIsEditingCourse(true);
    setShowCourseModal(true);
    setOpenMenuId(null);
  };

  const handleCloseCourseModal = () => {
    setShowCourseModal(false);
    setIsEditingCourse(false);
    setEditingCourseId(null);
    setCourseForm({ // Reseta o formulário
      nome: '', tema: '', professorResponsavel: user.displayName || '',
      descricaoLonga: '', capaUrl: '', cargaHoraria: '',
      publicoAlvo: 'Geral', geraCertificado: false
    });
  };

  const handleDeleteCourse = async (courseId: string) => {
    if (!confirm("Tem certeza que deseja excluir o curso inteiro?")) return;
    try {
      await deleteDoc(doc(db, 'cursos', courseId));
      setMyCourses(prev => prev.filter(c => c.id !== courseId));
      setOpenMenuId(null);
    } catch (error) { console.error(error); }
  };

  const handleDuplicateCourse = async (course: Course) => {
    try {
      const { id, ...data } = course;
      await addDoc(collection(db, 'cursos'), {
        ...data, nome: `${data.nome} (Cópia)`, createdAt: serverTimestamp()
      });
      fetchMyCourses();
      setOpenMenuId(null);
    } catch (error) { console.error(error); }
  };

  const handleDeleteModule = async (courseId: string, moduleId: string) => {
    if (!confirm("Excluir este módulo?")) return;
    try {
      await deleteDoc(doc(db, 'cursos', courseId, 'modulos', moduleId));
      if (selectedCourse) {
        setModules(prev => prev.filter(m => m.id !== moduleId));
      } else {
        fetchAllModulesGrouped();
      }
    } catch (error) { console.error(error); }
  };

  const handleDuplicateModule = async (mod: Module) => {
    try {
      const { id, ...data } = mod;
      await addDoc(collection(db, 'cursos', mod.courseId, 'modulos'), {
        ...data, nome: `${data.nome} (Cópia)`, ordem: (mod.ordem || 0) + 1, createdAt: serverTimestamp()
      });
      if (selectedCourse) {
        const mods = await fetchModulesForCourse(selectedCourse.id);
        setModules(mods);
      } else {
        fetchAllModulesGrouped();
      }
    } catch (error) { console.error(error); }
  };

  // Unified function for creating and updating modules
  const handleSaveModule = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedCourse) return;

    try {
      if (currentEditingModule) { // Editing existing module
        const modRef = doc(db, 'cursos', currentEditingModule.courseId, 'modulos', currentEditingModule.id);
        await updateDoc(modRef, { nome: moduleForm.nome });
      } else { // Creating new module
        await addDoc(collection(db, 'cursos', selectedCourse.id, 'modulos'), {
          nome: moduleForm.nome, ordem: modules.length + 1, createdAt: serverTimestamp()
        });
      }
      setShowModuleFormModal(false);
      setModuleForm({ nome: '' });
      setCurrentEditingModule(null); // Clear editing state
      const mods = await fetchModulesForCourse(selectedCourse.id);
      setModules(mods);
    }
    catch (error) { console.error("Erro ao salvar módulo:", error); }
  };

  // Function to open module form for creation
  const handleOpenCreateModule = () => {
    setModuleForm({ nome: '' });
    setCurrentEditingModule(null);
    setShowModuleFormModal(true);
  };

  // Function to open module form for editing
  const handleEditModule = (mod: Module) => {
    setCurrentEditingModule(mod);
    setModuleForm({ nome: mod.nome });
    setShowModuleFormModal(true);
  };

  const handleSaveLesson = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedCourse || !activeModuleId) return;

    try {
      if (isEditingLesson && editingLessonId) {
        const lessonRef = doc(db, 'cursos', selectedCourse.id, 'modulos', activeModuleId, 'aulas', editingLessonId);
        await updateDoc(lessonRef, { ...lessonForm });
      } else {
        await addDoc(collection(db, 'cursos', selectedCourse.id, 'modulos', activeModuleId, 'aulas'), {
          ...lessonForm, ordem: (lessonsByModule[activeModuleId]?.length || 0) + 1, createdAt: serverTimestamp()
        });
      }
      setShowLessonModal(false);
      setIsEditingLesson(false);
      setEditingLessonId(null);
      setLessonForm({ titulo: '', descricao: '', videoUrl: '', materialUrl: '' });
      fetchLessons(selectedCourse.id, activeModuleId);

      if (previewLesson && previewLesson.id === editingLessonId) {
        setPreviewLesson(null);
      }
    } catch (error) { console.error(error); }
  };

  const handleDeleteLesson = async (moduleId: string, lessonId: string) => {
    if (!selectedCourse) return;
    if (!confirm("Tem certeza que deseja DESTRUIR esta aula permanentemente?")) return;
    try {
      await deleteDoc(doc(db, 'cursos', selectedCourse.id, 'modulos', moduleId, 'aulas', lessonId));
      fetchLessons(selectedCourse.id, moduleId);
      if (previewLesson?.id === lessonId) setPreviewLesson(null);
    } catch (error) { console.error(error); }
  };

  const handleEditLesson = (lesson: Lesson, moduleId: string) => {
    setActiveModuleId(moduleId);
    setLessonForm({
      titulo: lesson.titulo, descricao: lesson.descricao || '',
      videoUrl: lesson.videoUrl, materialUrl: lesson.materialUrl
    });
    setEditingLessonId(lesson.id);
    setIsEditingLesson(true);
    setShowLessonModal(true);
  };

  const openCourseDetail = async (course: Course) => {
    setSelectedCourse(course);
    const mods = await fetchModulesForCourse(course.id);
    setModules(mods);
    for (const mod of mods) {
      fetchLessons(course.id, mod.id);
    }
  };

  /**
   * Função para abrir a pré-visualização da aula (modo cinema).
   * @param studentMode Se true, simula a experiência do aluno (restrições, timer, welcome modal).
   *                    Se false, professor tem controle total (sem restrições, sem timer, sem welcome modal).
   */
  const openPreview = (lesson: Lesson, moduleId: string, studentMode: boolean) => {
    setActiveModuleId(moduleId);
    setPreviewLesson(lesson);
    setIsPlaying(false); // Sempre começa pausado/com capa
    setTimeLeft(300); // Reseta o cronômetro
    setIsConcluded(false); // Reseta a conclusão
    setIsMuted(false); // Reseta o mute
    setPlayerVolume(80); // Reseta o volume para padrão
    sendPlayerCommand('setVolume', [80]); // Envia comando para iframe
    sendPlayerCommand('unMute'); // Envia comando para iframe
    setIsStudentSimulationMode(studentMode); // Define o modo de simulação/controle total
    setShowWelcomeModal(studentMode); // Mostra o modal de boas-vindas APENAS se for simulação de aluno
    setShowCompletionModal(false); // Garante que o modal de conclusão não esteja aberto
  };

  const handleNextLesson = () => {
    if (!previewLesson || !activeModuleId || !selectedCourse) {
      handleReturnToDashboard();
      return;
    }
    const currentModuleIndex = modules.findIndex(mod => mod.id === activeModuleId);
    if (currentModuleIndex === -1) { handleReturnToDashboard(); return; }

    const currentModuleLessons = lessonsByModule[activeModuleId] || [];
    const currentLessonIndex = currentModuleLessons.findIndex((lesson: Lesson) => lesson.id === previewLesson.id);

    if (currentLessonIndex !== -1 && currentLessonIndex < currentModuleLessons.length - 1) {
      const nextLesson = currentModuleLessons[currentLessonIndex + 1];
      openPreview(nextLesson, activeModuleId, isStudentSimulationMode);
    } else if (currentModuleIndex < modules.length - 1) {
      const nextModule = modules[currentModuleIndex + 1];
      const nextModuleLessons = lessonsByModule[nextModule.id] || [];
      if (nextModuleLessons.length > 0) {
        openPreview(nextModuleLessons[0], nextModule.id, isStudentSimulationMode);
      } else { handleReturnToDashboard(); }
    } else { handleReturnToDashboard(); }
    setShowCompletionModal(false);
  };

  const handleReturnToDashboard = () => {
    setPreviewLesson(null);
    setSelectedCourse(null);
    setShowCompletionModal(false);
    setIsStudentSimulationMode(false);
    setIsCertificateUnlocked(false);
    setIsPlaying(false); // Garante que o autoplay do iframe seja desativado
    sendPlayerCommand('pauseVideo'); // Pausa o vídeo se ele estiver ativo
  };

  // --- Renderização da View de Reprodução (Cinema Mode para TODOS) ---
  if (previewLesson && selectedCourse) { 
    const videoId = getYouTubeVideoId(previewLesson.videoUrl);
    // Adicionado `enablejsapi=1` para permitir controle via postMessage
    const iframeSrc = `https://www.youtube.com/embed/${videoId}?controls=0&modestbranding=1&rel=0&enablejsapi=1&autoplay=${isPlaying ? 1 : 0}&mute=${isMuted ? 1 : 0}`;

    return (
      <div className="fixed inset-0 z-[100] bg-gradient-to-br from-gray-900 to-slate-950 animate-in fade-in duration-300 overflow-y-auto">
        <div className="max-w-[1440px] mx-auto p-4 md:p-6 lg:p-8 flex flex-col h-full">
          <header className="flex items-center justify-between mb-6 pb-4 border-b border-gray-800">
            <div className="flex items-center gap-4">
              <button onClick={handleReturnToDashboard} className="h-10 w-10 bg-gray-800 border border-gray-700 hover:bg-gray-700 rounded-xl text-gray-300 transition-all shadow-sm flex items-center justify-center"><ArrowLeft size={20} /></button>
              <div>
                <h1 className="text-xl font-bold text-white leading-tight">{selectedCourse.nome}</h1>
                <p className="text-gray-400 text-sm mt-0.5">{isStudentSimulationMode ? 'Simulação Discente' : 'Construtor de Cursos'}</p>
              </div>
            </div>
            <button onClick={() => setPreviewLesson(null)} className="px-4 py-2 bg-gray-800 hover:bg-gray-700 rounded-xl text-gray-300 text-xs font-bold transition-colors">Fechar Pré-visualização</button>
          </header>

          <div className="flex-1 grid grid-cols-1 lg:grid-cols-4 gap-6">
            {/* Coluna Principal: Player de Vídeo e Detalhes da Aula */}
            <div className="lg:col-span-3 space-y-6">
              {/* MODAL DE BOAS-VINDAS PARA ALUNOS (simulação) */}
              {showWelcomeModal && isStudentSimulationMode ? (
                <div className="aspect-video bg-black/60 backdrop-blur-xl rounded-3xl overflow-hidden shadow-2xl border-4 border-indigo-500 relative flex items-center justify-center text-center p-8 animate-in zoom-in duration-300">
                  <button onClick={() => setShowWelcomeModal(false)} className="absolute top-4 right-4 text-white hover:text-indigo-200 p-2 rounded-full hover:bg-white/10 transition-colors"><X size={24} /></button>
                  <div className="relative z-10 space-y-6 max-w-lg">
                    <p className="text-white font-serif text-3xl font-bold leading-relaxed">
                      Bem-vindo à aula!
                    </p>
                    <p className="text-indigo-200 text-base leading-relaxed">
                      Para uma experiência imersiva, encontre um ambiente tranquilo, use fones de ouvido e coloque-se em uma posição confortável.
                    </p>
                    <button 
                      onClick={togglePlay} // Usa togglePlay para iniciar a aula e fechar o modal
                      className="px-8 py-4 bg-emerald-500 text-white rounded-full text-lg font-bold shadow-lg shadow-emerald-500/30 hover:bg-emerald-600 transition-all active:scale-95 flex items-center justify-center gap-3 mx-auto"
                    >
                      <Play size={24} fill="currentColor" /> Entendi! Começar Aula
                    </button>
                  </div>
                </div>
              ) : (
                /* CONTAINER DO PLAYER */
                <div ref={playerContainerRef} className="aspect-video bg-gray-900 rounded-3xl overflow-hidden shadow-2xl border-4 border-gray-700 relative group">

                  {/* Iframe do vídeo */}
                  <iframe 
                    ref={iframeRef} 
                    width="100%" 
                    height="100%" 
                    title="Video Player" 
                    frameBorder="0" 
                    allow="accelerometer; autoplay; encrypted-media; gyroscope; picture-in-picture" 
                    allowFullScreen
                    src={iframeSrc}
                  ></iframe>

                  {/* CAMADA INVISÍVEL (OVERLAY) PARA BLOQUEAR INTERAÇÃO DO ALUNO COM CONTROLES NATIVOS DO YOUTUBE */}
                  {isStudentSimulationMode && (
                    <div className="absolute inset-0 z-10 pointer-events-auto bg-transparent" onClick={() => !isPlaying && togglePlay()}>
                       {/* Overlay com um botão de play centralizado se o vídeo não estiver tocando */}
                      {!isPlaying && (
                        <div className="absolute inset-0 flex items-center justify-center bg-black/60 cursor-pointer">
                            <div className="w-20 h-20 bg-white/20 backdrop-blur-xl border border-white/30 rounded-full flex items-center justify-center text-white transition-all shadow-2xl hover:scale-110 active:scale-95">
                                <Play size={40} fill="currentColor" />
                            </div>
                        </div>
                      )}
                    </div>
                  )}

                  {/* CAPA (THUMBNAIL) COM BOTÃO DE PLAY (Visível apenas se não estiver tocando e sem modal de boas-vindas) */}
                  {/* Para professor em modo controle total, a capa é apenas um visual inicial até o play.
                      Para aluno, ela serve como bloqueio inicial antes do modal de boas vindas. */}
                  {(!isPlaying && !showWelcomeModal) && (
                    <div 
                      className="absolute inset-0 z-20 bg-black/60 flex items-center justify-center pointer-events-auto cursor-pointer"
                      onClick={togglePlay} 
                    >
                      <img 
                        src={`https://img.youtube.com/vi/${videoId}/sddefault.jpg`} 
                        alt="Video Thumbnail" 
                        className="absolute inset-0 w-full h-full object-cover opacity-50"
                      />
                      <div className="relative z-10 w-20 h-20 bg-white/20 backdrop-blur-xl border border-white/30 rounded-full flex items-center justify-center text-white transition-all shadow-2xl hover:scale-110 active:scale-95">
                        <Play size={40} fill="currentColor" />
                      </div>
                    </div>
                  )}

                  {/* CONTROLES CUSTOMIZADOS (AGORA FUNCIONAIS VIA POSTMESSAGE) */}
                  {(!showWelcomeModal) && ( // Visível para ambos (aluno simulado ou professor com controle total)
                      <div className="absolute inset-0 z-30 pointer-events-none flex flex-col justify-end">
                          <div className="p-4 bg-gradient-to-t from-black/80 to-transparent opacity-0 group-hover:opacity-100 transition-opacity pointer-events-auto">
                              <div className="flex items-center justify-between gap-6 px-4">
                                  <div className="flex items-center gap-4">
                                      <button onClick={togglePlay} className="text-white hover:text-indigo-400 transition-colors">
                                          {isPlaying ? <Pause size={24} fill="currentColor" /> : <Play size={24} fill="currentColor" />}
                                      </button>
                                      {/* Controles de volume usando postMessage para mute/unMute */}
                                      <div className="flex items-center gap-3 group/vol">
                                          <button onClick={toggleMute} className="text-white hover:text-indigo-400 transition-colors">{(isMuted || playerVolume === 0) ? <VolumeX size={20} /> : <Volume2 size={20} />}</button>
                                          <input type="range" min="0" max="100" value={isMuted ? 0 : playerVolume} onChange={handleVolumeChange} className="w-20 h-1.5 bg-white/20 rounded-full appearance-none cursor-pointer accent-indigo-500 hover:accent-indigo-400 transition-all" />
                                      </div>
                                  </div>
                                  <button onClick={toggleFullscreen} className="text-white hover:text-indigo-400 transition-colors"><Maximize size={20} /></button>
                              </div>
                          </div>
                      </div>
                  )}
                </div>
              )}

              {/* Informações da Aula */}
              <div className="p-8 bg-gray-800 rounded-3xl shadow-lg border border-gray-700 space-y-4">
                {/* REMOVIDO: H2 com o título da aula duplicado */}
                <p className="font-serif text-gray-300 text-lg leading-relaxed tracking-wide whitespace-pre-wrap">{previewLesson.descricao || "Nenhuma descrição detalhada disponível para este tópico."}</p>
              </div>
            </div>

            {/* Coluna Lateral: Conteúdo Programático e Métricas */}
            <div className="lg:col-span-1 space-y-6">
              <div className="bg-gray-800 p-6 rounded-3xl shadow-lg border border-gray-700 h-[calc(100vh-14rem)] overflow-y-auto">
                <h3 className="text-lg font-bold text-indigo-400 uppercase tracking-widest mb-6">Conteúdo Programático</h3>

                {modules.map(mod => (
                  <div key={mod.id} className="mb-6 last:mb-0">
                    <h4 className="font-bold text-lg text-white mb-3 flex items-center gap-2">
                      <Layers size={18} className="text-indigo-400" /> Unidade {mod.ordem}: {mod.nome}
                    </h4>
                    <div className="space-y-2">
                      {lessonsByModule[mod.id]?.map(lesson => {
                        const isCurrent = previewLesson?.id === lesson.id;
                        // Aula é considerada "concluída" se o ID está no set de aulas concluídas OU não é modo simulação (professor)
                        const isLessonGloballyConcluded = completedLessonIds.has(lesson.id) || !isStudentSimulationMode;

                        return (
                          <div key={lesson.id}> {/* Wrap in a div to include PDF */}
                            <button
                              onClick={() => openPreview(lesson, mod.id, isStudentSimulationMode)} // Persist studentMode
                              className={`flex items-center justify-between w-full p-3 rounded-xl transition-all ${
                                isCurrent 
                                  ? 'bg-indigo-600 text-white shadow-md' 
                                  : 'bg-gray-700 text-gray-300 hover:bg-gray-600'
                              }`}
                            >
                              <span className="flex items-center gap-3 text-sm font-medium">
                                {isCurrent ? <Play size={16} fill="currentColor" /> : (
                                  isLessonGloballyConcluded ? <CheckCircle size={16} className="text-emerald-400" /> : <Lock size={16} className="text-gray-500" />
                                )}
                                {lesson.titulo}
                              </span>
                              {!isCurrent && <ChevronRight size={16} className="text-gray-400" />}
                            </button>
                            {/* PDF dentro da playlist (se for a aula atual, tem material e está concluída/professor) */}
                            {isCurrent && ((isConcluded || !isStudentSimulationMode) && lesson.materialUrl) && (
                              <a
                                href={lesson.materialUrl}
                                target="_blank"
                                rel="noopener noreferrer"
                                className="block text-center mt-2 mx-auto px-4 py-2 bg-gray-900 text-indigo-400 rounded-lg text-xs font-semibold hover:bg-indigo-900 transition-colors animate-in fade-in duration-300"
                              >
                                <FileDown size={14} className="inline-block mr-2" /> Baixar Material de Apoio
                              </a>
                            )}
                          </div>
                        );
                      })}
                    </div>
                  </div>
                ))}

                {/* CERTIFICADO DE CONCLUSÃO (fora do loop de módulos, fixo no final da playlist) */}
                {selectedCourse?.geraCertificado && (
                  <div className="mt-8 pt-6 border-t border-gray-700">
                    <button
                      onClick={() => { if (isCertificateUnlocked) alert("Simulação: Certificado disponível para download!") }} // Placeholder para download
                      disabled={!isCertificateUnlocked} // Desabilitado baseado no estado de simulação
                      className={`flex items-center justify-between w-full p-3 rounded-xl transition-all ${
                        isCertificateUnlocked
                          ? 'bg-emerald-600 text-white shadow-md hover:bg-emerald-700'
                          : 'bg-gray-700 text-gray-400 cursor-not-allowed'
                      }`}
                    >
                      <span className="flex items-center gap-3 text-base font-bold">
                        {isCertificateUnlocked ? <GraduationCap size={20} /> : <Lock size={20} />}
                        Certificado de Conclusão
                      </span>
                      {isCertificateUnlocked && <ChevronRight size={20} className="opacity-50" />}
                    </button>
                  </div>
                )}
              </div>

              {/* Métricas Pedagógicas - Visível apenas para simulação estudantil */}
              {isStudentSimulationMode && (
                <div className="bg-gray-800 p-6 rounded-3xl shadow-lg border border-gray-700 text-center">
                  <h4 className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-4">Seu Progresso</h4>
                  <div className="py-2 flex flex-col items-center gap-1 text-white font-bold uppercase text-2xl tracking-widest">
                    {Math.floor(timeLeft / 60).toString().padStart(2, '0')}:{(timeLeft % 60).toString().padStart(2, '0')}
                    <span className="text-[10px] text-gray-500">Tempo Restante de Reprodução</span>
                  </div>
                </div>
              )}
            </div>
          </div>
        </div>

        {/* MODAL DE CONCLUSÃO DA AULA (APENAS EM SIMULAÇÃO ESTUDANTIL) */}
        {showCompletionModal && isStudentSimulationMode && (
          <div className="fixed inset-0 z-[210] flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm animate-in fade-in duration-300">
            <div className="bg-white w-full max-w-md rounded-2xl shadow-2xl p-6 text-center animate-in zoom-in-95 duration-200">
              <CheckCircle size={48} className="text-emerald-500 mx-auto mb-4" />
              <h3 className="font-bold text-gray-900 text-xl mb-2">Aula Concluída!</h3>
              <p className="text-gray-600 text-sm mb-6">Parabéns! Você concluiu os requisitos mínimos para esta aula. O que deseja fazer a seguir?</p>

              <div className="flex flex-col gap-3">
                <button 
                  onClick={handleNextLesson} 
                  className="flex items-center justify-center gap-2 px-6 py-3 bg-indigo-600 text-white rounded-xl font-bold text-sm shadow-lg shadow-indigo-100 hover:bg-indigo-700 transition-all active:scale-95"
                >
                  <ChevronRight size={18} /> Próxima Aula
                </button>
                <button 
                  onClick={handleReturnToDashboard} 
                  className="flex items-center justify-center gap-2 px-6 py-3 border border-gray-200 text-gray-600 rounded-xl font-bold text-sm hover:bg-gray-50 transition-all"
                >
                  <BookOpen size={18} /> Voltar ao Painel do Curso
                </button>
              </div>
            </div>
          </div>
        )}
      </div>
    );
  }


  // --- Renderização da View de Gestão Global de Módulos ---
  if (activeSub === 'modulos') {
    return (
      <div className="space-y-6 animate-in fade-in duration-500">
        <header className="flex items-center justify-between">
          <div>
            <h1 className="text-2xl font-bold text-slate-900 tracking-tight">Gestão Global de Módulos</h1>
            <p className="text-slate-500 text-sm">Organização da matriz curricular de todos os cursos ativos.</p>
          </div>
          {selectedCourse && (
            <button onClick={() => setActiveSub('cursos')} className="flex items-center gap-2 bg-white border border-slate-200 text-slate-600 px-4 py-2 rounded-xl text-sm font-bold hover:bg-slate-50 shadow-sm transition-all">
              <ArrowLeft size={18} /> Voltar ao Construtor
            </button>
          )}
        </header>

        {loading ? (
          <div className="flex items-center justify-center p-20"><div className="h-8 w-8 animate-spin rounded-full border-4 border-indigo-600 border-t-transparent"></div></div>
        ) : Object.keys(allModulesGrouped).length === 0 ? (
          <div className="bg-white p-20 rounded-2xl border border-slate-200 text-center opacity-50">
            <Layers size={48} className="mx-auto mb-4 text-slate-300" />
            <p className="font-bold text-slate-900">Nenhum módulo encontrado</p>
          </div>
        ) : (
          <div className="space-y-8">
            {Object.values(allModulesGrouped).map(({ course, modules }) => (
              <div key={course.id} className="bg-white rounded-2xl border border-slate-200 shadow-sm overflow-hidden">
                <div className="px-6 py-4 border-b border-slate-100 flex items-center justify-between bg-slate-50/50">
                  <div className="flex items-center gap-3">
                    <BookOpen size={16} className="text-indigo-600" />
                    <h2 className="text-sm font-bold text-slate-800 uppercase tracking-widest">{course.nome}</h2>
                  </div>
                  <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">{modules.length} Módulos</span>
                </div>
                <div className="overflow-x-auto">
                  <table className="w-full text-left">
                    <thead className="bg-slate-50/30 text-[10px] font-black text-slate-400 uppercase tracking-tighter border-b border-slate-100">
                      <tr>
                        <th className="px-6 py-3">Nome do Módulo</th>
                        <th className="px-6 py-3">Ordem</th>
                        <th className="px-6 py-3 text-right">Ações</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-100 text-sm">
                      {modules.map(mod => (
                        <tr key={mod.id} className="hover:bg-slate-50/50 transition-colors">
                          <td className="px-6 py-4 font-semibold text-slate-900">{mod.nome}</td>
                          <td className="px-6 py-4 text-slate-500">Unidade {mod.ordem}</td>
                          <td className="px-6 py-4">
                            <div className="flex items-center justify-end gap-1">
                              <button onClick={() => { setActiveSub('cursos'); openCourseDetail(course); }} className="p-2 text-indigo-600 hover:bg-indigo-50 rounded-lg transition-colors" title="Abrir no Construtor"><Layout size={16} /></button>
