                <button type="submit" disabled={loading} className={`flex-[2] bg-slate-900 text-white py-4 rounded-2xl font-black text-sm uppercase tracking-widest shadow-xl transition-all ${loading ? 'opacity-50' : 'hover:bg-slate-800 active:scale-95'}`}>{loading ? 'Processando...' : (isEditingCourse ? 'Salvar Alterações' : 'Criar Curso')}</button>
