  collection, 
  query, 
  where, 
  getDocs, 
  addDoc, 
  deleteDoc,
  serverTimestamp, 
  orderBy,
  doc,
  updateDoc,
  getDoc,
  arrayUnion 
} from 'firebase/firestore';
import { db } from '../firebase';
import { Course, Module, Lesson, User, ProfessorSubView } from '../types';
import { 
  BookOpen, 
  Plus, 
  X, 
  ChevronRight, 
  Play, 
  Pause, 
  Volume2, 
  VolumeX, 
  Maximize, 
  MoreVertical, 
  ArrowLeft, 
  Layout, 
  Trash2, 
  Layers, 
  Eye, 
  CheckCircle, 
  Copy, 
  Edit, 
  GraduationCap, 
  FileUp, 
  FileDown,
  Lock,
