              <CloudUpload size={18} /> Upload de Arquivo
            </button>
            <input 
              type="file" 
              ref={materialInputRef} 
              className="hidden" 
              multiple 
              onChange={handleMaterialUpload} 
              accept=".pdf,.docx,.xlsx,.pptx,.jpg,.jpeg,.png"
