    if (activeSub === 'modulos') {
      const allModules = Object.values(allModulesGrouped).flatMap((group: { course: Course; modules: Module[] }) => 
        group.modules.map(m => ({ ...m, courseName: group.course.nome }))
      ).sort((a, b) => a.ordem - b.ordem);

      return (
        <div className="space-y-6 animate-in fade-in duration-500">
          <header className="flex flex-col sm:flex-row items-center justify-between gap-4">
            <div>
              <h1 className="text-2xl font-bold text-slate-900 tracking-tight">Biblioteca de Módulos</h1>
              <p className="text-slate-500 text-sm">Matriz curricular integrada de todos os cursos acadêmicos.</p>
            </div>
            <button 
              onClick={handleOpenCreateModule} 
              className="flex items-center gap-2 bg-indigo-600 text-white px-5 py-3 rounded-xl text-sm font-bold hover:bg-indigo-700 transition-all shadow-lg shadow-indigo-100"
            >
              <Plus size={18} /> Novo Módulo
            </button>
          </header>

          {loading ? (
            <div className="flex items-center justify-center p-20"><div className="h-10 w-10 animate-spin rounded-full border-4 border-indigo-600 border-t-transparent"></div></div>
          ) : allModules.length === 0 ? (
            <div className="bg-white p-24 rounded-3xl border border-dashed border-slate-200 text-center flex flex-col items-center justify-center animate-in zoom-in-95">
              <div className="w-20 h-20 bg-slate-50 rounded-full flex items-center justify-center mb-6 text-slate-300">
                <Layers size={40} />
              </div>
