            </div>
          ) : (
            <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6">
              {allModules.map((mod: any) => (
                <div key={mod.id} className="group relative bg-slate-900 rounded-3xl border border-slate-800 p-6 shadow-xl hover:border-indigo-500/50 transition-all hover:shadow-indigo-500/10 animate-in fade-in slide-in-from-bottom-4 duration-300">
                  <div className="flex flex-col h-full">
                    <div className="flex justify-between items-start mb-4">
                      <div className="px-3 py-1 bg-indigo-500/10 border border-indigo-500/20 text-indigo-400 text-[9px] font-black uppercase tracking-widest rounded-full">
                        {mod.courseName}
                      </div>
                      <div className="flex gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                        <button 
                          onClick={() => handleEditModule(mod)}
                          className="p-2 bg-slate-800 text-slate-300 hover:text-white rounded-lg transition-colors border border-slate-700"
                        >
                          <Edit size={14} />
                        </button>
                        <button 
                          onClick={() => handleDeleteModule(mod.courseId, mod.id)}
                          className="p-2 bg-red-500/10 text-red-400 hover:bg-red-500 hover:text-white rounded-lg transition-colors border border-red-500/20"
                        >
                          <Trash2 size={14} />
                        </button>
                      </div>
                    </div>

                    <h3 className="text-white font-bold text-lg mb-2 leading-tight group-hover:text-indigo-400 transition-colors">
                      {mod.ordem.toString().padStart(2, '0')}. {mod.nome}
                    </h3>

                    <div className="mt-auto flex items-center gap-4 pt-4 border-t border-slate-800">
                      <div className="flex items-center gap-2 text-slate-500 text-xs font-bold uppercase tracking-tighter">
