                            <div className="flex items-center gap-4"><div className="p-2 bg-white border border-slate-100 text-indigo-600 rounded-lg"><Play size={12} fill="currentColor" /></div><span className="text-sm font-semibold text-slate-700">{lesson.titulo}</span></div>
                            <div className="flex items-center gap-1 opacity-0 group-hover/lesson:opacity-100 transition-all">
                              <button onClick={() => openPreview(lesson, mod.id, false)} className="p-1.5 text-indigo-600 hover:bg-indigo-50 rounded-lg transition-colors" title="Pré-visualizar"><Eye size={16} /></button>
                              <button onClick={() => handleEditLesson(lesson, mod.id)} className="p-1.5 text-slate-400 hover:bg-slate-100 rounded-lg transition-colors" title="Editar Aula"><Edit size={16} /></button>
                              <button onClick={() => handleDeleteLesson(mod.id, lesson.id)} className="p-1.5 text-red-400 hover:bg-red-50 rounded-lg transition-colors" title="Excluir Aula"><Trash2 size={16} /></button>
                            </div>
                          </div>
                        ))}
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            </div>
            <div className="bg-white p-5 rounded-2xl border border-slate-200 shadow-sm sticky top-24 h-fit"><img src={selectedCourse.capaUrl || 'https://images.unsplash.com/photo-1504052434139-443c40c98408?w=800'} className="w-full h-40 object-cover rounded-xl mb-4 border border-slate-100 shadow-sm" /><div className="space-y-3"><div className="flex justify-between border-b pb-2"><span className="text-[10px] text-slate-400 uppercase font-black">Professor</span><span className="text-xs font-bold">{selectedCourse.professorResponsavel}</span></div><div className="flex justify-between border-b pb-2"><span className="text-[10px] font-black text-slate-400 uppercase ml-1">Carga Horária</span><span className="text-xs font-bold">{selectedCourse.cargaHoraria}</span></div><div className="flex justify-between border-b pb-2"><span className="text-[10px] font-black text-slate-400 uppercase ml-1">Público Alvo</span><span className="text-xs font-bold">{selectedCourse.publicoAlvo}</span></div><p className="text-[11px] text-slate-500 leading-relaxed italic">{selectedCourse.descricaoLonga}</p></div></div>
          </div>
        </div>
      );
