              <div className="lg:col-span-1 space-y-6">
                <div className="bg-gray-800 p-6 rounded-3xl shadow-lg border border-gray-700 h-[calc(100vh-14rem)] overflow-y-auto">
                  <h3 className="text-lg font-bold text-indigo-400 uppercase tracking-widest mb-6">Conteúdo Programático</h3>
                  {modules.map(mod => (
                    <div key={mod.id} className="mb-6 last:mb-0">
                      <h4 className="font-bold text-lg text-white mb-3 flex items-center gap-2"><Layers size={18} className="text-indigo-400" /> Módulo {mod.ordem}: {mod.nome}</h4>
                      <div className="space-y-2">
                        {lessonsByModule[mod.id]?.map(lesson => {
                          const isCurrent = previewLesson?.id === lesson.id;
                          const isLessonGloballyConcluded = completedLessonIds.has(lesson.id) || !isStudentSimulationMode;
                          return (
                            <div key={lesson.id}>
                              <button onClick={() => openPreview(lesson, mod.id, isStudentSimulationMode)} className={`flex items-center justify-between w-full p-3 rounded-xl transition-all ${isCurrent ? 'bg-indigo-600 text-white shadow-md' : 'bg-gray-700 text-gray-300 hover:bg-gray-600'}`}>
                                <span className="flex items-center gap-3 text-sm font-medium">{isCurrent ? <Play size={16} fill="currentColor" /> : (isLessonGloballyConcluded ? <CheckCircle size={16} className="text-emerald-400" /> : <Lock size={16} className="text-gray-500" />)}{lesson.titulo}</span>
                                {!isCurrent && <ChevronRight size={16} className="text-gray-400" />}
                              </button>
                            </div>
                          );
                        })}
                      </div>
                    </div>
                  ))}
                  {isStudentSimulationMode && (
                    <div className="mt-8 pt-6 border-t border-gray-700">
                      <div className={`p-5 rounded-2xl border transition-all duration-500 group/cert ${isCertificateUnlocked ? 'bg-indigo-500/10 border-indigo-500/50 shadow-lg shadow-indigo-500/10' : 'bg-gray-900/50 border-gray-700 opacity-60 grayscale'}`}>
                        <div className="flex items-center justify-between mb-3">
                          <div className={`p-2 rounded-lg ${isCertificateUnlocked ? 'bg-indigo-600 text-white' : 'bg-gray-800 text-gray-500'}`}>
                            <GraduationCap size={20} />
                          </div>
                          {isCertificateUnlocked ? <Award size={22} className="text-amber-400 animate-pulse" /> : <Lock size={18} className="text-gray-600" />}
                        </div>
                        <h4 className={`text-sm font-bold uppercase tracking-tight mb-1 ${isCertificateUnlocked ? 'text-white' : 'text-gray-500'}`}>Certificado de Conclusão</h4>
                        {isCertificateUnlocked && (
                          <button className="w-full mt-4 py-2.5 bg-indigo-600 hover:bg-indigo-500 text-white text-[10px] font-black uppercase tracking-widest rounded-xl transition-all shadow-lg active:scale-95 flex items-center justify-center gap-2">
                            <FileDown size={14} /> Baixar Certificado
                          </button>
                        )}
                      </div>
                    </div>
                  )}
                </div>
              </div>
            </div>
          </div>
        </div>
      );
    }

    if (activeSub === 'avaliacao') {
      return (
        <div className="space-y-6 animate-in fade-in duration-500">
          <header className="flex flex-col sm:flex-row items-center justify-between gap-4">
            <div>
              <h1 className="text-2xl font-bold text-slate-900 tracking-tight">Gestão de Avaliações</h1>
              <p className="text-slate-500 text-sm">Criação de provas, simulados e testes de proficiência acadêmica.</p>
            </div>
            <button 
              onClick={() => { setIsEditingExam(false); setIsExamModalOpen(true); }}
              className="flex items-center gap-2 bg-indigo-600 text-white px-5 py-3 rounded-xl text-sm font-bold hover:bg-indigo-700 transition-all shadow-lg shadow-indigo-100"
            >
              <PlusCircle size={18} /> Nova Avaliação
            </button>
          </header>

          {exams.length === 0 ? (
            <div className="bg-white p-24 rounded-3xl border border-dashed border-slate-200 text-center flex flex-col items-center justify-center animate-in zoom-in-95">
              <div className="w-20 h-20 bg-slate-50 rounded-full flex items-center justify-center mb-6 text-slate-300">
                <ClipboardCheck size={40} />
              </div>
              <h3 className="font-bold text-slate-900 text-lg">Nenhuma prova cadastrada</h3>
              <p className="text-slate-500 text-sm mt-1 max-w-xs">Comece a construir seu currículo de avaliações para medir o aprendizado dos alunos.</p>
            </div>
          ) : (
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              {exams.map((exam) => (
                <div key={exam.id} className="group bg-slate-900 rounded-3xl border border-slate-800 p-6 shadow-xl hover:border-indigo-500/40 transition-all relative">
                  <div className="flex justify-between items-start mb-4">
                    <div className="p-3 bg-slate-800 rounded-2xl text-indigo-400">
                      <ListChecks size={24} />
                    </div>
                    <div className="flex gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                      <button onClick={() => handleEditExam(exam)} className="p-2 text-slate-400 hover:text-white hover:bg-slate-700 rounded-lg"><Edit size={16} /></button>
                      <button onClick={() => handleDeleteExam(exam.id)} className="p-2 text-red-400 hover:text-white hover:bg-red-500 rounded-lg"><Trash2 size={16} /></button>
                    </div>
                  </div>
                  <h3 className="text-white font-bold text-lg mb-1 leading-tight">{exam.title}</h3>
                  <p className="text-indigo-400 text-[10px] font-black uppercase tracking-widest mb-4">{exam.courseName}</p>
                  <div className="flex items-center justify-between pt-4 border-t border-slate-800">
                    <div className="flex items-center gap-2 text-slate-500 text-xs font-bold uppercase tracking-tighter">
                      <ClipboardCheck size={14} />
                      <span>{exam.questions.length} Questões</span>
                    </div>
                    <span className="text-[10px] font-black text-indigo-500 uppercase tracking-widest">Média {exam.passingGrade.toFixed(1)}</span>
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>
      );
    }

    if (activeSub === 'materiais') {
      const isCritical = storagePercentage > 90;
      const isWarning = storagePercentage > 70;
      return (
        <div className="space-y-6 animate-in fade-in duration-500">
          <div className="bg-white p-6 rounded-3xl border border-slate-200 shadow-sm space-y-4">
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-3 text-slate-900"><Database size={20} className="text-indigo-600" /><h2 className="font-bold">Quota de Armazenamento</h2></div>
              <span className={`text-xs font-black uppercase tracking-widest ${isCritical ? 'text-red-600' : isWarning ? 'text-amber-600' : 'text-slate-500'}`}>{formatFileSize(currentUsedStorage)} / 5 GB Utilizados</span>
            </div>
            <div className="h-3 w-full bg-slate-100 rounded-full overflow-hidden border border-slate-50 shadow-inner"><div className={`h-full transition-all duration-1000 ${isCritical ? 'bg-red-500' : isWarning ? 'bg-amber-500' : 'bg-emerald-500'}`} style={{ width: `${Math.min(storagePercentage, 100)}%` }} /></div>
          </div>
          <header className="flex flex-col sm:flex-row items-center justify-between gap-4">
            <div><h1 className="text-2xl font-bold text-slate-900 tracking-tight">Biblioteca de Materiais</h1><p className="text-slate-500 text-sm">Gerenciamento centralizado de apostilas e mídia pedagógica.</p></div>
            <button disabled={isCritical} onClick={() => materialInputRef.current?.click()} className={`flex items-center gap-2 px-5 py-3 rounded-xl text-sm font-bold shadow-lg ${isCritical ? 'bg-slate-200 text-slate-400 cursor-not-allowed' : 'bg-slate-900 text-white hover:bg-slate-800 shadow-slate-200 active:scale-95'}`}><CloudUpload size={18} /> Upload de Arquivo</button>
            <input type="file" ref={materialInputRef} className="hidden" multiple onChange={handleMaterialUpload} accept=".pdf,.docx,.xlsx,.pptx,.jpg,.jpeg,.png" />
          </header>
          {materials.length === 0 ? (<div className="bg-white p-24 rounded-3xl border border-dashed border-slate-200 text-center flex flex-col items-center justify-center animate-in zoom-in-95"><div className="w-20 h-20 bg-slate-50 rounded-full flex items-center justify-center mb-6 text-slate-300"><CloudUpload size={40} /></div><h3 className="font-bold text-slate-900 text-lg">Sua biblioteca está vazia</h3></div>) : (
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
              {materials.map((file) => (
                <div key={file.id} className="group relative bg-slate-900 rounded-3xl border border-slate-800 p-5 shadow-xl hover:border-indigo-500/40 transition-all hover:shadow-indigo-500/10 animate-in fade-in slide-in-from-bottom-4 duration-300">
                  <div className="flex flex-col h-full"><div className="flex justify-between items-start mb-6"><div className="p-3 bg-slate-800 rounded-2xl group-hover:scale-110 transition-transform shadow-lg">{getFileIcon(file.type)}</div><div className="flex gap-1 opacity-0 group-hover:opacity-100 transition-opacity"><a href={file.url} download={file.name} className="p-2 bg-slate-800 text-slate-300 hover:text-white rounded-lg transition-colors border border-slate-700" title="Backup"><Download size={14} /></a><button onClick={() => handleDeleteMaterial(file.id)} className="p-2 bg-red-500/10 text-red-400 hover:bg-red-500 hover:text-white rounded-lg transition-colors border border-red-500/20" title="Excluir"><Trash2 size={14} /></button></div></div><div className="flex-1 min-w-0"><h3 className="text-white font-bold text-sm truncate leading-tight mb-1" title={file.name}>{file.name}</h3><div className="flex items-center gap-3"><span className="text-[10px] font-black uppercase text-slate-500 tracking-wider bg-slate-800 px-1.5 py-0.5 rounded">{file.type}</span><span className="w-1 h-1 bg-slate-700 rounded-full" /><span className="text-[10px] font-bold text-slate-500">{file.size}</span></div></div><div className="mt-4 pt-4 border-t border-slate-800 flex items-center justify-between text-[10px] font-bold text-slate-600"><span className="uppercase tracking-tighter">{file.date.toLocaleDateString('pt-BR')}</span><Database size={12} className="opacity-20" /></div></div></div>
              ))}
            </div>
          )}
        </div>
      );
    }

    if (activeSub === 'modulos') {
      const allModules = Object.values(allModulesGrouped).flatMap((group: { course: Course; modules: Module[] }) => group.modules.map(m => ({ ...m, courseName: group.course.nome }))).sort((a, b) => a.ordem - b.ordem);
      return (
        <div className="space-y-6 animate-in fade-in duration-500">
          <header className="flex flex-col sm:flex-row items-center justify-between gap-4"><div><h1 className="text-2xl font-bold text-slate-900 tracking-tight">Biblioteca de Módulos</h1><p className="text-slate-500 text-sm">Matriz curricular integrada de todos os cursos acadêmicos.</p></div><button onClick={handleOpenCreateModule} className="flex items-center gap-2 bg-indigo-600 text-white px-5 py-3 rounded-xl text-sm font-bold hover:bg-indigo-700 transition-all shadow-lg shadow-indigo-100"><Plus size={18} /> Novo Módulo</button></header>
          {loading ? (<div className="flex items-center justify-center p-20"><div className="h-10 w-10 animate-spin rounded-full border-4 border-indigo-600 border-t-transparent"></div></div>) : (
            <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6">
              {allModules.map((mod: any) => (
                <div key={mod.id} className="group relative bg-slate-900 rounded-3xl border border-slate-800 p-6 shadow-xl hover:border-indigo-500/50 transition-all hover:shadow-indigo-500/10 animate-in fade-in slide-in-from-bottom-4 duration-300"><div className="flex flex-col h-full"><div className="flex justify-between items-start mb-4"><div className="px-3 py-1 bg-indigo-500/10 border border-indigo-500/20 text-indigo-400 text-[9px] font-black uppercase tracking-widest rounded-full">{mod.courseName}</div><div className="flex gap-1 opacity-0 group-hover:opacity-100 transition-opacity"><button onClick={() => handleEditModule(mod)} className="p-2 bg-slate-800 text-slate-300 hover:text-white rounded-lg border border-slate-700"><Edit size={14} /></button><button onClick={() => handleDeleteModule(mod.courseId, mod.id)} className="p-2 bg-red-500/10 text-red-400 hover:bg-red-500 hover:text-white rounded-lg border border-red-500/20"><Trash2 size={14} /></button></div></div><h3 className="text-white font-bold text-lg mb-2 group-hover:text-indigo-400 transition-colors">{mod.ordem.toString().padStart(2, '0')}. {mod.nome}</h3><div className="mt-auto flex items-center gap-4 pt-4 border-t border-slate-800"><div className="flex items-center gap-2 text-slate-500 text-xs font-bold uppercase tracking-tighter"><FileText size={14} /><span>{lessonsByModule[mod.id]?.length || 0} Aulas</span></div><div className="flex items-center gap-2 text-slate-500 text-xs font-bold uppercase tracking-tighter"><Layers size={14} /><span>Módulo {mod.ordem}</span></div></div></div></div>
              ))}
            </div>
          )}
        </div>
      );
    }

    if (activeSub === 'cursos' && selectedCourse) {
      return (
        <div className="space-y-6 animate-in fade-in duration-500">
          <header className="flex items-center justify-between gap-4"><div className="flex items-center gap-4"><button onClick={() => setSelectedCourse(null)} className="h-10 w-10 bg-white border border-slate-200 hover:bg-slate-50 rounded-xl text-slate-600 shadow-sm flex items-center justify-center"><ArrowLeft size={20} /></button><div><h1 className="text-2xl font-bold text-slate-900 leading-tight">{selectedCourse.nome}</h1><div className="flex items-center gap-3 mt-1"><span className="text-slate-500 text-sm">{selectedCourse.tema}</span>{selectedCourse.geraCertificado && <span className="flex items-center gap-1 bg-emerald-100 text-emerald-700 text-[9px] font-black uppercase px-2 py-0.5 rounded-md"><CheckCircle size={10} /> Emite Certificado</span>}</div></div></div><button onClick={handleOpenCreateModule} className="flex items-center gap-2 bg-indigo-600 text-white px-5 py-2.5 rounded-xl text-sm font-bold shadow-lg shadow-indigo-100"><Plus size={18} /> Novo Módulo</button></header>
          <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
            <div className="lg:col-span-2 space-y-4"><div className="bg-white rounded-2xl border border-slate-200 shadow-sm overflow-hidden"><div className="px-6 py-4 border-b border-slate-100 flex items-center justify-between bg-slate-50/50"><h2 className="text-xs font-bold text-slate-800 uppercase tracking-widest">Estrutura Curricular</h2><span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">{modules.length} Módulos</span></div><div className="p-4 space-y-4">{modules.map((mod) => (<div key={mod.id} className="border border-slate-100 rounded-xl overflow-hidden group bg-slate-50/20"><div className="px-4 py-3 border-b border-slate-100 flex items-center justify-between bg-white transition-colors"><h3 className="font-bold text-slate-800 text-sm">Módulo {mod.ordem}: {mod.nome}</h3><div className="flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity"><button onClick={() => { setActiveModuleId(mod.id); setIsEditingLesson(false); setEditingLessonId(null); setLessonForm({titulo:'', descricao:'', videoUrl:'', materialUrl:''}); setShowLessonModal(true); }} className="p-1.5 text-indigo-600 hover:bg-indigo-50 rounded-lg" title="Add Aula"><Plus size={18} /></button><button onClick={() => handleEditModule(mod)} className="p-1.5 text-slate-400 hover:bg-slate-50 rounded-lg" title="Edit Mod"><Edit size={18} /></button><button onClick={() => handleDeleteModule(selectedCourse.id, mod.id)} className="p-1.5 text-red-400 hover:bg-red-50 rounded-lg" title="Delete Mod"><Trash2 size={18} /></button></div></div><div className="p-2 space-y-1">{lessonsByModule[mod.id]?.map((lesson) => (<div key={lesson.id} className="flex items-center justify-between p-3 rounded-xl hover:bg-white hover:shadow-sm transition-all group/lesson bg-transparent"><div className="flex items-center gap-4"><div className="p-2 bg-white border border-slate-100 text-indigo-600 rounded-lg"><Play size={12} fill="currentColor" /></div><span className="text-sm font-semibold text-slate-700">{lesson.titulo}</span></div><div className="flex items-center gap-1 opacity-0 group-hover/lesson:opacity-100"><button onClick={() => openPreview(lesson, mod.id, false)} className="p-1.5 text-indigo-600 hover:bg-indigo-50 rounded-lg"><Eye size={16} /></button><button onClick={() => handleEditLesson(lesson, mod.id)} className="p-1.5 text-slate-400 hover:bg-slate-100 rounded-lg"><Edit size={16} /></button><button onClick={() => handleDeleteLesson(mod.id, lesson.id)} className="p-1.5 text-red-400 hover:bg-red-50 rounded-lg"><Trash2 size={16} /></button></div></div>))}</div></div>))}</div></div></div>
            <div className="bg-white p-5 rounded-2xl border border-slate-200 shadow-sm sticky top-24 h-fit"><img src={selectedCourse.capaUrl || 'https://images.unsplash.com/photo-1504052434139-443c40c98408?w=800'} className="w-full h-40 object-cover rounded-xl mb-4 shadow-sm" /><div className="space-y-3"><div className="flex justify-between border-b pb-2"><span className="text-[10px] text-slate-400 uppercase font-black">Professor</span><span className="text-xs font-bold">{selectedCourse.professorResponsavel}</span></div><div className="flex justify-between border-b pb-2"><span className="text-[10px] font-black text-slate-400 uppercase ml-1">Carga Horária</span><span className="text-xs font-bold">{selectedCourse.cargaHoraria}</span></div><div className="flex justify-between border-b pb-2"><span className="text-[10px] font-black text-slate-400 uppercase ml-1">Público Alvo</span><span className="text-xs font-bold">{selectedCourse.publicoAlvo}</span></div><p className="text-[11px] text-slate-500 leading-relaxed italic">{selectedCourse.descricaoLonga}</p></div></div>
          </div>
        </div>
      );
    }

    return (
      <div className="space-y-6 animate-in fade-in duration-500"><header className="flex flex-col sm:flex-row items-center justify-between gap-4"><div><h1 className="text-2xl font-bold text-slate-900 tracking-tight">Portal do Professor</h1><p className="text-slate-500 text-sm font-medium">Gestão acadêmica e configuração de cursos EAD.</p></div><button onClick={() => { setIsEditingCourse(false); setEditingCourseId(null); setCourseForm({ nome: '', tema: '', professorResponsavel: user.displayName || '', descricaoLonga: '', capaUrl: '', cargaHoraria: '', publicoAlvo: 'Geral', geraCertificado: false }); setShowCourseModal(true); }} className="flex items-center gap-2 bg-indigo-600 text-white px-5 py-3 rounded-xl text-sm font-bold shadow-lg"><Plus size={18} /> Novo Curso</button></header><div className="grid grid-cols-1 md:grid-cols-3 xl:grid-cols-6 gap-4">{loading ? (<div className="col-span-full py-20 flex justify-center"><div className="h-6 w-6 animate-spin rounded-full border-2 border-indigo-600 border-t-transparent"></div></div>) : myCourses.map(course => (<div key={course.id} onClick={() => openCourseDetail(course)} className="bg-white border border-slate-200 rounded-2xl overflow-hidden hover:shadow-xl hover:border-indigo-200 transition-all group cursor-pointer flex flex-col relative overflow-visible"><div className="absolute top-2 right-2 z-50"><button onClick={(e) => { e.stopPropagation(); setOpenMenuId(openMenuId === course.id ? null : course.id); }} className="p-1.5 bg-white/90 backdrop-blur-sm rounded-lg border border-slate-200 text-slate-500 shadow-sm"><MoreVertical size={14} /></button>{openMenuId === course.id && (<div className="absolute right-0 mt-1 w-32 bg-white rounded-xl shadow-2xl border border-slate-100 z-50 overflow-hidden text-[10px] font-bold"><button onClick={(e) => { e.stopPropagation(); handleEditCourseInfo(course); }} className="w-full px-3 py-2 text-left hover:bg-slate-50 flex items-center gap-2 transition-colors"><Edit size={12} /> Editar Info</button><button onClick={(e) => { e.stopPropagation(); handleDuplicateCourse(course); }} className="w-full px-3 py-2 text-left hover:bg-slate-50 flex items-center gap-2 transition-colors"><Copy size={12} /> Duplicar</button><button onClick={(e) => { e.stopPropagation(); handleDeleteCourse(course.id); }} className="w-full px-3 py-2 text-left hover:bg-red-50 text-red-500 flex items-center gap-2 transition-colors"><Trash2 size={12} /> Excluir</button></div>)}</div><div className="h-24 overflow-hidden bg-slate-100 border-b border-slate-100 relative">{course.capaUrl ? <img src={course.capaUrl} className="w-full h-full object-cover group-hover:scale-105 transition-transform" /> : <div className="h-full flex items-center justify-center text-slate-200"><BookOpen size={32} /></div>}<div className="absolute top-1 left-1 flex gap-1"><span className={`px-1.5 py-0.5 rounded text-[8px] font-black uppercase shadow-sm ${course.status === 'ativo' ? 'bg-emerald-500 text-white' : 'bg-slate-700 text-white'}`}>{course.status}</span></div></div><div className="p-3 flex-1 flex flex-col"><h3 className="font-bold text-slate-900 text-xs mb-1 group-hover:text-indigo-600 transition-colors leading-tight line-clamp-2">{course.nome}</h3><p className="text-[8px] text-slate-400 font-bold uppercase tracking-widest mb-2">{course.tema || 'Geral'}</p><div className="mt-auto pt-2 border-t border-slate-50 flex items-center justify-between text-[8px] text-slate-400 font-black uppercase tracking-widest"><div className="flex items-center gap-1"><Layout size={10} /><span>Ver Matriz</span></div><ChevronRight size={10} className="group-hover:translate-x-0.5 transition-transform" /></div></div></div>))}</div></div>
    );
  };

  return (
    <div className="relative">
      {renderMainContent()}

      {/* MODAL GLOBAL: CONSTRUTOR DE AVALIAÇÃO (EVALUATION BUILDER) */}
      {isExamModalOpen && (
        <div className="fixed inset-0 !z-[9999] flex items-center justify-center p-4 bg-slate-950/80 backdrop-blur-md animate-in fade-in duration-300">
          <div className="bg-slate-900 w-full max-w-4xl max-h-[90vh] rounded-3xl shadow-2xl overflow-hidden flex flex-col animate-in zoom-in-95 border border-slate-800">
            <header className="px-8 py-6 border-b border-slate-800 flex items-center justify-between">
              <div className="flex items-center gap-4">
                <div className="p-3 bg-indigo-600 text-white rounded-2xl shadow-lg shadow-indigo-600/20">
                  <ListChecks size={24} />
                </div>
                <div>
                  <h2 className="text-xl font-bold text-white leading-none">{isEditingExam ? 'Editar Avaliação' : 'Nova Avaliação Acadêmica'}</h2>
                  <p className="text-slate-500 text-[10px] font-bold uppercase tracking-[0.2em] mt-2">Construtor de Currículo Pedagógico</p>
                </div>
              </div>
              <button onClick={() => setIsExamModalOpen(false)} className="text-slate-500 hover:text-white transition-colors"><X size={24} /></button>
            </header>

            <form onSubmit={handleSaveExam} className="flex-1 overflow-y-auto p-8 space-y-10">
              {/* Configurações Básicas */}
              <div className="grid grid-cols-1 md:grid-cols-12 gap-6">
                <div className="md:col-span-6 space-y-2">
                  <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">Título da Prova</label>
                  <input required value={examForm.title} onChange={e => setExamForm({...examForm, title: e.target.value})} placeholder="Ex: Prova Mensal - Teologia Sistemática" className="w-full px-5 py-4 bg-slate-800 border border-slate-700 rounded-2xl text-white outline-none focus:ring-2 focus:ring-indigo-500 transition-all" />
                </div>
                <div className="md:col-span-4 space-y-2">
                  <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">Curso Vinculado</label>
                  <select required value={examForm.courseId} onChange={e => setExamForm({...examForm, courseId: e.target.value})} className="w-full px-5 py-4 bg-slate-800 border border-slate-700 rounded-2xl text-white outline-none focus:ring-2 focus:ring-indigo-500">
                    <option value="">Selecione o curso...</option>
                    {myCourses.map(c => <option key={c.id} value={c.id}>{c.nome}</option>)}
                  </select>
                </div>
                <div className="md:col-span-2 space-y-2">
                  <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">Nota Mínima</label>
                  <input type="number" step="0.1" value={examForm.passingGrade} onChange={e => setExamForm({...examForm, passingGrade: parseFloat(e.target.value)})} className="w-full px-5 py-4 bg-slate-800 border border-slate-700 rounded-2xl text-white outline-none" />
                </div>
              </div>

              {/* Questões */}
              <div className="space-y-6">
                <div className="flex items-center justify-between border-b border-slate-800 pb-4">
                  <h3 className="font-black text-indigo-400 text-xs uppercase tracking-[0.3em]">Questões da Avaliação</h3>
                  <button type="button" onClick={handleAddQuestion} className="flex items-center gap-2 text-indigo-400 hover:text-indigo-300 transition-colors font-bold text-xs uppercase">
                    <Plus size={16} /> Adicionar Pergunta
                  </button>
                </div>

                <div className="space-y-8">
                  {examForm.questions.map((q, qIndex) => (
                    <div key={q.id} className="bg-slate-800/40 p-6 rounded-3xl border border-slate-700/50 relative group/q animate-in slide-in-from-top-4">
                      <button type="button" onClick={() => handleRemoveQuestion(qIndex)} className="absolute -top-2 -right-2 p-2 bg-red-500 text-white rounded-full opacity-0 group-hover/q:opacity-100 transition-opacity shadow-lg">
                        <Trash2 size={14} />
                      </button>

                      <div className="space-y-6">
                        <div className="flex gap-4">
                          <span className="h-10 w-10 bg-indigo-600/20 text-indigo-400 border border-indigo-600/30 rounded-xl flex items-center justify-center font-bold text-sm shrink-0">{qIndex + 1}</span>
                          <input required value={q.text} onChange={e => handleUpdateQuestionText(qIndex, e.target.value)} placeholder="Enunciado da questão..." className="flex-1 bg-transparent border-b border-slate-700 focus:border-indigo-500 outline-none text-white font-medium py-2 transition-colors" />
                        </div>

                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4 pl-14">
                          {q.options.map((opt, oIndex) => (
                            <div key={oIndex} className={`flex items-center gap-3 p-3 rounded-2xl border transition-all ${q.correctOptionIndex === oIndex ? 'bg-emerald-500/10 border-emerald-500/50 shadow-lg shadow-emerald-500/5' : 'bg-slate-900/50 border-slate-700/50'}`}>
                              <button type="button" onClick={() => handleSetCorrectAnswer(qIndex, oIndex)} className={`h-5 w-5 rounded-full border-2 flex items-center justify-center transition-all ${q.correctOptionIndex === oIndex ? 'bg-emerald-500 border-emerald-500 text-white' : 'border-slate-600 hover:border-indigo-500'}`}>
                                {q.correctOptionIndex === oIndex && <CheckCircle size={14} />}
                              </button>
                              <input required value={opt} onChange={e => handleUpdateOption(qIndex, oIndex, e.target.value)} placeholder={`Alternativa ${String.fromCharCode(65 + oIndex)}`} className="bg-transparent text-xs text-white outline-none flex-1 placeholder:text-slate-600" />
                            </div>
                          ))}
                        </div>
                      </div>
                    </div>
                  ))}
                </div>
              </div>

              <footer className="pt-8 flex gap-4">
                <button type="button" onClick={() => setIsExamModalOpen(false)} className="flex-1 px-8 py-5 border border-slate-700 text-slate-400 rounded-2xl font-bold uppercase tracking-widest hover:bg-slate-800 transition-all">Cancelar</button>
                <button type="submit" className="flex-[2] px-8 py-5 bg-indigo-600 text-white rounded-2xl font-black uppercase tracking-widest shadow-xl shadow-indigo-600/20 hover:bg-indigo-500 transition-all active:scale-95">Salvar Avaliação Digital</button>
              </footer>
            </form>
          </div>
        </div>
      )}

      {/* MODALS EXISTENTES (Módulos, Aulas, Cursos) */}
      {isModuleModalOpen && (
        <div className="fixed inset-0 !z-[9999] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm animate-in fade-in duration-200">
          <div className="bg-white w-full max-w-md rounded-2xl shadow-2xl p-6 border border-slate-100">
            <h3 className="font-bold text-slate-900 mb-4">{currentEditingModule ? 'Editar Módulo' : 'Configurar Novo Módulo'}</h3>
            <form onSubmit={handleSaveModule} className="space-y-5">
              {!selectedCourse && !currentEditingModule && (<div className="space-y-1"><label className="text-[10px] font-black text-slate-400 uppercase ml-1">Curso</label><select required value={moduleForm.courseId} onChange={e => setModuleForm({...moduleForm, courseId: e.target.value})} className="w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm outline-none focus:ring-2 focus:ring-indigo-500">{myCourses.map(c => <option key={c.id} value={c.id}>{c.nome}</option>)}</select></div>)}
              <div className="space-y-1"><label className="text-[10px] font-black text-slate-400 uppercase ml-1">Título</label><input required autoFocus value={moduleForm.nome} onChange={e => setModuleForm({...moduleForm, nome: e.target.value})} className="w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm outline-none" /></div>
              <div className="flex gap-3"><button type="button" onClick={() => setIsModuleModalOpen(false)} className="flex-1 px-4 py-2.5 border rounded-xl font-bold text-sm">Cancelar</button><button type="submit" className="flex-1 bg-indigo-600 text-white py-2.5 rounded-xl font-bold text-sm shadow-lg">{currentEditingModule ? 'Salvar' : 'Criar'}</button></div>
            </form>
          </div>
        </div>
      )}

      {showLessonModal && (
        <div className="fixed inset-0 !z-[9998] flex items-center justify-center p-4 bg-slate-900/40 backdrop-blur-sm animate-in fade-in">
          <div className="bg-white w-full max-w-lg rounded-2xl shadow-2xl p-6"><h3 className="font-bold text-slate-900 mb-4">{isEditingLesson ? 'Editar Aula' : 'Nova Aula'}</h3><form onSubmit={handleSaveLesson} className="space-y-4"><input required value={lessonForm.titulo} onChange={e => setLessonForm({...lessonForm, titulo: e.target.value})} placeholder="Título" className="w-full px-4 py-2.5 bg-slate-50 border rounded-xl text-sm" /><textarea value={lessonForm.descricao} onChange={e => setLessonForm({...lessonForm, descricao: e.target.value})} placeholder="Descrição" className="w-full px-4 py-2.5 bg-slate-50 border rounded-xl text-sm" rows={4}></textarea><div className="grid grid-cols-2 gap-4"><input value={lessonForm.videoUrl} onChange={e => setLessonForm({...lessonForm, videoUrl: e.target.value})} placeholder="YouTube URL" className="w-full px-4 py-2.5 bg-slate-50 border rounded-xl text-sm" /><input value={lessonForm.materialUrl} onChange={e => setLessonForm({...lessonForm, materialUrl: e.target.value})} placeholder="Material URL" className="w-full px-4 py-2.5 bg-slate-50 border rounded-xl text-sm" /></div><div className="flex gap-3"><button type="button" onClick={() => setShowLessonModal(false)} className="flex-1 py-3 border rounded-xl font-bold text-sm">Cancelar</button><button type="submit" className="flex-1 bg-indigo-600 text-white py-3 rounded-xl font-bold text-sm shadow-lg">{isEditingLesson ? 'Salvar' : 'Publicar'}</button></div></form></div>
        </div>
      )}

      {showCourseModal && (
        <div className="fixed inset-0 !z-[9997] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm animate-in fade-in"><div className="bg-white w-full max-w-2xl rounded-3xl shadow-2xl overflow-hidden animate-in zoom-in-95 flex flex-col max-h-[90vh]"><div className="p-6 border-b flex items-center justify-between"><div className="flex items-center gap-3"><div className="bg-indigo-600 p-2.5 rounded-xl text-white"><GraduationCap size={20} /></div><h3 className="font-bold text-slate-900 text-lg">{isEditingCourse ? 'Editar Curso' : 'Novo Curso'}</h3></div><button onClick={handleCloseCourseModal} className="text-slate-400 p-2"><X size={20} /></button></div><form onSubmit={handleSaveCourse} className="p-8 space-y-6 overflow-y-auto"><div className="grid grid-cols-1 md:grid-cols-2 gap-6"><div className="space-y-4"><div className="space-y-1"><label className="text-[10px] font-black uppercase">Título</label><input required value={courseForm.nome} onChange={e => setCourseForm({...courseForm, nome: e.target.value})} className="w-full px-4 py-3 bg-slate-50 border rounded-2xl text-sm" /></div><div className="space-y-1"><label className="text-[10px] font-black uppercase">Docente</label><input required value={courseForm.professorResponsavel} onChange={e => setCourseForm({...courseForm, professorResponsavel: e.target.value})} className="w-full px-4 py-3 bg-slate-50 border rounded-2xl text-sm" /></div></div><div className="space-y-4"><div className="space-y-1"><label className="text-[10px] font-black uppercase">Capa</label><div className="relative h-32 bg-slate-50 border-2 border-dashed rounded-2xl flex flex-col items-center justify-center"><input type="file" onChange={handleFileUpload} className="absolute inset-0 opacity-0" />{courseForm.capaUrl ? <img src={courseForm.capaUrl} className="w-full h-full object-cover rounded-2xl" /> : <><FileUp size={24} className="text-slate-300" /><span className="text-[10px] font-bold">Enviar</span></>}</div></div></div></div><div className="flex gap-3"><button type="button" onClick={handleCloseCourseModal} className="flex-1 py-4 border rounded-2xl font-bold text-sm">Descartar</button><button type="submit" disabled={loading} className="flex-[2] bg-slate-900 text-white py-4 rounded-2xl font-black text-sm uppercase shadow-xl transition-all">{loading ? 'Processando...' : 'Confirmar'}</button></div></form></div></div>
      )}
    </div>
  );
};

export default ProfessorView;

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { 
  collection, 
  query, 
  where, 
  getDocs, 
  addDoc, 
  deleteDoc,
  serverTimestamp, 
  orderBy,
  doc,
  updateDoc,
  getDoc,
  arrayUnion 
} from 'firebase/firestore';
import { db } from '../firebase';
import { Course, Module, Lesson, User, ProfessorSubView } from '../types';
import { 
  BookOpen, 
  Plus, 
  X, 
  ChevronRight, 
  Play, 
  Pause, 
  Volume2, 
  VolumeX, 
  Maximize, 
  MoreVertical, 
  ArrowLeft, 
  Layout, 
  Trash2, 
  Layers, 
  Eye, 
  CheckCircle, 
  Copy, 
  Edit, 
  GraduationCap, 
  FileUp, 
  FileDown,
  Lock,
  FileText,
  Award,
  File,
  FileImage,
  FileSpreadsheet,
  CloudUpload,
  Download,
  Database,
  AlertTriangle,
  ClipboardCheck,
  ListChecks,
  PlusCircle,
  Search,
  Library
} from 'lucide-react';

// Constante de Armazenamento Máximo (5GB)
const MAX_STORAGE = 5 * 1024 * 1024 * 1024;

interface MaterialFile {
  id: string;
  name: string;
  type: string;
  size: string;
  sizeBytes: number;
  date: Date;
  url: string;
}

interface Question {
  id: string;
  text: string;
  options: string[];
  correctOptionIndex: number;
}

interface Exam {
  id: string;
  title: string;
  courseId: string;
  courseName: string;
  passingGrade: number;
  questions: Question[];
}

interface ProfessorViewProps {
  user: User;
  activeSub: ProfessorSubView;
  setActiveSub: (view: ProfessorSubView) => void;
}

const ProfessorView: React.FC<ProfessorViewProps> = ({ user, activeSub, setActiveSub }) => {
  const [myCourses, setMyCourses] = useState<Course[]>([]);
  const [loading, setLoading] = useState(true);
  const [selectedCourse, setSelectedCourse] = useState<Course | null>(null);
  const [modules, setModules] = useState<Module[]>([]);
  const [lessonsByModule, setLessonsByModule] = useState<Record<string, Lesson[]>>({});
  const [allModulesGrouped, setAllModulesGrouped] = useState<Record<string, { course: Course, modules: Module[] }>>({});
  const [openMenuId, setOpenMenuId] = useState<string | null>(null);

  // State para Materiais
  const [materials, setMaterials] = useState<MaterialFile[]>(() => {
    const saved = sessionStorage.getItem('eb_materials_mock');
    return saved ? JSON.parse(saved).map((m: any) => ({...m, date: new Date(m.date)})) : [];
  });

  // State para o Material Picker (INTEGRAÇÃO)
  const [isMaterialPickerOpen, setIsMaterialPickerOpen] = useState(false);
  const [pickerMode, setPickerMode] = useState<'image' | 'document'>('document');
  const [pickerCallback, setPickerCallback] = useState<(url: string) => void>(() => {});

  // State para Avaliações (Exams)
  const [exams, setExams] = useState<Exam[]>(() => {
    const saved = sessionStorage.getItem('eb_exams_mock');
    return saved ? JSON.parse(saved) : [];
  });
  const [isExamModalOpen, setIsExamModalOpen] = useState(false);
  const [isEditingExam, setIsEditingExam] = useState(false);
  const [examForm, setExamForm] = useState<{
    id?: string;
    title: string;
    courseId: string;
    passingGrade: number;
    questions: Question[];
  }>({
    title: '',
    courseId: '',
    passingGrade: 7.0,
    questions: [{ id: '1', text: '', options: ['', '', '', ''], correctOptionIndex: 0 }]
  });

  const materialInputRef = useRef<HTMLInputElement>(null);

  // Persistência simulada
  useEffect(() => {
    sessionStorage.setItem('eb_materials_mock', JSON.stringify(materials));
  }, [materials]);

  useEffect(() => {
    sessionStorage.setItem('eb_exams_mock', JSON.stringify(exams));
  }, [exams]);

  // Modal States
  const [showCourseModal, setShowCourseModal] = useState(false);
  const [isEditingCourse, setIsEditingCourse] = useState(false);
  const [editingCourseId, setEditingCourseId] = useState<string | null>(null);

  const [isModuleModalOpen, setIsModuleModalOpen] = useState(false); 
  const [showLessonModal, setShowLessonModal] = useState(false);
  const [isEditingLesson, setIsEditingLesson] = useState(false);
  const [activeModuleId, setActiveModuleId] = useState<string | null>(null);
  const [currentEditingModule, setCurrentEditingModule] = useState<Module | null>(null); 
  const [editingLessonId, setEditingLessonId] = useState<string | null>(null);

  // Preview States
  const [previewLesson, setPreviewLesson] = useState<Lesson | null>(null);
  const [isConcluded, setIsConcluded] = useState(false);
  const [isPlaying, setIsPlaying] = useState(false);
  const [timeLeft, setTimeLeft] = useState(300);
  const timerIntervalRef = useRef<number | null>(null);
  const [showWelcomeModal, setShowWelcomeModal] = useState(false);
  const [showCompletionModal, setShowCompletionModal] = useState(false);

  const [isStudentSimulationMode, setIsStudentSimulationMode] = useState(false);
  const [isCertificateUnlocked, setIsCertificateUnlocked] = useState(false);
  const [completedLessonIds, setCompletedLessonIds] = useState<Set<string>>(new Set());
  const [totalLessons, setTotalLessons] = useState(0);

  const [playerVolume, setPlayerVolume] = useState(80); 
  const [isMuted, setIsMuted] = useState(false); 
  const iframeRef = useRef<HTMLIFrameElement>(null); 
  const playerContainerRef = useRef<HTMLDivElement>(null); 

  // Form States
  const [courseForm, setCourseForm] = useState({
    nome: '', tema: '', professorResponsavel: user.displayName || '',
    descricaoLonga: '', capaUrl: '', cargaHoraria: '',
    publicoAlvo: 'Geral' as const, geraCertificado: false
  });
  const [moduleForm, setModuleForm] = useState({ nome: '', courseId: '' });
  const [lessonForm, setLessonForm] = useState({
    titulo: '', descricao: '', videoUrl: '', materialUrl: ''
  });

  // --- Funções de Dados ---
  const fetchMyCourses = async () => {
    setLoading(true);
    try {
      const q = query(collection(db, 'cursos'), where('professorId', '==', user.uid), orderBy('createdAt', 'desc'));
      const querySnapshot = await getDocs(q);
      const fetched: Course[] = [];
      querySnapshot.forEach((doc) => {
        fetched.push({ id: doc.id, ...doc.data() } as Course);
      });
      setMyCourses(fetched);
    } catch (error) {
      console.error(error);
    } finally {
      setLoading(false);
    }
  };

  const fetchModulesForCourse = async (courseId: string) => {
    const q = query(collection(db, 'cursos', courseId, 'modulos'), orderBy('ordem', 'asc'));
    const querySnapshot = await getDocs(q);
    const fetched: Module[] = [];
    querySnapshot.forEach((doc) => {
      fetched.push({ id: doc.id, ...doc.data(), courseId } as Module);
    });
    return fetched;
  };

  const fetchAllModulesGrouped = async () => {
    setLoading(true);
    try {
      const grouped: Record<string, { course: Course, modules: Module[] }> = {};
      for (const course of myCourses) {
        const mods = await fetchModulesForCourse(course.id);
        for (const mod of mods) {
          await fetchLessons(course.id, mod.id);
        }
        grouped[course.id] = { course, modules: mods };
      }
      setAllModulesGrouped(grouped);
    } catch (error) {
      console.error(error);
    } finally {
      setLoading(false);
    }
  };

  const fetchLessons = async (courseId: string, moduleId: string) => {
    try {
      const q = query(collection(db, 'cursos', courseId, 'modulos', moduleId, 'aulas'), orderBy('ordem', 'asc'));
      const querySnapshot = await getDocs(q);
      const fetched: Lesson[] = [];
      querySnapshot.forEach((doc) => {
        fetched.push({ id: doc.id, ...doc.data() } as Lesson);
      });
      setLessonsByModule(prev => ({ ...prev, [moduleId]: fetched }));
    } catch (error) {
      console.error(error);
    }
  };

  const fetchCompletedLessons = useCallback(async (studentId: string, courseId: string) => {
    if (!studentId || !courseId) return new Set<string>();
    try {
      const key = `completed_lessons_sim_${studentId}_${courseId}`;
      const stored = localStorage.getItem(key);
      return new Set(stored ? JSON.parse(stored) : []);
    } catch (error) {
      console.error(error);
    }
    return new Set<string>();
  }, []);

  const updateCompletedLesson = useCallback(async (studentId: string, lessonId: string) => {
    if (!studentId || !lessonId) return;
    try {
      const key = `completed_lessons_sim_${studentId}_${selectedCourse?.id}`;
      const currentCompleted = await fetchCompletedLessons(studentId, selectedCourse?.id || '');
      if (!currentCompleted.has(lessonId)) {
        currentCompleted.add(lessonId);
        localStorage.setItem(key, JSON.stringify(Array.from(currentCompleted)));
        setCompletedLessonIds(currentCompleted);
      }
    } catch (error) {
      console.error(error);
    }
  }, [fetchCompletedLessons, selectedCourse?.id]);

  // --- Effects ---
  useEffect(() => { fetchMyCourses(); }, [user.uid]);

  useEffect(() => {
    if (activeSub === 'modulos') { fetchAllModulesGrouped(); }
  }, [activeSub, myCourses]);

  useEffect(() => {
    if (selectedCourse && modules.length > 0) {
      let count = 0;
      for (const mod of modules) { count += (lessonsByModule[mod.id]?.length || 0); }
      setTotalLessons(count);
    } else { setTotalLessons(0); }
  }, [selectedCourse, modules, lessonsByModule]);

  useEffect(() => {
    const shouldStartTimer = isStudentSimulationMode && previewLesson && !showWelcomeModal && isPlaying;
    if (shouldStartTimer && timeLeft > 0) {
      if (!timerIntervalRef.current) {
        timerIntervalRef.current = window.setInterval(async () => {
          setTimeLeft(prevTime => {
            if (prevTime <= 1) {
              if (timerIntervalRef.current) { clearInterval(timerIntervalRef.current); timerIntervalRef.current = null; }
              setIsConcluded(true);
              if (user.uid && previewLesson?.id) { updateCompletedLesson(user.uid, previewLesson.id); }
              if (!showCompletionModal) { setShowCompletionModal(true); }
              return 0;
            }
            return prevTime - 1;
          });
        }, 1000);
      }
    } else if (timerIntervalRef.current) {
      clearInterval(timerIntervalRef.current);
      timerIntervalRef.current = null;
    }
    return () => { if (timerIntervalRef.current) { clearInterval(timerIntervalRef.current); timerIntervalRef.current = null; } };
  }, [previewLesson, isStudentSimulationMode, showWelcomeModal, isPlaying, timeLeft, showCompletionModal, user.uid, previewLesson?.id, updateCompletedLesson]);

  useEffect(() => {
    if (selectedCourse && user.uid) { fetchCompletedLessons(user.uid, selectedCourse.id).then(setCompletedLessonIds); }
    else { setCompletedLessonIds(new Set()); }
  }, [selectedCourse, user.uid, fetchCompletedLessons]);

  const getYouTubeVideoId = (url: string) => {
    const ytRegex = /(?:https?:\/\/)?(?:www\.)?(?:youtube\.com\/(?:[^\/\n\s]+\/\S+\/|(?:v|e(?:mbed)?)\/|\S*?[?&]v=)|youtu\.be\/)([a-zA-Z0-9_-]{11})/;
    const ytMatch = url.match(ytRegex);
    return ytMatch && ytMatch[1];
  };

  const sendPlayerCommand = useCallback((command: string, args: any = '') => {
    if (iframeRef.current && iframeRef.current.contentWindow) {
      iframeRef.current.contentWindow.postMessage(JSON.stringify({ event: 'command', func: command, args: args }), '*');
    }
  }, []);

  const togglePlay = () => {
    if (isPlaying) { sendPlayerCommand('pauseVideo'); setIsPlaying(false); }
    else { sendPlayerCommand('playVideo'); setIsPlaying(true); setShowWelcomeModal(false); }
  };

  const toggleMute = () => {
    if (isMuted) { sendPlayerCommand('unMute'); } else { sendPlayerCommand('mute'); }
    setIsMuted(prev => !prev);
  };

  const handleVolumeChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const vol = parseInt(e.target.value);
    setPlayerVolume(vol);
    if (vol === 0) { if (!isMuted) sendPlayerCommand('mute'); setIsMuted(true); }
    else { if (isMuted) sendPlayerCommand('unMute'); sendPlayerCommand('setVolume', [vol]); setIsMuted(false); }
  };

  const toggleFullscreen = () => {
    if (playerContainerRef.current) {
      if (!document.fullscreenElement) playerContainerRef.current.requestFullscreen();
      else document.exitFullscreen();
    }
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    if (file.size > 5 * 1024 * 1024) { alert("A imagem de capa não pode exceder 5 MB."); e.target.value = ''; return; }
    const reader = new FileReader();
    reader.onloadend = () => { setCourseForm(prev => ({ ...prev, capaUrl: reader.result as string })); };
    reader.readAsDataURL(file);
  };

  const handleSaveCourse = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      setLoading(true);
      if (isEditingCourse && editingCourseId) {
        const courseRef = doc(db, 'cursos', editingCourseId);
        await updateDoc(courseRef, { ...courseForm });
        if (selectedCourse?.id === editingCourseId) { setSelectedCourse({ ...selectedCourse, ...courseForm }); }
      } else {
        await addDoc(collection(db, 'cursos'), { ...courseForm, professorId: user.uid, inscritos: 0, status: 'rascunho', createdAt: serverTimestamp() });
      }
      handleCloseCourseModal();
      await fetchMyCourses();
    } catch (error) {
      console.error(error);
    } finally { setLoading(false); }
  };

  const handleEditCourseInfo = (course: Course) => {
    setCourseForm({
      nome: course.nome, tema: course.tema || '', professorResponsavel: course.professorResponsavel || '',
      descricaoLonga: course.descricaoLonga || '', capaUrl: course.capaUrl || '',
      cargaHoraria: course.cargaHoraria, publicoAlvo: course.publicoAlvo,
      geraCertificado: course.geraCertificado || false
    });
    setEditingCourseId(course.id);
    setIsEditingCourse(true);
    setShowCourseModal(true);
    setOpenMenuId(null);
  };

  const handleCloseCourseModal = () => {
    setShowCourseModal(false);
    setIsEditingCourse(false);
    setEditingCourseId(null);
    setCourseForm({
      nome: '', tema: '', professorResponsavel: user.displayName || '',
      descricaoLonga: '', capaUrl: '', cargaHoraria: '',
      publicoAlvo: 'Geral', geraCertificado: false
    });
  };

  const handleDeleteCourse = async (courseId: string) => {
    if (!confirm("Tem certeza que deseja excluir o curso inteiro?")) return;
    try {
      await deleteDoc(doc(db, 'cursos', courseId));
      setMyCourses(prev => prev.filter(c => c.id !== courseId));
      setOpenMenuId(null);
    } catch (error) { console.error(error); }
  };

  const handleDuplicateCourse = async (course: Course) => {
    try {
      const { id, ...data } = course;
      await addDoc(collection(db, 'cursos'), { ...data, nome: `${data.nome} (Cópia)`, createdAt: serverTimestamp() });
      fetchMyCourses();
      setOpenMenuId(null);
    } catch (error) { console.error(error); }
  };

  const handleDeleteModule = async (courseId: string, moduleId: string) => {
    if (!confirm("Excluir este módulo e todo seu conteúdo?")) return;
    try {
      await deleteDoc(doc(db, 'cursos', courseId, 'modulos', moduleId));
      if (selectedCourse) { setModules(prev => prev.filter(m => m.id !== moduleId)); }
      fetchAllModulesGrouped();
    } catch (error) { console.error(error); }
  };

  const handleSaveModule = async (e: React.FormEvent) => {
    e.preventDefault();
    const finalCourseId = selectedCourse?.id || moduleForm.courseId;
    if (!finalCourseId) {
       alert("Selecione um curso.");
       return;
    }
    try {
      if (currentEditingModule) {
        const modRef = doc(db, 'cursos', currentEditingModule.courseId, 'modulos', currentEditingModule.id);
        await updateDoc(modRef, { nome: moduleForm.nome });
      } else {
        const qOrder = query(collection(db, 'cursos', finalCourseId, 'modulos'));
        const snapOrder = await getDocs(qOrder);
        const nextOrder = snapOrder.size + 1;

        await addDoc(collection(db, 'cursos', finalCourseId, 'modulos'), { 
          nome: moduleForm.nome, 
          ordem: nextOrder, 
          createdAt: serverTimestamp() 
        });
      }
      setIsModuleModalOpen(false);
      setModuleForm({ nome: '', courseId: '' });
      setCurrentEditingModule(null);
      if (selectedCourse) {
         const mods = await fetchModulesForCourse(selectedCourse.id);
         setModules(mods);
      }
      fetchAllModulesGrouped();
    } catch (error) { console.error(error); }
  };

  const handleOpenCreateModule = () => {
    setModuleForm({ nome: '', courseId: selectedCourse?.id || '' });
    setCurrentEditingModule(null);
    setIsModuleModalOpen(true);
  };

  const handleEditModule = (mod: Module) => {
    setCurrentEditingModule(mod);
    setModuleForm({ nome: mod.nome, courseId: mod.courseId });
    setIsModuleModalOpen(true);
  };

  const handleSaveLesson = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedCourse || !activeModuleId) return;
    try {
      if (isEditingLesson && editingLessonId) {
        const lessonRef = doc(db, 'cursos', selectedCourse.id, 'modulos', activeModuleId, 'aulas', editingLessonId);
        await updateDoc(lessonRef, { ...lessonForm });
        if (previewLesson && previewLesson.id === editingLessonId) {
           setPreviewLesson(prev => prev ? ({ ...prev, ...lessonForm }) : null);
        }
      } else {
        await addDoc(collection(db, 'cursos', selectedCourse.id, 'modulos', activeModuleId, 'aulas'), { ...lessonForm, ordem: (lessonsByModule[activeModuleId]?.length || 0) + 1, createdAt: serverTimestamp() });
      }
      setShowLessonModal(false);
      setIsEditingLesson(false);
      setEditingLessonId(null);
      setLessonForm({ titulo: '', descricao: '', videoUrl: '', materialUrl: '' });
      fetchLessons(selectedCourse.id, activeModuleId);
    } catch (error) { console.error(error); }
  };

  const handleDeleteLesson = async (moduleId: string, lessonId: string) => {
    if (!selectedCourse) return;
    if (!confirm("Tem certeza que deseja DESTRUIR esta aula permanentemente?")) return;
    try {
      await deleteDoc(doc(db, 'cursos', selectedCourse.id, 'modulos', moduleId, 'aulas', lessonId));
      fetchLessons(selectedCourse.id, moduleId);
      if (previewLesson?.id === lessonId) setPreviewLesson(null);
    } catch (error) { console.error(error); }
  };

  const handleEditLesson = (lesson: Lesson, moduleId: string) => {
    setActiveModuleId(moduleId);
    setLessonForm({ titulo: lesson.titulo, descricao: lesson.descricao || '', videoUrl: lesson.videoUrl, materialUrl: lesson.materialUrl });
    setEditingLessonId(lesson.id);
    setIsEditingLesson(true);
    setShowLessonModal(true);
  };

  const openCourseDetail = async (course: Course) => {
    setSelectedCourse(course);
    const mods = await fetchModulesForCourse(course.id);
    setModules(mods);
    for (const mod of mods) { fetchLessons(course.id, mod.id); }
  };

  const openPreview = (lesson: Lesson, moduleId: string, studentMode: boolean) => {
    setActiveModuleId(moduleId);
    setPreviewLesson(lesson);
    setIsPlaying(false);
    setTimeLeft(300);
    setIsConcluded(false);
    setIsMuted(false);
    setPlayerVolume(80);
    sendPlayerCommand('setVolume', [80]);
    sendPlayerCommand('unMute');
    setIsStudentSimulationMode(studentMode);
    setShowWelcomeModal(studentMode);
    setShowCompletionModal(false);
  };

  const handleReturnToDashboard = () => {
    setPreviewLesson(null);
    setSelectedCourse(null);
    setShowCompletionModal(false);
    setIsStudentSimulationMode(false);
    setIsCertificateUnlocked(false);
    setIsPlaying(false);
    sendPlayerCommand('pauseVideo');
  };

  // --- Lógica de Materiais ---
  const formatFileSize = (bytes: number) => {
    if (bytes === 0) return '0 Bytes';
    const k = 1024;
    const sizes = ['Bytes', 'KB', 'MB', 'GB', 'TB'];
    const i = Math.floor(Math.log(bytes) / Math.log(k));
    return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i];
  };

  const currentUsedStorage = materials.reduce((acc, m) => acc + m.sizeBytes, 0);
  const storagePercentage = (currentUsedStorage / MAX_STORAGE) * 100;

  const handleMaterialUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (!files) return;
    let tempUsed = currentUsedStorage;
    const newMaterials: MaterialFile[] = [];
    for (let i = 0; i < files.length; i++) {
      const file = files[i];
      if (tempUsed + file.size > MAX_STORAGE) {
        alert(`Espaço insuficiente para o arquivo "${file.name}". Limite de 5GB atingido.`);
        continue;
      }
      tempUsed += file.size;
      const extension = file.name.split('.').pop()?.toLowerCase() || '';
      const blobUrl = URL.createObjectURL(file);
      newMaterials.push({
        id: Math.random().toString(36).substr(2, 9),
        name: file.name,
        type: extension,
        size: formatFileSize(file.size),
        sizeBytes: file.size,
        date: new Date(),
        url: blobUrl
      });
    }
    setMaterials(prev => [...newMaterials, ...prev]);
    if (materialInputRef.current) materialInputRef.current.value = '';
  };

  const handleDeleteMaterial = (id: string) => {
    const file = materials.find(m => m.id === id);
    if (!file) return;
    if (confirm(`Excluir "${file.name}"? Isso liberará ${file.size} do armazenamento.`)) {
      if (file.url.startsWith('blob:')) URL.revokeObjectURL(file.url);
      setMaterials(prev => prev.filter(m => m.id !== id));
    }
  };

  const getFileIcon = (type: string) => {
    switch (type) {
      case 'pdf': return <FileText size={32} className="text-red-400" />;
      case 'jpg':
      case 'jpeg':
      case 'png':
      case 'webp': return <FileImage size={32} className="text-blue-400" />;
      case 'xlsx':
      case 'xls':
      case 'csv': return <FileSpreadsheet size={32} className="text-emerald-400" />;
      default: return <File size={32} className="text-slate-400" />;
    }
  };

  // --- INTEGRAÇÃO MATERIAL PICKER ---
  const handleOpenMaterialPicker = (mode: 'image' | 'document', callback: (url: string) => void) => {
    setPickerMode(mode);
    setPickerCallback(() => callback);
    setIsMaterialPickerOpen(true);
  };

  const handleSelectMaterialFromPicker = (material: MaterialFile) => {
    pickerCallback(material.url);
    setIsMaterialPickerOpen(false);
  };

  // --- Lógica de Avaliações (Exams) ---
  const handleAddQuestion = () => {
    setExamForm(prev => ({
      ...prev,
      questions: [
        ...prev.questions,
        { 
          id: (prev.questions.length + 1).toString(), 
          text: '', 
          options: ['', '', '', ''], 
          correctOptionIndex: 0 
        }
      ]
    }));
  };

  const handleRemoveQuestion = (index: number) => {
    if (examForm.questions.length <= 1) return;
    setExamForm(prev => {
      const newQuestions = [...prev.questions];
      newQuestions.splice(index, 1);
      return { ...prev, questions: newQuestions };
    });
  };

  const handleUpdateQuestionText = (index: number, text: string) => {
    setExamForm(prev => {
      const newQuestions = [...prev.questions];
      newQuestions[index].text = text;
      return { ...prev, questions: newQuestions };
    });
  };

  const handleUpdateOption = (qIndex: number, oIndex: number, text: string) => {
    setExamForm(prev => {
      const newQuestions = [...prev.questions];
      newQuestions[qIndex].options[oIndex] = text;
      return { ...prev, questions: newQuestions };
    });
  };

  const handleSetCorrectAnswer = (qIndex: number, oIndex: number) => {
    setExamForm(prev => {
      const newQuestions = [...prev.questions];
      newQuestions[qIndex].correctOptionIndex = oIndex;
      return { ...prev, questions: newQuestions };
    });
  };

  const handleSaveExam = (e: React.FormEvent) => {
    e.preventDefault();
    if (!examForm.courseId) return alert("Selecione um curso.");
    const course = myCourses.find(c => c.id === examForm.courseId);
    const newExam: Exam = {
      id: examForm.id || Math.random().toString(36).substr(2, 9),
      title: examForm.title,
      courseId: examForm.courseId,
      courseName: course?.nome || 'Curso não encontrado',
      passingGrade: examForm.passingGrade,
      questions: examForm.questions
    };
    if (isEditingExam) {
      setExams(prev => prev.map(ex => ex.id === newExam.id ? newExam : ex));
    } else {
      setExams(prev => [newExam, ...prev]);
    }
    setIsExamModalOpen(false);
    setIsEditingExam(false);
    setExamForm({ title: '', courseId: '', passingGrade: 7.0, questions: [{ id: '1', text: '', options: ['', '', '', ''], correctOptionIndex: 0 }] });
  };

  const handleEditExam = (exam: Exam) => {
    setExamForm({
      id: exam.id,
      title: exam.title,
      courseId: exam.courseId,
      passingGrade: exam.passingGrade,
      questions: exam.questions
    });
    setIsEditingExam(true);
    setIsExamModalOpen(true);
  };

  const handleDeleteExam = (id: string) => {
    if (confirm("Deseja excluir esta avaliação permanentemente?")) {
      setExams(prev => prev.filter(ex => ex.id !== id));
    }
  };

  // --- RENDERIZAÇÃO UNIFICADA ---
  const renderMainContent = () => {
    if (previewLesson && selectedCourse) {
      const videoId = getYouTubeVideoId(previewLesson.videoUrl);
      const iframeSrc = `https://www.youtube.com/embed/${videoId}?controls=0&modestbranding=1&rel=0&enablejsapi=1&autoplay=${isPlaying ? 1 : 0}&mute=${isMuted ? 1 : 0}`;
      return (
        <div className="fixed inset-0 z-[100] bg-gradient-to-br from-gray-900 to-slate-950 animate-in fade-in duration-300 overflow-y-auto">
          <div className="max-w-[1440px] mx-auto p-4 md:p-6 lg:p-8 flex flex-col h-full">
            <header className="flex items-center justify-between mb-6 pb-4 border-b border-gray-800">
              <div className="flex items-center gap-4">
                <button onClick={handleReturnToDashboard} className="h-10 w-10 bg-gray-800 border border-gray-700 hover:bg-gray-700 rounded-xl text-gray-300 transition-all shadow-sm flex items-center justify-center"><ArrowLeft size={20} /></button>
                <div>
                  <h1 className="text-xl font-bold text-white leading-tight">{selectedCourse.nome}</h1>
                  <p className="text-gray-400 text-sm mt-0.5">{isStudentSimulationMode ? 'Simulação Discente' : 'Construtor de Cursos'}</p>
                </div>
              </div>
              <button onClick={() => setPreviewLesson(null)} className="px-4 py-2 bg-gray-800 hover:bg-gray-700 rounded-xl text-gray-300 text-xs font-bold transition-colors">Fechar Pré-visualização</button>
            </header>
            <div className="flex-1 grid grid-cols-1 lg:grid-cols-4 gap-6">
              <div className="lg:col-span-3 space-y-6">
                {showWelcomeModal && isStudentSimulationMode ? (
                  <div className="aspect-video bg-black/60 backdrop-blur-xl rounded-3xl overflow-hidden shadow-2xl border-4 border-indigo-500 relative flex items-center justify-center text-center p-8 animate-in zoom-in duration-300">
                    <button onClick={() => setShowWelcomeModal(false)} className="absolute top-4 right-4 text-white hover:text-indigo-200 p-2 rounded-full hover:bg-white/10 transition-colors"><X size={24} /></button>
                    <div className="relative z-10 space-y-6 max-w-lg">
                      <p className="text-white font-serif text-3xl font-bold leading-relaxed">Bem-vindo à aula!</p>
                      <p className="text-indigo-200 text-base leading-relaxed">Para uma experiência imersiva, encontre um ambiente tranquilo e coloque-se em uma posição confortável.</p>
                      <button onClick={togglePlay} className="px-8 py-4 bg-emerald-500 text-white rounded-full text-lg font-bold shadow-lg hover:bg-emerald-600 transition-all active:scale-95 flex items-center justify-center gap-3 mx-auto"><Play size={24} fill="currentColor" /> Entendi! Começar Aula</button>
                    </div>
                  </div>
                ) : (
                  <div ref={playerContainerRef} className="aspect-video bg-gray-900 rounded-3xl overflow-hidden shadow-2xl border-4 border-gray-700 relative group">
                    <iframe ref={iframeRef} width="100%" height="100%" title="Video Player" frameBorder="0" allow="accelerometer; autoplay; encrypted-media; gyroscope; picture-in-picture" allowFullScreen src={iframeSrc}></iframe>
                    {isStudentSimulationMode && <div className="absolute inset-0 z-10 pointer-events-auto bg-transparent" onClick={() => !isPlaying && togglePlay()}>{!isPlaying && <div className="absolute inset-0 flex items-center justify-center bg-black/60 cursor-pointer"><div className="w-20 h-20 bg-white/20 backdrop-blur-xl border border-white/30 rounded-full flex items-center justify-center text-white transition-all shadow-2xl hover:scale-110 active:scale-95"><Play size={40} fill="currentColor" /></div></div>}</div>}
                    {!showWelcomeModal && (
                      <div className="absolute inset-0 z-30 pointer-events-none flex flex-col justify-end">
                        <div className="p-4 bg-gradient-to-t from-black/80 to-transparent opacity-0 group-hover:opacity-100 transition-opacity pointer-events-auto">
                          <div className="flex items-center justify-between gap-6 px-4">
                            <div className="flex items-center gap-4">
                              <button onClick={togglePlay} className="text-white hover:text-indigo-400 transition-colors">{isPlaying ? <Pause size={24} fill="currentColor" /> : <Play size={24} fill="currentColor" />}</button>
                              <div className="flex items-center gap-3 group/vol">
                                <button onClick={toggleMute} className="text-white hover:text-indigo-400 transition-colors">{(isMuted || playerVolume === 0) ? <VolumeX size={20} /> : <Volume2 size={20} />}</button>
                                <input type="range" min="0" max="100" value={isMuted ? 0 : playerVolume} onChange={handleVolumeChange} className="w-20 h-1.5 bg-white/20 rounded-full appearance-none cursor-pointer accent-indigo-500 hover:accent-indigo-400 transition-all" />
                              </div>
                            </div>
                            <button onClick={toggleFullscreen} className="text-white hover:text-indigo-400 transition-colors"><Maximize size={20} /></button>
                          </div>
                        </div>
                      </div>
                    )}
                  </div>
                )}
                <div className="p-8 bg-gray-800 rounded-3xl shadow-lg border border-gray-700">
                  <p className="font-serif text-gray-300 text-lg leading-relaxed tracking-wide whitespace-pre-wrap">
                    {previewLesson.descricao || "Aguardando cadastro de conteúdo para esta aula."}
                  </p>
                </div>
              </div>
              <div className="lg:col-span-1 space-y-6">
                <div className="bg-gray-800 p-6 rounded-3xl shadow-lg border border-gray-700 h-[calc(100vh-14rem)] overflow-y-auto">
                  <h3 className="text-lg font-bold text-indigo-400 uppercase tracking-widest mb-6">Conteúdo Programático</h3>
                  {modules.map(mod => (
                    <div key={mod.id} className="mb-6 last:mb-0">
                      <h4 className="font-bold text-lg text-white mb-3 flex items-center gap-2"><Layers size={18} className="text-indigo-400" /> Módulo {mod.ordem}: {mod.nome}</h4>
                      <div className="space-y-2">
                        {lessonsByModule[mod.id]?.map(lesson => {
                          const isCurrent = previewLesson?.id === lesson.id;
                          const isLessonGloballyConcluded = completedLessonIds.has(lesson.id) || !isStudentSimulationMode;
                          return (
                            <div key={lesson.id}>
                              <button onClick={() => openPreview(lesson, mod.id, isStudentSimulationMode)} className={`flex items-center justify-between w-full p-3 rounded-xl transition-all ${isCurrent ? 'bg-indigo-600 text-white shadow-md' : 'bg-gray-700 text-gray-300 hover:bg-gray-600'}`}>
                                <span className="flex items-center gap-3 text-sm font-medium">{isCurrent ? <Play size={16} fill="currentColor" /> : (isLessonGloballyConcluded ? <CheckCircle size={16} className="text-emerald-400" /> : <Lock size={16} className="text-gray-500" />)}{lesson.titulo}</span>
                                {!isCurrent && <ChevronRight size={16} className="text-gray-400" />}
                              </button>
                            </div>
                          );
                        })}
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            </div>
          </div>
        </div>
      );
    }

    if (activeSub === 'avaliacao') {
      return (
        <div className="space-y-6 animate-in fade-in duration-500">
          <header className="flex flex-col sm:flex-row items-center justify-between gap-4">
            <div><h1 className="text-2xl font-bold text-slate-900 tracking-tight">Gestão de Avaliações</h1><p className="text-slate-500 text-sm">Criação de provas e testes de proficiência.</p></div>
            <button onClick={() => { setIsEditingExam(false); setIsExamModalOpen(true); }} className="flex items-center gap-2 bg-indigo-600 text-white px-5 py-3 rounded-xl text-sm font-bold shadow-lg"><PlusCircle size={18} /> Nova Avaliação</button>
          </header>
          {exams.length === 0 ? (<div className="bg-white p-24 rounded-3xl border border-dashed border-slate-200 text-center flex flex-col items-center justify-center animate-in zoom-in-95"><div className="w-20 h-20 bg-slate-50 rounded-full flex items-center justify-center mb-6 text-slate-300"><ClipboardCheck size={40} /></div><h3 className="font-bold text-slate-900 text-lg">Nenhuma prova cadastrada</h3></div>) : (
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              {exams.map((exam) => (
                <div key={exam.id} className="group bg-slate-900 rounded-3xl border border-slate-800 p-6 shadow-xl hover:border-indigo-500/40 transition-all relative"><div className="flex justify-between items-start mb-4"><div className="p-3 bg-slate-800 rounded-2xl text-indigo-400"><ListChecks size={24} /></div><div className="flex gap-1 opacity-0 group-hover:opacity-100 transition-opacity"><button onClick={() => handleEditExam(exam)} className="p-2 text-slate-400 hover:text-white hover:bg-slate-700 rounded-lg"><Edit size={16} /></button><button onClick={() => handleDeleteExam(exam.id)} className="p-2 text-red-400 hover:text-white hover:bg-red-500 rounded-lg"><Trash2 size={16} /></button></div></div><h3 className="text-white font-bold text-lg mb-1 leading-tight">{exam.title}</h3><p className="text-indigo-400 text-[10px] font-black uppercase tracking-widest mb-4">{exam.courseName}</p><div className="flex items-center justify-between pt-4 border-t border-slate-800"><div className="flex items-center gap-2 text-slate-500 text-xs font-bold uppercase tracking-tighter"><ClipboardCheck size={14} /><span>{exam.questions.length} Questões</span></div><span className="text-[10px] font-black text-indigo-500 uppercase tracking-widest">Média {exam.passingGrade.toFixed(1)}</span></div></div>
              ))}
            </div>
          )}
        </div>
      );
    }

    if (activeSub === 'materiais') {
      const isCritical = storagePercentage > 90;
      const isWarning = storagePercentage > 70;
      return (
        <div className="space-y-6 animate-in fade-in duration-500">
          <div className="bg-white p-6 rounded-3xl border border-slate-200 shadow-sm space-y-4">
            <div className="flex items-center justify-between"><div className="flex items-center gap-3 text-slate-900"><Database size={20} className="text-indigo-600" /><h2 className="font-bold">Quota de Armazenamento</h2></div><span className={`text-xs font-black uppercase tracking-widest ${isCritical ? 'text-red-600' : isWarning ? 'text-amber-600' : 'text-slate-500'}`}>{formatFileSize(currentUsedStorage)} / 5 GB Utilizados</span></div>
            <div className="h-3 w-full bg-slate-100 rounded-full overflow-hidden border border-slate-50 shadow-inner"><div className={`h-full transition-all duration-1000 ${isCritical ? 'bg-red-500' : isWarning ? 'bg-amber-500' : 'bg-emerald-500'}`} style={{ width: `${Math.min(storagePercentage, 100)}%` }} /></div>
          </div>
          <header className="flex flex-col sm:flex-row items-center justify-between gap-4">
            <div><h1 className="text-2xl font-bold text-slate-900 tracking-tight">Biblioteca de Materiais</h1><p className="text-slate-500 text-sm">Gerenciamento centralizado de mídia pedagógica.</p></div>
            <button disabled={isCritical} onClick={() => materialInputRef.current?.click()} className={`flex items-center gap-2 px-5 py-3 rounded-xl text-sm font-bold shadow-lg ${isCritical ? 'bg-slate-200 text-slate-400 cursor-not-allowed' : 'bg-slate-900 text-white hover:bg-slate-800 active:scale-95'}`}><CloudUpload size={18} /> Upload de Arquivo</button>
            <input type="file" ref={materialInputRef} className="hidden" multiple onChange={handleMaterialUpload} accept=".pdf,.docx,.xlsx,.pptx,.jpg,.jpeg,.png" />
          </header>
          {materials.length === 0 ? (<div className="bg-white p-24 rounded-3xl border border-dashed border-slate-200 text-center flex flex-col items-center justify-center animate-in zoom-in-95"><div className="w-20 h-20 bg-slate-50 rounded-full flex items-center justify-center mb-6 text-slate-300"><CloudUpload size={40} /></div><h3 className="font-bold text-slate-900 text-lg">Biblioteca Vazia</h3></div>) : (
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
              {materials.map((file) => (
                <div key={file.id} className="group relative bg-slate-900 rounded-3xl border border-slate-800 p-5 shadow-xl hover:border-indigo-500/40 transition-all hover:shadow-indigo-500/10 animate-in fade-in slide-in-from-bottom-4 duration-300"><div className="flex flex-col h-full"><div className="flex justify-between items-start mb-6"><div className="p-3 bg-slate-800 rounded-2xl group-hover:scale-110 transition-transform shadow-lg">{getFileIcon(file.type)}</div><div className="flex gap-1 opacity-0 group-hover:opacity-100 transition-opacity"><a href={file.url} download={file.name} className="p-2 bg-slate-800 text-slate-300 hover:text-white rounded-lg border border-slate-700"><Download size={14} /></a><button onClick={() => handleDeleteMaterial(file.id)} className="p-2 bg-red-500/10 text-red-400 hover:bg-red-500 rounded-lg border border-red-500/20"><Trash2 size={14} /></button></div></div><div className="flex-1 min-w-0"><h3 className="text-white font-bold text-sm truncate leading-tight mb-1">{file.name}</h3><div className="flex items-center gap-3"><span className="text-[10px] font-black uppercase text-slate-500 tracking-wider bg-slate-800 px-1.5 py-0.5 rounded">{file.type}</span><span className="w-1 h-1 bg-slate-700 rounded-full" /><span className="text-[10px] font-bold text-slate-500">{file.size}</span></div></div></div></div>
              ))}
            </div>
          )}
        </div>
      );
    }

    if (activeSub === 'modulos') {
      const allModules = Object.values(allModulesGrouped).flatMap((group: { course: Course; modules: Module[] }) => group.modules.map(m => ({ ...m, courseName: group.course.nome }))).sort((a, b) => a.ordem - b.ordem);
      return (
        <div className="space-y-6 animate-in fade-in duration-500">
          <header className="flex flex-col sm:flex-row items-center justify-between gap-4"><div><h1 className="text-2xl font-bold text-slate-900 tracking-tight">Biblioteca de Módulos</h1><p className="text-slate-500 text-sm">Matriz integrada de cursos.</p></div><button onClick={handleOpenCreateModule} className="flex items-center gap-2 bg-indigo-600 text-white px-5 py-3 rounded-xl text-sm font-bold shadow-lg"><Plus size={18} /> Novo Módulo</button></header>
          {loading ? (<div className="flex items-center justify-center p-20"><div className="h-10 w-10 animate-spin rounded-full border-4 border-indigo-600 border-t-transparent"></div></div>) : (
            <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6">
              {allModules.map((mod: any) => (<div key={mod.id} className="group bg-slate-900 rounded-3xl border border-slate-800 p-6 shadow-xl hover:border-indigo-500/50 transition-all"><div className="flex flex-col h-full"><div className="flex justify-between items-start mb-4"><div className="px-3 py-1 bg-indigo-500/10 border border-indigo-500/20 text-indigo-400 text-[9px] font-black uppercase tracking-widest rounded-full">{mod.courseName}</div><div className="flex gap-1 opacity-0 group-hover:opacity-100"><button onClick={() => handleEditModule(mod)} className="p-2 bg-slate-800 text-slate-300 rounded-lg border border-slate-700"><Edit size={14} /></button><button onClick={() => handleDeleteModule(mod.courseId, mod.id)} className="p-2 bg-red-500/10 text-red-400 rounded-lg border border-red-500/20"><Trash2 size={14} /></button></div></div><h3 className="text-white font-bold text-lg mb-2">{mod.ordem.toString().padStart(2, '0')}. {mod.nome}</h3></div></div>))}
            </div>
          )}
        </div>
      );
    }

    if (activeSub === 'cursos' && selectedCourse) {
      return (
        <div className="space-y-6 animate-in fade-in duration-500">
          <header className="flex items-center justify-between gap-4"><div className="flex items-center gap-4"><button onClick={() => setSelectedCourse(null)} className="h-10 w-10 bg-white border border-slate-200 hover:bg-slate-50 rounded-xl text-slate-600 shadow-sm flex items-center justify-center"><ArrowLeft size={20} /></button><div><h1 className="text-2xl font-bold text-slate-900 leading-tight">{selectedCourse.nome}</h1><div className="flex items-center gap-3 mt-1"><span className="text-slate-500 text-sm">{selectedCourse.tema}</span>{selectedCourse.geraCertificado && <span className="flex items-center gap-1 bg-emerald-100 text-emerald-700 text-[9px] font-black uppercase px-2 py-0.5 rounded-md"><CheckCircle size={10} /> Emite Certificado</span>}</div></div></div><button onClick={handleOpenCreateModule} className="flex items-center gap-2 bg-indigo-600 text-white px-5 py-2.5 rounded-xl text-sm font-bold shadow-lg"><Plus size={18} /> Novo Módulo</button></header>
          <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
            <div className="lg:col-span-2 space-y-4"><div className="bg-white rounded-2xl border border-slate-200 shadow-sm overflow-hidden"><div className="px-6 py-4 border-b border-slate-100 bg-slate-50/50"><h2 className="text-xs font-bold text-slate-800 uppercase tracking-widest">Matriz Curricular</h2></div><div className="p-4 space-y-4">{modules.map((mod) => (<div key={mod.id} className="border border-slate-100 rounded-xl group bg-slate-50/20"><div className="px-4 py-3 border-b border-slate-100 flex items-center justify-between bg-white"><h3 className="font-bold text-slate-800 text-sm">Módulo {mod.ordem}: {mod.nome}</h3><div className="flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity"><button onClick={() => { setActiveModuleId(mod.id); setIsEditingLesson(false); setEditingLessonId(null); setLessonForm({titulo:'', descricao:'', videoUrl:'', materialUrl:''}); setShowLessonModal(true); }} className="p-1.5 text-indigo-600 hover:bg-indigo-50 rounded-lg"><Plus size={18} /></button><button onClick={() => handleEditModule(mod)} className="p-1.5 text-slate-400 hover:bg-slate-50 rounded-lg"><Edit size={18} /></button><button onClick={() => handleDeleteModule(selectedCourse.id, mod.id)} className="p-1.5 text-red-400 hover:bg-red-50 rounded-lg"><Trash2 size={18} /></button></div></div><div className="p-2 space-y-1">{lessonsByModule[mod.id]?.map((lesson) => (<div key={lesson.id} className="flex items-center justify-between p-3 rounded-xl hover:bg-white hover:shadow-sm group/lesson transition-all"><div className="flex items-center gap-4"><div className="p-2 bg-white border rounded-lg text-indigo-600"><Play size={12} fill="currentColor" /></div><span className="text-sm font-semibold text-slate-700">{lesson.titulo}</span></div><div className="flex items-center gap-1 opacity-0 group-hover/lesson:opacity-100"><button onClick={() => openPreview(lesson, mod.id, false)} className="p-1.5 text-indigo-600 hover:bg-indigo-50 rounded-lg"><Eye size={16} /></button><button onClick={() => handleEditLesson(lesson, mod.id)} className="p-1.5 text-slate-400 rounded-lg"><Edit size={16} /></button><button onClick={() => handleDeleteLesson(mod.id, lesson.id)} className="p-1.5 text-red-400 rounded-lg"><Trash2 size={16} /></button></div></div>))}</div></div>))}</div></div></div>
            <div className="bg-white p-5 rounded-2xl border border-slate-200 shadow-sm sticky top-24 h-fit"><img src={selectedCourse.capaUrl || 'https://images.unsplash.com/photo-1504052434139-443c40c98408?w=800'} className="w-full h-40 object-cover rounded-xl mb-4" /><div className="space-y-3"><div className="flex justify-between border-b pb-2"><span className="text-[10px] text-slate-400 font-black uppercase">Professor</span><span className="text-xs font-bold">{selectedCourse.professorResponsavel}</span></div></div></div>
          </div>
        </div>
      );
    }

    return (
      <div className="space-y-6 animate-in fade-in duration-500"><header className="flex flex-col sm:flex-row items-center justify-between gap-4"><div><h1 className="text-2xl font-bold text-slate-900 tracking-tight">Portal do Professor</h1><p className="text-slate-500 text-sm">Gestão educacional de cursos EAD.</p></div><button onClick={() => { setIsEditingCourse(false); setEditingCourseId(null); setCourseForm({ nome: '', tema: '', professorResponsavel: user.displayName || '', descricaoLonga: '', capaUrl: '', cargaHoraria: '', publicoAlvo: 'Geral', geraCertificado: false }); setShowCourseModal(true); }} className="flex items-center gap-2 bg-indigo-600 text-white px-5 py-3 rounded-xl text-sm font-bold shadow-lg"><Plus size={18} /> Novo Curso</button></header><div className="grid grid-cols-1 md:grid-cols-3 xl:grid-cols-6 gap-4">{loading ? (<div className="col-span-full py-20 flex justify-center"><div className="h-6 w-6 animate-spin rounded-full border-2 border-indigo-600 border-t-transparent"></div></div>) : myCourses.map(course => (<div key={course.id} onClick={() => openCourseDetail(course)} className="bg-white border border-slate-200 rounded-2xl overflow-hidden hover:shadow-xl hover:border-indigo-200 group cursor-pointer flex flex-col relative"><div className="absolute top-2 right-2 z-50"><button onClick={(e) => { e.stopPropagation(); setOpenMenuId(openMenuId === course.id ? null : course.id); }} className="p-1.5 bg-white/90 backdrop-blur-sm rounded-lg border border-slate-200 text-slate-500 shadow-sm"><MoreVertical size={14} /></button>{openMenuId === course.id && (<div className="absolute right-0 mt-1 w-32 bg-white rounded-xl shadow-2xl border border-slate-100 z-50 overflow-hidden text-[10px] font-bold"><button onClick={(e) => { e.stopPropagation(); handleEditCourseInfo(course); }} className="w-full px-3 py-2 text-left hover:bg-slate-50 flex items-center gap-2"><Edit size={12} /> Editar</button><button onClick={(e) => { e.stopPropagation(); handleDuplicateCourse(course); }} className="w-full px-3 py-2 text-left hover:bg-slate-50 flex items-center gap-2"><Copy size={12} /> Copiar</button><button onClick={(e) => { e.stopPropagation(); handleDeleteCourse(course.id); }} className="w-full px-3 py-2 text-left hover:bg-red-50 text-red-500 flex items-center gap-2"><Trash2 size={12} /> Apagar</button></div>)}</div><div className="h-24 overflow-hidden bg-slate-100 relative">{course.capaUrl ? <img src={course.capaUrl} className="w-full h-full object-cover group-hover:scale-105 transition-transform" /> : <div className="h-full flex items-center justify-center text-slate-200"><BookOpen size={32} /></div>}</div><div className="p-3 flex-1 flex flex-col"><h3 className="font-bold text-slate-900 text-xs mb-1 group-hover:text-indigo-600 transition-colors leading-tight line-clamp-2">{course.nome}</h3></div></div>))}</div></div>
    );
  };

  // --- COMPONENTE MATERIAL PICKER (MODAL) ---
  const renderMaterialPicker = () => {
    if (!isMaterialPickerOpen) return null;

    const filteredMaterials = materials.filter(m => {
      const isImg = ['jpg', 'jpeg', 'png', 'webp', 'gif'].includes(m.type.toLowerCase());
      return pickerMode === 'image' ? isImg : !isImg;
    });

    return (
      <div className="fixed inset-0 !z-[9999] flex items-center justify-center p-4 bg-slate-950/90 backdrop-blur-md animate-in fade-in duration-300">
        <div className="bg-slate-900 w-full max-w-5xl h-[85vh] rounded-[2.5rem] shadow-2xl border border-slate-800 flex flex-col overflow-hidden">
          <header className="px-8 py-6 border-b border-slate-800 flex items-center justify-between">
            <div className="flex items-center gap-4">
              <div className="p-3 bg-indigo-600 text-white rounded-2xl shadow-lg">
                <Library size={24} />
              </div>
              <div>
                <h2 className="text-xl font-bold text-white">Selecionar da Biblioteca</h2>
                <p className="text-slate-500 text-[10px] font-black uppercase tracking-widest mt-1">
                  Filtrando por: {pickerMode === 'image' ? 'Imagens (JPG, PNG)' : 'Documentos (PDF, DOC)'}
                </p>
              </div>
            </div>
            <button onClick={() => setIsMaterialPickerOpen(false)} className="p-2 text-slate-400 hover:text-white transition-colors">
              <X size={28} />
            </button>
          </header>

          <div className="flex-1 overflow-y-auto p-8">
            {filteredMaterials.length === 0 ? (
              <div className="h-full flex flex-col items-center justify-center text-center space-y-4 opacity-40">
                <Search size={60} className="text-slate-600" />
                <div>
                  <h3 className="text-white font-bold text-lg">Nenhum arquivo compatível</h3>
                  <p className="text-slate-500 text-sm">Faça upload de materiais deste tipo na aba "Materiais".</p>
                </div>
              </div>
            ) : (
              <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-6">
                {filteredMaterials.map((file) => (
                  <div 
                    key={file.id} 
                    onClick={() => handleSelectMaterialFromPicker(file)}
                    className="group bg-slate-800/40 rounded-3xl border border-slate-700/50 p-4 hover:border-indigo-500 hover:bg-slate-800 transition-all cursor-pointer relative overflow-hidden"
                  >
                    <div className="aspect-square bg-slate-900 rounded-2xl mb-4 flex items-center justify-center overflow-hidden border border-slate-700/30">
                      {pickerMode === 'image' ? (
                        <img src={file.url} className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-500" alt="" />
                      ) : (
                        getFileIcon(file.type)
                      )}
                    </div>
                    <div className="min-w-0">
                      <h4 className="text-white text-xs font-bold truncate">{file.name}</h4>
                      <p className="text-slate-500 text-[9px] font-black uppercase tracking-tighter mt-1">{file.size} • {file.type}</p>
                    </div>
                    <div className="absolute inset-0 bg-indigo-600/0 group-hover:bg-indigo-600/10 flex items-center justify-center opacity-0 group-hover:opacity-100 transition-all">
                       <div className="px-4 py-2 bg-indigo-600 text-white text-[10px] font-black uppercase rounded-full shadow-xl">Vincular Arquivo</div>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>
        </div>
      </div>
    );
  };

  return (
    <div className="relative">
      {renderMainContent()}
      {renderMaterialPicker()}

      {/* MODAL GLOBAL: CONSTRUTOR DE AVALIAÇÃO */}
      {isExamModalOpen && (
        <div className="fixed inset-0 !z-[9999] flex items-center justify-center p-4 bg-slate-950/80 backdrop-blur-md animate-in fade-in duration-300">
          <div className="bg-slate-900 w-full max-w-4xl max-h-[90vh] rounded-3xl shadow-2xl overflow-hidden flex flex-col animate-in zoom-in-95 border border-slate-800">
            <header className="px-8 py-6 border-b border-slate-800 flex items-center justify-between">
              <div className="flex items-center gap-4">
                <div className="p-3 bg-indigo-600 text-white rounded-2xl shadow-lg shadow-indigo-600/20"><ListChecks size={24} /></div>
                <div><h2 className="text-xl font-bold text-white leading-none">{isEditingExam ? 'Editar Avaliação' : 'Nova Avaliação Acadêmica'}</h2><p className="text-slate-500 text-[10px] font-bold uppercase tracking-[0.2em] mt-2">Construtor de Currículo Pedagógico</p></div>
              </div>
              <button onClick={() => setIsExamModalOpen(false)} className="text-slate-500 hover:text-white transition-colors"><X size={24} /></button>
            </header>
            <form onSubmit={handleSaveExam} className="flex-1 overflow-y-auto p-8 space-y-10">
              <div className="grid grid-cols-1 md:grid-cols-12 gap-6">
                <div className="md:col-span-6 space-y-2"><label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">Título da Prova</label><input required value={examForm.title} onChange={e => setExamForm({...examForm, title: e.target.value})} placeholder="Ex: Prova Mensal" className="w-full px-5 py-4 bg-slate-800 border border-slate-700 rounded-2xl text-white outline-none focus:ring-2 focus:ring-indigo-500" /></div>
                <div className="md:col-span-4 space-y-2"><label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">Curso Vinculado</label><select required value={examForm.courseId} onChange={e => setExamForm({...examForm, courseId: e.target.value})} className="w-full px-5 py-4 bg-slate-800 border border-slate-700 rounded-2xl text-white outline-none focus:ring-2 focus:ring-indigo-500"><option value="">Selecione o curso...</option>{myCourses.map(c => <option key={c.id} value={c.id}>{c.nome}</option>)}</select></div>
                <div className="md:col-span-2 space-y-2"><label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">Nota Mínima</label><input type="number" step="0.1" value={examForm.passingGrade} onChange={e => setExamForm({...examForm, passingGrade: parseFloat(e.target.value)})} className="w-full px-5 py-4 bg-slate-800 border border-slate-700 rounded-2xl text-white outline-none" /></div>
              </div>
              <div className="space-y-6">
                <div className="flex items-center justify-between border-b border-slate-800 pb-4"><h3 className="font-black text-indigo-400 text-xs uppercase tracking-[0.3em]">Questões da Avaliação</h3><button type="button" onClick={handleAddQuestion} className="flex items-center gap-2 text-indigo-400 hover:text-indigo-300 transition-colors font-bold text-xs uppercase"><Plus size={16} /> Adicionar Pergunta</button></div>
                <div className="space-y-8">{examForm.questions.map((q, qIndex) => (<div key={q.id} className="bg-slate-800/40 p-6 rounded-3xl border border-slate-700/50 relative group/q animate-in slide-in-from-top-4"><button type="button" onClick={() => handleRemoveQuestion(qIndex)} className="absolute -top-2 -right-2 p-2 bg-red-500 text-white rounded-full opacity-0 group-hover/q:opacity-100 transition-opacity"><Trash2 size={14} /></button><div className="space-y-6"><div className="flex gap-4"><span className="h-10 w-10 bg-indigo-600/20 text-indigo-400 border border-indigo-600/30 rounded-xl flex items-center justify-center font-bold text-sm shrink-0">{qIndex + 1}</span><input required value={q.text} onChange={e => handleUpdateQuestionText(qIndex, e.target.value)} placeholder="Enunciado da questão..." className="flex-1 bg-transparent border-b border-slate-700 focus:border-indigo-500 outline-none text-white font-medium py-2" /></div><div className="grid grid-cols-1 md:grid-cols-2 gap-4 pl-14">{q.options.map((opt, oIndex) => (<div key={oIndex} className={`flex items-center gap-3 p-3 rounded-2xl border transition-all ${q.correctOptionIndex === oIndex ? 'bg-emerald-500/10 border-emerald-500/50 shadow-lg' : 'bg-slate-900/50 border-slate-700/50'}`}><button type="button" onClick={() => handleSetCorrectAnswer(qIndex, oIndex)} className={`h-5 w-5 rounded-full border-2 flex items-center justify-center ${q.correctOptionIndex === oIndex ? 'bg-emerald-500 border-emerald-500 text-white' : 'border-slate-600'}`}>{q.correctOptionIndex === oIndex && <CheckCircle size={14} />}</button><input required value={opt} onChange={e => handleUpdateOption(qIndex, oIndex, e.target.value)} placeholder={`Alternativa ${String.fromCharCode(65 + oIndex)}`} className="bg-transparent text-xs text-white outline-none flex-1 placeholder:text-slate-600" /></div>))}</div></div></div>))}</div>
              </div>
              <footer className="pt-8 flex gap-4"><button type="button" onClick={() => setIsExamModalOpen(false)} className="flex-1 px-8 py-5 border border-slate-700 text-slate-400 rounded-2xl font-bold uppercase tracking-widest hover:bg-slate-800 transition-all">Cancelar</button><button type="submit" className="flex-[2] px-8 py-5 bg-indigo-600 text-white rounded-2xl font-black uppercase tracking-widest shadow-xl hover:bg-indigo-500 transition-all active:scale-95">Salvar Avaliação Digital</button></footer>
            </form>
          </div>
        </div>
      )}

      {/* MODAL GLOBAL: NOVO/EDITAR MÓDULO */}
      {isModuleModalOpen && (
        <div className="fixed inset-0 !z-[9999] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm animate-in fade-in duration-200">
          <div className="bg-white w-full max-w-md rounded-2xl shadow-2xl p-6 border border-slate-100"><h3 className="font-bold text-slate-900 mb-4">{currentEditingModule ? 'Editar Módulo' : 'Configurar Novo Módulo'}</h3><form onSubmit={handleSaveModule} className="space-y-5">{!selectedCourse && !currentEditingModule && (<div className="space-y-1"><label className="text-[10px] font-black text-slate-400 uppercase ml-1">Curso</label><select required value={moduleForm.courseId} onChange={e => setModuleForm({...moduleForm, courseId: e.target.value})} className="w-full px-4 py-2.5 bg-slate-50 border rounded-xl text-sm">{myCourses.map(c => <option key={c.id} value={c.id}>{c.nome}</option>)}</select></div>)}<div className="space-y-1"><label className="text-[10px] font-black text-slate-400 uppercase ml-1">Título</label><input required autoFocus value={moduleForm.nome} onChange={e => setModuleForm({...moduleForm, nome: e.target.value})} className="w-full px-4 py-2.5 bg-slate-50 border rounded-xl text-sm" /></div><div className="flex gap-3"><button type="button" onClick={() => setIsModuleModalOpen(false)} className="flex-1 px-4 py-2.5 border rounded-xl font-bold text-sm">Cancelar</button><button type="submit" className="flex-1 bg-indigo-600 text-white py-2.5 rounded-xl font-bold text-sm shadow-lg">Salvar</button></div></form></div>
        </div>
      )}

      {/* MODAL GLOBAL: NOVA AULA / EDIÇÃO DE AULA (COM INTEGRAÇÃO BIBLIOTECA) */}
      {showLessonModal && (
        <div className="fixed inset-0 !z-[9998] flex items-center justify-center p-4 bg-slate-900/40 backdrop-blur-sm animate-in fade-in">
          <div className="bg-white w-full max-w-xl rounded-3xl shadow-2xl p-8 animate-in zoom-in-95 border border-slate-100">
            <h3 className="font-bold text-slate-900 text-xl mb-6 flex items-center gap-3"><PlusCircle size={24} className="text-indigo-600" /> {isEditingLesson ? 'Editar Aula' : 'Publicar Nova Unidade'}</h3>
            <form onSubmit={handleSaveLesson} className="space-y-5">
              <input required value={lessonForm.titulo} onChange={e => setLessonForm({...lessonForm, titulo: e.target.value})} placeholder="Título da Aula" className="w-full px-5 py-3.5 bg-slate-50 border border-slate-200 rounded-2xl text-sm outline-none focus:ring-2 focus:ring-indigo-500" />
              <textarea value={lessonForm.descricao} onChange={e => setLessonForm({...lessonForm, descricao: e.target.value})} placeholder="Descrição pedagógica..." className="w-full px-5 py-3.5 bg-slate-50 border border-slate-200 rounded-2xl text-sm resize-none" rows={4}></textarea>
              <div className="space-y-4">
                <div className="space-y-1">
                  <label className="text-[10px] font-black text-slate-400 uppercase ml-1">Vínculo de Vídeo (YouTube)</label>
                  <input value={lessonForm.videoUrl} onChange={e => setLessonForm({...lessonForm, videoUrl: e.target.value})} placeholder="https://youtube.com/watch?v=..." className="w-full px-5 py-3.5 bg-slate-50 border border-slate-200 rounded-2xl text-sm outline-none focus:ring-2 focus:ring-indigo-500" />
                </div>

                {/* INTEGRAÇÃO BIBLIOTECA: MATERIAL DE APOIO */}
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-slate-400 uppercase ml-1">Material de Apoio (PDF/Documento)</label>
                  <div className="flex gap-2">
                    <input value={lessonForm.materialUrl} onChange={e => setLessonForm({...lessonForm, materialUrl: e.target.value})} placeholder="URL do arquivo..." className="flex-1 px-5 py-3.5 bg-slate-50 border border-slate-200 rounded-2xl text-sm outline-none" />
                    <button 
                      type="button" 
                      onClick={() => handleOpenMaterialPicker('document', (url) => setLessonForm(prev => ({...prev, materialUrl: url})))}
                      className="px-4 bg-indigo-600 text-white rounded-2xl hover:bg-indigo-700 transition-all shadow-lg flex items-center gap-2"
                      title="Selecionar da Biblioteca"
                    >
                      <Library size={18} />
                    </button>
                  </div>
                  {lessonForm.materialUrl && (
                    <div className="px-4 py-2 bg-emerald-50 border border-emerald-100 rounded-xl flex items-center gap-3 animate-in fade-in slide-in-from-left-2">
                      <CheckCircle size={14} className="text-emerald-500" />
                      <span className="text-[10px] font-bold text-emerald-700 uppercase tracking-tight truncate">Arquivo vinculado com sucesso</span>
                      <button type="button" onClick={() => setLessonForm(prev => ({...prev, materialUrl: ''}))} className="ml-auto text-emerald-400 hover:text-emerald-600"><X size={12} /></button>
                    </div>
                  )}
                </div>
              </div>
              <div className="flex gap-4 pt-4">
                <button type="button" onClick={() => setShowLessonModal(false)} className="flex-1 py-4 border border-slate-200 text-slate-500 rounded-2xl font-bold text-sm hover:bg-slate-50">Cancelar</button>
                <button type="submit" className="flex-[2] bg-slate-900 text-white py-4 rounded-2xl font-bold text-sm shadow-xl hover:bg-slate-800 transition-all active:scale-95">{isEditingLesson ? 'Salvar Alterações' : 'Publicar Aula'}</button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* MODAL GLOBAL: CURSO (COM INTEGRAÇÃO BIBLIOTECA) */}
      {showCourseModal && (
        <div className="fixed inset-0 !z-[9997] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm animate-in fade-in">
          <div className="bg-white w-full max-w-3xl rounded-[2.5rem] shadow-2xl overflow-hidden animate-in zoom-in-95 flex flex-col max-h-[90vh] border border-slate-100">
            <div className="p-8 border-b border-slate-50 flex items-center justify-between bg-slate-50/30">
              <div className="flex items-center gap-4">
                <div className="bg-indigo-600 p-3 rounded-2xl text-white shadow-xl shadow-indigo-200"><GraduationCap size={24} /></div>
                <div><h3 className="font-bold text-slate-900 text-xl">{isEditingCourse ? 'Editar Parâmetros' : 'Novo Curso Acadêmico'}</h3><p className="text-[10px] text-slate-400 font-black uppercase tracking-widest">Configuração de Matrícula e Mídia</p></div>
              </div>
              <button onClick={handleCloseCourseModal} className="text-slate-300 hover:text-slate-600 p-2 transition-colors"><X size={24} /></button>
            </div>
            <form onSubmit={handleSaveCourse} className="p-10 space-y-8 overflow-y-auto">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-10">
                <div className="space-y-6">
                  <div className="space-y-1"><label className="text-[10px] font-black text-slate-400 uppercase ml-1">Título do Curso</label><input required value={courseForm.nome} onChange={e => setCourseForm({...courseForm, nome: e.target.value})} className="w-full px-5 py-4 bg-slate-50 border border-slate-200 rounded-2xl text-sm" /></div>
                  <div className="space-y-1"><label className="text-[10px] font-black text-slate-400 uppercase ml-1">Docente Responsável</label><input required value={courseForm.professorResponsavel} onChange={e => setCourseForm({...courseForm, professorResponsavel: e.target.value})} className="w-full px-5 py-4 bg-slate-50 border border-slate-200 rounded-2xl text-sm" /></div>
                </div>

                {/* INTEGRAÇÃO BIBLIOTECA: CAPA DO CURSO */}
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-slate-400 uppercase ml-1">Capa do Curso</label>
                  <div className="relative group/capa h-44 w-full bg-slate-50 border-2 border-dashed border-slate-200 rounded-3xl flex flex-col items-center justify-center overflow-hidden transition-all hover:border-indigo-400">
                    {courseForm.capaUrl ? (
                      <>
                        <img src={courseForm.capaUrl} className="w-full h-full object-cover transition-transform group-hover/capa:scale-110" />
                        <div className="absolute inset-0 bg-black/40 opacity-0 group-hover/capa:opacity-100 flex items-center justify-center gap-3 transition-opacity">
                           <button type="button" onClick={() => handleOpenMaterialPicker('image', (url) => setCourseForm(prev => ({...prev, capaUrl: url})))} className="p-3 bg-white text-indigo-600 rounded-xl shadow-xl hover:scale-110 transition-transform"><Library size={20} /></button>
                           <button type="button" onClick={() => setCourseForm(prev => ({...prev, capaUrl: ''}))} className="p-3 bg-white text-red-600 rounded-xl shadow-xl hover:scale-110 transition-transform"><X size={20} /></button>
                        </div>
                      </>
                    ) : (
                      <div className="flex flex-col items-center space-y-4">
                        <FileUp size={32} className="text-slate-300" />
                        <div className="flex gap-2">
                          <button type="button" onClick={() => handleOpenMaterialPicker('image', (url) => setCourseForm(prev => ({...prev, capaUrl: url})))} className="px-4 py-2 bg-indigo-600 text-white text-[10px] font-black uppercase rounded-xl shadow-lg">Biblioteca</button>
                          <label className="px-4 py-2 bg-slate-900 text-white text-[10px] font-black uppercase rounded-xl shadow-lg cursor-pointer">Upload<input type="file" className="hidden" onChange={handleFileUpload} accept="image/*" /></label>
                        </div>
                      </div>
                    )}
                  </div>
                  {courseForm.capaUrl && <p className="text-[9px] text-indigo-500 font-bold uppercase tracking-tighter text-center">Imagem de capa vinculada com sucesso</p>}
                </div>
              </div>
              <div className="flex gap-4 pt-6">
                <button type="button" onClick={handleCloseCourseModal} className="flex-1 py-5 border border-slate-200 text-slate-500 rounded-[1.5rem] font-bold text-sm hover:bg-slate-50">Descartar</button>
                <button type="submit" disabled={loading} className="flex-[2] bg-slate-900 text-white py-5 rounded-[1.5rem] font-black text-xs uppercase tracking-[0.2em] shadow-2xl shadow-slate-300 hover:bg-slate-800 transition-all active:scale-95">{loading ? 'Processando...' : (isEditingCourse ? 'Salvar Alterações' : 'Criar Curso EAD')}</button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default ProfessorView;

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { 
  collection, 
  query, 
  where, 
  getDocs, 
  addDoc, 
  deleteDoc,
  serverTimestamp, 
  orderBy,
  doc,
  updateDoc,
  getDoc,
  arrayUnion 
} from 'firebase/firestore';
import { db } from '../firebase';
import { Course, Module, Lesson, User, ProfessorSubView } from '../types';
import { 
  BookOpen, 
  Plus, 
  X, 
  ChevronRight, 
  Play, 
  Pause, 
  Volume2, 
  VolumeX, 
  Maximize, 
  MoreVertical, 
  ArrowLeft, 
  Layout, 
  Trash2, 
  Layers, 
  Eye, 
  CheckCircle, 
  Copy, 
  Edit, 
  GraduationCap, 
  FileUp, 
  FileDown,
  Lock,
  FileText,
  Award,
  File,
  FileImage,
  FileSpreadsheet,
  CloudUpload,
  Download,
  Database,
  AlertTriangle,
  ClipboardCheck,
  ListChecks,
  PlusCircle,
  Search,
  Library
} from 'lucide-react';

// Constante de Armazenamento Máximo (5GB)
const MAX_STORAGE = 5 * 1024 * 1024 * 1024;

interface MaterialFile {
  id: string;
  name: string;
  type: string;
  size: string;
  sizeBytes: number;
  date: Date;
  url: string;
}

interface Question {
  id: string;
  text: string;
  options: string[];
  correctOptionIndex: number;
}

interface Exam {
  id: string;
  title: string;
  courseId: string;
  courseName: string;
  passingGrade: number;
  questions: Question[];
}

interface ProfessorViewProps {
  user: User;
  activeSub: ProfessorSubView;
  setActiveSub: (view: ProfessorSubView) => void;
}

const ProfessorView: React.FC<ProfessorViewProps> = ({ user, activeSub, setActiveSub }) => {
  const [myCourses, setMyCourses] = useState<Course[]>([]);
  const [loading, setLoading] = useState(true);
  const [selectedCourse, setSelectedCourse] = useState<Course | null>(null);
  const [modules, setModules] = useState<Module[]>([]);
  const [lessonsByModule, setLessonsByModule] = useState<Record<string, Lesson[]>>({});
  const [allModulesGrouped, setAllModulesGrouped] = useState<Record<string, { course: Course, modules: Module[] }>>({});
  const [openMenuId, setOpenMenuId] = useState<string | null>(null);

  // State para Materiais
  const [materials, setMaterials] = useState<MaterialFile[]>(() => {
    const saved = sessionStorage.getItem('eb_materials_mock');
    return saved ? JSON.parse(saved).map((m: any) => ({...m, date: new Date(m.date)})) : [];
  });

  // State para o Material Picker
  const [isMaterialPickerOpen, setIsMaterialPickerOpen] = useState(false);
  const [pickerMode, setPickerMode] = useState<'image' | 'document'>('document');
  const [pickerCallback, setPickerCallback] = useState<(url: string) => void>(() => {});

  // State para Avaliações (Exams)
  const [exams, setExams] = useState<Exam[]>(() => {
    const saved = sessionStorage.getItem('eb_exams_mock');
    return saved ? JSON.parse(saved) : [];
  });
  const [isExamModalOpen, setIsExamModalOpen] = useState(false);
  const [isEditingExam, setIsEditingExam] = useState(false);
  const [examForm, setExamForm] = useState<{
    id?: string;
    title: string;
    courseId: string;
    passingGrade: number;
    questions: Question[];
  }>({
    title: '',
    courseId: '',
    passingGrade: 7.0,
    questions: [{ id: '1', text: '', options: ['', '', '', ''], correctOptionIndex: 0 }]
  });

  const materialInputRef = useRef<HTMLInputElement>(null);

  // Persistência simulada
  useEffect(() => {
    sessionStorage.setItem('eb_materials_mock', JSON.stringify(materials));
  }, [materials]);

  useEffect(() => {
    sessionStorage.setItem('eb_exams_mock', JSON.stringify(exams));
  }, [exams]);

  // Modal States
  const [showCourseModal, setShowCourseModal] = useState(false);
  const [isEditingCourse, setIsEditingCourse] = useState(false);
  const [editingCourseId, setEditingCourseId] = useState<string | null>(null);

  const [isModuleModalOpen, setIsModuleModalOpen] = useState(false); 
  const [showLessonModal, setShowLessonModal] = useState(false);
  const [isEditingLesson, setIsEditingLesson] = useState(false);
  const [activeModuleId, setActiveModuleId] = useState<string | null>(null);
  const [currentEditingModule, setCurrentEditingModule] = useState<Module | null>(null); 
  const [editingLessonId, setEditingLessonId] = useState<string | null>(null);

  // Preview States
  const [previewLesson, setPreviewLesson] = useState<Lesson | null>(null);
  const [isConcluded, setIsConcluded] = useState(false);
  const [isPlaying, setIsPlaying] = useState(false);
  const [timeLeft, setTimeLeft] = useState(300);
  const timerIntervalRef = useRef<number | null>(null);
  const [showWelcomeModal, setShowWelcomeModal] = useState(false);
  const [showCompletionModal, setShowCompletionModal] = useState(false);

  const [isStudentSimulationMode, setIsStudentSimulationMode] = useState(false);
  const [isCertificateUnlocked, setIsCertificateUnlocked] = useState(false);
  const [completedLessonIds, setCompletedLessonIds] = useState<Set<string>>(new Set());
  const [totalLessons, setTotalLessons] = useState(0);

  const [playerVolume, setPlayerVolume] = useState(80); 
  const [isMuted, setIsMuted] = useState(false); 
  const iframeRef = useRef<HTMLIFrameElement>(null); 
  const playerContainerRef = useRef<HTMLDivElement>(null); 

  // Form States
  const [courseForm, setCourseForm] = useState({
    nome: '', tema: '', professorResponsavel: user.displayName || '',
    descricaoLonga: '', capaUrl: '', cargaHoraria: '',
    publicoAlvo: 'Geral' as const, geraCertificado: false
  });
  const [moduleForm, setModuleForm] = useState({ nome: '', courseId: '' });
  const [lessonForm, setLessonForm] = useState({
    titulo: '', descricao: '', videoUrl: '', materialUrl: ''
  });

  // --- Funções de Dados ---
  const fetchMyCourses = async () => {
    setLoading(true);
    try {
      const q = query(collection(db, 'cursos'), where('professorId', '==', user.uid), orderBy('createdAt', 'desc'));
      const querySnapshot = await getDocs(q);
      const fetched: Course[] = [];
      querySnapshot.forEach((doc) => {
        fetched.push({ id: doc.id, ...doc.data() } as Course);
      });
      setMyCourses(fetched);
    } catch (error) {
      console.error(error);
    } finally {
      setLoading(false);
    }
  };

  const fetchModulesForCourse = async (courseId: string) => {
    const q = query(collection(db, 'cursos', courseId, 'modulos'), orderBy('ordem', 'asc'));
    const querySnapshot = await getDocs(q);
    const fetched: Module[] = [];
    querySnapshot.forEach((doc) => {
      fetched.push({ id: doc.id, ...doc.data(), courseId } as Module);
    });
    return fetched;
  };

  const fetchAllModulesGrouped = async () => {
    setLoading(true);
    try {
      const grouped: Record<string, { course: Course, modules: Module[] }> = {};
      for (const course of myCourses) {
        const mods = await fetchModulesForCourse(course.id);
        for (const mod of mods) {
          await fetchLessons(course.id, mod.id);
        }
        grouped[course.id] = { course, modules: mods };
      }
      setAllModulesGrouped(grouped);
    } catch (error) {
      console.error(error);
    } finally {
      setLoading(false);
    }
  };

  const fetchLessons = async (courseId: string, moduleId: string) => {
    try {
      const q = query(collection(db, 'cursos', courseId, 'modulos', moduleId, 'aulas'), orderBy('ordem', 'asc'));
      const querySnapshot = await getDocs(q);
      const fetched: Lesson[] = [];
      querySnapshot.forEach((doc) => {
        fetched.push({ id: doc.id, ...doc.data() } as Lesson);
      });
      setLessonsByModule(prev => ({ ...prev, [moduleId]: fetched }));
    } catch (error) {
      console.error(error);
    }
  };

  const fetchCompletedLessons = useCallback(async (studentId: string, courseId: string) => {
    if (!studentId || !courseId) return new Set<string>();
    try {
      const key = `completed_lessons_sim_${studentId}_${courseId}`;
      const stored = localStorage.getItem(key);
      return new Set(stored ? JSON.parse(stored) : []);
    } catch (error) {
      console.error(error);
    }
    return new Set<string>();
  }, []);

  const updateCompletedLesson = useCallback(async (studentId: string, lessonId: string) => {
    if (!studentId || !lessonId) return;
    try {
      const key = `completed_lessons_sim_${studentId}_${selectedCourse?.id}`;
      const currentCompleted = await fetchCompletedLessons(studentId, selectedCourse?.id || '');
      if (!currentCompleted.has(lessonId)) {
        currentCompleted.add(lessonId);
        localStorage.setItem(key, JSON.stringify(Array.from(currentCompleted)));
        setCompletedLessonIds(currentCompleted);
      }
    } catch (error) {
      console.error(error);
    }
  }, [fetchCompletedLessons, selectedCourse?.id]);

  // --- Effects ---
  useEffect(() => { fetchMyCourses(); }, [user.uid]);

  useEffect(() => {
    if (activeSub === 'modulos') { fetchAllModulesGrouped(); }
  }, [activeSub, myCourses]);

  useEffect(() => {
    if (selectedCourse && modules.length > 0) {
      let count = 0;
      for (const mod of modules) { count += (lessonsByModule[mod.id]?.length || 0); }
      setTotalLessons(count);
    } else { setTotalLessons(0); }
  }, [selectedCourse, modules, lessonsByModule]);

  useEffect(() => {
    const shouldStartTimer = isStudentSimulationMode && previewLesson && !showWelcomeModal && isPlaying;
    if (shouldStartTimer && timeLeft > 0) {
      if (!timerIntervalRef.current) {
        timerIntervalRef.current = window.setInterval(async () => {
          setTimeLeft(prevTime => {
            if (prevTime <= 1) {
              if (timerIntervalRef.current) { clearInterval(timerIntervalRef.current); timerIntervalRef.current = null; }
              setIsConcluded(true);
              if (user.uid && previewLesson?.id) { updateCompletedLesson(user.uid, previewLesson.id); }
              if (!showCompletionModal) { setShowCompletionModal(true); }
              return 0;
            }
            return prevTime - 1;
          });
        }, 1000);
      }
    } else if (timerIntervalRef.current) {
      clearInterval(timerIntervalRef.current);
      timerIntervalRef.current = null;
    }
    return () => { if (timerIntervalRef.current) { clearInterval(timerIntervalRef.current); timerIntervalRef.current = null; } };
  }, [previewLesson, isStudentSimulationMode, showWelcomeModal, isPlaying, timeLeft, showCompletionModal, user.uid, previewLesson?.id, updateCompletedLesson]);

  useEffect(() => {
    if (selectedCourse?.geraCertificado && isStudentSimulationMode && totalLessons > 0) {
      setIsCertificateUnlocked(completedLessonIds.size >= totalLessons);
    } else { setIsCertificateUnlocked(false); }
  }, [selectedCourse?.geraCertificado, isStudentSimulationMode, completedLessonIds, totalLessons]);

  useEffect(() => {
    if (selectedCourse && user.uid) { fetchCompletedLessons(user.uid, selectedCourse.id).then(setCompletedLessonIds); }
    else { setCompletedLessonIds(new Set()); }
  }, [selectedCourse, user.uid, fetchCompletedLessons]);

  const getYouTubeVideoId = (url: string) => {
    const ytRegex = /(?:https?:\/\/)?(?:www\.)?(?:youtube\.com\/(?:[^\/\n\s]+\/\S+\/|(?:v|e(?:mbed)?)\/|\S*?[?&]v=)|youtu\.be\/)([a-zA-Z0-9_-]{11})/;
    const ytMatch = url.match(ytRegex);
    return ytMatch && ytMatch[1];
  };

  const sendPlayerCommand = useCallback((command: string, args: any = '') => {
    if (iframeRef.current && iframeRef.current.contentWindow) {
      iframeRef.current.contentWindow.postMessage(JSON.stringify({ event: 'command', func: command, args: args }), '*');
    }
  }, []);

  const togglePlay = () => {
    if (isPlaying) { sendPlayerCommand('pauseVideo'); setIsPlaying(false); }
    else { sendPlayerCommand('playVideo'); setIsPlaying(true); setShowWelcomeModal(false); }
  };

  const toggleMute = () => {
    if (isMuted) { sendPlayerCommand('unMute'); } else { sendPlayerCommand('mute'); }
    setIsMuted(prev => !prev);
  };

  const handleVolumeChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const vol = parseInt(e.target.value);
    setPlayerVolume(vol);
    if (vol === 0) { if (!isMuted) sendPlayerCommand('mute'); setIsMuted(true); }
    else { if (isMuted) sendPlayerCommand('unMute'); sendPlayerCommand('setVolume', [vol]); setIsMuted(false); }
  };

  const toggleFullscreen = () => {
    if (playerContainerRef.current) {
      if (!document.fullscreenElement) playerContainerRef.current.requestFullscreen();
      else document.exitFullscreen();
    }
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    if (file.size > 5 * 1024 * 1024) { alert("A imagem de capa não pode exceder 5 MB."); e.target.value = ''; return; }
    const reader = new FileReader();
    reader.onloadend = () => { setCourseForm(prev => ({ ...prev, capaUrl: reader.result as string })); };
    reader.readAsDataURL(file);
  };

  const handleSaveCourse = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      setLoading(true);
      if (isEditingCourse && editingCourseId) {
        const courseRef = doc(db, 'cursos', editingCourseId);
        await updateDoc(courseRef, { ...courseForm });
        if (selectedCourse?.id === editingCourseId) { setSelectedCourse({ ...selectedCourse, ...courseForm }); }
      } else {
        await addDoc(collection(db, 'cursos'), { ...courseForm, professorId: user.uid, inscritos: 0, status: 'rascunho', createdAt: serverTimestamp() });
      }
      handleCloseCourseModal();
      await fetchMyCourses();
    } catch (error) {
      console.error(error);
    } finally { setLoading(false); }
  };

  const handleEditCourseInfo = (course: Course) => {
    setCourseForm({
      nome: course.nome, tema: course.tema || '', professorResponsavel: course.professorResponsavel || '',
      descricaoLonga: course.descricaoLonga || '', capaUrl: course.capaUrl || '',
      cargaHoraria: course.cargaHoraria, publicoAlvo: course.publicoAlvo,
      geraCertificado: course.geraCertificado || false
    });
    setEditingCourseId(course.id);
    setIsEditingCourse(true);
    setShowCourseModal(true);
    setOpenMenuId(null);
  };

  const handleCloseCourseModal = () => {
    setShowCourseModal(false);
    setIsEditingCourse(false);
    setEditingCourseId(null);
    setCourseForm({
      nome: '', tema: '', professorResponsavel: user.displayName || '',
      descricaoLonga: '', capaUrl: '', cargaHoraria: '',
      publicoAlvo: 'Geral', geraCertificado: false
    });
  };

  const handleDeleteCourse = async (courseId: string) => {
    if (!confirm("Tem certeza que deseja excluir o curso inteiro?")) return;
    try {
      await deleteDoc(doc(db, 'cursos', courseId));
      setMyCourses(prev => prev.filter(c => c.id !== courseId));
      setOpenMenuId(null);
    } catch (error) { console.error(error); }
  };

  const handleDuplicateCourse = async (course: Course) => {
    try {
      const { id, ...data } = course;
      await addDoc(collection(db, 'cursos'), { ...data, nome: `${data.nome} (Cópia)`, createdAt: serverTimestamp() });
      fetchMyCourses();
      setOpenMenuId(null);
    } catch (error) { console.error(error); }
  };

  const handleDeleteModule = async (courseId: string, moduleId: string) => {
    if (!confirm("Excluir este módulo e todo seu conteúdo?")) return;
    try {
      await deleteDoc(doc(db, 'cursos', courseId, 'modulos', moduleId));
      if (selectedCourse) { setModules(prev => prev.filter(m => m.id !== moduleId)); }
      fetchAllModulesGrouped();
    } catch (error) { console.error(error); }
  };

  const handleSaveModule = async (e: React.FormEvent) => {
    e.preventDefault();
    const finalCourseId = selectedCourse?.id || moduleForm.courseId;
    if (!finalCourseId) {
       alert("Selecione um curso.");
       return;
    }
    try {
      if (currentEditingModule) {
        const modRef = doc(db, 'cursos', currentEditingModule.courseId, 'modulos', currentEditingModule.id);
        await updateDoc(modRef, { nome: moduleForm.nome });
      } else {
        const qOrder = query(collection(db, 'cursos', finalCourseId, 'modulos'));
        const snapOrder = await getDocs(qOrder);
        const nextOrder = snapOrder.size + 1;

        await addDoc(collection(db, 'cursos', finalCourseId, 'modulos'), { 
          nome: moduleForm.nome, 
          ordem: nextOrder, 
          createdAt: serverTimestamp() 
        });
      }
      setIsModuleModalOpen(false);
      setModuleForm({ nome: '', courseId: '' });
      setCurrentEditingModule(null);
      if (selectedCourse) {
         const mods = await fetchModulesForCourse(selectedCourse.id);
         setModules(mods);
      }
      fetchAllModulesGrouped();
    } catch (error) { console.error(error); }
  };

  const handleOpenCreateModule = () => {
    setModuleForm({ nome: '', courseId: selectedCourse?.id || '' });
    setCurrentEditingModule(null);
    setIsModuleModalOpen(true);
  };

  const handleEditModule = (mod: Module) => {
    setCurrentEditingModule(mod);
    setModuleForm({ nome: mod.nome, courseId: mod.courseId });
    setIsModuleModalOpen(true);
  };

  const handleSaveLesson = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedCourse || !activeModuleId) return;

    // TRAVA DE DUPLICIDADE (VALORIZAÇÃO PEDAGÓGICA)
    const allLessonsFlattened = Object.values(lessonsByModule).flat();
    const arquivoJaUsado = allLessonsFlattened.find(l => 
        l.materialUrl === lessonForm.materialUrl && 
        l.materialUrl !== '' && // Ignora campos vazios
        l.id !== editingLessonId
    );

    if (arquivoJaUsado) {
        alert(`Atenção: O arquivo selecionado já está vinculado à aula "${arquivoJaUsado.titulo}". Por favor, escolha outro arquivo para evitar conflitos de download.`);
        return;
    }

    try {
      if (isEditingLesson && editingLessonId) {
        const lessonRef = doc(db, 'cursos', selectedCourse.id, 'modulos', activeModuleId, 'aulas', editingLessonId);
        await updateDoc(lessonRef, { ...lessonForm });
        if (previewLesson && previewLesson.id === editingLessonId) {
           setPreviewLesson(prev => prev ? ({ ...prev, ...lessonForm }) : null);
        }
      } else {
        await addDoc(collection(db, 'cursos', selectedCourse.id, 'modulos', activeModuleId, 'aulas'), { ...lessonForm, ordem: (lessonsByModule[activeModuleId]?.length || 0) + 1, createdAt: serverTimestamp() });
      }
      setShowLessonModal(false);
      setIsEditingLesson(false);
      setEditingLessonId(null);
      setLessonForm({ titulo: '', descricao: '', videoUrl: '', materialUrl: '' });
      fetchLessons(selectedCourse.id, activeModuleId);
    } catch (error) { console.error(error); }
  };

  const handleDeleteLesson = async (moduleId: string, lessonId: string) => {
    if (!selectedCourse) return;
    if (!confirm("Tem certeza que deseja DESTRUIR esta aula permanentemente?")) return;
    try {
      await deleteDoc(doc(db, 'cursos', selectedCourse.id, 'modulos', moduleId, 'aulas', lessonId));
      fetchLessons(selectedCourse.id, moduleId);
      if (previewLesson?.id === lessonId) setPreviewLesson(null);
    } catch (error) { console.error(error); }
  };

  const handleEditLesson = (lesson: Lesson, moduleId: string) => {
    setActiveModuleId(moduleId);
    setLessonForm({ titulo: lesson.titulo, descricao: lesson.descricao || '', videoUrl: lesson.videoUrl, materialUrl: lesson.materialUrl });
    setEditingLessonId(lesson.id);
    setIsEditingLesson(true);
    setShowLessonModal(true);
  };

  const openCourseDetail = async (course: Course) => {
    setSelectedCourse(course);
    const mods = await fetchModulesForCourse(course.id);
    setModules(mods);
    for (const mod of mods) { fetchLessons(course.id, mod.id); }
  };

  const openPreview = (lesson: Lesson, moduleId: string, studentMode: boolean) => {
    setActiveModuleId(moduleId);
    setPreviewLesson(lesson);
    setIsPlaying(false);
    setTimeLeft(300);
    setIsConcluded(false);
    setIsMuted(false);
    setPlayerVolume(80);
    sendPlayerCommand('setVolume', [80]);
    sendPlayerCommand('unMute');
    setIsStudentSimulationMode(studentMode);
    setShowWelcomeModal(studentMode);
    setShowCompletionModal(false);
  };

  const handleReturnToDashboard = () => {
    setPreviewLesson(null);
    setSelectedCourse(null);
    setShowCompletionModal(false);
    setIsStudentSimulationMode(false);
    setIsCertificateUnlocked(false);
    setIsPlaying(false);
    sendPlayerCommand('pauseVideo');
  };

  // --- Lógica de Materiais ---
  const formatFileSize = (bytes: number) => {
    if (bytes === 0) return '0 Bytes';
    const k = 1024;
    const sizes = ['Bytes', 'KB', 'MB', 'GB', 'TB'];
    const i = Math.floor(Math.log(bytes) / Math.log(k));
    return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i];
  };

  const currentUsedStorage = materials.reduce((acc, m) => acc + m.sizeBytes, 0);
  const storagePercentage = (currentUsedStorage / MAX_STORAGE) * 100;

  const handleMaterialUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (!files) return;
    let tempUsed = currentUsedStorage;
    const newMaterials: MaterialFile[] = [];
    for (let i = 0; i < files.length; i++) {
      const file = files[i];
      if (tempUsed + file.size > MAX_STORAGE) {
        alert(`Espaço insuficiente para o arquivo "${file.name}". Limite de 5GB atingido.`);
        continue;
      }
      tempUsed += file.size;
      const extension = file.name.split('.').pop()?.toLowerCase() || '';
      const blobUrl = URL.createObjectURL(file);
      newMaterials.push({
        id: Math.random().toString(36).substr(2, 9),
        name: file.name,
        type: extension,
        size: formatFileSize(file.size),
        sizeBytes: file.size,
        date: new Date(),
        url: blobUrl
      });
    }
    setMaterials(prev => [...newMaterials, ...prev]);
    if (materialInputRef.current) materialInputRef.current.value = '';
  };

  const handleDeleteMaterial = (id: string) => {
    const file = materials.find(m => m.id === id);
    if (!file) return;
    if (confirm(`Excluir "${file.name}"? Isso liberará ${file.size} do armazenamento.`)) {
      if (file.url.startsWith('blob:')) URL.revokeObjectURL(file.url);
      setMaterials(prev => prev.filter(m => m.id !== id));
    }
  };

  const getFileIcon = (type: string) => {
    switch (type) {
      case 'pdf': return <FileText size={32} className="text-red-400" />;
      case 'jpg':
      case 'jpeg':
      case 'png':
      case 'webp': return <FileImage size={32} className="text-blue-400" />;
      case 'xlsx':
      case 'xls':
      case 'csv': return <FileSpreadsheet size={32} className="text-emerald-400" />;
      default: return <File size={32} className="text-slate-400" />;
    }
  };

  // --- INTEGRAÇÃO MATERIAL PICKER ---
  const handleOpenMaterialPicker = (mode: 'image' | 'document', callback: (url: string) => void) => {
    setPickerMode(mode);
    setPickerCallback(() => callback);
    setIsMaterialPickerOpen(true);
  };

  const handleSelectMaterialFromPicker = (material: MaterialFile) => {
    pickerCallback(material.url);
    setIsMaterialPickerOpen(false);
  };

  // --- Lógica de Avaliações (Exams) ---
  const handleAddQuestion = () => {
    setExamForm(prev => ({
      ...prev,
      questions: [
        ...prev.questions,
        { 
          id: (prev.questions.length + 1).toString(), 
          text: '', 
          options: ['', '', '', ''], 
          correctOptionIndex: 0 
        }
      ]
    }));
  };

  const handleRemoveQuestion = (index: number) => {
    if (examForm.questions.length <= 1) return;
    setExamForm(prev => {
      const newQuestions = [...prev.questions];
      newQuestions.splice(index, 1);
      return { ...prev, questions: newQuestions };
    });
  };

  const handleUpdateQuestionText = (index: number, text: string) => {
    setExamForm(prev => {
      const newQuestions = [...prev.questions];
      newQuestions[index].text = text;
      return { ...prev, questions: newQuestions };
    });
  };

  const handleUpdateOption = (qIndex: number, oIndex: number, text: string) => {
    setExamForm(prev => {
      const newQuestions = [...prev.questions];
      newQuestions[qIndex].options[oIndex] = text;
      return { ...prev, questions: newQuestions };
    });
  };

  const handleSetCorrectAnswer = (qIndex: number, oIndex: number) => {
    setExamForm(prev => {
      const newQuestions = [...prev.questions];
      newQuestions[qIndex].correctOptionIndex = oIndex;
      return { ...prev, questions: newQuestions };
    });
  };

  const handleSaveExam = (e: React.FormEvent) => {
    e.preventDefault();
    if (!examForm.courseId) return alert("Selecione um curso.");
    const course = myCourses.find(c => c.id === examForm.courseId);
    const newExam: Exam = {
      id: examForm.id || Math.random().toString(36).substr(2, 9),
      title: examForm.title,
      courseId: examForm.courseId,
      courseName: course?.nome || 'Curso não encontrado',
      passingGrade: examForm.passingGrade,
      questions: examForm.questions
    };
    if (isEditingExam) {
      setExams(prev => prev.map(ex => ex.id === newExam.id ? newExam : ex));
    } else {
      setExams(prev => [newExam, ...prev]);
    }
    setIsExamModalOpen(false);
    setIsEditingExam(false);
    setExamForm({ title: '', courseId: '', passingGrade: 7.0, questions: [{ id: '1', text: '', options: ['', '', '', ''], correctOptionIndex: 0 }] });
  };

  const handleEditExam = (exam: Exam) => {
    setExamForm({
      id: exam.id,
      title: exam.title,
      courseId: exam.courseId,
      passingGrade: exam.passingGrade,
      questions: exam.questions
    });
    setIsEditingExam(true);
    setIsExamModalOpen(true);
  };

  const handleDeleteExam = (id: string) => {
    if (confirm("Deseja excluir esta avaliação permanentemente?")) {
      setExams(prev => prev.filter(ex => ex.id !== id));
    }
  };

  // --- RENDERIZAÇÃO UNIFICADA ---
  const renderMainContent = () => {
    if (previewLesson && selectedCourse) {
      const videoId = getYouTubeVideoId(previewLesson.videoUrl);
      const iframeSrc = `https://www.youtube.com/embed/${videoId}?controls=0&modestbranding=1&rel=0&enablejsapi=1&autoplay=${isPlaying ? 1 : 0}&mute=${isMuted ? 1 : 0}`;
      return (
        <div className="fixed inset-0 z-[100] bg-gradient-to-br from-gray-900 to-slate-950 animate-in fade-in duration-300 overflow-y-auto">
          <div className="max-w-[1440px] mx-auto p-4 md:p-6 lg:p-8 flex flex-col h-full">
            <header className="flex items-center justify-between mb-6 pb-4 border-b border-gray-800">
              <div className="flex items-center gap-4">
                <button onClick={handleReturnToDashboard} className="h-10 w-10 bg-gray-800 border border-gray-700 hover:bg-gray-700 rounded-xl text-gray-300 transition-all shadow-sm flex items-center justify-center"><ArrowLeft size={20} /></button>
                <div>
                  <h1 className="text-xl font-bold text-white leading-tight">{selectedCourse.nome}</h1>
                  <p className="text-gray-400 text-sm mt-0.5">{isStudentSimulationMode ? 'Simulação Discente' : 'Construtor de Cursos'}</p>
                </div>
              </div>
              <button onClick={() => setPreviewLesson(null)} className="px-4 py-2 bg-gray-800 hover:bg-gray-700 rounded-xl text-gray-300 text-xs font-bold transition-colors">Fechar Pré-visualização</button>
            </header>
            <div className="flex-1 grid grid-cols-1 lg:grid-cols-4 gap-6">
              <div className="lg:col-span-3 space-y-6">
                {showWelcomeModal && isStudentSimulationMode ? (
                  <div className="aspect-video bg-black/60 backdrop-blur-xl rounded-3xl overflow-hidden shadow-2xl border-4 border-indigo-500 relative flex items-center justify-center text-center p-8 animate-in zoom-in duration-300">
                    <button onClick={() => setShowWelcomeModal(false)} className="absolute top-4 right-4 text-white hover:text-indigo-200 p-2 rounded-full hover:bg-white/10 transition-colors"><X size={24} /></button>
                    <div className="relative z-10 space-y-6 max-w-lg">
                      <p className="text-white font-serif text-3xl font-bold leading-relaxed">Bem-vindo à aula!</p>
                      <p className="text-indigo-200 text-base leading-relaxed">Para uma experiência imersiva, encontre um ambiente tranquilo e coloque-se em uma posição confortável.</p>
                      <button onClick={togglePlay} className="px-8 py-4 bg-emerald-500 text-white rounded-full text-lg font-bold shadow-lg hover:bg-emerald-600 transition-all active:scale-95 flex items-center justify-center gap-3 mx-auto"><Play size={24} fill="currentColor" /> Entendi! Começar Aula</button>
                    </div>
                  </div>
                ) : (
                  <div ref={playerContainerRef} className="aspect-video bg-gray-900 rounded-3xl overflow-hidden shadow-2xl border-4 border-gray-700 relative group">
                    <iframe ref={iframeRef} width="100%" height="100%" title="Video Player" frameBorder="0" allow="accelerometer; autoplay; encrypted-media; gyroscope; picture-in-picture" allowFullScreen src={iframeSrc}></iframe>
                    {isStudentSimulationMode && <div className="absolute inset-0 z-10 pointer-events-auto bg-transparent" onClick={() => !isPlaying && togglePlay()}>{!isPlaying && <div className="absolute inset-0 flex items-center justify-center bg-black/60 cursor-pointer"><div className="w-20 h-20 bg-white/20 backdrop-blur-xl border border-white/30 rounded-full flex items-center justify-center text-white transition-all shadow-2xl hover:scale-110 active:scale-95"><Play size={40} fill="currentColor" /></div></div>}</div>}
                    {!showWelcomeModal && (
                      <div className="absolute inset-0 z-30 pointer-events-none flex flex-col justify-end">
                        <div className="p-4 bg-gradient-to-t from-black/80 to-transparent opacity-0 group-hover:opacity-100 transition-opacity pointer-events-auto">
                          <div className="flex items-center justify-between gap-6 px-4">
                            <div className="flex items-center gap-4">
                              <button onClick={togglePlay} className="text-white hover:text-indigo-400 transition-colors">{isPlaying ? <Pause size={24} fill="currentColor" /> : <Play size={24} fill="currentColor" />}</button>
                              <div className="flex items-center gap-3 group/vol">
                                <button onClick={toggleMute} className="text-white hover:text-indigo-400 transition-colors">{(isMuted || playerVolume === 0) ? <VolumeX size={20} /> : <Volume2 size={20} />}</button>
                                <input type="range" min="0" max="100" value={isMuted ? 0 : playerVolume} onChange={handleVolumeChange} className="w-20 h-1.5 bg-white/20 rounded-full appearance-none cursor-pointer accent-indigo-500 hover:accent-indigo-400 transition-all" />
                              </div>
                            </div>
                            <button onClick={toggleFullscreen} className="text-white hover:text-indigo-400 transition-colors"><Maximize size={20} /></button>
                          </div>
                        </div>
                      </div>
                    )}
                  </div>
                )}
                <div className="p-8 bg-gray-800 rounded-3xl shadow-lg border border-gray-700">
                  <p className="font-serif text-gray-300 text-lg leading-relaxed tracking-wide whitespace-pre-wrap">
                    {previewLesson.descricao || "Aguardando cadastro de conteúdo para esta aula."}
                  </p>
                </div>
              </div>
              <div className="lg:col-span-1 space-y-6">
                <div className="bg-gray-800 p-6 rounded-3xl shadow-lg border border-gray-700 h-[calc(100vh-14rem)] overflow-y-auto">
                  <h3 className="text-lg font-bold text-indigo-400 uppercase tracking-widest mb-6">Conteúdo Programático</h3>
                  {modules.map(mod => (
                    <div key={mod.id} className="mb-6 last:mb-0">
                      <h4 className="font-bold text-lg text-white mb-3 flex items-center gap-2"><Layers size={18} className="text-indigo-400" /> Módulo {mod.ordem}: {mod.nome}</h4>
                      <div className="space-y-2">
                        {lessonsByModule[mod.id]?.map(lesson => {
                          const isCurrent = previewLesson?.id === lesson.id;
                          const isLessonGloballyConcluded = completedLessonIds.has(lesson.id) || !isStudentSimulationMode;
                          return (
                            <div key={lesson.id} className="group/lesson-item">
                              <button onClick={() => openPreview(lesson, mod.id, isStudentSimulationMode)} className={`flex items-center justify-between w-full p-3 rounded-xl transition-all ${isCurrent ? 'bg-indigo-600 text-white shadow-md' : 'bg-gray-700 text-gray-300 hover:bg-gray-600'}`}>
                                <span className="flex items-center gap-3 text-sm font-medium">{isCurrent ? <Play size={16} fill="currentColor" /> : (isLessonGloballyConcluded ? <CheckCircle size={16} className="text-emerald-400" /> : <Lock size={16} className="text-gray-500" />)}{lesson.titulo}</span>
                                {!isCurrent && <ChevronRight size={16} className="text-gray-400" />}
                              </button>

                              {/* SIDEBAR PLAYLIST: MATERIAL DOWNLOAD LINK (EXIBIÇÃO DINÂMICA) */}
                              {lesson.materialUrl && (isLessonGloballyConcluded || !isStudentSimulationMode) && (
                                <a 
                                  href={lesson.materialUrl} 
                                  target="_blank" 
                                  rel="noopener noreferrer"
                                  className="flex items-center gap-2 mt-1.5 ml-8 text-[10px] font-bold text-indigo-400 hover:text-indigo-300 hover:underline transition-all"
                                >
                                  <FileDown size={12} />
                                  Baixar Material de Apoio
                                </a>
                              )}
                            </div>
                          );
                        })}
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            </div>
          </div>
        </div>
      );
    }

    if (activeSub === 'avaliacao') {
      return (
        <div className="space-y-6 animate-in fade-in duration-500">
          <header className="flex flex-col sm:flex-row items-center justify-between gap-4">
            <div><h1 className="text-2xl font-bold text-slate-900 tracking-tight">Gestão de Avaliações</h1><p className="text-slate-500 text-sm">Criação de provas e testes de proficiência.</p></div>
            <button onClick={() => { setIsEditingExam(false); setIsExamModalOpen(true); }} className="flex items-center gap-2 bg-indigo-600 text-white px-5 py-3 rounded-xl text-sm font-bold shadow-lg"><PlusCircle size={18} /> Nova Avaliação</button>
          </header>
          {exams.length === 0 ? (<div className="bg-white p-24 rounded-3xl border border-dashed border-slate-200 text-center flex flex-col items-center justify-center animate-in zoom-in-95"><div className="w-20 h-20 bg-slate-50 rounded-full flex items-center justify-center mb-6 text-slate-300"><ClipboardCheck size={40} /></div><h3 className="font-bold text-slate-900 text-lg">Nenhuma prova cadastrada</h3></div>) : (
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              {exams.map((exam) => (
                <div key={exam.id} className="group bg-slate-900 rounded-3xl border border-slate-800 p-6 shadow-xl hover:border-indigo-500/40 transition-all relative"><div className="flex justify-between items-start mb-4"><div className="p-3 bg-slate-800 rounded-2xl text-indigo-400"><ListChecks size={24} /></div><div className="flex gap-1 opacity-0 group-hover:opacity-100 transition-opacity"><button onClick={() => handleEditExam(exam)} className="p-2 text-slate-400 hover:text-white hover:bg-slate-700 rounded-lg"><Edit size={16} /></button><button onClick={() => handleDeleteExam(exam.id)} className="p-2 text-red-400 hover:text-white hover:bg-red-500 rounded-lg"><Trash2 size={16} /></button></div></div><h3 className="text-white font-bold text-lg mb-1 leading-tight">{exam.title}</h3><p className="text-indigo-400 text-[10px] font-black uppercase tracking-widest mb-4">{exam.courseName}</p><div className="flex items-center justify-between pt-4 border-t border-slate-800"><div className="flex items-center gap-2 text-slate-500 text-xs font-bold uppercase tracking-tighter"><ClipboardCheck size={14} /><span>{exam.questions.length} Questões</span></div><span className="text-[10px] font-black text-indigo-500 uppercase tracking-widest">Média {exam.passingGrade.toFixed(1)}</span></div></div>
              ))}
            </div>
          )}
        </div>
      );
    }

    if (activeSub === 'materiais') {
      const isCritical = storagePercentage > 90;
      const isWarning = storagePercentage > 70;
      return (
        <div className="space-y-6 animate-in fade-in duration-500">
          <div className="bg-white p-6 rounded-3xl border border-slate-200 shadow-sm space-y-4">
            <div className="flex items-center justify-between"><div className="flex items-center gap-3 text-slate-900"><Database size={20} className="text-indigo-600" /><h2 className="font-bold">Quota de Armazenamento</h2></div><span className={`text-xs font-black uppercase tracking-widest ${isCritical ? 'text-red-600' : isWarning ? 'text-amber-600' : 'text-slate-500'}`}>{formatFileSize(currentUsedStorage)} / 5 GB Utilizados</span></div>
            <div className="h-3 w-full bg-slate-100 rounded-full overflow-hidden border border-slate-50 shadow-inner"><div className={`h-full transition-all duration-1000 ${isCritical ? 'bg-red-500' : isWarning ? 'bg-amber-500' : 'bg-emerald-500'}`} style={{ width: `${Math.min(storagePercentage, 100)}%` }} /></div>
          </div>
          <header className="flex flex-col sm:flex-row items-center justify-between gap-4">
            <div><h1 className="text-2xl font-bold text-slate-900 tracking-tight">Biblioteca de Materiais</h1><p className="text-slate-500 text-sm">Gerenciamento centralizado de mídia pedagógica.</p></div>
            <button disabled={isCritical} onClick={() => materialInputRef.current?.click()} className={`flex items-center gap-2 px-5 py-3 rounded-xl text-sm font-bold shadow-lg ${isCritical ? 'bg-slate-200 text-slate-400 cursor-not-allowed' : 'bg-slate-900 text-white hover:bg-slate-800 active:scale-95'}`}><CloudUpload size={18} /> Upload de Arquivo</button>
            <input type="file" ref={materialInputRef} className="hidden" multiple onChange={handleMaterialUpload} accept=".pdf,.docx,.xlsx,.pptx,.jpg,.jpeg,.png" />
          </header>
          {materials.length === 0 ? (<div className="bg-white p-24 rounded-3xl border border-dashed border-slate-200 text-center flex flex-col items-center justify-center animate-in zoom-in-95"><div className="w-20 h-20 bg-slate-50 rounded-full flex items-center justify-center mb-6 text-slate-300"><CloudUpload size={40} /></div><h3 className="font-bold text-slate-900 text-lg">Biblioteca Vazia</h3></div>) : (
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
              {materials.map((file) => (
                <div key={file.id} className="group relative bg-slate-900 rounded-3xl border border-slate-800 p-5 shadow-xl hover:border-indigo-500/40 transition-all hover:shadow-indigo-500/10 animate-in fade-in slide-in-from-bottom-4 duration-300"><div className="flex flex-col h-full"><div className="flex justify-between items-start mb-6"><div className="p-3 bg-slate-800 rounded-2xl group-hover:scale-110 transition-transform shadow-lg">{getFileIcon(file.type)}</div><div className="flex gap-1 opacity-0 group-hover:opacity-100 transition-opacity"><a href={file.url} download={file.name} className="p-2 bg-slate-800 text-slate-300 hover:text-white rounded-lg border border-slate-700"><Download size={14} /></a><button onClick={() => handleDeleteMaterial(file.id)} className="p-2 bg-red-500/10 text-red-400 hover:bg-red-500 rounded-lg border border-red-500/20"><Trash2 size={14} /></button></div></div><div className="flex-1 min-w-0"><h3 className="text-white font-bold text-sm truncate leading-tight mb-1">{file.name}</h3><div className="flex items-center gap-3"><span className="text-[10px] font-black uppercase text-slate-500 tracking-wider bg-slate-800 px-1.5 py-0.5 rounded">{file.type}</span><span className="w-1 h-1 bg-slate-700 rounded-full" /><span className="text-[10px] font-bold text-slate-500">{file.size}</span></div></div></div></div>
              ))}
            </div>
          )}
        </div>
      );
    }

    if (activeSub === 'modulos') {
      const allModules = Object.values(allModulesGrouped).flatMap((group: { course: Course; modules: Module[] }) => group.modules.map(m => ({ ...m, courseName: group.course.nome }))).sort((a, b) => a.ordem - b.ordem);
      return (
        <div className="space-y-6 animate-in fade-in duration-500">
          <header className="flex flex-col sm:flex-row items-center justify-between gap-4"><div><h1 className="text-2xl font-bold text-slate-900 tracking-tight">Biblioteca de Módulos</h1><p className="text-slate-500 text-sm">Matriz integrada de cursos.</p></div><button onClick={handleOpenCreateModule} className="flex items-center gap-2 bg-indigo-600 text-white px-5 py-3 rounded-xl text-sm font-bold shadow-lg"><Plus size={18} /> Novo Módulo</button></header>
          {loading ? (<div className="flex items-center justify-center p-20"><div className="h-10 w-10 animate-spin rounded-full border-4 border-indigo-600 border-t-transparent"></div></div>) : (
            <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6">
              {allModules.map((mod: any) => (<div key={mod.id} className="group bg-slate-900 rounded-3xl border border-slate-800 p-6 shadow-xl hover:border-indigo-500/50 transition-all"><div className="flex flex-col h-full"><div className="flex justify-between items-start mb-4"><div className="px-3 py-1 bg-indigo-500/10 border border-indigo-500/20 text-indigo-400 text-[9px] font-black uppercase tracking-widest rounded-full">{mod.courseName}</div><div className="flex gap-1 opacity-0 group-hover:opacity-100"><button onClick={() => handleEditModule(mod)} className="p-2 bg-slate-800 text-slate-300 rounded-lg border border-slate-700"><Edit size={14} /></button><button onClick={() => handleDeleteModule(mod.courseId, mod.id)} className="p-2 bg-red-500/10 text-red-400 rounded-lg border border-red-500/20"><Trash2 size={14} /></button></div></div><h3 className="text-white font-bold text-lg mb-2">{mod.ordem.toString().padStart(2, '0')}. {mod.nome}</h3></div></div>))}
            </div>
          )}
        </div>
      );
    }

    if (activeSub === 'cursos' && selectedCourse) {
      return (
        <div className="space-y-6 animate-in fade-in duration-500">
          <header className="flex items-center justify-between gap-4"><div className="flex items-center gap-4"><button onClick={() => setSelectedCourse(null)} className="h-10 w-10 bg-white border border-slate-200 hover:bg-slate-50 rounded-xl text-slate-600 shadow-sm flex items-center justify-center"><ArrowLeft size={20} /></button><div><h1 className="text-2xl font-bold text-slate-900 leading-tight">{selectedCourse.nome}</h1><div className="flex items-center gap-3 mt-1"><span className="text-slate-500 text-sm">{selectedCourse.tema}</span>{selectedCourse.geraCertificado && <span className="flex items-center gap-1 bg-emerald-100 text-emerald-700 text-[9px] font-black uppercase px-2 py-0.5 rounded-md"><CheckCircle size={10} /> Emite Certificado</span>}</div></div></div><button onClick={handleOpenCreateModule} className="flex items-center gap-2 bg-indigo-600 text-white px-5 py-2.5 rounded-xl text-sm font-bold shadow-lg"><Plus size={18} /> Novo Módulo</button></header>
          <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
            <div className="lg:col-span-2 space-y-4"><div className="bg-white rounded-2xl border border-slate-200 shadow-sm overflow-hidden"><div className="px-6 py-4 border-b border-slate-100 bg-slate-50/50"><h2 className="text-xs font-bold text-slate-800 uppercase tracking-widest">Matriz Curricular</h2></div><div className="p-4 space-y-4">{modules.map((mod) => (<div key={mod.id} className="border border-slate-100 rounded-xl group bg-slate-50/20"><div className="px-4 py-3 border-b border-slate-100 flex items-center justify-between bg-white"><h3 className="font-bold text-slate-800 text-sm">Módulo {mod.ordem}: {mod.nome}</h3><div className="flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity"><button onClick={() => { setActiveModuleId(mod.id); setIsEditingLesson(false); setEditingLessonId(null); setLessonForm({titulo:'', descricao:'', videoUrl:'', materialUrl:''}); setShowLessonModal(true); }} className="p-1.5 text-indigo-600 hover:bg-indigo-50 rounded-lg"><Plus size={18} /></button><button onClick={() => handleEditModule(mod)} className="p-1.5 text-slate-400 hover:bg-slate-50 rounded-lg"><Edit size={18} /></button><button onClick={() => handleDeleteModule(selectedCourse.id, mod.id)} className="p-1.5 text-red-400 hover:bg-red-50 rounded-lg"><Trash2 size={18} /></button></div></div><div className="p-2 space-y-1">{lessonsByModule[mod.id]?.map((lesson) => (<div key={lesson.id} className="flex items-center justify-between p-3 rounded-xl hover:bg-white hover:shadow-sm group/lesson transition-all"><div className="flex items-center gap-4"><div className="p-2 bg-white border rounded-lg text-indigo-600"><Play size={12} fill="currentColor" /></div><span className="text-sm font-semibold text-slate-700">{lesson.titulo}</span></div><div className="flex items-center gap-1 opacity-0 group-hover/lesson:opacity-100"><button onClick={() => openPreview(lesson, mod.id, false)} className="p-1.5 text-indigo-600 hover:bg-indigo-50 rounded-lg"><Eye size={16} /></button><button onClick={() => handleEditLesson(lesson, mod.id)} className="p-1.5 text-slate-400 rounded-lg"><Edit size={16} /></button><button onClick={() => handleDeleteLesson(mod.id, lesson.id)} className="p-1.5 text-red-400 rounded-lg"><Trash2 size={16} /></button></div></div>))}</div></div>))}</div></div></div>
            <div className="bg-white p-5 rounded-2xl border border-slate-200 shadow-sm sticky top-24 h-fit"><img src={selectedCourse.capaUrl || 'https://images.unsplash.com/photo-1504052434139-443c40c98408?w=800'} className="w-full h-40 object-cover rounded-xl mb-4" /><div className="space-y-3"><div className="flex justify-between border-b pb-2"><span className="text-[10px] text-slate-400 font-black uppercase">Professor</span><span className="text-xs font-bold">{selectedCourse.professorResponsavel}</span></div></div></div>
          </div>
        </div>
      );
    }

    return (
      <div className="space-y-6 animate-in fade-in duration-500"><header className="flex flex-col sm:flex-row items-center justify-between gap-4"><div><h1 className="text-2xl font-bold text-slate-900 tracking-tight">Portal do Professor</h1><p className="text-slate-500 text-sm">Gestão educacional de cursos EAD.</p></div><button onClick={() => { setIsEditingCourse(false); setEditingCourseId(null); setCourseForm({ nome: '', tema: '', professorResponsavel: user.displayName || '', descricaoLonga: '', capaUrl: '', cargaHoraria: '', publicoAlvo: 'Geral', geraCertificado: false }); setShowCourseModal(true); }} className="flex items-center gap-2 bg-indigo-600 text-white px-5 py-3 rounded-xl text-sm font-bold shadow-lg"><Plus size={18} /> Novo Curso</button></header><div className="grid grid-cols-1 md:grid-cols-3 xl:grid-cols-6 gap-4">{loading ? (<div className="col-span-full py-20 flex justify-center"><div className="h-6 w-6 animate-spin rounded-full border-2 border-indigo-600 border-t-transparent"></div></div>) : myCourses.map(course => (<div key={course.id} onClick={() => openCourseDetail(course)} className="bg-white border border-slate-200 rounded-2xl overflow-hidden hover:shadow-xl hover:border-indigo-200 group cursor-pointer flex flex-col relative"><div className="absolute top-2 right-2 z-50"><button onClick={(e) => { e.stopPropagation(); setOpenMenuId(openMenuId === course.id ? null : course.id); }} className="p-1.5 bg-white/90 backdrop-blur-sm rounded-lg border border-slate-200 text-slate-500 shadow-sm"><MoreVertical size={14} /></button>{openMenuId === course.id && (<div className="absolute right-0 mt-1 w-32 bg-white rounded-xl shadow-2xl border border-slate-100 z-50 overflow-hidden text-[10px] font-bold"><button onClick={(e) => { e.stopPropagation(); handleEditCourseInfo(course); }} className="w-full px-3 py-2 text-left hover:bg-slate-50 flex items-center gap-2"><Edit size={12} /> Editar</button><button onClick={(e) => { e.stopPropagation(); handleDuplicateCourse(course); }} className="w-full px-3 py-2 text-left hover:bg-slate-50 flex items-center gap-2"><Copy size={12} /> Copiar</button><button onClick={(e) => { e.stopPropagation(); handleDeleteCourse(course.id); }} className="w-full px-3 py-2 text-left hover:bg-red-50 text-red-500 flex items-center gap-2"><Trash2 size={12} /> Apagar</button></div>)}</div><div className="h-24 overflow-hidden bg-slate-100 relative">{course.capaUrl ? <img src={course.capaUrl} className="w-full h-full object-cover group-hover:scale-105 transition-transform" /> : <div className="h-full flex items-center justify-center text-slate-200"><BookOpen size={32} /></div>}</div><div className="p-3 flex-1 flex flex-col"><h3 className="font-bold text-slate-900 text-xs mb-1 group-hover:text-indigo-600 transition-colors leading-tight line-clamp-2">{course.nome}</h3></div></div>))}</div></div>
    );
  };

  // --- COMPONENTE MATERIAL PICKER (MODAL) ---
  const renderMaterialPicker = () => {
    if (!isMaterialPickerOpen) return null;

    const filteredMaterials = materials.filter(m => {
      const isImg = ['jpg', 'jpeg', 'png', 'webp', 'gif'].includes(m.type.toLowerCase());
      return pickerMode === 'image' ? isImg : !isImg;
    });

    return (
      <div className="fixed inset-0 !z-[9999] flex items-center justify-center p-4 bg-slate-950/90 backdrop-blur-md animate-in fade-in duration-300">
        <div className="bg-slate-900 w-full max-w-5xl h-[85vh] rounded-[2.5rem] shadow-2xl border border-slate-800 flex flex-col overflow-hidden">
          <header className="px-8 py-6 border-b border-slate-800 flex items-center justify-between">
            <div className="flex items-center gap-4">
              <div className="p-3 bg-indigo-600 text-white rounded-2xl shadow-lg">
                <Library size={24} />
              </div>
              <div>
                <h2 className="text-xl font-bold text-white">Selecionar da Biblioteca</h2>
                <p className="text-slate-500 text-[10px] font-black uppercase tracking-widest mt-1">
                  Filtrando por: {pickerMode === 'image' ? 'Imagens (JPG, PNG)' : 'Documentos (PDF, DOC)'}
                </p>
              </div>
            </div>
            <button onClick={() => setIsMaterialPickerOpen(false)} className="p-2 text-slate-400 hover:text-white transition-colors">
              <X size={28} />
            </button>
          </header>

          <div className="flex-1 overflow-y-auto p-8">
            {filteredMaterials.length === 0 ? (
              <div className="h-full flex flex-col items-center justify-center text-center space-y-4 opacity-40">
                <Search size={60} className="text-slate-600" />
                <div>
                  <h3 className="text-white font-bold text-lg">Nenhum arquivo compatível</h3>
                  <p className="text-slate-500 text-sm">Faça upload de materiais deste tipo na aba "Materiais".</p>
                </div>
              </div>
            ) : (
              <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-6">
                {filteredMaterials.map((file) => (
                  <div 
                    key={file.id} 
                    onClick={() => handleSelectMaterialFromPicker(file)}
                    className="group bg-slate-800/40 rounded-3xl border border-slate-700/50 p-4 hover:border-indigo-500 hover:bg-slate-800 transition-all cursor-pointer relative overflow-hidden"
                  >
                    <div className="aspect-square bg-slate-900 rounded-2xl mb-4 flex items-center justify-center overflow-hidden border border-slate-700/30">
                      {pickerMode === 'image' ? (
                        <img src={file.url} className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-500" alt="" />
                      ) : (
                        getFileIcon(file.type)
                      )}
                    </div>
                    <div className="min-w-0">
                      <h4 className="text-white text-xs font-bold truncate">{file.name}</h4>
                      <p className="text-slate-500 text-[9px] font-black uppercase tracking-tighter mt-1">{file.size} • {file.type}</p>
                    </div>
                    <div className="absolute inset-0 bg-indigo-600/0 group-hover:bg-indigo-600/10 flex items-center justify-center opacity-0 group-hover:opacity-100 transition-all">
                       <div className="px-4 py-2 bg-indigo-600 text-white text-[10px] font-black uppercase rounded-full shadow-xl">Vincular Arquivo</div>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>
        </div>
      </div>
    );
  };

  return (
    <div className="relative">
      {renderMainContent()}
      {renderMaterialPicker()}

      {/* MODAL GLOBAL: CONSTRUTOR DE AVALIAÇÃO */}
      {isExamModalOpen && (
        <div className="fixed inset-0 !z-[9999] flex items-center justify-center p-4 bg-slate-950/80 backdrop-blur-md animate-in fade-in duration-300">
          <div className="bg-slate-900 w-full max-w-4xl max-h-[90vh] rounded-3xl shadow-2xl overflow-hidden flex flex-col animate-in zoom-in-95 border border-slate-800">
            <header className="px-8 py-6 border-b border-slate-800 flex items-center justify-between">
              <div className="flex items-center gap-4">
                <div className="p-3 bg-indigo-600 text-white rounded-2xl shadow-lg shadow-indigo-600/20"><ListChecks size={24} /></div>
                <div><h2 className="text-xl font-bold text-white leading-none">{isEditingExam ? 'Editar Avaliação' : 'Nova Avaliação Acadêmica'}</h2><p className="text-slate-500 text-[10px] font-bold uppercase tracking-[0.2em] mt-2">Construtor de Currículo Pedagógico</p></div>
              </div>
              <button onClick={() => setIsExamModalOpen(false)} className="text-slate-500 hover:text-white transition-colors"><X size={24} /></button>
            </header>
            <form onSubmit={handleSaveExam} className="flex-1 overflow-y-auto p-8 space-y-10">
              <div className="grid grid-cols-1 md:grid-cols-12 gap-6">
                <div className="md:col-span-6 space-y-2"><label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">Título da Prova</label><input required value={examForm.title} onChange={e => setExamForm({...examForm, title: e.target.value})} placeholder="Ex: Prova Mensal" className="w-full px-5 py-4 bg-slate-800 border border-slate-700 rounded-2xl text-white outline-none focus:ring-2 focus:ring-indigo-500" /></div>
                <div className="md:col-span-4 space-y-2"><label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">Curso Vinculado</label><select required value={examForm.courseId} onChange={e => setExamForm({...examForm, courseId: e.target.value})} className="w-full px-5 py-4 bg-slate-800 border border-slate-700 rounded-2xl text-white outline-none focus:ring-2 focus:ring-indigo-500"><option value="">Selecione o curso...</option>{myCourses.map(c => <option key={c.id} value={c.id}>{c.nome}</option>)}</select></div>
                <div className="md:col-span-2 space-y-2"><label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">Nota Mínima</label><input type="number" step="0.1" value={examForm.passingGrade} onChange={e => setExamForm({...examForm, passingGrade: parseFloat(e.target.value)})} className="w-full px-5 py-4 bg-slate-800 border border-slate-700 rounded-2xl text-white outline-none" /></div>
              </div>
              <div className="space-y-6">
                <div className="flex items-center justify-between border-b border-slate-800 pb-4"><h3 className="font-black text-indigo-400 text-xs uppercase tracking-[0.3em]">Questões da Avaliação</h3><button type="button" onClick={handleAddQuestion} className="flex items-center gap-2 text-indigo-400 hover:text-indigo-300 transition-colors font-bold text-xs uppercase"><Plus size={16} /> Adicionar Pergunta</button></div>
                <div className="space-y-8">{examForm.questions.map((q, qIndex) => (<div key={q.id} className="bg-slate-800/40 p-6 rounded-3xl border border-slate-700/50 relative group/q animate-in slide-in-from-top-4"><button type="button" onClick={() => handleRemoveQuestion(qIndex)} className="absolute -top-2 -right-2 p-2 bg-red-500 text-white rounded-full opacity-0 group-hover/q:opacity-100 transition-opacity"><Trash2 size={14} /></button><div className="space-y-6"><div className="flex gap-4"><span className="h-10 w-10 bg-indigo-600/20 text-indigo-400 border border-indigo-600/30 rounded-xl flex items-center justify-center font-bold text-sm shrink-0">{qIndex + 1}</span><input required value={q.text} onChange={e => handleUpdateQuestionText(qIndex, e.target.value)} placeholder="Enunciado da questão..." className="flex-1 bg-transparent border-b border-slate-700 focus:border-indigo-500 outline-none text-white font-medium py-2" /></div><div className="grid grid-cols-1 md:grid-cols-2 gap-4 pl-14">{q.options.map((opt, oIndex) => (<div key={oIndex} className={`flex items-center gap-3 p-3 rounded-2xl border transition-all ${q.correctOptionIndex === oIndex ? 'bg-emerald-500/10 border-emerald-500/50 shadow-lg' : 'bg-slate-900/50 border-slate-700/50'}`}><button type="button" onClick={() => handleSetCorrectAnswer(qIndex, oIndex)} className={`h-5 w-5 rounded-full border-2 flex items-center justify-center ${q.correctOptionIndex === oIndex ? 'bg-emerald-500 border-emerald-500 text-white' : 'border-slate-600'}`}>{q.correctOptionIndex === oIndex && <CheckCircle size={14} />}</button><input required value={opt} onChange={e => handleUpdateOption(qIndex, oIndex, e.target.value)} placeholder={`Alternativa ${String.fromCharCode(65 + oIndex)}`} className="bg-transparent text-xs text-white outline-none flex-1 placeholder:text-slate-600" /></div>))}</div></div></div>))}</div>
              </div>
              <footer className="pt-8 flex gap-4"><button type="button" onClick={() => setIsExamModalOpen(false)} className="flex-1 px-8 py-5 border border-slate-700 text-slate-400 rounded-2xl font-bold uppercase tracking-widest hover:bg-slate-800 transition-all">Cancelar</button><button type="submit" className="flex-[2] px-8 py-5 bg-indigo-600 text-white rounded-2xl font-black uppercase tracking-widest shadow-xl hover:bg-indigo-500 transition-all active:scale-95">Salvar Avaliação Digital</button></footer>
            </form>
          </div>
        </div>
      )}

      {/* MODAL GLOBAL: NOVO/EDITAR MÓDULO */}
      {isModuleModalOpen && (
        <div className="fixed inset-0 !z-[9999] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm animate-in fade-in duration-200">
          <div className="bg-white w-full max-w-md rounded-2xl shadow-2xl p-6 border border-slate-100"><h3 className="font-bold text-slate-900 mb-4">{currentEditingModule ? 'Editar Módulo' : 'Configurar Novo Módulo'}</h3><form onSubmit={handleSaveModule} className="space-y-5">{!selectedCourse && !currentEditingModule && (<div className="space-y-1"><label className="text-[10px] font-black text-slate-400 uppercase ml-1">Curso</label><select required value={moduleForm.courseId} onChange={e => setModuleForm({...moduleForm, courseId: e.target.value})} className="w-full px-4 py-2.5 bg-slate-50 border rounded-xl text-sm">{myCourses.map(c => <option key={c.id} value={c.id}>{c.nome}</option>)}</select></div>)}<div className="space-y-1"><label className="text-[10px] font-black text-slate-400 uppercase ml-1">Título</label><input required autoFocus value={moduleForm.nome} onChange={e => setModuleForm({...moduleForm, nome: e.target.value})} className="w-full px-4 py-2.5 bg-slate-50 border rounded-xl text-sm" /></div><div className="flex gap-3"><button type="button" onClick={() => setIsModuleModalOpen(false)} className="flex-1 px-4 py-2.5 border rounded-xl font-bold text-sm">Cancelar</button><button type="submit" className="flex-1 bg-indigo-600 text-white py-2.5 rounded-xl font-bold text-sm shadow-lg">Salvar</button></div></form></div>
        </div>
      )}

      {/* MODAL GLOBAL: NOVA AULA / EDIÇÃO DE AULA (COM INTEGRAÇÃO BIBLIOTECA) */}
      {showLessonModal && (
        <div className="fixed inset-0 !z-[9998] flex items-center justify-center p-4 bg-slate-900/40 backdrop-blur-sm animate-in fade-in">
          <div className="bg-white w-full max-w-xl rounded-3xl shadow-2xl p-8 animate-in zoom-in-95 border border-slate-100">
            <h3 className="font-bold text-slate-900 text-xl mb-6 flex items-center gap-3"><PlusCircle size={24} className="text-indigo-600" /> {isEditingLesson ? 'Editar Aula' : 'Publicar Nova Unidade'}</h3>
            <form onSubmit={handleSaveLesson} className="space-y-5">
              <input required value={lessonForm.titulo} onChange={e => setLessonForm({...lessonForm, titulo: e.target.value})} placeholder="Título da Aula" className="w-full px-5 py-3.5 bg-slate-50 border border-slate-200 rounded-2xl text-sm outline-none focus:ring-2 focus:ring-indigo-500" />
              <textarea value={lessonForm.descricao} onChange={e => setLessonForm({...lessonForm, descricao: e.target.value})} placeholder="Descrição pedagógica..." className="w-full px-5 py-3.5 bg-slate-50 border border-slate-200 rounded-2xl text-sm resize-none" rows={4}></textarea>
              <div className="space-y-4">
                <div className="space-y-1">
                  <label className="text-[10px] font-black text-slate-400 uppercase ml-1">Vínculo de Vídeo (YouTube)</label>
                  <input value={lessonForm.videoUrl} onChange={e => setLessonForm({...lessonForm, videoUrl: e.target.value})} placeholder="https://youtube.com/watch?v=..." className="w-full px-5 py-3.5 bg-slate-50 border border-slate-200 rounded-2xl text-sm outline-none focus:ring-2 focus:ring-indigo-500" />
                </div>

                {/* INTEGRAÇÃO BIBLIOTECA: MATERIAL DE APOIO */}
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-slate-400 uppercase ml-1">Material de Apoio (PDF/Documento)</label>
                  <div className="flex gap-2">
                    <input value={lessonForm.materialUrl} onChange={e => setLessonForm({...lessonForm, materialUrl: e.target.value})} placeholder="URL do arquivo..." className="flex-1 px-5 py-3.5 bg-slate-50 border border-slate-200 rounded-2xl text-sm outline-none" />
                    <button 
                      type="button" 
                      onClick={() => handleOpenMaterialPicker('document', (url) => setLessonForm(prev => ({...prev, materialUrl: url})))}
                      className="px-4 bg-indigo-600 text-white rounded-2xl hover:bg-indigo-700 transition-all shadow-lg flex items-center gap-2"
                      title="Selecionar da Biblioteca"
                    >
                      <Library size={18} />
                    </button>
                  </div>
                  {lessonForm.materialUrl && (
                    <div className="px-4 py-2 bg-emerald-50 border border-emerald-100 rounded-xl flex items-center gap-3 animate-in fade-in slide-in-from-left-2">
                      <CheckCircle size={14} className="text-emerald-500" />
                      <span className="text-[10px] font-bold text-emerald-700 uppercase tracking-tight truncate">Arquivo vinculado com sucesso</span>
                      <button type="button" onClick={() => setLessonForm(prev => ({...prev, materialUrl: ''}))} className="ml-auto text-emerald-400 hover:text-emerald-600"><X size={12} /></button>
                    </div>
                  )}
                </div>
              </div>
              <div className="flex gap-4 pt-4">
                <button type="button" onClick={() => setShowLessonModal(false)} className="flex-1 py-4 border border-slate-200 text-slate-500 rounded-2xl font-bold text-sm hover:bg-slate-50">Cancelar</button>
                <button type="submit" className="flex-[2] bg-slate-900 text-white py-4 rounded-2xl font-bold text-sm shadow-xl hover:bg-slate-800 transition-all active:scale-95">{isEditingLesson ? 'Salvar Alterações' : 'Publicar Aula'}</button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* MODAL GLOBAL: CURSO (COM INTEGRAÇÃO BIBLIOTECA) */}
      {showCourseModal && (
        <div className="fixed inset-0 !z-[9997] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm animate-in fade-in">
          <div className="bg-white w-full max-w-3xl rounded-[2.5rem] shadow-2xl overflow-hidden animate-in zoom-in-95 flex flex-col max-h-[90vh] border border-slate-100">
            <div className="p-8 border-b border-slate-50 flex items-center justify-between bg-slate-50/30">
              <div className="flex items-center gap-4">
                <div className="bg-indigo-600 p-3 rounded-2xl text-white shadow-xl shadow-indigo-200"><GraduationCap size={24} /></div>
                <div><h3 className="font-bold text-slate-900 text-xl">{isEditingCourse ? 'Editar Parâmetros' : 'Novo Curso Acadêmico'}</h3><p className="text-[10px] text-slate-400 font-black uppercase tracking-widest">Configuração de Matrícula e Mídia</p></div>
              </div>
              <button onClick={handleCloseCourseModal} className="text-slate-300 hover:text-slate-600 p-2 transition-colors"><X size={24} /></button>
            </div>
            <form onSubmit={handleSaveCourse} className="p-10 space-y-8 overflow-y-auto">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-10">
                <div className="space-y-6">
                  <div className="space-y-1"><label className="text-[10px] font-black text-slate-400 uppercase ml-1">Título do Curso</label><input required value={courseForm.nome} onChange={e => setCourseForm({...courseForm, nome: e.target.value})} className="w-full px-5 py-4 bg-slate-50 border border-slate-200 rounded-2xl text-sm" /></div>
                  <div className="space-y-1"><label className="text-[10px] font-black text-slate-400 uppercase ml-1">Docente Responsável</label><input required value={courseForm.professorResponsavel} onChange={e => setCourseForm({...courseForm, professorResponsavel: e.target.value})} className="w-full px-5 py-4 bg-slate-50 border border-slate-200 rounded-2xl text-sm" /></div>
                </div>

                {/* INTEGRAÇÃO BIBLIOTECA: CAPA DO CURSO */}
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-slate-400 uppercase ml-1">Capa do Curso</label>
                  <div className="relative group/capa h-44 w-full bg-slate-50 border-2 border-dashed border-slate-200 rounded-3xl flex flex-col items-center justify-center overflow-hidden transition-all hover:border-indigo-400">
                    {courseForm.capaUrl ? (
                      <>
                        <img src={courseForm.capaUrl} className="w-full h-full object-cover transition-transform group-hover/capa:scale-110" />
                        <div className="absolute inset-0 bg-black/40 opacity-0 group-hover/capa:opacity-100 flex items-center justify-center gap-3 transition-opacity">
                           <button type="button" onClick={() => handleOpenMaterialPicker('image', (url) => setCourseForm(prev => ({...prev, capaUrl: url})))} className="p-3 bg-white text-indigo-600 rounded-xl shadow-xl hover:scale-110 transition-transform"><Library size={20} /></button>
                           <button type="button" onClick={() => setCourseForm(prev => ({...prev, capaUrl: ''}))} className="p-3 bg-white text-red-600 rounded-xl shadow-xl hover:scale-110 transition-transform"><X size={20} /></button>
                        </div>
                      </>
                    ) : (
                      <div className="flex flex-col items-center space-y-4">
                        <FileUp size={32} className="text-slate-300" />
                        <div className="flex gap-2">
                          <button type="button" onClick={() => handleOpenMaterialPicker('image', (url) => setCourseForm(prev => ({...prev, capaUrl: url})))} className="px-4 py-2 bg-indigo-600 text-white text-[10px] font-black uppercase rounded-xl shadow-lg">Biblioteca</button>
                          <label className="px-4 py-2 bg-slate-900 text-white text-[10px] font-black uppercase rounded-xl shadow-lg cursor-pointer">Upload<input type="file" className="hidden" onChange={handleFileUpload} accept="image/*" /></label>
                        </div>
                      </div>
                    )}
                  </div>
                  {courseForm.capaUrl && <p className="text-[9px] text-indigo-500 font-bold uppercase tracking-tighter text-center">Imagem de capa vinculada com sucesso</p>}
                </div>
              </div>
              <div className="flex gap-4 pt-6">
                <button type="button" onClick={handleCloseCourseModal} className="flex-1 py-5 border border-slate-200 text-slate-500 rounded-[1.5rem] font-bold text-sm hover:bg-slate-50">Descartar</button>
                <button type="submit" disabled={loading} className="flex-[2] bg-slate-900 text-white py-5 rounded-[1.5rem] font-black text-xs uppercase tracking-[0.2em] shadow-2xl shadow-slate-300 hover:bg-slate-800 transition-all active:scale-95">{loading ? 'Processando...' : (isEditingCourse ? 'Salvar Alterações' : 'Criar Curso EAD')}</button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default ProfessorView;

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { 
  collection, 
  query, 
  where, 
  getDocs, 
  addDoc, 
  deleteDoc,
  serverTimestamp, 
  orderBy,
  doc,
  updateDoc,
  getDoc,
  arrayUnion 
} from 'firebase/firestore';
import { db } from '../firebase';
import { Course, Module, Lesson, User, ProfessorSubView } from '../types';
import { 
  BookOpen, 
  Plus, 
  X, 
  ChevronRight, 
  Play, 
  Pause, 
  Volume2, 
  VolumeX, 
  Maximize, 
  MoreVertical, 
  ArrowLeft, 
  Layout, 
  Trash2, 
  Layers, 
  Eye, 
  CheckCircle, 
  Copy, 
  Edit, 
  GraduationCap, 
  FileUp, 
  FileDown,
  Lock,
  FileText,
  Award,
  File,
  FileImage,
  FileSpreadsheet,
  CloudUpload,
  Download,
  Database,
  AlertTriangle,
  ClipboardCheck,
  ListChecks,
  PlusCircle,
  Search,
  Library
} from 'lucide-react';

// Constante de Armazenamento Máximo (5GB)
const MAX_STORAGE = 5 * 1024 * 1024 * 1024;

interface MaterialFile {
  id: string;
  name: string;
  type: string;
  size: string;
  sizeBytes: number;
  date: Date;
  url: string;
}

interface Question {
  id: string;
  text: string;
  options: string[];
  correctOptionIndex: number;
}

interface Exam {
  id: string;
  title: string;
  courseId: string;
  courseName: string;
  passingGrade: number;
  questions: Question[];
}

interface ProfessorViewProps {
  user: User;
  activeSub: ProfessorSubView;
  setActiveSub: (view: ProfessorSubView) => void;
}

const ProfessorView: React.FC<ProfessorViewProps> = ({ user, activeSub, setActiveSub }) => {
  const [myCourses, setMyCourses] = useState<Course[]>([]);
  const [loading, setLoading] = useState(true);
  const [selectedCourse, setSelectedCourse] = useState<Course | null>(null);
  const [modules, setModules] = useState<Module[]>([]);
  const [lessonsByModule, setLessonsByModule] = useState<Record<string, Lesson[]>>({});
  const [allModulesGrouped, setAllModulesGrouped] = useState<Record<string, { course: Course, modules: Module[] }>>({});
  const [openMenuId, setOpenMenuId] = useState<string | null>(null);

  // State para Materiais
  const [materials, setMaterials] = useState<MaterialFile[]>(() => {
    const saved = sessionStorage.getItem('eb_materials_mock');
    return saved ? JSON.parse(saved).map((m: any) => ({...m, date: new Date(m.date)})) : [];
  });

  // State para o Material Picker
  const [isMaterialPickerOpen, setIsMaterialPickerOpen] = useState(false);
  const [pickerMode, setPickerMode] = useState<'image' | 'document'>('document');
  const [pickerCallback, setPickerCallback] = useState<(url: string) => void>(() => {});

  // State para Avaliações (Exams)
  const [exams, setExams] = useState<Exam[]>(() => {
    const saved = sessionStorage.getItem('eb_exams_mock');
    return saved ? JSON.parse(saved) : [];
  });
  const [isExamModalOpen, setIsExamModalOpen] = useState(false);
  const [isEditingExam, setIsEditingExam] = useState(false);
  const [examForm, setExamForm] = useState<{
    id?: string;
    title: string;
    courseId: string;
    passingGrade: number;
    questions: Question[];
  }>({
    title: '',
    courseId: '',
    passingGrade: 7.0,
    questions: [{ id: '1', text: '', options: ['', '', '', ''], correctOptionIndex: 0 }]
  });

  const materialInputRef = useRef<HTMLInputElement>(null);

  // Persistência simulada
  useEffect(() => {
    sessionStorage.setItem('eb_materials_mock', JSON.stringify(materials));
  }, [materials]);

  useEffect(() => {
    sessionStorage.setItem('eb_exams_mock', JSON.stringify(exams));
  }, [exams]);

  // Modal States
  const [showCourseModal, setShowCourseModal] = useState(false);
  const [isEditingCourse, setIsEditingCourse] = useState(false);
  const [editingCourseId, setEditingCourseId] = useState<string | null>(null);

  const [isModuleModalOpen, setIsModuleModalOpen] = useState(false); 
  const [showLessonModal, setShowLessonModal] = useState(false);
  const [isEditingLesson, setIsEditingLesson] = useState(false);
  const [activeModuleId, setActiveModuleId] = useState<string | null>(null);
  const [currentEditingModule, setCurrentEditingModule] = useState<Module | null>(null); 
  const [editingLessonId, setEditingLessonId] = useState<string | null>(null);

  // Preview States
  const [previewLesson, setPreviewLesson] = useState<Lesson | null>(null);
  const [isConcluded, setIsConcluded] = useState(false);
  const [isPlaying, setIsPlaying] = useState(false);
  const [timeLeft, setTimeLeft] = useState(300);
  const timerIntervalRef = useRef<number | null>(null);
  const [showWelcomeModal, setShowWelcomeModal] = useState(false);
  const [showCompletionModal, setShowCompletionModal] = useState(false);

  const [isStudentSimulationMode, setIsStudentSimulationMode] = useState(false);
  const [isCertificateUnlocked, setIsCertificateUnlocked] = useState(false);
  const [completedLessonIds, setCompletedLessonIds] = useState<Set<string>>(new Set());
  const [totalLessons, setTotalLessons] = useState(0);

  const [playerVolume, setPlayerVolume] = useState(80); 
  const [isMuted, setIsMuted] = useState(false); 
  const iframeRef = useRef<HTMLIFrameElement>(null); 
  const playerContainerRef = useRef<HTMLDivElement>(null); 

  // Form States
  const [courseForm, setCourseForm] = useState({
    nome: '', tema: '', professorResponsavel: user.displayName || '',
    descricaoLonga: '', capaUrl: '', cargaHoraria: '',
    publicoAlvo: 'Geral' as const, geraCertificado: false
  });
  const [moduleForm, setModuleForm] = useState({ nome: '', courseId: '' });
  const [lessonForm, setLessonForm] = useState({
    titulo: '', descricao: '', videoUrl: '', materialUrl: ''
  });

  // --- Funções de Dados ---
  const fetchMyCourses = async () => {
    setLoading(true);
    try {
      const q = query(collection(db, 'cursos'), where('professorId', '==', user.uid), orderBy('createdAt', 'desc'));
      const querySnapshot = await getDocs(q);
      const fetched: Course[] = [];
      querySnapshot.forEach((doc) => {
        fetched.push({ id: doc.id, ...doc.data() } as Course);
      });
      setMyCourses(fetched);
    } catch (error) {
      console.error(error);
    } finally {
      setLoading(false);
    }
  };

  const fetchModulesForCourse = async (courseId: string) => {
    const q = query(collection(db, 'cursos', courseId, 'modulos'), orderBy('ordem', 'asc'));
    const querySnapshot = await getDocs(q);
    const fetched: Module[] = [];
    querySnapshot.forEach((doc) => {
      fetched.push({ id: doc.id, ...doc.data(), courseId } as Module);
    });
    return fetched;
  };

  const fetchAllModulesGrouped = async () => {
    setLoading(true);
    try {
      const grouped: Record<string, { course: Course, modules: Module[] }> = {};
      for (const course of myCourses) {
        const mods = await fetchModulesForCourse(course.id);
        for (const mod of mods) {
          await fetchLessons(course.id, mod.id);
        }
        grouped[course.id] = { course, modules: mods };
      }
      setAllModulesGrouped(grouped);
    } catch (error) {
      console.error(error);
    } finally {
      setLoading(false);
    }
  };

  const fetchLessons = async (courseId: string, moduleId: string) => {
    try {
      const q = query(collection(db, 'cursos', courseId, 'modulos', moduleId, 'aulas'), orderBy('ordem', 'asc'));
      const querySnapshot = await getDocs(q);
      const fetched: Lesson[] = [];
      querySnapshot.forEach((doc) => {
        fetched.push({ id: doc.id, ...doc.data() } as Lesson);
      });
      setLessonsByModule(prev => ({ ...prev, [moduleId]: fetched }));
    } catch (error) {
      console.error(error);
    }
  };

  const fetchCompletedLessons = useCallback(async (studentId: string, courseId: string) => {
    if (!studentId || !courseId) return new Set<string>();
    try {
      const key = `completed_lessons_sim_${studentId}_${courseId}`;
      const stored = localStorage.getItem(key);
      return new Set(stored ? JSON.parse(stored) : []);
    } catch (error) {
      console.error(error);
    }
    return new Set<string>();
  }, []);

  const updateCompletedLesson = useCallback(async (studentId: string, lessonId: string) => {
    if (!studentId || !lessonId) return;
    try {
      const key = `completed_lessons_sim_${studentId}_${selectedCourse?.id}`;
      const currentCompleted = await fetchCompletedLessons(studentId, selectedCourse?.id || '');
      if (!currentCompleted.has(lessonId)) {
        currentCompleted.add(lessonId);
        localStorage.setItem(key, JSON.stringify(Array.from(currentCompleted)));
        setCompletedLessonIds(currentCompleted);
      }
    } catch (error) {
      console.error(error);
    }
  }, [fetchCompletedLessons, selectedCourse?.id]);

  // --- Effects ---
  useEffect(() => { fetchMyCourses(); }, [user.uid]);

  useEffect(() => {
    if (activeSub === 'modulos') { fetchAllModulesGrouped(); }
  }, [activeSub, myCourses]);

  useEffect(() => {
    if (selectedCourse && modules.length > 0) {
      let count = 0;
      for (const mod of modules) { count += (lessonsByModule[mod.id]?.length || 0); }
      setTotalLessons(count);
    } else { setTotalLessons(0); }
  }, [selectedCourse, modules, lessonsByModule]);

  useEffect(() => {
    const shouldStartTimer = isStudentSimulationMode && previewLesson && !showWelcomeModal && isPlaying;
    if (shouldStartTimer && timeLeft > 0) {
      if (!timerIntervalRef.current) {
        timerIntervalRef.current = window.setInterval(async () => {
          setTimeLeft(prevTime => {
            if (prevTime <= 1) {
              if (timerIntervalRef.current) { clearInterval(timerIntervalRef.current); timerIntervalRef.current = null; }
              setIsConcluded(true);
              if (user.uid && previewLesson?.id) { updateCompletedLesson(user.uid, previewLesson.id); }
              if (!showCompletionModal) { setShowCompletionModal(true); }
              return 0;
            }
            return prevTime - 1;
          });
        }, 1000);
      }
    } else if (timerIntervalRef.current) {
      clearInterval(timerIntervalRef.current);
      timerIntervalRef.current = null;
    }
    return () => { if (timerIntervalRef.current) { clearInterval(timerIntervalRef.current); timerIntervalRef.current = null; } };
  }, [previewLesson, isStudentSimulationMode, showWelcomeModal, isPlaying, timeLeft, showCompletionModal, user.uid, previewLesson?.id, updateCompletedLesson]);

  useEffect(() => {
    if (selectedCourse?.geraCertificado && isStudentSimulationMode && totalLessons > 0) {
      setIsCertificateUnlocked(completedLessonIds.size >= totalLessons);
    } else { setIsCertificateUnlocked(false); }
  }, [selectedCourse?.geraCertificado, isStudentSimulationMode, completedLessonIds, totalLessons]);

  useEffect(() => {
    if (selectedCourse && user.uid) { fetchCompletedLessons(user.uid, selectedCourse.id).then(setCompletedLessonIds); }
    else { setCompletedLessonIds(new Set()); }
  }, [selectedCourse, user.uid, fetchCompletedLessons]);

  const getYouTubeVideoId = (url: string) => {
    const ytRegex = /(?:https?:\/\/)?(?:www\.)?(?:youtube\.com\/(?:[^\/\n\s]+\/\S+\/|(?:v|e(?:mbed)?)\/|\S*?[?&]v=)|youtu\.be\/)([a-zA-Z0-9_-]{11})/;
    const ytMatch = url.match(ytRegex);
    return ytMatch && ytMatch[1];
  };

  const sendPlayerCommand = useCallback((command: string, args: any = '') => {
    if (iframeRef.current && iframeRef.current.contentWindow) {
      iframeRef.current.contentWindow.postMessage(JSON.stringify({ event: 'command', func: command, args: args }), '*');
    }
  }, []);

  const togglePlay = () => {
    if (isPlaying) { sendPlayerCommand('pauseVideo'); setIsPlaying(false); }
    else { sendPlayerCommand('playVideo'); setIsPlaying(true); setShowWelcomeModal(false); }
  };

  const toggleMute = () => {
    if (isMuted) { sendPlayerCommand('unMute'); } else { sendPlayerCommand('mute'); }
    setIsMuted(prev => !prev);
  };

  const handleVolumeChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const vol = parseInt(e.target.value);
    setPlayerVolume(vol);
    if (vol === 0) { if (!isMuted) sendPlayerCommand('mute'); setIsMuted(true); }
    else { if (isMuted) sendPlayerCommand('unMute'); sendPlayerCommand('setVolume', [vol]); setIsMuted(false); }
  };

  const toggleFullscreen = () => {
    if (playerContainerRef.current) {
      if (!document.fullscreenElement) playerContainerRef.current.requestFullscreen();
      else document.exitFullscreen();
    }
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    if (file.size > 5 * 1024 * 1024) { alert("A imagem de capa não pode exceder 5 MB."); e.target.value = ''; return; }
    const reader = new FileReader();
    reader.onloadend = () => { setCourseForm(prev => ({ ...prev, capaUrl: reader.result as string })); };
    reader.readAsDataURL(file);
  };

  const handleSaveCourse = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      setLoading(true);
      if (isEditingCourse && editingCourseId) {
        const courseRef = doc(db, 'cursos', editingCourseId);
        await updateDoc(courseRef, { ...courseForm });
        if (selectedCourse?.id === editingCourseId) { setSelectedCourse({ ...selectedCourse, ...courseForm }); }
      } else {
        await addDoc(collection(db, 'cursos'), { ...courseForm, professorId: user.uid, inscritos: 0, status: 'rascunho', createdAt: serverTimestamp() });
      }
      handleCloseCourseModal();
      await fetchMyCourses();
    } catch (error) {
      console.error(error);
    } finally { setLoading(false); }
  };

  const handleEditCourseInfo = (course: Course) => {
    setCourseForm({
      nome: course.nome, tema: course.tema || '', professorResponsavel: course.professorResponsavel || '',
      descricaoLonga: course.descricaoLonga || '', capaUrl: course.capaUrl || '',
      cargaHoraria: course.cargaHoraria, publicoAlvo: course.publicoAlvo,
      geraCertificado: course.geraCertificado || false
    });
    setEditingCourseId(course.id);
    setIsEditingCourse(true);
    setShowCourseModal(true);
    setOpenMenuId(null);
  };

  const handleCloseCourseModal = () => {
    setShowCourseModal(false);
    setIsEditingCourse(false);
    setEditingCourseId(null);
    setCourseForm({
      nome: '', tema: '', professorResponsavel: user.displayName || '',
      descricaoLonga: '', capaUrl: '', cargaHoraria: '',
      publicoAlvo: 'Geral', geraCertificado: false
    });
  };

  const handleDeleteCourse = async (courseId: string) => {
    if (!confirm("Tem certeza que deseja excluir o curso inteiro?")) return;
    try {
      await deleteDoc(doc(db, 'cursos', courseId));
      setMyCourses(prev => prev.filter(c => c.id !== courseId));
      setOpenMenuId(null);
    } catch (error) { console.error(error); }
  };

  const handleDuplicateCourse = async (course: Course) => {
    try {
      const { id, ...data } = course;
      await addDoc(collection(db, 'cursos'), { ...data, nome: `${data.nome} (Cópia)`, createdAt: serverTimestamp() });
      fetchMyCourses();
      setOpenMenuId(null);
    } catch (error) { console.error(error); }
  };

  const handleDeleteModule = async (courseId: string, moduleId: string) => {
    if (!confirm("Excluir este módulo e todo seu conteúdo?")) return;
    try {
      await deleteDoc(doc(db, 'cursos', courseId, 'modulos', moduleId));
      if (selectedCourse) { setModules(prev => prev.filter(m => m.id !== moduleId)); }
      fetchAllModulesGrouped();
    } catch (error) { console.error(error); }
  };

  const handleSaveModule = async (e: React.FormEvent) => {
    e.preventDefault();
    const finalCourseId = selectedCourse?.id || moduleForm.courseId;
    if (!finalCourseId) {
       alert("Selecione um curso.");
       return;
    }
    try {
      if (currentEditingModule) {
        const modRef = doc(db, 'cursos', currentEditingModule.courseId, 'modulos', currentEditingModule.id);
        await updateDoc(modRef, { nome: moduleForm.nome });
      } else {
        const qOrder = query(collection(db, 'cursos', finalCourseId, 'modulos'));
        const snapOrder = await getDocs(qOrder);
        const nextOrder = snapOrder.size + 1;

        await addDoc(collection(db, 'cursos', finalCourseId, 'modulos'), { 
          nome: moduleForm.nome, 
          ordem: nextOrder, 
          createdAt: serverTimestamp() 
        });
      }
      setIsModuleModalOpen(false);
      setModuleForm({ nome: '', courseId: '' });
      setCurrentEditingModule(null);
      if (selectedCourse) {
         const mods = await fetchModulesForCourse(selectedCourse.id);
         setModules(mods);
      }
      fetchAllModulesGrouped();
    } catch (error) { console.error(error); }
  };

  const handleOpenCreateModule = () => {
    setModuleForm({ nome: '', courseId: selectedCourse?.id || '' });
    setCurrentEditingModule(null);
    setIsModuleModalOpen(true);
  };

  const handleEditModule = (mod: Module) => {
    setCurrentEditingModule(mod);
    setModuleForm({ nome: mod.nome, courseId: mod.courseId });
    setIsModuleModalOpen(true);
  };

  const handleSaveLesson = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedCourse || !activeModuleId) return;

    // TRAVA DE DUPLICIDADE (VALORIZAÇÃO PEDAGÓGICA)
    // Fix: Explicitly cast to Lesson[] to avoid "unknown" type access errors
    const allLessonsFlattened = Object.values(lessonsByModule).flat() as Lesson[];
    const arquivoJaUsado = allLessonsFlattened.find(l => 
        l.materialUrl === lessonForm.materialUrl && 
        l.materialUrl !== '' && // Ignora campos vazios
        l.id !== editingLessonId
    );

    if (arquivoJaUsado) {
        alert(`Atenção: O arquivo selecionado já está vinculado à aula "${arquivoJaUsado.titulo}". Por favor, escolha outro arquivo para evitar conflitos de download.`);
        return;
    }

    try {
      if (isEditingLesson && editingLessonId) {
        const lessonRef = doc(db, 'cursos', selectedCourse.id, 'modulos', activeModuleId, 'aulas', editingLessonId);
        await updateDoc(lessonRef, { ...lessonForm });
        if (previewLesson && previewLesson.id === editingLessonId) {
           setPreviewLesson(prev => prev ? ({ ...prev, ...lessonForm }) : null);
        }
      } else {
        await addDoc(collection(db, 'cursos', selectedCourse.id, 'modulos', activeModuleId, 'aulas'), { ...lessonForm, ordem: (lessonsByModule[activeModuleId]?.length || 0) + 1, createdAt: serverTimestamp() });
      }
      setShowLessonModal(false);
      setIsEditingLesson(false);
      setEditingLessonId(null);
      setLessonForm({ titulo: '', descricao: '', videoUrl: '', materialUrl: '' });
      fetchLessons(selectedCourse.id, activeModuleId);
    } catch (error) { console.error(error); }
  };

  const handleDeleteLesson = async (moduleId: string, lessonId: string) => {
    if (!selectedCourse) return;
    if (!confirm("Tem certeza que deseja DESTRUIR esta aula permanentemente?")) return;
    try {
      await deleteDoc(doc(db, 'cursos', selectedCourse.id, 'modulos', moduleId, 'aulas', lessonId));
      fetchLessons(selectedCourse.id, moduleId);
      if (previewLesson?.id === lessonId) setPreviewLesson(null);
    } catch (error) { console.error(error); }
  };

  const handleEditLesson = (lesson: Lesson, moduleId: string) => {
    setActiveModuleId(moduleId);
    setLessonForm({ titulo: lesson.titulo, descricao: lesson.descricao || '', videoUrl: lesson.videoUrl, materialUrl: lesson.materialUrl });
    setEditingLessonId(lesson.id);
    setIsEditingLesson(true);
    setShowLessonModal(true);
  };

  const openCourseDetail = async (course: Course) => {
    setSelectedCourse(course);
    const mods = await fetchModulesForCourse(course.id);
    setModules(mods);
    for (const mod of mods) { fetchLessons(course.id, mod.id); }
  };

  const openPreview = (lesson: Lesson, moduleId: string, studentMode: boolean) => {
    setActiveModuleId(moduleId);
    setPreviewLesson(lesson);
    setIsPlaying(false);
    setTimeLeft(300);
    setIsConcluded(false);
    setIsMuted(false);
    setPlayerVolume(80);
    sendPlayerCommand('setVolume', [80]);
    sendPlayerCommand('unMute');
    setIsStudentSimulationMode(studentMode);
    setShowWelcomeModal(studentMode);
    setShowCompletionModal(false);
  };

  const handleReturnToDashboard = () => {
    setPreviewLesson(null);
    setSelectedCourse(null);
    setShowCompletionModal(false);
    setIsStudentSimulationMode(false);
    setIsCertificateUnlocked(false);
    setIsPlaying(false);
    sendPlayerCommand('pauseVideo');
  };

  // --- Lógica de Materiais ---
  const formatFileSize = (bytes: number) => {
    if (bytes === 0) return '0 Bytes';
    const k = 1024;
    const sizes = ['Bytes', 'KB', 'MB', 'GB', 'TB'];
    const i = Math.floor(Math.log(bytes) / Math.log(k));
    return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i];
  };

  const currentUsedStorage = materials.reduce((acc, m) => acc + m.sizeBytes, 0);
  const storagePercentage = (currentUsedStorage / MAX_STORAGE) * 100;

  const handleMaterialUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (!files) return;
    let tempUsed = currentUsedStorage;
    const newMaterials: MaterialFile[] = [];
    for (let i = 0; i < files.length; i++) {
      const file = files[i];
      if (tempUsed + file.size > MAX_STORAGE) {
        alert(`Espaço insuficiente para o arquivo "${file.name}". Limite de 5GB atingido.`);
        continue;
      }
      tempUsed += file.size;
      const extension = file.name.split('.').pop()?.toLowerCase() || '';
      const blobUrl = URL.createObjectURL(file);
      newMaterials.push({
        id: Math.random().toString(36).substr(2, 9),
        name: file.name,
        type: extension,
        size: formatFileSize(file.size),
        sizeBytes: file.size,
        date: new Date(),
        url: blobUrl
      });
    }
    setMaterials(prev => [...newMaterials, ...prev]);
    if (materialInputRef.current) materialInputRef.current.value = '';
  };

  const handleDeleteMaterial = (id: string) => {
    const file = materials.find(m => m.id === id);
    if (!file) return;
    if (confirm(`Excluir "${file.name}"? Isso liberará ${file.size} do armazenamento.`)) {
      if (file.url.startsWith('blob:')) URL.revokeObjectURL(file.url);
      setMaterials(prev => prev.filter(m => m.id !== id));
    }
  };

  const getFileIcon = (type: string) => {
    switch (type) {
      case 'pdf': return <FileText size={32} className="text-red-400" />;
      case 'jpg':
      case 'jpeg':
      case 'png':
      case 'webp': return <FileImage size={32} className="text-blue-400" />;
      case 'xlsx':
      case 'xls':
      case 'csv': return <FileSpreadsheet size={32} className="text-emerald-400" />;
      default: return <File size={32} className="text-slate-400" />;
    }
  };

  // --- INTEGRAÇÃO MATERIAL PICKER ---
  const handleOpenMaterialPicker = (mode: 'image' | 'document', callback: (url: string) => void) => {
    setPickerMode(mode);
    setPickerCallback(() => callback);
    setIsMaterialPickerOpen(true);
  };

  const handleSelectMaterialFromPicker = (material: MaterialFile) => {
    pickerCallback(material.url);
    setIsMaterialPickerOpen(false);
  };

  // --- Lógica de Avaliações (Exams) ---
  const handleAddQuestion = () => {
    setExamForm(prev => ({
      ...prev,
      questions: [
        ...prev.questions,
        { 
          id: (prev.questions.length + 1).toString(), 
          text: '', 
          options: ['', '', '', ''], 
          correctOptionIndex: 0 
        }
      ]
    }));
  };

  const handleRemoveQuestion = (index: number) => {
    if (examForm.questions.length <= 1) return;
    setExamForm(prev => {
      const newQuestions = [...prev.questions];
      newQuestions.splice(index, 1);
      return { ...prev, questions: newQuestions };
    });
  };

  const handleUpdateQuestionText = (index: number, text: string) => {
    setExamForm(prev => {
      const newQuestions = [...prev.questions];
      newQuestions[index].text = text;
      return { ...prev, questions: newQuestions };
    });
  };

  const handleUpdateOption = (qIndex: number, oIndex: number, text: string) => {
    setExamForm(prev => {
      const newQuestions = [...prev.questions];
      newQuestions[qIndex].options[oIndex] = text;
      return { ...prev, questions: newQuestions };
    });
  };

  const handleSetCorrectAnswer = (qIndex: number, oIndex: number) => {
    setExamForm(prev => {
      const newQuestions = [...prev.questions];
      newQuestions[qIndex].correctOptionIndex = oIndex;
      return { ...prev, questions: newQuestions };
    });
  };

  const handleSaveExam = (e: React.FormEvent) => {
    e.preventDefault();
    if (!examForm.courseId) return alert("Selecione um curso.");
    const course = myCourses.find(c => c.id === examForm.courseId);
    const newExam: Exam = {
      id: examForm.id || Math.random().toString(36).substr(2, 9),
      title: examForm.title,
      courseId: examForm.courseId,
      courseName: course?.nome || 'Curso não encontrado',
      passingGrade: examForm.passingGrade,
      questions: examForm.questions
    };
    if (isEditingExam) {
      setExams(prev => prev.map(ex => ex.id === newExam.id ? newExam : ex));
    } else {
      setExams(prev => [newExam, ...prev]);
    }
    setIsExamModalOpen(false);
    setIsEditingExam(false);
    setExamForm({ title: '', courseId: '', passingGrade: 7.0, questions: [{ id: '1', text: '', options: ['', '', '', ''], correctOptionIndex: 0 }] });
  };

  const handleEditExam = (exam: Exam) => {
    setExamForm({
      id: exam.id,
      title: exam.title,
      courseId: exam.courseId,
      passingGrade: exam.passingGrade,
      questions: exam.questions
    });
    setIsEditingExam(true);
    setIsExamModalOpen(true);
  };

  const handleDeleteExam = (id: string) => {
    if (confirm("Deseja excluir esta avaliação permanentemente?")) {
      setExams(prev => prev.filter(ex => ex.id !== id));
    }
  };

  // --- RENDERIZAÇÃO UNIFICADA ---
  const renderMainContent = () => {
    if (previewLesson && selectedCourse) {
      const videoId = getYouTubeVideoId(previewLesson.videoUrl);
      const iframeSrc = `https://www.youtube.com/embed/${videoId}?controls=0&modestbranding=1&rel=0&enablejsapi=1&autoplay=${isPlaying ? 1 : 0}&mute=${isMuted ? 1 : 0}`;
      return (
        <div className="fixed inset-0 z-[100] bg-gradient-to-br from-gray-900 to-slate-950 animate-in fade-in duration-300 overflow-y-auto">
          <div className="max-w-[1440px] mx-auto p-4 md:p-6 lg:p-8 flex flex-col h-full">
            <header className="flex items-center justify-between mb-6 pb-4 border-b border-gray-800">
              <div className="flex items-center gap-4">
                <button onClick={handleReturnToDashboard} className="h-10 w-10 bg-gray-800 border border-gray-700 hover:bg-gray-700 rounded-xl text-gray-300 transition-all shadow-sm flex items-center justify-center"><ArrowLeft size={20} /></button>
                <div>
                  <h1 className="text-xl font-bold text-white leading-tight">{selectedCourse.nome}</h1>
                  <p className="text-gray-400 text-sm mt-0.5">{isStudentSimulationMode ? 'Simulação Discente' : 'Construtor de Cursos'}</p>
                </div>
              </div>
              <button onClick={() => setPreviewLesson(null)} className="px-4 py-2 bg-gray-800 hover:bg-gray-700 rounded-xl text-gray-300 text-xs font-bold transition-colors">Fechar Pré-visualização</button>
            </header>
            <div className="flex-1 grid grid-cols-1 lg:grid-cols-4 gap-6">
              <div className="lg:col-span-3 space-y-6">
                {showWelcomeModal && isStudentSimulationMode ? (
                  <div className="aspect-video bg-black/60 backdrop-blur-xl rounded-3xl overflow-hidden shadow-2xl border-4 border-indigo-500 relative flex items-center justify-center text-center p-8 animate-in zoom-in-95 duration-300">
                    <button onClick={() => setShowWelcomeModal(false)} className="absolute top-4 right-4 text-white hover:text-indigo-200 p-2 rounded-full hover:bg-white/10 transition-colors"><X size={24} /></button>
                    <div className="relative z-10 space-y-6 max-w-lg">
                      <p className="text-white font-serif text-3xl font-bold leading-relaxed">Bem-vindo à aula!</p>
                      <p className="text-indigo-200 text-base leading-relaxed">Para uma experiência imersiva, encontre um ambiente tranquilo e coloque-se em uma posição confortável.</p>
                      <button onClick={togglePlay} className="px-8 py-4 bg-emerald-500 text-white rounded-full text-lg font-bold shadow-lg hover:bg-emerald-600 transition-all active:scale-95 flex items-center justify-center gap-3 mx-auto"><Play size={24} fill="currentColor" /> Entendi! Começar Aula</button>
                    </div>
                  </div>
                ) : (
                  <div ref={playerContainerRef} className="aspect-video bg-gray-900 rounded-3xl overflow-hidden shadow-2xl border-4 border-gray-700 relative group">
                    <iframe ref={iframeRef} width="100%" height="100%" title="Video Player" frameBorder="0" allow="accelerometer; autoplay; encrypted-media; gyroscope; picture-in-picture" allowFullScreen src={iframeSrc}></iframe>
                    {isStudentSimulationMode && <div className="absolute inset-0 z-10 pointer-events-auto bg-transparent" onClick={() => !isPlaying && togglePlay()}>{!isPlaying && <div className="absolute inset-0 flex items-center justify-center bg-black/60 cursor-pointer"><div className="w-20 h-20 bg-white/20 backdrop-blur-xl border border-white/30 rounded-full flex items-center justify-center text-white transition-all shadow-2xl hover:scale-110 active:scale-95"><Play size={40} fill="currentColor" /></div></div>}</div>}
                    {!showWelcomeModal && (
                      <div className="absolute inset-0 z-30 pointer-events-none flex flex-col justify-end">
                        <div className="p-4 bg-gradient-to-t from-black/80 to-transparent opacity-0 group-hover:opacity-100 transition-opacity pointer-events-auto">
                          <div className="flex items-center justify-between gap-6 px-4">
                            <div className="flex items-center gap-4">
                              <button onClick={togglePlay} className="text-white hover:text-indigo-400 transition-colors">{isPlaying ? <Pause size={24} fill="currentColor" /> : <Play size={24} fill="currentColor" />}</button>
                              <div className="flex items-center gap-3 group/vol">
                                <button onClick={toggleMute} className="text-white hover:text-indigo-400 transition-colors">{(isMuted || playerVolume === 0) ? <VolumeX size={20} /> : <Volume2 size={20} />}</button>
                                <input type="range" min="0" max="100" value={isMuted ? 0 : playerVolume} onChange={handleVolumeChange} className="w-20 h-1.5 bg-white/20 rounded-full appearance-none cursor-pointer accent-indigo-500 hover:accent-indigo-400 transition-all" />
                              </div>
                            </div>
                            <button onClick={toggleFullscreen} className="text-white hover:text-indigo-400 transition-colors"><Maximize size={20} /></button>
                          </div>
                        </div>
                      </div>
                    )}
                  </div>
                )}
                <div className="p-8 bg-gray-800 rounded-3xl shadow-lg border border-gray-700">
                  <p className="font-serif text-gray-300 text-lg leading-relaxed tracking-wide whitespace-pre-wrap">
                    {previewLesson.descricao || "Aguardando cadastro de conteúdo para esta aula."}
                  </p>
                </div>
              </div>
              <div className="lg:col-span-1 space-y-6">
                <div className="bg-gray-800 p-6 rounded-3xl shadow-lg border border-gray-700 h-[calc(100vh-14rem)] overflow-y-auto">
                  <h3 className="text-lg font-bold text-indigo-400 uppercase tracking-widest mb-6">Conteúdo Programático</h3>
                  {modules.map(mod => (
                    <div key={mod.id} className="mb-6 last:mb-0">
                      <h4 className="font-bold text-lg text-white mb-3 flex items-center gap-2"><Layers size={18} className="text-indigo-400" /> Módulo {mod.ordem}: {mod.nome}</h4>
                      <div className="space-y-2">
                        {lessonsByModule[mod.id]?.map(lesson => {
                          const isCurrent = previewLesson?.id === lesson.id;
                          const isLessonGloballyConcluded = completedLessonIds.has(lesson.id) || !isStudentSimulationMode;
                          return (
                            <div key={lesson.id} className="group/lesson-item">
                              <button onClick={() => openPreview(lesson, mod.id, isStudentSimulationMode)} className={`flex items-center justify-between w-full p-3 rounded-xl transition-all ${isCurrent ? 'bg-indigo-600 text-white shadow-md' : 'bg-gray-700 text-gray-300 hover:bg-gray-600'}`}>
                                <span className="flex items-center gap-3 text-sm font-medium">{isCurrent ? <Play size={16} fill="currentColor" /> : (isLessonGloballyConcluded ? <CheckCircle size={16} className="text-emerald-400" /> : <Lock size={16} className="text-gray-500" />)}{lesson.titulo}</span>
                                {!isCurrent && <ChevronRight size={16} className="text-gray-400" />}
                              </button>

                              {/* SIDEBAR PLAYLIST: MATERIAL DOWNLOAD LINK (EXIBIÇÃO DINÂMICA) */}
                              {lesson.materialUrl && (isLessonGloballyConcluded || !isStudentSimulationMode) && (
                                <a 
                                  href={lesson.materialUrl} 
                                  target="_blank" 
                                  rel="noopener noreferrer"
                                  className="flex items-center gap-2 mt-1.5 ml-8 text-[10px] font-bold text-indigo-400 hover:text-indigo-300 hover:underline transition-all"
                                >
                                  <FileDown size={12} />
                                  Baixar Material de Apoio
                                </a>
                              )}
                            </div>
                          );
                        })}
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            </div>
          </div>
        </div>
      );
    }

    if (activeSub === 'avaliacao') {
      return (
        <div className="space-y-6 animate-in fade-in duration-500">
          <header className="flex flex-col sm:flex-row items-center justify-between gap-4">
            <div><h1 className="text-2xl font-bold text-slate-900 tracking-tight">Gestão de Avaliações</h1><p className="text-slate-500 text-sm">Criação de provas e testes de proficiência.</p></div>
            <button onClick={() => { setIsEditingExam(false); setIsExamModalOpen(true); }} className="flex items-center gap-2 bg-indigo-600 text-white px-5 py-3 rounded-xl text-sm font-bold shadow-lg"><PlusCircle size={18} /> Nova Avaliação</button>
          </header>
          {exams.length === 0 ? (<div className="bg-white p-24 rounded-3xl border border-dashed border-slate-200 text-center flex flex-col items-center justify-center animate-in zoom-in-95"><div className="w-20 h-20 bg-slate-50 rounded-full flex items-center justify-center mb-6 text-slate-300"><ClipboardCheck size={40} /></div><h3 className="font-bold text-slate-900 text-lg">Nenhuma prova cadastrada</h3></div>) : (
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              {exams.map((exam) => (
                <div key={exam.id} className="group bg-slate-900 rounded-3xl border border-slate-800 p-6 shadow-xl hover:border-indigo-500/40 transition-all relative"><div className="flex justify-between items-start mb-4"><div className="p-3 bg-slate-800 rounded-2xl text-indigo-400"><ListChecks size={24} /></div><div className="flex gap-1 opacity-0 group-hover:opacity-100 transition-opacity"><button onClick={() => handleEditExam(exam)} className="p-2 text-slate-400 hover:text-white hover:bg-slate-700 rounded-lg"><Edit size={16} /></button><button onClick={() => handleDeleteExam(exam.id)} className="p-2 text-red-400 hover:text-white hover:bg-red-500 rounded-lg"><Trash2 size={16} /></button></div></div><h3 className="text-white font-bold text-lg mb-1 leading-tight">{exam.title}</h3><p className="text-indigo-400 text-[10px] font-black uppercase tracking-widest mb-4">{exam.courseName}</p><div className="flex items-center justify-between pt-4 border-t border-slate-800"><div className="flex items-center gap-2 text-slate-500 text-xs font-bold uppercase tracking-tighter"><ClipboardCheck size={14} /><span>{exam.questions.length} Questões</span></div><span className="text-[10px] font-black text-indigo-500 uppercase tracking-widest">Média {exam.passingGrade.toFixed(1)}</span></div></div>
              ))}
            </div>
          )}
        </div>
      );
    }

    if (activeSub === 'materiais') {
      const isCritical = storagePercentage > 90;
      const isWarning = storagePercentage > 70;
      return (
        <div className="space-y-6 animate-in fade-in duration-500">
          <div className="bg-white p-6 rounded-3xl border border-slate-200 shadow-sm space-y-4">
            <div className="flex items-center justify-between"><div className="flex items-center gap-3 text-slate-900"><Database size={20} className="text-indigo-600" /><h2 className="font-bold">Quota de Armazenamento</h2></div><span className={`text-xs font-black uppercase tracking-widest ${isCritical ? 'text-red-600' : isWarning ? 'text-amber-600' : 'text-slate-500'}`}>{formatFileSize(currentUsedStorage)} / 5 GB Utilizados</span></div>
            <div className="h-3 w-full bg-slate-100 rounded-full overflow-hidden border border-slate-50 shadow-inner"><div className={`h-full transition-all duration-1000 ${isCritical ? 'bg-red-500' : isWarning ? 'bg-amber-500' : 'bg-emerald-500'}`} style={{ width: `${Math.min(storagePercentage, 100)}%` }} /></div>
          </div>
          <header className="flex flex-col sm:flex-row items-center justify-between gap-4"><div><h1 className="text-2xl font-bold text-slate-900 tracking-tight">Biblioteca de Materiais</h1><p className="text-slate-500 text-sm">Gerenciamento centralizado de mídia pedagógica.</p></div><button disabled={isCritical} onClick={() => materialInputRef.current?.click()} className={`flex items-center gap-2 px-5 py-3 rounded-xl text-sm font-bold shadow-lg ${isCritical ? 'bg-slate-200 text-slate-400 cursor-not-allowed' : 'bg-slate-900 text-white hover:bg-slate-800 active:scale-95'}`}><CloudUpload size={18} /> Upload de Arquivo</button>            <input type="file" ref={materialInputRef} className="hidden" multiple onChange={handleMaterialUpload} accept=".pdf,.docx,.xlsx,.pptx,.jpg,.jpeg,.png" />
          </header>
          {materials.length === 0 ? (<div className="bg-white p-24 rounded-3xl border border-dashed border-slate-200 text-center flex flex-col items-center justify-center animate-in zoom-in-95"><div className="w-20 h-20 bg-slate-50 rounded-full flex items-center justify-center mb-6 text-slate-300"><CloudUpload size={40} /></div><h3 className="font-bold text-slate-900 text-lg">Biblioteca Vazia</h3></div>) : (
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
              {materials.map((file) => (
                <div key={file.id} className="group relative bg-slate-900 rounded-3xl border border-slate-800 p-5 shadow-xl hover:border-indigo-500/40 transition-all hover:shadow-indigo-500/10 animate-in fade-in slide-in-from-bottom-4 duration-300"><div className="flex flex-col h-full"><div className="flex justify-between items-start mb-6"><div className="p-3 bg-slate-800 rounded-2xl group-hover:scale-110 transition-transform shadow-lg">{getFileIcon(file.type)}</div><div className="flex gap-1 opacity-0 group-hover:opacity-100 transition-opacity"><a href={file.url} download={file.name} className="p-2 bg-slate-800 text-slate-300 hover:text-white rounded-lg border border-slate-700"><Download size={14} /></a><button onClick={() => handleDeleteMaterial(file.id)} className="p-2 bg-red-500/10 text-red-400 hover:bg-red-500 rounded-lg border border-red-500/20"><Trash2 size={14} /></button></div></div><div className="flex-1 min-w-0"><h3 className="text-white font-bold text-sm truncate leading-tight mb-1">{file.name}</h3><div className="flex items-center gap-3"><span className="text-[10px] font-black uppercase text-slate-500 tracking-wider bg-slate-800 px-1.5 py-0.5 rounded">{file.type}</span><span className="w-1 h-1 bg-slate-700 rounded-full" /><span className="text-[10px] font-bold text-slate-500">{file.size}</span></div></div></div></div>
              ))}
            </div>
          )}
        </div>
      );
    }

    if (activeSub === 'modulos') {
      const allModules = Object.values(allModulesGrouped).flatMap((group: { course: Course; modules: Module[] }) => group.modules.map(m => ({ ...m, courseName: group.course.nome }))).sort((a, b) => a.ordem - b.ordem);
      return (
        <div className="space-y-6 animate-in fade-in duration-500">
          <header className="flex flex-col sm:flex-row items-center justify-between gap-4"><div><h1 className="text-2xl font-bold text-slate-900 tracking-tight">Biblioteca de Módulos</h1><p className="text-slate-500 text-sm">Matriz integrada de cursos.</p></div><button onClick={handleOpenCreateModule} className="flex items-center gap-2 bg-indigo-600 text-white px-5 py-3 rounded-xl text-sm font-bold shadow-lg"><Plus size={18} /> Novo Módulo</button></header>
          {loading ? (<div className="flex items-center justify-center p-20"><div className="h-10 w-10 animate-spin rounded-full border-4 border-indigo-600 border-t-transparent"></div></div>) : (
            <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6">
              {allModules.map((mod: any) => (<div key={mod.id} className="group bg-slate-900 rounded-3xl border border-slate-800 p-6 shadow-xl hover:border-indigo-500/50 transition-all"><div className="flex flex-col h-full"><div className="flex justify-between items-start mb-4"><div className="px-3 py-1 bg-indigo-500/10 border border-indigo-500/20 text-indigo-400 text-[9px] font-black uppercase tracking-widest rounded-full">{mod.courseName}</div><div className="flex gap-1 opacity-0 group-hover:opacity-100"><button onClick={() => handleEditModule(mod)} className="p-2 bg-slate-800 text-slate-300 rounded-lg border border-slate-700"><Edit size={14} /></button><button onClick={() => handleDeleteModule(mod.courseId, mod.id)} className="p-2 bg-red-500/10 text-red-400 rounded-lg border border-red-500/20"><Trash2 size={14} /></button></div></div><h3 className="text-white font-bold text-lg mb-2">{mod.ordem.toString().padStart(2, '0')}. {mod.nome}</h3></div></div>))}
            </div>
          )}
        </div>
      );
    }

    if (activeSub === 'cursos' && selectedCourse) {
      return (
        <div className="space-y-6 animate-in fade-in duration-500">
          <header className="flex items-center justify-between gap-4"><div className="flex items-center gap-4"><button onClick={() => setSelectedCourse(null)} className="h-10 w-10 bg-white border border-slate-200 hover:bg-slate-50 rounded-xl text-slate-600 shadow-sm flex items-center justify-center"><ArrowLeft size={20} /></button><div><h1 className="text-2xl font-bold text-slate-900 leading-tight">{selectedCourse.nome}</h1><div className="flex items-center gap-3 mt-1"><span className="text-slate-500 text-sm">{selectedCourse.tema}</span>{selectedCourse.geraCertificado && <span className="flex items-center gap-1 bg-emerald-100 text-emerald-700 text-[9px] font-black uppercase px-2 py-0.5 rounded-md"><CheckCircle size={10} /> Emite Certificado</span>}</div></div></div><button onClick={handleOpenCreateModule} className="flex items-center gap-2 bg-indigo-600 text-white px-5 py-2.5 rounded-xl text-sm font-bold shadow-lg"><Plus size={18} /> Novo Módulo</button></header>
          <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
            <div className="lg:col-span-2 space-y-4"><div className="bg-white rounded-2xl border border-slate-200 shadow-sm overflow-hidden"><div className="px-6 py-4 border-b border-slate-100 bg-slate-50/50"><h2 className="text-xs font-bold text-slate-800 uppercase tracking-widest">Matriz Curricular</h2></div><div className="p-4 space-y-4">{modules.map((mod) => (<div key={mod.id} className="border border-slate-100 rounded-xl group bg-slate-50/20"><div className="px-4 py-3 border-b border-slate-100 flex items-center justify-between bg-white"><h3 className="font-bold text-slate-800 text-sm">Módulo {mod.ordem}: {mod.nome}</h3><div className="flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity"><button onClick={() => { setActiveModuleId(mod.id); setIsEditingLesson(false); setEditingLessonId(null); setLessonForm({titulo:'', descricao:'', videoUrl:'', materialUrl:''}); setShowLessonModal(true); }} className="p-1.5 text-indigo-600 hover:bg-indigo-50 rounded-lg"><Plus size={18} /></button><button onClick={() => handleEditModule(mod)} className="p-1.5 text-slate-400 hover:bg-slate-50 rounded-lg"><Edit size={18} /></button><button onClick={() => handleDeleteModule(selectedCourse.id, mod.id)} className="p-1.5 text-red-400 hover:bg-red-50 rounded-lg"><Trash2 size={18} /></button></div></div><div className="p-2 space-y-1">{lessonsByModule[mod.id]?.map((lesson) => (<div key={lesson.id} className="flex items-center justify-between p-3 rounded-xl hover:bg-white hover:shadow-sm group/lesson transition-all"><div className="flex items-center gap-4"><div className="p-2 bg-white border rounded-lg text-indigo-600"><Play size={12} fill="currentColor" /></div><span className="text-sm font-semibold text-slate-700">{lesson.titulo}</span></div><div className="flex items-center gap-1 opacity-0 group-hover/lesson:opacity-100"><button onClick={() => openPreview(lesson, mod.id, false)} className="p-1.5 text-indigo-600 hover:bg-indigo-50 rounded-lg"><Eye size={16} /></button><button onClick={() => handleEditLesson(lesson, mod.id)} className="p-1.5 text-slate-400 rounded-lg"><Edit size={16} /></button><button onClick={() => handleDeleteLesson(mod.id, lesson.id)} className="p-1.5 text-red-400 rounded-lg"><Trash2 size={16} /></button></div></div>))}</div></div>))}</div></div></div>
            <div className="bg-white p-5 rounded-2xl border border-slate-200 shadow-sm sticky top-24 h-fit"><img src={selectedCourse.capaUrl || 'https://images.unsplash.com/photo-1504052434139-443c40c98408?w=800'} className="w-full h-40 object-cover rounded-xl mb-4" /><div className="space-y-3"><div className="flex justify-between border-b pb-2"><span className="text-[10px] text-slate-400 font-black uppercase">Professor</span><span className="text-xs font-bold">{selectedCourse.professorResponsavel}</span></div></div></div>
          </div>
        </div>
      );
    }

    return (
      <div className="space-y-6 animate-in fade-in duration-500"><header className="flex flex-col sm:flex-row items-center justify-between gap-4"><div><h1 className="text-2xl font-bold text-slate-900 tracking-tight">Portal do Professor</h1><p className="text-slate-500 text-sm">Gestão educacional de cursos EAD.</p></div><button onClick={() => { setIsEditingCourse(false); setEditingCourseId(null); setCourseForm({ nome: '', tema: '', professorResponsavel: user.displayName || '', descricaoLonga: '', capaUrl: '', cargaHoraria: '', publicoAlvo: 'Geral', geraCertificado: false }); setShowCourseModal(true); }} className="flex items-center gap-2 bg-indigo-600 text-white px-5 py-3 rounded-xl text-sm font-bold shadow-lg"><Plus size={18} /> Novo Curso</button></header><div className="grid grid-cols-1 md:grid-cols-3 xl:grid-cols-6 gap-4">{loading ? (<div className="col-span-full py-20 flex justify-center"><div className="h-6 w-6 animate-spin rounded-full border-2 border-indigo-600 border-t-transparent"></div></div>) : myCourses.map(course => (<div key={course.id} onClick={() => openCourseDetail(course)} className="bg-white border border-slate-200 rounded-2xl overflow-hidden hover:shadow-xl hover:border-indigo-200 group cursor-pointer flex flex-col relative"><div className="absolute top-2 right-2 z-50"><button onClick={(e) => { e.stopPropagation(); setOpenMenuId(openMenuId === course.id ? null : course.id); }} className="p-1.5 bg-white/90 backdrop-blur-sm rounded-lg border border-slate-200 text-slate-500 shadow-sm"><MoreVertical size={14} /></button>{openMenuId === course.id && (<div className="absolute right-0 mt-1 w-32 bg-white rounded-xl shadow-2xl border border-slate-100 z-50 overflow-hidden text-[10px] font-bold"><button onClick={(e) => { e.stopPropagation(); handleEditCourseInfo(course); }} className="w-full px-3 py-2 text-left hover:bg-slate-50 flex items-center gap-2"><Edit size={12} /> Editar</button><button onClick={(e) => { e.stopPropagation(); handleDuplicateCourse(course); }} className="w-full px-3 py-2 text-left hover:bg-slate-50 flex items-center gap-2"><Copy size={12} /> Copiar</button><button onClick={(e) => { e.stopPropagation(); handleDeleteCourse(course.id); }} className="w-full px-3 py-2 text-left hover:bg-red-50 text-red-500 flex items-center gap-2"><Trash2 size={12} /> Apagar</button></div>)}</div><div className="h-24 overflow-hidden bg-slate-100 relative">{course.capaUrl ? <img src={course.capaUrl} className="w-full h-full object-cover group-hover:scale-105 transition-transform" /> : <div className="h-full flex items-center justify-center text-slate-200"><BookOpen size={32} /></div>}</div><div className="p-3 flex-1 flex flex-col"><h3 className="font-bold text-slate-900 text-xs mb-1 group-hover:text-indigo-600 transition-colors leading-tight line-clamp-2">{course.nome}</h3></div></div>))}</div></div>
    );
