              </div>
              <button onClick={handleCloseCourseModal} className="text-slate-300 hover:text-slate-600 p-2 transition-colors"><X size={24} /></button>
            </div>
            <form onSubmit={handleSaveCourse} className="p-10 space-y-8 overflow-y-auto">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-10">
                <div className="space-y-6">
                  <div className="space-y-1"><label className="text-[10px] font-black text-slate-400 uppercase ml-1">Título do Curso</label><input required value={courseForm.nome} onChange={e => setCourseForm({...courseForm, nome: e.target.value})} className="w-full px-5 py-4 bg-slate-50 border border-slate-200 rounded-2xl text-sm" /></div>
                  <div className="space-y-1"><label className="text-[10px] font-black text-slate-400 uppercase ml-1">Docente Responsável</label><input required value={courseForm.professorResponsavel} onChange={e => setCourseForm({...courseForm, professorResponsavel: e.target.value})} className="w-full px-5 py-4 bg-slate-50 border border-slate-200 rounded-2xl text-sm" /></div>
                </div>

                {/* INTEGRAÇÃO BIBLIOTECA: CAPA DO CURSO */}
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-slate-400 uppercase ml-1">Capa do Curso</label>
                  <div className="relative group/capa h-44 w-full bg-slate-50 border-2 border-dashed border-slate-200 rounded-3xl flex flex-col items-center justify-center overflow-hidden transition-all hover:border-indigo-400">
                    {courseForm.capaUrl ? (
                      <>
                        <img src={courseForm.capaUrl} className="w-full h-full object-cover transition-transform group-hover/capa:scale-110" />
                        <div className="absolute inset-0 bg-black/40 opacity-0 group-hover/capa:opacity-100 flex items-center justify-center gap-3 transition-opacity">
                           <button type="button" onClick={() => handleOpenMaterialPicker('image', (url) => setCourseForm(prev => ({...prev, capaUrl: url})))} className="p-3 bg-white text-indigo-600 rounded-xl shadow-xl hover:scale-110 transition-transform"><Library size={20} /></button>
                           <button type="button" onClick={() => setCourseForm(prev => ({...prev, capaUrl: ''}))} className="p-3 bg-white text-red-600 rounded-xl shadow-xl hover:scale-110 transition-transform"><X size={20} /></button>
                        </div>
                      </>
                    ) : (
                      <div className="flex flex-col items-center space-y-4">
                        <FileUp size={32} className="text-slate-300" />
                        <div className="flex gap-2">
                          <button type="button" onClick={() => handleOpenMaterialPicker('image', (url) => setCourseForm(prev => ({...prev, capaUrl: url})))} className="px-4 py-2 bg-indigo-600 text-white text-[10px] font-black uppercase rounded-xl shadow-lg">Biblioteca</button>
                          <label className="px-4 py-2 bg-slate-900 text-white text-[10px] font-black uppercase rounded-xl shadow-lg cursor-pointer">Upload<input type="file" className="hidden" onChange={handleFileUpload} accept="image/*" /></label>
                        </div>
                      </div>
                    )}
                  </div>
                  {courseForm.capaUrl && <p className="text-[9px] text-indigo-500 font-bold uppercase tracking-tighter text-center">Imagem de capa vinculada com sucesso</p>}
                </div>
              </div>
              <div className="flex gap-4 pt-6">
                <button type="button" onClick={handleCloseCourseModal} className="flex-1 py-5 border border-slate-200 text-slate-500 rounded-[1.5rem] font-bold text-sm hover:bg-slate-50">Descartar</button>
                <button type="submit" disabled={loading} className="flex-[2] bg-slate-900 text-white py-5 rounded-[1.5rem] font-black text-xs uppercase tracking-[0.2em] shadow-2xl shadow-slate-300 hover:bg-slate-800 transition-all active:scale-95">{loading ? 'Processando...' : (isEditingCourse ? 'Salvar Alterações' : 'Criar Curso EAD')}</button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

