                  <div className="flex justify-between items-start mb-4">
                    <div className={`p-3 rounded-2xl ${exam.type === 'evaluation' ? 'bg-orange-500/10 text-orange-400' : 'bg-blue-500/10 text-blue-400'}`}>
                      {exam.type === 'evaluation' ? <Star size={24} /> : <PencilLine size={24} />}
                    </div>
                    <div className="flex gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                      <button onClick={() => handleEditExam(exam)} className="p-2 text-slate-400 hover:text-white hover:bg-slate-700 rounded-lg"><Edit size={16} /></button>
