                  <p className="text-slate-500 text-sm">Faça upload de materiais deste tipo na aba "Materiais".</p>
                </div>
              </div>
            ) : (
              <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-6">
                {filteredMaterials.map((file) => (
                  <div 
                    key={file.id} 
                    onClick={() => handleSelectMaterialFromPicker(file)}
                    className="group bg-slate-800/40 rounded-3xl border border-slate-700/50 p-4 hover:border-indigo-500 hover:bg-slate-800 transition-all cursor-pointer relative overflow-hidden"
