                        </div>
                      </div>
                    ) : (
                      <div ref={playerContainerRef} className="aspect-video bg-gray-900 rounded-3xl overflow-hidden shadow-2xl border-4 border-gray-700 relative group">
                        <iframe ref={iframeRef} width="100%" height="100%" title="Video Player" frameBorder="0" allow="accelerometer; autoplay; encrypted-media; gyroscope; picture-in-picture" allowFullScreen src={iframeSrc}></iframe>
                        {isStudentSimulationMode && <div className="absolute inset-0 z-10 pointer-events-auto bg-transparent" onClick={() => !isPlaying && togglePlay()}>{!isPlaying && <div className="absolute inset-0 flex items-center justify-center bg-black/60 cursor-pointer"><div className="w-20 h-20 bg-white/20 backdrop-blur-xl border border-white/30 rounded-full flex items-center justify-center text-white transition-all shadow-2xl hover:scale-110 active:scale-95"><Play size={40} fill="currentColor" /></div></div>}</div>}
