urse); }} className="w-full px-3 py-2 text-left hover:bg-slate-50 flex items-center gap-2"><Copy size={12} /> Copiar</button><button onClick={(e) => { e.stopPropagation(); handleDeleteCourse(course.id); }} className="w-full px-3 py-2 text-left hover:bg-red-50 text-red-500 flex items-center gap-2"><Trash2 size={12} /> Apagar</button></div>)}</div><div className="h-24 overflow-hidden bg-slate-100 relative">{course.capaUrl ? <img src={course.capaUrl} className="w-full h-full object-cover group-hover:scale-105 transition-transform" /> : <div className="h-full flex items-center justify-center text-slate-200"><BookOpen size={32} /></div>}</div><div className="p-3 flex-1 flex flex-col"><h3 className="font-bold text-slate-900 text-xs mb-1 group-hover:text-indigo-600 transition-colors leading-tight line-clamp-2">{course.nome}</h3></div></div>))}</div></div>
