                </div>
              </div>
              <button onClick={() => { setPreviewLesson(null); setPreviewExam(null); setShowCertificateScreen(false); }} className="px-4 py-2 bg-gray-800 hover:bg-gray-700 rounded-xl text-gray-300 text-xs font-bold transition-colors">Fechar Visualização</button>
            </header>

            <div className="flex-1 grid grid-cols-1 lg:grid-cols-4 gap-6">
