                      <div className="flex flex-col items-center space-y-4"><FileUp size={32} className="text-slate-300" /><div className="flex gap-2"><button type="button" onClick={() => handleOpenMaterialPicker('image', (url) => setCourseForm(prev => ({...prev, capaUrl: url})))} className="px-4 py-2 bg-indigo-600 text-white rounded-xl">Biblioteca</button><label className="px-4 py-2 bg-slate-900 text-white rounded-xl cursor-pointer">Upload<input type="file" className="hidden" onChange={handleFileUpload} accept="image/*" /></label></div></div>
                    )}
                  </div>
                </div>
              </div>
              <div className="flex gap-4 pt-6"><button type="button" onClick={handleCloseCourseModal} className="flex-1 py-5 border rounded-[1.5rem] font-bold">Descartar</button><button type="submit" disabled={loading} className="flex-[2] bg-slate-900 text-white py-5 rounded-[1.5rem] font-black uppercase shadow-2xl">{loading ? 'Processando...' : 'Salvar Alterações'}</button></div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default ProfessorView;

