                    <p className="text-slate-400 text-sm italic leading-relaxed">"Lembre-se: O verdadeiro conhecimento é construído na verdade. Deus vê todas as coisas, inclusive este momento. Esta avaliação é um teste de sua honestidade. Confie no Senhor e no que aprendeu."</p>
                  </div>
                  <button onClick={handleStartExamAfterPact} className="w-full py-5 bg-indigo-600 text-white font-black uppercase tracking-[0.2em] text-xs rounded-2xl">Estou em paz e pronto para iniciar</button>
                  <button onClick={() => { setShowIntegrityModal(false); setPendingExam(null); }} className="text-slate-500 text-[10px] font-bold uppercase">Preciso de mais tempo</button>
               </div>
            </div>
          )}
        </div>
      );
    }

    if (activeSub === 'feedback') {
      const avgRating = feedbacks.reduce((acc, f) => acc + f.rating, 0) / feedbacks.length;
      return (
        <div className="space-y-8 animate-in fade-in duration-500">
          <header><h1 className="text-2xl font-bold text-slate-900 tracking-tight">Dashboard de Reputação</h1></header>
          <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
            <div className="bg-slate-900 p-8 rounded-[2rem] border border-slate-800 flex flex-col justify-center items-center text-center space-y-4">
              <Star size={40} fill="#fbbf24" className="text-amber-400" />
              <h3 className="text-4xl font-black text-white">{avgRating.toFixed(1)}</h3>
              <p className="text-slate-400 text-xs font-bold uppercase tracking-widest mt-1">Nota Geral</p>
            </div>
            <div className="lg:col-span-2 bg-slate-900 p-8 rounded-[2rem] border border-slate-800 space-y-6">
              <h3 className="text-sm font-black text-indigo-400 uppercase tracking-widest">Radar Pedagógico</h3>
              {[
                { label: '🗣️ Didática', val: 4.8, color: 'bg-indigo-500' },
                { label: '🆘 Suporte', val: 4.2, color: 'bg-emerald-500' },
                { label: '📚 Materiais', val: 4.9, color: 'bg-amber-500' }
              ].map((item, i) => (
                <div key={i} className="space-y-2">
                  <div className="flex justify-between text-[10px] font-black uppercase text-slate-400"><span>{item.label}</span><span>{item.val.toFixed(1)}</span></div>
                  <div className="h-2 w-full bg-slate-800 rounded-full overflow-hidden"><div className={`h-full ${item.color}`} style={{ width: `${(item.val / 5) * 100}%` }} /></div>
                </div>
              ))}
            </div>
          </div>
        </div>
      );
    }

    if (activeSub === 'avaliacao') {
      return (
        <div className="space-y-6 animate-in fade-in duration-500">
          <header className="flex items-center justify-between">
            <h1 className="text-2xl font-bold text-slate-900 tracking-tight">Avaliações e Testes</h1>
            <button onClick={() => { setIsEditingExam(false); setExamForm({ title: '', courseId: '', passingGrade: 7.0, questions: [{ id: '1', text: '', options: ['', '', '', ''], correctOptionIndex: 0 }], type: 'activity' }); setIsExamModalOpen(true); }} className="flex items-center gap-2 bg-indigo-600 text-white px-5 py-3 rounded-xl text-sm font-bold shadow-lg"><PlusCircle size={18} /> Nova Avaliação</button>
          </header>
          {loadingExams ? (<div className="p-20 text-center text-slate-400">Carregando provas do Firestore...</div>) : exams.length === 0 ? (<div className="p-20 text-center border-2 border-dashed rounded-3xl text-slate-400">Nenhuma avaliação cadastrada.</div>) : (
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              {exams.map((exam) => (
                <div key={exam.id} className="bg-slate-900 rounded-3xl p-6 border border-slate-800 group relative flex flex-col h-full hover:border-indigo-500/50 transition-all">
                   <div className="flex justify-between mb-4">
                     <div className={`p-3 rounded-2xl ${exam.type === 'evaluation' ? 'bg-orange-500/10 text-orange-400' : 'bg-blue-500/10 text-blue-400'}`}>{exam.type === 'evaluation' ? <Star size={24} /> : <PencilLine size={24} />}</div>
                     <div className="flex gap-1 opacity-0 group-hover:opacity-100 transition-opacity"><button onClick={() => handleEditExam(exam)} className="p-2 text-slate-400 hover:text-white"><Edit size={16} /></button><button onClick={() => handleDeleteExam(exam.id)} className="p-2 text-red-400 hover:text-white"><Trash2 size={16} /></button></div>
                   </div>
                   <h3 className="text-white font-bold text-lg mb-1 leading-tight">{exam.title}</h3>
                   <div className="mt-auto pt-4 flex items-center justify-between border-t border-slate-800/50">
                      <p className="text-indigo-400 text-[10px] font-black uppercase tracking-widest">{exam.courseName}</p>
                      <span className="text-slate-600 text-[9px] font-bold">{exam.questions.length} Q.</span>
                   </div>
                </div>
              ))}
            </div>
          )}
        </div>
      );
    }

    if (activeSub === 'materiais') {
      return (
        <div className="space-y-6 animate-in fade-in duration-500">
           <header className="flex items-center justify-between">
            <h1 className="text-2xl font-bold text-slate-900 tracking-tight">Biblioteca de Materiais</h1>
            <button onClick={handleOpenDrivePicker} className="flex items-center gap-2 bg-slate-900 text-white px-5 py-3 rounded-xl text-sm font-bold shadow-lg hover:bg-slate-800 transition-all active:scale-95">
              <Database size={18} className="text-indigo-400" /> Importar do Google Drive
            </button>
          </header>
          {loadingMaterials ? (<div className="p-20 text-center text-slate-400">Consultando biblioteca...</div>) : materials.length === 0 ? (<div className="p-20 text-center border-2 border-dashed rounded-3xl text-slate-400">A biblioteca está vazia no banco de dados.</div>) : (
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
              {materials.map((file) => (
                <div key={file.id} className="bg-slate-900 rounded-3xl p-5 border border-slate-800 group relative flex flex-col h-full hover:border-indigo-500/50 transition-all">
                   <div className="flex justify-between mb-6">
                     <div className="p-3 bg-slate-800 rounded-2xl">
                        {file.iconUrl ? (
                          <img src={file.iconUrl} className="w-8 h-8 object-contain" alt="icon" />
                        ) : getFileIcon(file.type)}
                     </div>
                     <div className="flex gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                       <a href={file.url} target="_blank" rel="noopener noreferrer" className="p-2 text-indigo-400 hover:bg-indigo-500/10 rounded-lg"><ExternalLink size={14} /></a>
                       <button onClick={() => handleDeleteMaterial(file.id)} className="p-2 text-red-400 hover:bg-red-500/10 rounded-lg"><Trash2 size={14} /></button>
                     </div>
                   </div>
                   <h3 className="text-white font-bold text-sm truncate" title={file.name}>{file.name}</h3>
                   <div className="mt-auto pt-4 flex items-center justify-between border-t border-slate-800/50">
                      <span className="text-slate-500 text-[10px] font-black uppercase tracking-tighter flex items-center gap-1.5">
                        <Share2 size={10} /> {file.source === 'google-drive' ? 'Google Drive' : 'Local'}
                      </span>
                      <span className="text-slate-600 text-[9px] font-bold">{file.type}</span>
                   </div>
                </div>
              ))}
            </div>
          )}
        </div>
      );
    }

    // Fallback: Dashboard do Professor
    return (
      <div className="space-y-6 animate-in fade-in duration-500"><header className="flex flex-col sm:flex-row items-center justify-between gap-4"><div><h1 className="text-2xl font-bold text-slate-900 tracking-tight">Portal do Professor</h1><p className="text-slate-500 text-sm">Gestão educacional de cursos EAD.</p></div><button onClick={() => { setIsEditingCourse(false); setEditingCourseId(null); setCourseForm({ nome: '', tema: '', professorResponsavel: user.displayName || '', descricaoLonga: '', capaUrl: '', cargaHoraria: '', publicoAlvo: 'Geral', geraCertificado: false }); setShowCourseModal(true); }} className="flex items-center gap-2 bg-indigo-600 text-white px-5 py-3 rounded-xl text-sm font-bold shadow-lg"><Plus size={18} /> Novo Curso</button></header><div className="grid grid-cols-1 md:grid-cols-3 xl:grid-cols-6 gap-4">{loading ? (<div className="col-span-full py-20 flex justify-center"><div className="h-6 w-6 animate-spin rounded-full border-2 border-indigo-600 border-t-transparent"></div></div>) : myCourses.map(course => (<div key={course.id} onClick={() => openCourseDetail(course)} className="bg-white border border-slate-200 rounded-2xl overflow-hidden hover:shadow-xl hover:border-indigo-200 group cursor-pointer flex flex-col relative"><div className="absolute top-2 right-2 z-50"><button onClick={(e) => { e.stopPropagation(); setOpenMenuId(openMenuId === course.id ? null : course.id); }} className="p-1.5 bg-white/90 backdrop-blur-sm rounded-lg border border-slate-200 text-slate-500 shadow-sm"><MoreVertical size={14} /></button>{openMenuId === course.id && (<div className="absolute right-0 mt-1 w-32 bg-white rounded-xl shadow-2xl border border-slate-100 z-50 overflow-hidden text-[10px] font-bold"><button onClick={(e) => { e.stopPropagation(); handleEditCourseInfo(course); }} className="w-full px-3 py-2 text-left hover:bg-slate-50 flex items-center gap-2"><Edit size={12} /> Editar</button><button onClick={(e) => { e.stopPropagation(); handleDuplicateCourse(course); }} className="w-full px-3 py-2 text-left hover:bg-slate-50 flex items-center gap-2"><Copy size={12} /> Copiar</button><button onClick={(e) => { e.stopPropagation(); handleDeleteCourse(course.id); }} className="w-full px-3 py-2 text-left hover:bg-red-50 text-red-500 flex items-center gap-2"><Trash2 size={12} /> Apagar</button></div>)}</div><div className="h-24 overflow-hidden bg-slate-100 relative">{course.capaUrl ? <img src={course.capaUrl} className="w-full h-full object-cover group-hover:scale-105 transition-transform" /> : <div className="h-full flex items-center justify-center text-slate-200"><BookOpen size={32} /></div>}</div><div className="p-3 flex-1 flex flex-col"><h3 className="font-bold text-slate-900 text-xs mb-1 group-hover:text-indigo-600 transition-colors leading-tight line-clamp-2">{course.nome}</h3></div></div>))}</div></div>
    );
  };

  return (
    <div className="relative">
      {renderMainContent()}

      {/* MODAL PICKER MATERIAL */}
      {isMaterialPickerOpen && (
        <div className="fixed inset-0 !z-[9999] flex items-center justify-center p-4 bg-slate-950/90 backdrop-blur-md">
          <div className="bg-slate-900 w-full max-w-4xl h-[80vh] rounded-[2.5rem] shadow-2xl border border-slate-800 flex flex-col overflow-hidden">
            <header className="px-8 py-6 border-b border-slate-800 flex items-center justify-between">
              <h2 className="text-xl font-bold text-white">Selecionar da Biblioteca</h2>
              <button onClick={() => setIsMaterialPickerOpen(false)} className="p-2 text-slate-400 hover:text-white"><X size={28} /></button>
            </header>
            <div className="flex-1 overflow-y-auto p-8 grid grid-cols-2 md:grid-cols-4 gap-6">
              {materials.filter(m => pickerMode === 'image' ? ['jpg','jpeg','png','webp'].includes(m.type) : true).map((file) => (
                <div key={file.id} onClick={() => handleSelectMaterialFromPicker(file)} className="bg-slate-800 p-4 rounded-3xl border border-slate-700 hover:border-indigo-500 transition-all cursor-pointer">
                  <div className="aspect-square bg-slate-900 rounded-2xl mb-3 flex items-center justify-center overflow-hidden">
                    {file.iconUrl ? <img src={file.iconUrl} className="w-8 h-8" /> : getFileIcon(file.type)}
                  </div>
                  <h4 className="text-white text-[10px] font-bold truncate">{file.name}</h4>
                </div>
              ))}
            </div>
          </div>
        </div>
      )}

      {/* MODAL CONSTRUTOR DE AVALIAÇÃO */}
      {isExamModalOpen && (
        <div className="fixed inset-0 !z-[9999] flex items-center justify-center p-4 bg-slate-950/80 backdrop-blur-md">
          <div className="bg-slate-900 w-full max-w-4xl max-h-[90vh] rounded-3xl shadow-2xl overflow-hidden flex flex-col border border-slate-800">
            <header className="px-8 py-6 border-b border-slate-800 flex items-center justify-between">
              <h2 className="text-xl font-bold text-white">{isEditingExam ? 'Editar Conteúdo' : 'Novo Recurso Pedagógico'}</h2>
              <button onClick={() => setIsExamModalOpen(false)} className="text-slate-500 hover:text-white"><X size={24} /></button>
            </header>
            <form onSubmit={handleSaveExam} className="flex-1 overflow-y-auto p-8 space-y-10">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4 p-4 bg-slate-800/20 rounded-2xl">
                 <button type="button" onClick={() => setExamForm(prev => ({...prev, type: 'activity'}))} className={`p-4 rounded-xl border ${examForm.type === 'activity' ? 'border-blue-500 bg-blue-500/10 text-blue-400' : 'border-slate-800 text-slate-500'}`}>Atividade (Fixação)</button>
                 <button type="button" onClick={() => setExamForm(prev => ({...prev, type: 'evaluation'}))} className={`p-4 rounded-xl border ${examForm.type === 'evaluation' ? 'border-orange-500 bg-orange-500/10 text-orange-400' : 'border-slate-800 text-slate-500'}`}>Avaliação (Oficial)</button>
              </div>
              <input required value={examForm.title} onChange={e => setExamForm({...examForm, title: e.target.value})} placeholder="Título da Prova" className="w-full px-5 py-4 bg-slate-800 border border-slate-700 rounded-2xl text-white outline-none" />
              <select required value={examForm.courseId} onChange={e => setExamForm({...examForm, courseId: e.target.value})} className="w-full px-5 py-4 bg-slate-800 border border-slate-700 rounded-2xl text-white outline-none">
                <option value="">Vincular ao Curso...</option>
                {myCourses.map(c => <option key={c.id} value={c.id}>{c.nome}</option>)}
              </select>
              {examForm.courseId && (
                <div className="space-y-4">
                  {examForm.type === 'activity' ? (
                    <select required value={examForm.linkedLessonId} onChange={e => setExamForm({...examForm, linkedLessonId: e.target.value})} className="w-full px-5 py-4 bg-slate-800 border border-slate-700 rounded-2xl text-white outline-none">
                       <option value="">Aparecer após qual aula?</option>
                       {Object.values(lessonsByModule).flat().map((l: any) => <option key={l.id} value={l.id}>{l.titulo}</option>)}
                    </select>
                  ) : (
                    <select required value={examForm.linkedModuleId} onChange={e => setExamForm({...examForm, linkedModuleId: e.target.value})} className="w-full px-5 py-4 bg-slate-800 border border-slate-700 rounded-2xl text-white outline-none">
                       <option value="">Aparecer no final de qual módulo?</option>
                       {modules.map(m => <option key={m.id} value={m.id}>{m.nome}</option>)}
                    </select>
                  )}
                </div>
              )}

              {/* Questões */}
              <div className="space-y-6">
                <div className="flex items-center justify-between border-b border-slate-800 pb-4">
                  <h3 className="font-black text-indigo-400 text-xs uppercase tracking-[0.3em]">Questões Disponíveis</h3>
                  <button type="button" onClick={handleAddQuestion} className="flex items-center gap-2 text-indigo-400 hover:text-indigo-300 transition-colors font-bold text-xs uppercase"><Plus size={16} /> Adicionar Pergunta</button>
                </div>
                <div className="space-y-8">
                  {examForm.questions.map((q, qIndex) => (
                    <div key={q.id} className="bg-slate-800/40 p-6 rounded-3xl border border-slate-700/50 relative group/q animate-in slide-in-from-top-4">
                      <button type="button" onClick={() => handleRemoveQuestion(qIndex)} className="absolute -top-2 -right-2 p-2 bg-red-500 text-white rounded-full opacity-0 group-hover/q:opacity-100 transition-opacity"><Trash2 size={14} /></button>
                      <div className="space-y-6">
                        <div className="flex gap-4">
                          <span className="h-10 w-10 bg-indigo-600/20 text-indigo-400 border border-indigo-600/30 rounded-xl flex items-center justify-center font-bold text-sm shrink-0">{qIndex + 1}</span>
                          <input required value={q.text} onChange={e => handleUpdateQuestionText(qIndex, e.target.value)} placeholder="Enunciado da questão..." className="flex-1 bg-transparent border-b border-slate-700 focus:border-indigo-500 outline-none text-white font-medium py-2" />
                        </div>
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4 pl-14">
                          {q.options.map((opt, oIndex) => (
                            <div key={oIndex} className={`flex items-center gap-3 p-3 rounded-2xl border transition-all ${q.correctOptionIndex === oIndex ? 'bg-emerald-500/10 border-emerald-500/50 shadow-lg' : 'bg-slate-900/50 border-slate-700/50'}`}>
                              <button type="button" onClick={() => handleSetCorrectAnswer(qIndex, oIndex)} className={`h-5 w-5 rounded-full border-2 flex items-center justify-center ${q.correctOptionIndex === oIndex ? 'bg-emerald-500 border-emerald-500 text-white' : 'border-slate-600'}`}>{q.correctOptionIndex === oIndex && <CheckCircle size={14} />}</button>
                              <input required value={opt} onChange={e => handleUpdateOption(qIndex, oIndex, e.target.value)} placeholder={`Alternativa ${String.fromCharCode(65 + oIndex)}`} className="bg-transparent text-xs text-white outline-none flex-1 placeholder:text-slate-600" />
                            </div>
                          ))}
                        </div>
                      </div>
                    </div>
                  ))}
                </div>
              </div>

              <div className="flex gap-4">
                 <button type="button" onClick={() => setIsExamModalOpen(false)} className="flex-1 py-4 border border-slate-700 text-slate-500 rounded-2xl font-bold uppercase tracking-widest">Cancelar</button>
                 <button type="submit" disabled={loadingExams} className="flex-[2] py-4 bg-indigo-600 text-white rounded-2xl font-black uppercase tracking-widest shadow-xl">Salvar no Firestore</button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* MODAL MÓDULO */}
      {isModuleModalOpen && (
        <div className="fixed inset-0 !z-[9999] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm animate-in fade-in duration-200">
          <div className="bg-white w-full max-w-md rounded-2xl shadow-2xl p-6 border border-slate-100">
            <h3 className="font-bold text-slate-900 mb-4">{currentEditingModule ? 'Editar Módulo' : 'Novo Módulo'}</h3>
            <form onSubmit={handleSaveModule} className="space-y-5">
              {!selectedCourse && !currentEditingModule && (<select required value={moduleForm.courseId} onChange={e => setModuleForm({...moduleForm, courseId: e.target.value})} className="w-full px-4 py-2.5 bg-slate-50 border rounded-xl text-sm">{myCourses.map(c => <option key={c.id} value={c.id}>{c.nome}</option>)}</select>)}
              <input required value={moduleForm.nome} onChange={e => setModuleForm({...moduleForm, nome: e.target.value})} placeholder="Título" className="w-full px-4 py-2.5 bg-slate-50 border rounded-xl text-sm" />
              <div className="flex gap-3"><button type="button" onClick={() => setIsModuleModalOpen(false)} className="flex-1 px-4 py-2.5 border rounded-xl">Cancelar</button><button type="submit" className="flex-1 bg-indigo-600 text-white py-2.5 rounded-xl font-bold">Salvar</button></div>
            </form>
          </div>
        </div>
      )}

      {/* MODAL AULA */}
      {showLessonModal && (
        <div className="fixed inset-0 !z-[9998] flex items-center justify-center p-4 bg-slate-900/40 backdrop-blur-sm">
          <div className="bg-white w-full max-w-xl rounded-3xl shadow-2xl p-8 border border-slate-100">
            <h3 className="font-bold text-slate-900 text-xl mb-6">{isEditingLesson ? 'Editar Aula' : 'Nova Aula'}</h3>
            <form onSubmit={handleSaveLesson} className="space-y-5">
              <input required value={lessonForm.titulo} onChange={e => setLessonForm({...lessonForm, titulo: e.target.value})} placeholder="Título da Aula" className="w-full px-5 py-3.5 bg-slate-50 border border-slate-200 rounded-2xl text-sm outline-none" />
              <textarea value={lessonForm.descricao} onChange={e => setLessonForm({...lessonForm, descricao: e.target.value})} placeholder="Descrição..." className="w-full px-5 py-3.5 bg-slate-50 border border-slate-200 rounded-2xl text-sm resize-none" rows={4}></textarea>
              <div className="space-y-4">
                <input value={lessonForm.videoUrl} onChange={e => setLessonForm({...lessonForm, videoUrl: e.target.value})} placeholder="URL do Vídeo (YouTube)" className="w-full px-5 py-3.5 bg-slate-50 border border-slate-200 rounded-2xl text-sm outline-none" />
                <div className="flex gap-2">
                  <input value={lessonForm.materialUrl} onChange={e => setLessonForm({...lessonForm, materialUrl: e.target.value})} placeholder="Material do Drive vinculado..." className="flex-1 px-5 py-3.5 bg-slate-50 border border-slate-200 rounded-2xl text-sm outline-none" />
                  <button type="button" onClick={() => handleOpenMaterialPicker('document', (url) => setLessonForm(prev => ({...prev, materialUrl: url})))} className="px-4 bg-indigo-600 text-white rounded-2xl shadow-lg hover:bg-indigo-700 transition-all"><Library size={18} /></button>
                </div>
              </div>
              <div className="flex gap-4 pt-4"><button type="button" onClick={() => setShowLessonModal(false)} className="flex-1 py-4 border border-slate-200 rounded-2xl">Cancelar</button><button type="submit" className="flex-[2] bg-slate-900 text-white py-4 rounded-2xl font-bold">Salvar Aula</button></div>
            </form>
          </div>
        </div>
      )}

      {/* MODAL CURSO */}
      {showCourseModal && (
        <div className="fixed inset-0 !z-[9997] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm">
          <div className="bg-white w-full max-w-3xl rounded-[2.5rem] shadow-2xl overflow-hidden flex flex-col max-h-[90vh]">
            <div className="p-8 border-b border-slate-50 flex items-center justify-between">
              <h3 className="font-bold text-slate-900 text-xl">{isEditingCourse ? 'Editar Parâmetros' : 'Novo Curso Acadêmico'}</h3>
              <button onClick={handleCloseCourseModal} className="text-slate-300 hover:text-slate-600 p-2"><X size={24} /></button>
            </div>
            <form onSubmit={handleSaveCourse} className="p-10 space-y-8 overflow-y-auto">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-10">
                <div className="space-y-6">
                  <input required value={courseForm.nome} onChange={e => setCourseForm({...courseForm, nome: e.target.value})} placeholder="Título" className="w-full px-5 py-4 bg-slate-50 border rounded-2xl text-sm" />
                  <input required value={courseForm.professorResponsavel} onChange={e => setCourseForm({...courseForm, professorResponsavel: e.target.value})} placeholder="Professor" className="w-full px-5 py-4 bg-slate-50 border rounded-2xl text-sm" />
                </div>
                <div className="space-y-2">
                  <div className="relative h-44 w-full bg-slate-50 border-2 border-dashed rounded-3xl flex flex-col items-center justify-center overflow-hidden hover:border-indigo-400 transition-all">
                    {courseForm.capaUrl ? (<><img src={courseForm.capaUrl} className="w-full h-full object-cover" /><div className="absolute inset-0 bg-black/40 opacity-0 hover:opacity-100 flex items-center justify-center gap-3"><button type="button" onClick={() => handleOpenMaterialPicker('image', (url) => setCourseForm(prev => ({...prev, capaUrl: url})))} className="p-3 bg-white text-indigo-600 rounded-xl"><Library size={20} /></button><button type="button" onClick={() => setCourseForm(prev => ({...prev, capaUrl: ''}))} className="p-3 bg-white text-red-600 rounded-xl"><X size={20} /></button></div></>) : (
                      <div className="flex flex-col items-center space-y-4"><FileUp size={32} className="text-slate-300" /><div className="flex gap-2"><button type="button" onClick={() => handleOpenMaterialPicker('image', (url) => setCourseForm(prev => ({...prev, capaUrl: url})))} className="px-4 py-2 bg-indigo-600 text-white rounded-xl">Biblioteca</button><label className="px-4 py-2 bg-slate-900 text-white rounded-xl cursor-pointer">Capa Local<input type="file" className="hidden" onChange={handleFileUpload} accept="image/*" /></label></div></div>
                    )}
                  </div>
                </div>
              </div>
              <div className="flex gap-4 pt-6"><button type="button" onClick={handleCloseCourseModal} className="flex-1 py-5 border rounded-[1.5rem] font-bold">Descartar</button><button type="submit" disabled={loading} className="flex-[2] bg-slate-900 text-white py-5 rounded-[1.5rem] font-black uppercase shadow-2xl">{loading ? 'Processando...' : 'Salvar Alterações'}</button></div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default ProfessorView;

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { 
  collection, 
  query, 
  where, 
  getDocs, 
  addDoc, 
  deleteDoc,
  serverTimestamp, 
  orderBy,
  doc,
  updateDoc,
  onSnapshot,
  setDoc
} from 'firebase/firestore';
import { db } from '../firebase';
import { Course, Module, Lesson, User, ProfessorSubView } from '../types';
import { 
  BookOpen, 
  Plus, 
  X, 
  ChevronRight, 
  Play, 
  Pause, 
  Volume2, 
  VolumeX, 
  Maximize, 
  MoreVertical, 
  ArrowLeft, 
  Layout, 
  Trash2, 
  Layers, 
  Eye, 
  CheckCircle, 
  Copy, 
  Edit, 
  GraduationCap, 
  FileUp, 
  FileDown,
  Lock,
  FileText,
  Award,
  File,
  FileImage,
  FileSpreadsheet,
  CloudUpload,
  Download,
  Database,
  AlertTriangle,
  ClipboardCheck,
  ListChecks,
  PlusCircle,
  Search,
  Library,
  PencilLine,
  Star,
  Quote,
  ShieldAlert,
  MessageSquareHeart,
  User as UserIcon,
  MessageCircle,
  Share2,
  ExternalLink
} from 'lucide-react';

// Constante de Armazenamento Máximo (5GB)
const MAX_STORAGE = 5 * 1024 * 1024 * 1024;

interface MaterialFile {
  id: string;
  name: string;
  type: string;
  size: string;
  sizeBytes: number;
  date: any;
  url: string;
  professorId?: string;
  source?: 'google-drive' | 'local';
  iconUrl?: string;
}

interface Question {
  id: string;
  text: string;
  options: string[];
  correctOptionIndex: number;
}

interface Exam {
  id: string;
  title: string;
  courseId: string;
  courseName: string;
  passingGrade: number;
  questions: Question[];
  type: 'evaluation' | 'activity';
  linkedLessonId?: string;
  linkedModuleId?: string;
  createdAt?: any;
}

interface Feedback {
  id: string;
  studentName: string;
  courseName: string;
  rating: number;
  date: Date;
  text: string;
  type: 'praise' | 'criticism' | 'suggestion';
  criteria: {
    didactics: number;
    support: number;
    material: number;
  };
}

interface ProfessorViewProps {
  user: User;
  activeSub: ProfessorSubView;
  setActiveSub: (view: ProfessorSubView) => void;
}

const ProfessorView: React.FC<ProfessorViewProps> = ({ user, activeSub, setActiveSub }) => {
  const [myCourses, setMyCourses] = useState<Course[]>([]);
  const [loading, setLoading] = useState(true);
  const [selectedCourse, setSelectedCourse] = useState<Course | null>(null);
  const [modules, setModules] = useState<Module[]>([]);
  const [lessonsByModule, setLessonsByModule] = useState<Record<string, Lesson[]>>({});
  const [allModulesGrouped, setAllModulesGrouped] = useState<Record<string, { course: Course, modules: Module[] }>>({});
  const [openMenuId, setOpenMenuId] = useState<string | null>(null);

  // State para Materiais (Agora sincronizado com o Firestore)
  const [materials, setMaterials] = useState<MaterialFile[]>([]);

  // State para Avaliações (Agora sincronizado com o Firestore)
  const [exams, setExams] = useState<Exam[]>([]);

  // Sincronização Silenciosa de Dados (Cloud-Sync)
  useEffect(() => {
    // Escuta em tempo real para Materiais do Professor
    const qMaterials = query(
      collection(db, 'materials'), 
      where('professorId', '==', user.uid),
      orderBy('date', 'desc')
    );
    const unsubMaterials = onSnapshot(qMaterials, (snapshot) => {
      const data: MaterialFile[] = [];
      snapshot.forEach(doc => data.push({ ...doc.data(), id: doc.id } as MaterialFile));
      setMaterials(data);
    });

    // Escuta em tempo real para Avaliações (Global do Professor)
    const qExams = query(collection(db, 'exams'), orderBy('createdAt', 'desc'));
    const unsubExams = onSnapshot(qExams, (snapshot) => {
      const data: Exam[] = [];
      snapshot.forEach(doc => data.push({ ...doc.data(), id: doc.id } as Exam));
      setExams(data);
    });

    return () => {
      unsubMaterials();
      unsubExams();
    };
  }, [user.uid]);

  // State para o Material Picker
  const [isMaterialPickerOpen, setIsMaterialPickerOpen] = useState(false);
  const [pickerMode, setPickerMode] = useState<'image' | 'document'>('document');
  const [pickerCallback, setPickerCallback] = useState<(url: string) => void>(() => {});

  // State de Modais de Avaliação
  const [isExamModalOpen, setIsExamModalOpen] = useState(false);
  const [isEditingExam, setIsEditingExam] = useState(false);
  const [examForm, setExamForm] = useState<{
    id?: string;
    title: string;
    courseId: string;
    passingGrade: number;
    questions: Question[];
    type: 'evaluation' | 'activity';
    linkedLessonId?: string;
    linkedModuleId?: string;
  }>({
    title: '',
    courseId: '',
    passingGrade: 7.0,
    questions: [{ id: '1', text: '', options: ['', '', '', ''], correctOptionIndex: 0 }],
    type: 'activity'
  });

  // State para Feedbacks (Mural de Voz)
  const [feedbacks] = useState<Feedback[]>([
    {
      id: '1',
      studentName: 'Lucas Oliveira',
      courseName: 'Teologia Sistemática I',
      rating: 5,
      date: new Date('2024-03-20'),
      text: 'O professor tem uma didática excelente! Os materiais de apoio são muito ricos e ajudam muito na fixação.',
      type: 'praise',
      criteria: { didactics: 5, support: 5, material: 5 }
    },
    {
      id: '2',
      studentName: 'Ana Clara Souza',
      courseName: 'História do Cristianismo',
      rating: 4,
      date: new Date('2024-03-18'),
      text: 'Gostaria de sugerir mais aulas ao vivo para tirarmos dúvidas em tempo real.',
      type: 'suggestion',
      criteria: { didactics: 4, support: 3, material: 5 }
    }
  ]);

  const materialInputRef = useRef<HTMLInputElement>(null);

  // UX Emoção: States de Fluxo
  const [showIntegrityModal, setShowIntegrityModal] = useState(false);
  const [pendingExam, setPendingExam] = useState<Exam | null>(null);
  const [showCertificateScreen, setShowCertificateScreen] = useState(false);

  // Lógica de Tentativas (Business Logic)
  const [userExamAttempts, setUserExamAttempts] = useState<Record<string, number>>(() => {
    const saved = localStorage.getItem(`eb_attempts_${user.uid}`);
    return saved ? JSON.parse(saved) : {};
  });

  useEffect(() => {
    localStorage.setItem(`eb_attempts_${user.uid}`, JSON.stringify(userExamAttempts));
  }, [userExamAttempts, user.uid]);

  // Modal States Administrativos
  const [showCourseModal, setShowCourseModal] = useState(false);
  const [isEditingCourse, setIsEditingCourse] = useState(false);
  const [editingCourseId, setEditingCourseId] = useState<string | null>(null);

  const [isModuleModalOpen, setIsModuleModalOpen] = useState(false); 
  const [showLessonModal, setShowLessonModal] = useState(false);
  const [isEditingLesson, setIsEditingLesson] = useState(false);
  const [activeModuleId, setActiveModuleId] = useState<string | null>(null);
  const [currentEditingModule, setCurrentEditingModule] = useState<Module | null>(null); 
  const [editingLessonId, setEditingLessonId] = useState<string | null>(null);

  // Preview States
  const [previewLesson, setPreviewLesson] = useState<Lesson | null>(null);
  const [previewExam, setPreviewExam] = useState<Exam | null>(null); 
  const [isConcluded, setIsConcluded] = useState(false);
  const [isPlaying, setIsPlaying] = useState(false);
  const [timeLeft, setTimeLeft] = useState(300);
  const timerIntervalRef = useRef<number | null>(null);
  const [showWelcomeModal, setShowWelcomeModal] = useState(false);
  const [showCompletionModal, setShowCompletionModal] = useState(false);

  const [isStudentSimulationMode, setIsStudentSimulationMode] = useState(false);
  const [isCertificateUnlocked, setIsCertificateUnlocked] = useState(false);
  const [completedLessonIds, setCompletedLessonIds] = useState<Set<string>>(new Set());
  const [totalLessons, setTotalLessons] = useState(0);

  const [playerVolume, setPlayerVolume] = useState(80); 
  const [isMuted, setIsMuted] = useState(false); 
  const iframeRef = useRef<HTMLIFrameElement>(null); 
  const playerContainerRef = useRef<HTMLDivElement>(null); 

  // Form States
  const [courseForm, setCourseForm] = useState({
    nome: '', tema: '', professorResponsavel: user.displayName || '',
    descricaoLonga: '', capaUrl: '', cargaHoraria: '',
    publicoAlvo: 'Geral' as const, geraCertificado: false
  });
  const [moduleForm, setModuleForm] = useState({ nome: '', courseId: '' });
  const [lessonForm, setLessonForm] = useState({
    titulo: '', descricao: '', videoUrl: '', materialUrl: ''
  });

  // --- Funções de Dados (Cloud Persistence) ---
  const fetchMyCourses = async () => {
    setLoading(true);
    try {
      const q = query(collection(db, 'cursos'), where('professorId', '==', user.uid), orderBy('createdAt', 'desc'));
      const querySnapshot = await getDocs(q);
      const fetched: Course[] = [];
      querySnapshot.forEach((doc) => {
        fetched.push({ id: doc.id, ...doc.data() } as Course);
      });
      setMyCourses(fetched);
    } catch (error) {
      console.error(error);
    } finally {
      setLoading(false);
    }
  };

  const fetchModulesForCourse = async (courseId: string) => {
    const q = query(collection(db, 'cursos', courseId, 'modulos'), orderBy('ordem', 'asc'));
    const querySnapshot = await getDocs(q);
    const fetched: Module[] = [];
    querySnapshot.forEach((doc) => {
      fetched.push({ id: doc.id, ...doc.data(), courseId } as Module);
    });
    return fetched;
  };

  const fetchAllModulesGrouped = async () => {
    setLoading(true);
    try {
      const grouped: Record<string, { course: Course, modules: Module[] }> = {};
      for (const course of myCourses) {
        const mods = await fetchModulesForCourse(course.id);
        for (const mod of mods) {
          await fetchLessons(course.id, mod.id);
        }
        grouped[course.id] = { course, modules: mods };
      }
      setAllModulesGrouped(grouped);
    } catch (error) {
      console.error(error);
    } finally {
      setLoading(false);
    }
  };

  const fetchLessons = async (courseId: string, moduleId: string) => {
    try {
      const q = query(collection(db, 'cursos', courseId, 'modulos', moduleId, 'aulas'), orderBy('ordem', 'asc'));
      const querySnapshot = await getDocs(q);
      const fetched: Lesson[] = [];
      querySnapshot.forEach((doc) => {
        fetched.push({ id: doc.id, ...doc.data() } as Lesson);
      });
      setLessonsByModule(prev => ({ ...prev, [moduleId]: fetched }));
    } catch (error) {
      console.error(error);
    }
  };

  const fetchCompletedLessons = useCallback(async (studentId: string, courseId: string) => {
    if (!studentId || !courseId) return new Set<string>();
    try {
      const key = `completed_lessons_sim_${studentId}_${courseId}`;
      const stored = localStorage.getItem(key);
      return new Set(stored ? JSON.parse(stored) : []);
    } catch (error) {
      console.error(error);
    }
    return new Set<string>();
  }, []);

  const updateCompletedLesson = useCallback(async (studentId: string, lessonId: string) => {
    if (!studentId || !lessonId) return;
    try {
      const key = `completed_lessons_sim_${studentId}_${selectedCourse?.id}`;
      const currentCompleted = await fetchCompletedLessons(studentId, selectedCourse?.id || '');
      if (!currentCompleted.has(lessonId)) {
        currentCompleted.add(lessonId);
        localStorage.setItem(key, JSON.stringify(Array.from(currentCompleted)));
        setCompletedLessonIds(currentCompleted);
      }
    } catch (error) {
      console.error(error);
    }
  }, [fetchCompletedLessons, selectedCourse?.id]);

  // --- Effects de Inicialização ---
  useEffect(() => { fetchMyCourses(); }, [user.uid]);

  useEffect(() => {
    if (activeSub === 'modulos') { fetchAllModulesGrouped(); }
  }, [activeSub, myCourses]);

  useEffect(() => {
    if (selectedCourse && modules.length > 0) {
      let count = 0;
      for (const mod of modules) { count += (lessonsByModule[mod.id]?.length || 0); }
      setTotalLessons(count);
    } else { setTotalLessons(0); }
  }, [selectedCourse, modules, lessonsByModule]);

  useEffect(() => {
    const shouldStartTimer = isStudentSimulationMode && previewLesson && !showWelcomeModal && isPlaying;
    if (shouldStartTimer && timeLeft > 0) {
      if (!timerIntervalRef.current) {
        timerIntervalRef.current = window.setInterval(async () => {
          setTimeLeft(prevTime => {
            if (prevTime <= 1) {
              if (timerIntervalRef.current) { clearInterval(timerIntervalRef.current); timerIntervalRef.current = null; }
              setIsConcluded(true);
              if (user.uid && previewLesson?.id) { updateCompletedLesson(user.uid, previewLesson.id); }
              if (!showCompletionModal) { setShowCompletionModal(true); }
              return 0;
            }
            return prevTime - 1;
          });
        }, 1000);
      }
    } else if (timerIntervalRef.current) {
      clearInterval(timerIntervalRef.current);
      timerIntervalRef.current = null;
    }
    return () => { if (timerIntervalRef.current) { clearInterval(timerIntervalRef.current); timerIntervalRef.current = null; } };
  }, [previewLesson, isStudentSimulationMode, showWelcomeModal, isPlaying, timeLeft, showCompletionModal, user.uid, previewLesson?.id, updateCompletedLesson]);

  useEffect(() => {
    if (selectedCourse?.geraCertificado && isStudentSimulationMode && totalLessons > 0) {
      setIsCertificateUnlocked(completedLessonIds.size >= totalLessons);
    } else { setIsCertificateUnlocked(false); }
  }, [selectedCourse?.geraCertificado, isStudentSimulationMode, completedLessonIds, totalLessons]);

  useEffect(() => {
    if (selectedCourse && user.uid) { fetchCompletedLessons(user.uid, selectedCourse.id).then(setCompletedLessonIds); }
    else { setCompletedLessonIds(new Set()); }
  }, [selectedCourse, user.uid, fetchCompletedLessons]);

  const getYouTubeVideoId = (url: string) => {
    const ytRegex = /(?:https?:\/\/)?(?:www\.)?(?:youtube\.com\/(?:[^\/\n\s]+\/\S+\/|(?:v|e(?:mbed)?)\/|\S*?[?&]v=)|youtu\.be\/)([a-zA-Z0-9_-]{11})/;
    const ytMatch = url.match(ytRegex);
    return ytMatch && ytMatch[1];
  };

  const sendPlayerCommand = useCallback((command: string, args: any = '') => {
    if (iframeRef.current && iframeRef.current.contentWindow) {
      iframeRef.current.contentWindow.postMessage(JSON.stringify({ event: 'command', func: command, args: args }), '*');
    }
  }, []);

  const togglePlay = () => {
    if (isPlaying) { sendPlayerCommand('pauseVideo'); setIsPlaying(false); }
    else { sendPlayerCommand('playVideo'); setIsPlaying(true); setShowWelcomeModal(false); }
  };

  const toggleMute = () => {
    if (isMuted) { sendPlayerCommand('unMute'); } else { sendPlayerCommand('mute'); }
    setIsMuted(prev => !prev);
  };

  const handleVolumeChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const vol = parseInt(e.target.value);
    setPlayerVolume(vol);
    if (vol === 0) { if (!isMuted) sendPlayerCommand('mute'); setIsMuted(true); }
    else { if (isMuted) sendPlayerCommand('unMute'); sendPlayerCommand('setVolume', [vol]); setIsMuted(false); }
  };

  const toggleFullscreen = () => {
    if (playerContainerRef.current) {
      if (!document.fullscreenElement) playerContainerRef.current.requestFullscreen();
      else document.exitFullscreen();
    }
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    if (file.size > 5 * 1024 * 1024) { alert("A imagem de capa não pode exceder 5 MB."); e.target.value = ''; return; }
    const reader = new FileReader();
    reader.onloadend = () => { setCourseForm(prev => ({ ...prev, capaUrl: reader.result as string })); };
    reader.readAsDataURL(file);
  };

  const handleSaveCourse = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      setLoading(true);
      if (isEditingCourse && editingCourseId) {
        const courseRef = doc(db, 'cursos', editingCourseId);
        await updateDoc(courseRef, { ...courseForm });
        if (selectedCourse?.id === editingCourseId) { setSelectedCourse({ ...selectedCourse, ...courseForm }); }
      } else {
        await addDoc(collection(db, 'cursos'), { ...courseForm, professorId: user.uid, inscritos: 0, status: 'rascunho', createdAt: serverTimestamp() });
      }
      handleCloseCourseModal();
      await fetchMyCourses();
    } catch (error) {
      console.error(error);
    } finally { setLoading(false); }
  };

  const handleEditCourseInfo = (course: Course) => {
    setCourseForm({
      nome: course.nome, tema: course.tema || '', professorResponsavel: course.professorResponsavel || '',
      descricaoLonga: course.descricaoLonga || '', capaUrl: course.capaUrl || '',
      cargaHoraria: course.cargaHoraria, publicoAlvo: course.publicoAlvo,
      geraCertificado: course.geraCertificado || false
    });
    setEditingCourseId(course.id);
    setIsEditingCourse(true);
    setShowCourseModal(true);
    setOpenMenuId(null);
  };

  const handleCloseCourseModal = () => {
    setShowCourseModal(false);
    setIsEditingCourse(false);
    setEditingCourseId(null);
    setCourseForm({
      nome: '', tema: '', professorResponsavel: user.displayName || '',
      descricaoLonga: '', capaUrl: '', cargaHoraria: '',
      publicoAlvo: 'Geral', geraCertificado: false
    });
  };

  const handleDeleteCourse = async (courseId: string) => {
    if (!confirm("Tem certeza que deseja excluir o curso inteiro?")) return;
    try {
      await deleteDoc(doc(db, 'cursos', courseId));
      setMyCourses(prev => prev.filter(c => c.id !== courseId));
      setOpenMenuId(null);
    } catch (error) { console.error(error); }
  };

  const handleDuplicateCourse = async (course: Course) => {
    try {
      const { id, ...data } = course;
      await addDoc(collection(db, 'cursos'), { ...data, nome: `${data.nome} (Cópia)`, createdAt: serverTimestamp() });
      fetchMyCourses();
      setOpenMenuId(null);
    } catch (error) { console.error(error); }
  };

  const handleDeleteModule = async (courseId: string, moduleId: string) => {
    if (!confirm("Excluir este módulo e todo seu conteúdo?")) return;
    try {
      await deleteDoc(doc(db, 'cursos', courseId, 'modulos', moduleId));
      if (selectedCourse) { setModules(prev => prev.filter(m => m.id !== moduleId)); }
      fetchAllModulesGrouped();
    } catch (error) { console.error(error); }
  };

  const handleSaveModule = async (e: React.FormEvent) => {
    e.preventDefault();
    const finalCourseId = selectedCourse?.id || moduleForm.courseId;
    if (!finalCourseId) {
       alert("Selecione um curso.");
       return;
    }
    try {
      if (currentEditingModule) {
        const modRef = doc(db, 'cursos', currentEditingModule.courseId, 'modulos', currentEditingModule.id);
        await updateDoc(modRef, { nome: moduleForm.nome });
      } else {
        const qOrder = query(collection(db, 'cursos', finalCourseId, 'modulos'));
        const snapOrder = await getDocs(qOrder);
        const nextOrder = snapOrder.size + 1;

        await addDoc(collection(db, 'cursos', finalCourseId, 'modulos'), { 
          nome: moduleForm.nome, 
          ordem: nextOrder, 
          createdAt: serverTimestamp() 
        });
      }
      setIsModuleModalOpen(false);
      setModuleForm({ nome: '', courseId: '' });
      setCurrentEditingModule(null);
      if (selectedCourse) {
         const mods = await fetchModulesForCourse(selectedCourse.id);
         setModules(mods);
      }
      fetchAllModulesGrouped();
    } catch (error) { console.error(error); }
  };

  const handleOpenCreateModule = () => {
    setModuleForm({ nome: '', courseId: selectedCourse?.id || '' });
    setCurrentEditingModule(null);
    setIsModuleModalOpen(true);
  };

  const handleEditModule = (mod: Module) => {
    setCurrentEditingModule(mod);
    setModuleForm({ nome: mod.nome, courseId: mod.courseId });
    setIsModuleModalOpen(true);
  };

  const handleSaveLesson = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedCourse || !activeModuleId) return;

    const allLessonsFlattened = Object.values(lessonsByModule).flat() as Lesson[];
    const arquivoJaUsado = allLessonsFlattened.find(l => 
        l.materialUrl === lessonForm.materialUrl && 
        l.materialUrl !== '' && 
        l.id !== editingLessonId
    );

    if (arquivoJaUsado) {
        alert(`Atenção: O arquivo selecionado já está vinculado à aula "${arquivoJaUsado.titulo}". Por favor, escolha outro arquivo para evitar conflitos de download.`);
        return;
    }

    try {
      if (isEditingLesson && editingLessonId) {
        const lessonRef = doc(db, 'cursos', selectedCourse.id, 'modulos', activeModuleId, 'aulas', editingLessonId);
        await updateDoc(lessonRef, { ...lessonForm });
        if (previewLesson && previewLesson.id === editingLessonId) {
           setPreviewLesson(prev => prev ? ({ ...prev, ...lessonForm }) : null);
        }
      } else {
        await addDoc(collection(db, 'cursos', selectedCourse.id, 'modulos', activeModuleId, 'aulas'), { ...lessonForm, ordem: (lessonsByModule[activeModuleId]?.length || 0) + 1, createdAt: serverTimestamp() });
      }
      setShowLessonModal(false);
      setIsEditingLesson(false);
      setEditingLessonId(null);
      setLessonForm({ titulo: '', descricao: '', videoUrl: '', materialUrl: '' });
      fetchLessons(selectedCourse.id, activeModuleId);
    } catch (error) { console.error(error); }
  };

  const handleDeleteLesson = async (moduleId: string, lessonId: string) => {
    if (!selectedCourse) return;
    if (!confirm("Tem certeza que deseja DESTRUIR esta aula permanentemente?")) return;
    try {
      await deleteDoc(doc(db, 'cursos', selectedCourse.id, 'modulos', moduleId, 'aulas', lessonId));
      fetchLessons(selectedCourse.id, moduleId);
      if (previewLesson?.id === lessonId) setPreviewLesson(null);
    } catch (error) { console.error(error); }
  };

  const handleEditLesson = (lesson: Lesson, moduleId: string) => {
    setActiveModuleId(moduleId);
    setLessonForm({ titulo: lesson.titulo, descricao: lesson.descricao || '', videoUrl: lesson.videoUrl, materialUrl: lesson.materialUrl });
    setEditingLessonId(lesson.id);
    setIsEditingLesson(true);
    setShowLessonModal(true);
  };

