interface MaterialFile {
  id: string;
  name: string;
  type: string;
  size: string;
  sizeBytes: number;
  date: any;
  url: string;
  professorId?: string;
  source?: 'google-drive' | 'local';
  iconUrl?: string;
}

interface Question {
  id: string;
  text: string;
  options: string[];
  correctOptionIndex: number;
}

interface Exam {
