  title: string;
  courseId: string;
  courseName: string;
  passingGrade: number;
  questions: Question[];
  type: 'evaluation' | 'activity';
  linkedLessonId?: string;
  linkedModuleId?: string;
  createdAt?: any;
}

interface Feedback {
