                    <h2 className="text-2xl font-serif text-white mb-6">Pacto de Integridade</h2>
                    <p className="text-slate-400 text-sm italic leading-relaxed font-medium">"O verdadeiro conhecimento é construído na verdade. Deus vê todas as coisas, inclusive este momento."</p>
                  </div>
                  <button onClick={handleStartExamAfterPact} className="w-full py-5 bg-indigo-600 text-white font-black uppercase tracking-[0.2em] text-xs rounded-2xl">Estou pronto para iniciar</button>
                  <button onClick={() => { setShowIntegrityModal(false); setPendingExam(null); }} className="w-full py-4 text-slate-500 hover:text-white transition-colors font-bold text-[10px] uppercase">Preciso de mais tempo</button>
               </div>
            </div>
          )}
        </div>
      );
    }

    if (activeSub === 'feedback') {
      const avgRating = feedbacks.reduce((acc, f) => acc + f.rating, 0) / feedbacks.length;
      return (
        <div className="space-y-8 animate-in fade-in duration-500">
          <header><h1 className="text-2xl font-bold text-slate-900 tracking-tight">Dashboard de Reputação</h1></header>
          <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
            <div className="bg-slate-900 p-8 rounded-[2rem] border border-slate-800 shadow-xl flex flex-col justify-center items-center text-center space-y-4">
              <Star size={40} fill="#fbbf24" className="text-amber-400" />
              <div>
                <h3 className="text-4xl font-black text-white">{avgRating.toFixed(1)}</h3>
                <p className="text-slate-400 text-xs font-bold uppercase tracking-widest mt-1">Nota Geral</p>
              </div>
            </div>
            <div className="lg:col-span-2 bg-slate-900 p-8 rounded-[2rem] border border-slate-800 shadow-xl space-y-6">
              <h3 className="text-sm font-black text-indigo-400 uppercase tracking-widest">Radar de Competências</h3>
              {[
                { label: '🗣️ Didática', val: 4.8, color: 'bg-indigo-500' },
                { label: '🆘 Suporte', val: 4.2, color: 'bg-emerald-500' },
                { label: '📚 Material', val: 4.9, color: 'bg-amber-500' }
              ].map((item, i) => (
                <div key={i} className="space-y-2">
                  <div className="flex justify-between items-center text-[10px] font-black uppercase tracking-wider text-slate-400">
                    <span>{item.label}</span>
                    <span className="text-white">{item.val.toFixed(1)} / 5.0</span>
                  </div>
                  <div className="h-2 w-full bg-slate-800 rounded-full overflow-hidden">
                    <div className={`h-full ${item.color}`} style={{ width: `${(item.val / 5) * 100}%` }} />
                  </div>
                </div>
              ))}
            </div>
          </div>
        </div>
      );
    }

    if (activeSub === 'avaliacao') {
      return (
        <div className="space-y-6 animate-in fade-in duration-500">
          <header className="flex flex-col sm:flex-row items-center justify-between gap-4">
            <div><h1 className="text-2xl font-bold text-slate-900 tracking-tight">Gestão de Avaliações</h1></div>
            <button onClick={() => { setIsEditingExam(false); setExamForm({ title: '', courseId: '', passingGrade: 7.0, questions: [{ id: '1', text: '', options: ['', '', '', ''], correctOptionIndex: 0 }], type: 'activity' }); setIsExamModalOpen(true); }} className="flex items-center gap-2 bg-indigo-600 text-white px-5 py-3 rounded-xl text-sm font-bold shadow-lg"><PlusCircle size={18} /> Nova Avaliação</button>
          </header>
          {exams.length === 0 ? (<div className="bg-white p-24 rounded-3xl border border-dashed border-slate-200 text-center"><h3 className="font-bold text-slate-900 text-lg">Nenhuma prova cadastrada</h3></div>) : (
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              {exams.map((exam) => (
                <div key={exam.id} className="group bg-slate-900 rounded-3xl border border-slate-800 p-6 shadow-xl hover:border-indigo-500/40 transition-all relative">
                  <div className="flex justify-between items-start mb-4">
                    <div className={`p-3 rounded-2xl ${exam.type === 'evaluation' ? 'bg-orange-500/10 text-orange-400' : 'bg-blue-500/10 text-blue-400'}`}>
                      {exam.type === 'evaluation' ? <Star size={24} /> : <PencilLine size={24} />}
                    </div>
                    <div className="flex gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                      <button onClick={() => handleEditExam(exam)} className="p-2 text-slate-400 hover:text-white hover:bg-slate-700 rounded-lg"><Edit size={16} /></button>
                      <button onClick={() => handleDeleteExam(exam.id)} className="p-2 text-red-400 hover:text-white hover:bg-red-500 rounded-lg"><Trash2 size={16} /></button>
                    </div>
                  </div>
                  <h3 className="text-white font-bold text-lg mb-1 leading-tight">{exam.title}</h3>
                  <p className="text-indigo-400 text-[10px] font-black uppercase tracking-widest">{exam.courseName}</p>
                </div>
              ))}
            </div>
          )}
        </div>
      );
    }

    if (activeSub === 'materiais') {
      return (
        <div className="space-y-6 animate-in fade-in duration-500">
           <header className="flex items-center justify-between">
            <h1 className="text-2xl font-bold text-slate-900 tracking-tight">Biblioteca de Materiais</h1>
            <button onClick={() => materialInputRef.current?.click()} className="flex items-center gap-2 bg-slate-900 text-white px-5 py-3 rounded-xl text-sm font-bold shadow-lg hover:bg-slate-800 transition-all active:scale-95">
              <Database size={18} className="text-indigo-400" /> Upload de Arquivo
            </button>
            <input type="file" ref={materialInputRef} className="hidden" multiple onChange={handleMaterialUpload} />
          </header>
          {materials.length === 0 ? (<div className="p-20 text-center border-2 border-dashed rounded-3xl text-slate-400">A biblioteca está vazia.</div>) : (
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
              {materials.map((file) => (
                <div key={file.id} className="bg-slate-900 rounded-3xl p-5 border border-slate-800 group relative flex flex-col h-full hover:border-indigo-500/50 transition-all">
                   <div className="flex justify-between mb-6">
                     <div className="p-3 bg-slate-800 rounded-2xl">{getFileIcon(file.type)}</div>
                     <div className="flex gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                       <a href={file.url} target="_blank" rel="noopener noreferrer" className="p-2 text-indigo-400 hover:bg-indigo-500/10 rounded-lg"><ExternalLink size={14} /></a>
                       <button onClick={() => handleDeleteMaterial(file.id)} className="p-2 text-red-400 hover:bg-red-500/10 rounded-lg"><Trash2 size={14} /></button>
                     </div>
                   </div>
                   <h3 className="text-white font-bold text-sm truncate" title={file.name}>{file.name}</h3>
                   <div className="mt-auto pt-4 flex items-center justify-between border-t border-slate-800/50">
                      <span className="text-slate-500 text-[10px] font-black uppercase tracking-tighter flex items-center gap-1.5">
                        <Share2 size={10} /> {file.source === 'google-drive' ? 'Drive' : 'Local'}
                      </span>
                      <span className="text-slate-600 text-[9px] font-bold">{file.type}</span>
                   </div>
                </div>
              ))}
            </div>
          )}
        </div>
      );
    }

    if (activeSub === 'modulos') {
      const allModules = Object.values(allModulesGrouped).flatMap((group: { course: Course; modules: Module[] }) => group.modules.map(m => ({ ...m, courseName: group.course.nome }))).sort((a, b) => a.ordem - b.ordem);
      return (
        <div className="space-y-6 animate-in fade-in duration-500">
          <header className="flex flex-col sm:flex-row items-center justify-between gap-4"><div><h1 className="text-2xl font-bold text-slate-900 tracking-tight">Biblioteca de Módulos</h1></div><button onClick={handleOpenCreateModule} className="flex items-center gap-2 bg-indigo-600 text-white px-5 py-3 rounded-xl text-sm font-bold shadow-lg"><Plus size={18} /> Novo Módulo</button></header>
          <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6">
            {allModules.map((mod: any) => (<div key={mod.id} className="group bg-slate-900 rounded-3xl border border-slate-800 p-6 shadow-xl hover:border-indigo-500/50 transition-all"><div className="flex flex-col h-full"><div className="flex justify-between items-start mb-4"><div className="px-3 py-1 bg-indigo-500/10 border border-indigo-500/20 text-indigo-400 text-[9px] font-black uppercase tracking-widest rounded-full">{mod.courseName}</div><div className="flex gap-1 opacity-0 group-hover:opacity-100"><button onClick={() => handleEditModule(mod)} className="p-2 bg-slate-800 text-slate-300 rounded-lg border border-slate-700"><Edit size={14} /></button><button onClick={() => handleDeleteModule(mod.courseId, mod.id)} className="p-2 bg-red-500/10 text-red-400 rounded-lg border border-red-500/20"><Trash2 size={14} /></button></div></div><h3 className="text-white font-bold text-lg mb-2">{mod.ordem.toString().padStart(2, '0')}. {mod.nome}</h3></div></div>))}
          </div>
        </div>
      );
    }

    if (activeSub === 'cursos' && selectedCourse) {
      return (
        <div className="space-y-6 animate-in fade-in duration-500">
          <header className="flex items-center justify-between gap-4"><div className="flex items-center gap-4"><button onClick={() => setSelectedCourse(null)} className="h-10 w-10 bg-white border border-slate-200 hover:bg-slate-50 rounded-xl text-slate-600 shadow-sm flex items-center justify-center"><ArrowLeft size={20} /></button><div><h1 className="text-2xl font-bold text-slate-900 leading-tight">{selectedCourse.nome}</h1></div></div><button onClick={handleOpenCreateModule} className="flex items-center gap-2 bg-indigo-600 text-white px-5 py-2.5 rounded-xl text-sm font-bold shadow-lg"><Plus size={18} /> Novo Módulo</button></header>
          <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
            <div className="lg:col-span-2 space-y-4"><div className="bg-white rounded-2xl border border-slate-200 shadow-sm overflow-hidden"><div className="px-6 py-4 border-b border-slate-100 bg-slate-50/50"><h2 className="text-xs font-bold text-slate-800 uppercase tracking-widest">Matriz Curricular</h2></div><div className="p-4 space-y-4">{modules.map((mod) => (<div key={mod.id} className="border border-slate-100 rounded-xl group bg-slate-50/20"><div className="px-4 py-3 border-b border-slate-100 flex items-center justify-between bg-white"><h3 className="font-bold text-slate-800 text-sm">Módulo {mod.ordem}: {mod.nome}</h3><div className="flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity"><button onClick={() => { setActiveModuleId(mod.id); setIsEditingLesson(false); setEditingLessonId(null); setLessonForm({titulo:'', descricao:'', videoUrl:'', materialUrl:''}); setShowLessonModal(true); }} className="p-1.5 text-indigo-600 hover:bg-indigo-50 rounded-lg"><Plus size={18} /></button><button onClick={() => handleEditModule(mod)} className="p-1.5 text-slate-400 hover:bg-slate-50 rounded-lg"><Edit size={18} /></button><button onClick={() => handleDeleteModule(selectedCourse.id, mod.id)} className="p-1.5 text-red-400 hover:bg-red-50 rounded-lg"><Trash2 size={18} /></button></div></div><div className="p-2 space-y-1">{lessonsByModule[mod.id]?.map((lesson) => (<div key={lesson.id} className="flex items-center justify-between p-3 rounded-xl hover:bg-white hover:shadow-sm group/lesson transition-all"><div className="flex items-center gap-4"><div className="p-2 bg-white border rounded-lg text-indigo-600"><Play size={12} fill="currentColor" /></div><span className="text-sm font-semibold text-slate-700">{lesson.titulo}</span></div><div className="flex items-center gap-1 opacity-0 group-hover/lesson:opacity-100"><button onClick={() => openPreview(lesson, mod.id, false)} className="p-1.5 text-indigo-600 hover:bg-indigo-50 rounded-lg"><Eye size={16} /></button><button onClick={() => handleEditLesson(lesson, mod.id)} className="p-1.5 text-slate-400 rounded-lg"><Edit size={16} /></button><button onClick={() => handleDeleteLesson(mod.id, lesson.id)} className="p-1.5 text-red-400 rounded-lg"><Trash2 size={16} /></button></div></div>))}</div></div>))}</div></div></div>
            <div className="bg-white p-5 rounded-2xl border border-slate-200 shadow-sm sticky top-24 h-fit"><img src={selectedCourse.capaUrl || 'https://images.unsplash.com/photo-1504052434139-443c40c98408?w=800'} className="w-full h-40 object-cover rounded-xl mb-4" /><div className="space-y-3"><div className="flex justify-between border-b pb-2"><span className="text-[10px] text-slate-400 font-black uppercase">Professor</span><span className="text-xs font-bold">{selectedCourse.professorResponsavel}</span></div></div></div>
          </div>
        </div>
      );
    }

    return (
      <div className="space-y-6 animate-in fade-in duration-500"><header className="flex flex-col sm:flex-row items-center justify-between gap-4"><div><h1 className="text-2xl font-bold text-slate-900 tracking-tight">Portal do Professor</h1></div><button onClick={() => { setIsEditingCourse(false); setEditingCourseId(null); setCourseForm({ nome: '', tema: '', professorResponsavel: user.displayName || '', professorBio: '', professorFoto: '', dificuldade: 'Iniciante', descricaoLonga: '', capaUrl: '', cargaHoraria: '', publicoAlvo: 'Geral', geraCertificado: false }); setShowCourseModal(true); }} className="flex items-center gap-2 bg-indigo-600 text-white px-5 py-3 rounded-xl text-sm font-bold shadow-lg"><Plus size={18} /> Novo Curso</button></header><div className="grid grid-cols-1 md:grid-cols-3 xl:grid-cols-6 gap-4">{loading ? (<div className="col-span-full py-20 flex justify-center"><div className="h-6 w-6 animate-spin rounded-full border-2 border-indigo-600 border-t-transparent"></div></div>) : myCourses.map(course => (<div key={course.id} onClick={() => openCourseDetail(course)} className="bg-white border border-slate-200 rounded-2xl overflow-hidden hover:shadow-xl hover:border-indigo-200 group cursor-pointer flex flex-col relative"><div className="absolute top-2 right-2 z-50"><button onClick={(e) => { e.stopPropagation(); setOpenMenuId(openMenuId === course.id ? null : course.id); }} className="p-1.5 bg-white/90 backdrop-blur-sm rounded-lg border border-slate-200 text-slate-500 shadow-sm"><MoreVertical size={14} /></button>{openMenuId === course.id && (<div className="absolute right-0 mt-1 w-32 bg-white rounded-xl shadow-2xl border border-slate-100 z-50 overflow-hidden text-[10px] font-bold"><button onClick={(e) => { e.stopPropagation(); handleEditCourseInfo(course); }} className="w-full px-3 py-2 text-left hover:bg-slate-50 flex items-center gap-2"><Edit size={12} /> Editar</button><button onClick={(e) => { e.stopPropagation(); handleDuplicateCourse(course); }} className="w-full px-3 py-2 text-left hover:bg-slate-50 flex items-center gap-2"><Copy size={12} /> Copiar</button><button onClick={(e) => { e.stopPropagation(); handleDeleteCourse(course.id); }} className="w-full px-3 py-2 text-left hover:bg-red-50 text-red-500 flex items-center gap-2"><Trash2 size={12} /> Apagar</button></div>)}</div><div className="h-24 overflow-hidden bg-slate-100 relative">{course.capaUrl ? <img src={course.capaUrl} className="w-full h-full object-cover group-hover:scale-105 transition-transform" /> : <div className="h-full flex items-center justify-center text-slate-200"><BookOpen size={32} /></div>}</div><div className="p-3 flex-1 flex flex-col"><h3 className="font-bold text-slate-900 text-xs mb-1 group-hover:text-indigo-600 transition-colors leading-tight line-clamp-2">{course.nome}</h3></div></div>))}</div></div>
    );
  };

  const renderMaterialPicker = () => {
    if (!isMaterialPickerOpen) return null;

    const filteredMaterials = materials.filter(m => {
      const isImg = ['jpg', 'jpeg', 'png', 'webp', 'gif'].includes(m.type.toLowerCase());
      return pickerMode === 'image' ? isImg : !isImg;
    });

    return (
      <div className="fixed inset-0 !z-[9999] flex items-center justify-center p-4 bg-slate-950/90 backdrop-blur-md animate-in fade-in duration-300">
        <div className="bg-slate-900 w-full max-w-5xl h-[85vh] rounded-[2.5rem] shadow-2xl border border-slate-800 flex flex-col overflow-hidden">
          <header className="px-8 py-6 border-b border-slate-800 flex items-center justify-between">
            <div className="flex items-center gap-4">
              <div className="p-3 bg-indigo-600 text-white rounded-2xl shadow-lg"><Library size={24} /></div>
              <div>
                <h2 className="text-xl font-bold text-white">Biblioteca Cloud</h2>
              </div>
            </div>
            <button onClick={() => setIsMaterialPickerOpen(false)} className="p-2 text-slate-400 hover:text-white transition-colors"><X size={28} /></button>
          </header>
          <div className="flex-1 overflow-y-auto p-8">
            <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-6">
              {filteredMaterials.map((file) => (
                <div key={file.id} onClick={() => handleSelectMaterialFromPicker(file)} className="group bg-slate-800/40 rounded-3xl border border-slate-700/50 p-4 hover:border-indigo-500 hover:bg-slate-800 transition-all cursor-pointer relative overflow-hidden">
                  <div className="aspect-square bg-slate-900 rounded-2xl mb-4 flex items-center justify-center overflow-hidden">
                    {pickerMode === 'image' ? (
                      <img src={file.url} className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-500" alt="" />
                    ) : ( getFileIcon(file.type) )}
                  </div>
                  <div className="min-w-0"><h4 className="text-white text-xs font-bold truncate">{file.name}</h4></div>
                </div>
              ))}
            </div>
          </div>
        </div>
      </div>
    );
  };

  return (
    <div className="relative">
      {renderMainContent()}
      {renderMaterialPicker()}

      {/* MODAL GLOBAL: CONSTRUTOR DE AVALIAÇÃO */}
      {isExamModalOpen && (
        <div className="fixed inset-0 !z-[9999] flex items-center justify-center p-4 bg-slate-950/80 backdrop-blur-md animate-in fade-in duration-300">
          <div className="bg-slate-900 w-full max-w-4xl max-h-[90vh] rounded-3xl shadow-2xl overflow-hidden flex flex-col animate-in zoom-in-95 border border-slate-800">
            <header className="px-8 py-6 border-b border-slate-800 flex items-center justify-between">
              <div className="flex items-center gap-4">
                <div className={`p-3 rounded-2xl shadow-lg ${examForm.type === 'evaluation' ? 'bg-orange-600 shadow-orange-600/20' : 'bg-blue-600 shadow-blue-600/20'}`}>{examForm.type === 'evaluation' ? <Star size={24} /> : <PencilLine size={24} />}</div>
                <div><h2 className="text-xl font-bold text-white leading-none">{isEditingExam ? 'Editar Conteúdo' : 'Novo Recurso Pedagógico'}</h2><p className="text-slate-500 text-[10px] font-bold uppercase tracking-[0.2em] mt-2">Personalização da Experiência do Aluno</p></div>
              </div>
              <button onClick={() => setIsExamModalOpen(false)} className="text-slate-500 hover:text-white transition-colors"><X size={24} /></button>
            </header>
            <form onSubmit={handleSaveExam} className="flex-1 overflow-y-auto p-8 space-y-10">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6 p-4 bg-slate-800/20 rounded-3xl border border-slate-800">
                <button type="button" onClick={() => setExamForm(prev => ({...prev, type: 'activity'}))} className={`flex flex-col items-center gap-2 p-6 rounded-2xl border transition-all ${examForm.type === 'activity' ? 'bg-blue-600/10 border-blue-500 text-blue-400' : 'border-slate-800 text-slate-500 hover:bg-slate-800'}`}><PencilLine size={32} /><span className="font-bold text-xs uppercase tracking-widest">Atividade de Fixação</span></button>
                <button type="button" onClick={() => setExamForm(prev => ({...prev, type: 'evaluation'}))} className={`flex flex-col items-center gap-2 p-6 rounded-2xl border transition-all ${examForm.type === 'evaluation' ? 'bg-orange-600/10 border-orange-500 text-orange-400' : 'border-slate-800 text-slate-500 hover:bg-slate-800'}`}><Star size={32} /><span className="font-bold text-xs uppercase tracking-widest">Avaliação Oficial</span></button>
              </div>
              <div className="grid grid-cols-1 md:grid-cols-12 gap-6">
                <div className="md:col-span-7 space-y-2"><label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">Título da Prova</label><input required value={examForm.title} onChange={e => setExamForm({...examForm, title: e.target.value})} placeholder="Ex: Prova Mensal" className="w-full px-5 py-4 bg-slate-800 border border-slate-700 rounded-2xl text-white outline-none focus:ring-2 focus:ring-indigo-500" /></div>
                <div className="md:col-span-3 space-y-2"><label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">Curso Alvo</label><select required value={examForm.courseId} onChange={e => setExamForm({...examForm, courseId: e.target.value})} className="w-full px-5 py-4 bg-slate-800 border border-slate-700 rounded-2xl text-white outline-none"><option value="">Selecione...</option>{myCourses.map(c => <option key={c.id} value={c.id}>{c.nome}</option>)}</select></div>
                <div className="md:col-span-2 space-y-2"><label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">Nota Mínima</label><input type="number" step="0.1" value={examForm.passingGrade} onChange={e => setExamForm({...examForm, passingGrade: parseFloat(e.target.value)})} className="w-full px-5 py-4 bg-slate-800 border border-slate-700 rounded-2xl text-white outline-none" /></div>
              </div>
              {examForm.courseId && (
                <div className="space-y-4 animate-in slide-in-from-left-4">
                  {examForm.type === 'activity' ? (
                    <div className="space-y-2"><label className="text-[10px] text-slate-500 uppercase font-black tracking-widest ml-1">Aparecer após qual aula?</label><select required value={examForm.linkedLessonId} onChange={e => setExamForm({...examForm, linkedLessonId: e.target.value})} className="w-full px-5 py-4 bg-slate-800 border border-slate-700 rounded-2xl text-white outline-none"><option value="">Selecione a aula vinculada...</option>{Object.values(lessonsByModule).flat().map((l: any) => (<option key={l.id} value={l.id}>{l.titulo}</option>))}</select></div>
                  ) : (
                    <div className="space-y-2"><label className="text-[10px] text-slate-500 uppercase font-black tracking-widest ml-1">Final de qual Módulo?</label><select required value={examForm.linkedModuleId} onChange={e => setExamForm({...examForm, linkedModuleId: e.target.value})} className="w-full px-5 py-4 bg-slate-800 border border-slate-700 rounded-2xl text-white outline-none"><option value="">Selecione o módulo...</option>{modules.map(m => (<option key={m.id} value={m.id}>Módulo {m.ordem}: {m.nome}</option>))}</select></div>
                  )}
                </div>
              )}
              <footer className="pt-8 flex gap-4"><button type="button" onClick={() => setIsExamModalOpen(false)} className="flex-1 px-8 py-5 border border-slate-700 text-slate-400 rounded-2xl font-bold uppercase hover:bg-slate-800 transition-all">Cancelar</button><button type="submit" className="flex-[2] px-8 py-5 bg-indigo-600 text-white rounded-2xl font-black uppercase tracking-widest shadow-xl hover:bg-indigo-500 transition-all">Salvar Recurso</button></footer>
            </form>
          </div>
        </div>
      )}

      {/* MODAL MÓDULO */}
      {isModuleModalOpen && (
        <div className="fixed inset-0 !z-[9999] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm animate-in fade-in duration-200">
          <div className="bg-white w-full max-w-md rounded-2xl shadow-2xl p-6 border border-slate-100"><h3 className="font-bold text-slate-900 mb-4">{currentEditingModule ? 'Editar Módulo' : 'Configurar Novo Módulo'}</h3><form onSubmit={handleSaveModule} className="space-y-5">{!selectedCourse && !currentEditingModule && (<div className="space-y-1"><label className="text-[10px] font-black text-slate-400 uppercase ml-1">Curso</label><select required value={moduleForm.courseId} onChange={e => setModuleForm({...moduleForm, courseId: e.target.value})} className="w-full px-4 py-2.5 bg-slate-50 border rounded-xl text-sm">{myCourses.map(c => <option key={c.id} value={c.id}>{c.nome}</option>)}</select></div>)}<div className="space-y-1"><label className="text-[10px] font-black text-slate-400 uppercase ml-1">Título</label><input required autoFocus value={moduleForm.nome} onChange={e => setModuleForm({...moduleForm, nome: e.target.value})} className="w-full px-4 py-2.5 bg-slate-50 border rounded-xl text-sm" /></div><div className="flex gap-3"><button type="button" onClick={() => setIsModuleModalOpen(false)} className="flex-1 px-4 py-2.5 border rounded-xl font-bold text-sm">Cancelar</button><button type="submit" className="flex-1 bg-indigo-600 text-white py-2.5 rounded-xl font-bold text-sm shadow-lg">Salvar</button></div></form></div>
        </div>
      )}

      {/* MODAL AULA */}
      {showLessonModal && (
        <div className="fixed inset-0 !z-[9998] flex items-center justify-center p-4 bg-slate-900/40 backdrop-blur-sm animate-in fade-in">
          <div className="bg-white w-full max-w-xl rounded-3xl shadow-2xl p-8 border border-slate-100">
            <h3 className="font-bold text-slate-900 text-xl mb-6 flex items-center gap-3"><PlusCircle size={24} className="text-indigo-600" /> {isEditingLesson ? 'Editar Aula' : 'Nova Unidade'}</h3>
            <form onSubmit={handleSaveLesson} className="space-y-5">
              <input required value={lessonForm.titulo} onChange={e => setLessonForm({...lessonForm, titulo: e.target.value})} placeholder="Título da Aula" className="w-full px-5 py-3.5 bg-slate-50 border border-slate-200 rounded-2xl text-sm outline-none" />
              <textarea value={lessonForm.descricao} onChange={e => setLessonForm({...lessonForm, descricao: e.target.value})} placeholder="Descrição pedagógica..." className="w-full px-5 py-3.5 bg-slate-50 border border-slate-200 rounded-2xl text-sm resize-none" rows={4}></textarea>
              <div className="space-y-4">
                <input value={lessonForm.videoUrl} onChange={e => setLessonForm({...lessonForm, videoUrl: e.target.value})} placeholder="URL do Vídeo (YouTube)" className="w-full px-5 py-3.5 bg-slate-50 border border-slate-200 rounded-2xl text-sm outline-none" />
                <div className="flex gap-2">
                  <input value={lessonForm.materialUrl} onChange={e => setLessonForm({...lessonForm, materialUrl: e.target.value})} placeholder="URL do arquivo..." className="flex-1 px-5 py-3.5 bg-slate-50 border border-slate-200 rounded-2xl text-sm outline-none" /><button type="button" onClick={() => handleOpenMaterialPicker('document', (url) => setLessonForm(prev => ({...prev, materialUrl: url})))} className="px-4 bg-indigo-600 text-white rounded-2xl hover:bg-indigo-700 shadow-lg"><Library size={18} /></button>
                </div>
              </div>
              <div className="flex gap-4 pt-4"><button type="button" onClick={() => setShowLessonModal(false)} className="flex-1 py-4 border border-slate-200 text-slate-500 rounded-2xl font-bold text-sm">Cancelar</button><button type="submit" className="flex-[2] bg-slate-900 text-white py-4 rounded-2xl font-bold text-sm shadow-xl">Salvar Aula</button></div>
            </form>
          </div>
        </div>
      )}

      {/* RESTAURAÇÃO: MODAL CURSO ACADÊMICO */}
      {showCourseModal && (
        <div className="fixed inset-0 !z-[9997] flex items-center justify-center p-4 bg-slate-950/80 backdrop-blur-md animate-in fade-in">
          <div className="bg-slate-900 w-full max-w-4xl rounded-[2.5rem] shadow-2xl overflow-hidden flex flex-col max-h-[95vh] border border-slate-800 animate-in zoom-in-95 duration-300">
            {/* Header com Abas */}
            <div className="bg-slate-900 border-b border-slate-800 pt-8 px-10">
              <div className="flex items-center justify-between mb-8">
                <div className="flex items-center gap-4 text-white">
                   <div className="p-3 bg-indigo-600 rounded-2xl shadow-xl shadow-indigo-600/20"><BookOpen size={24} /></div>
                   <div>
                     <h3 className="font-bold text-xl">{isEditingCourse ? 'Editar Parâmetros Acadêmicos' : 'Novo Curso de Teologia'}</h3>
                     <p className="text-slate-500 text-xs font-bold uppercase tracking-widest mt-1">Configuração de Ementa e Docência</p>
                   </div>
                </div>
                <button onClick={handleCloseCourseModal} className="text-slate-500 hover:text-white p-2 transition-colors"><X size={24} /></button>
              </div>

              <div className="flex gap-8">
                {[
                  { id: 'geral', label: 'Dados Gerais', icon: <Info size={16} /> },
                  { id: 'professor', label: 'Professor & Docência', icon: <UserCheck size={16} /> },
                  { id: 'midia', label: 'Mídia & Capa', icon: <ImageIcon size={16} /> }
                ].map(tab => (
                  <button 
                    key={tab.id}
                    onClick={() => setCourseModalTab(tab.id as any)}
                    className={`pb-4 flex items-center gap-2 text-xs font-black uppercase tracking-widest transition-all border-b-2 ${courseModalTab === tab.id ? 'border-indigo-600 text-white' : 'border-transparent text-slate-500 hover:text-slate-300'}`}
                  >
                    {tab.icon} {tab.label}
                  </button>
                ))}
              </div>
            </div>

            <form onSubmit={handleSaveCourse} className="p-10 space-y-8 overflow-y-auto flex-1 custom-scrollbar">

              {/* ABA GERAL */}
              {courseModalTab === 'geral' && (
                <div className="space-y-8 animate-in slide-in-from-left-4 duration-300">
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                    <div className="space-y-2">
                      <label className="text-[10px] font-black text-slate-500 uppercase tracking-[0.2em] ml-1">Título do Curso</label>
                      <input required value={courseForm.nome} onChange={e => setCourseForm({...courseForm, nome: e.target.value})} placeholder="Ex: Exegese Bíblica de Romanos" className="w-full px-6 py-4 bg-slate-800 border border-slate-700 rounded-2xl text-white outline-none focus:ring-2 focus:ring-indigo-500 transition-all" />
                    </div>
                    <div className="space-y-2">
                      <label className="text-[10px] font-black text-slate-500 uppercase tracking-[0.2em] ml-1">Tema / Categoria</label>
                      <input required value={courseForm.tema} onChange={e => setCourseForm({...courseForm, tema: e.target.value})} placeholder="Ex: Teologia Sistemática" className="w-full px-6 py-4 bg-slate-800 border border-slate-700 rounded-2xl text-white outline-none" />
                    </div>
                  </div>

                  <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
                    <div className="space-y-2">
                      <label className="text-[10px] font-black text-slate-500 uppercase tracking-[0.2em] ml-1">Carga Horária</label>
                      <input required value={courseForm.cargaHoraria} onChange={e => setCourseForm({...courseForm, cargaHoraria: e.target.value})} placeholder="Ex: 40h" className="w-full px-6 py-4 bg-slate-800 border border-slate-700 rounded-2xl text-white outline-none" />
                    </div>
                    <div className="space-y-2">
                      <label className="text-[10px] font-black text-slate-500 uppercase tracking-[0.2em] ml-1">Nível de Dificuldade</label>
                      <select required value={courseForm.dificuldade} onChange={e => setCourseForm({...courseForm, dificuldade: e.target.value as any})} className="w-full px-6 py-4 bg-slate-800 border border-slate-700 rounded-2xl text-white outline-none appearance-none">
                        <option value="Iniciante">Iniciante</option>
                        <option value="Intermediário">Intermediário</option>
                        <option value="Avançado">Avançado</option>
                      </select>
                    </div>
                    <div className="space-y-2">
                      <label className="text-[10px] font-black text-slate-500 uppercase tracking-[0.2em] ml-1">Público Alvo</label>
                      <select required value={courseForm.publicoAlvo} onChange={e => setCourseForm({...courseForm, publicoAlvo: e.target.value as any})} className="w-full px-6 py-4 bg-slate-800 border border-slate-700 rounded-2xl text-white outline-none appearance-none">
                        <option value="Geral">Geral</option>
                        <option value="Líderes">Líderes de Ministério</option>
                        <option value="Obreiros">Obreiros & Pastores</option>
                      </select>
                    </div>
                  </div>

                  <div className="space-y-2">
                    <label className="text-[10px] font-black text-slate-500 uppercase tracking-[0.2em] ml-1">Ementa Detalhada (Descrição)</label>
                    <textarea value={courseForm.descricaoLonga} onChange={e => setCourseForm({...courseForm, descricaoLonga: e.target.value})} rows={6} placeholder="Descreva os objetivos, metodologia e o que o aluno aprenderá..." className="w-full px-6 py-4 bg-slate-800 border border-slate-700 rounded-3xl text-white outline-none focus:ring-2 focus:ring-indigo-500 resize-none" />
                  </div>

                  <div className="flex items-center gap-3 p-4 bg-slate-800/50 rounded-2xl border border-slate-700/50">
                    <input type="checkbox" id="cert" checked={courseForm.geraCertificado} onChange={e => setCourseForm({...courseForm, geraCertificado: e.target.checked})} className="w-5 h-5 rounded border-slate-700 bg-slate-900 text-indigo-600 focus:ring-indigo-500" />
                    <label htmlFor="cert" className="text-sm font-bold text-slate-300 cursor-pointer select-none">Este curso emite certificado automático após conclusão de todos os módulos.</label>
                  </div>
                </div>
              )}

              {/* ABA PROFESSOR */}
              {courseModalTab === 'professor' && (
                <div className="space-y-8 animate-in slide-in-from-right-4 duration-300">
                  <div className="grid grid-cols-1 md:grid-cols-12 gap-8">
                    <div className="md:col-span-8 space-y-8">
                      <div className="space-y-2">
                        <label className="text-[10px] font-black text-slate-500 uppercase tracking-[0.2em] ml-1">Nome do Professor Responsável</label>
                        <input required value={courseForm.professorResponsavel} onChange={e => setCourseForm({...courseForm, professorResponsavel: e.target.value})} placeholder="Nome Completo" className="w-full px-6 py-4 bg-slate-800 border border-slate-700 rounded-2xl text-white outline-none focus:ring-2 focus:ring-indigo-500" />
                      </div>
                      <div className="space-y-2">
                        <label className="text-[10px] font-black text-slate-500 uppercase tracking-[0.2em] ml-1">Biografia Acadêmica / Mini-Bio</label>
                        <textarea value={courseForm.professorBio} onChange={e => setCourseForm({...courseForm, professorBio: e.target.value})} rows={5} placeholder="Ex: Pós-graduado em Novo Testamento, 15 anos de docência..." className="w-full px-6 py-4 bg-slate-800 border border-slate-700 rounded-3xl text-white outline-none focus:ring-2 focus:ring-indigo-500 resize-none" />
                      </div>
                    </div>

                    <div className="md:col-span-4 space-y-4">
                      <label className="text-[10px] font-black text-slate-500 uppercase tracking-[0.2em] ml-1">Foto do Professor (Link ou Picker)</label>
                      <div className="relative group/prof h-64 w-full bg-slate-800 border-2 border-dashed border-slate-700 rounded-[2.5rem] flex flex-col items-center justify-center overflow-hidden hover:border-indigo-500 transition-all">
                         {courseForm.professorFoto ? (
                           <>
                             <img src={courseForm.professorFoto} className="w-full h-full object-cover" />
                             <div className="absolute inset-0 bg-black/60 opacity-0 group-hover/prof:opacity-100 flex flex-col items-center justify-center gap-3 transition-opacity">
                               <button type="button" onClick={() => handleOpenMaterialPicker('image', (url) => setCourseForm({...courseForm, professorFoto: url}))} className="px-4 py-2 bg-indigo-600 text-white rounded-xl text-[10px] font-black uppercase">Trocar Foto</button>
                               <button type="button" onClick={() => setCourseForm({...courseForm, professorFoto: ''})} className="text-red-400 text-[10px] font-bold uppercase underline">Remover</button>
                             </div>
                           </>
                         ) : (
                           <div className="flex flex-col items-center text-center p-6 space-y-4">
                             <div className="p-4 bg-slate-900 rounded-full text-slate-600"><UserIcon size={32} /></div>
                             <button type="button" onClick={() => handleOpenMaterialPicker('image', (url) => setCourseForm({...courseForm, professorFoto: url}))} className="px-6 py-3 bg-slate-900 text-slate-300 rounded-2xl text-[10px] font-black uppercase hover:bg-indigo-600 hover:text-white transition-all">Selecionar Foto</button>
                           </div>
                         )}
                      </div>
                      <input value={courseForm.professorFoto} onChange={e => setCourseForm({...courseForm, professorFoto: e.target.value})} placeholder="Link externo da foto (opcional)" className="w-full px-4 py-2.5 bg-slate-800/50 border border-slate-700 rounded-xl text-[10px] text-white outline-none" />
                    </div>
                  </div>
                </div>
              )}

              {/* ABA MÍDIA */}
              {courseModalTab === 'midia' && (
                <div className="space-y-8 animate-in zoom-in-95 duration-300">
                  <div className="grid grid-cols-1 md:grid-cols-12 gap-10">
                    <div className="md:col-span-7 space-y-6">
                       <div className="bg-slate-800/30 p-8 rounded-[2.5rem] border border-slate-800/50 space-y-4">
                         <div className="flex items-center gap-3 text-indigo-400">
                           <ImageIcon size={20} />
                           <h4 className="font-bold text-sm">Diretrizes Visuais</h4>
                         </div>
                         <p className="text-slate-400 text-xs leading-relaxed italic">"A capa é a primeira conexão do aluno com o conhecimento. Utilize imagens de alta resolução que transmitam seriedade e espiritualidade. Formatos aceitos: JPG, PNG, WEBP."</p>
                       </div>

                       <div className="space-y-2">
                        <label className="text-[10px] font-black text-slate-500 uppercase tracking-[0.2em] ml-1">URL da Imagem de Capa (Link Direto)</label>
                        <input value={courseForm.capaUrl} onChange={e => setCourseForm({...courseForm, capaUrl: e.target.value})} placeholder="https://exemplo.com/imagem.jpg" className="w-full px-6 py-4 bg-slate-800 border border-slate-700 rounded-2xl text-white outline-none focus:ring-2 focus:ring-indigo-500 transition-all" />
                        <p className="text-[9px] text-slate-600 font-bold ml-1 uppercase">Você pode colar o link do seu Google Drive ou Dropbox aqui.</p>
                       </div>
                    </div>

                    <div className="md:col-span-5 space-y-4">
                      <label className="text-[10px] font-black text-slate-500 uppercase tracking-[0.2em] ml-1">Prévia da Capa</label>
                      <div className="relative group/capa h-64 w-full bg-slate-800 border-2 border-dashed border-slate-700 rounded-[2.5rem] flex flex-col items-center justify-center overflow-hidden hover:border-indigo-500 transition-all">
                        {courseForm.capaUrl ? (
                          <>
                            <img src={courseForm.capaUrl} className="w-full h-full object-cover group-hover/capa:scale-110 transition-transform duration-700" />
                            <div className="absolute inset-0 bg-black/60 opacity-0 group-hover/capa:opacity-100 flex items-center justify-center gap-4 transition-opacity">
                              <button type="button" onClick={() => handleOpenMaterialPicker('image', (url) => setCourseForm({...courseForm, capaUrl: url}))} className="p-3 bg-white text-indigo-600 rounded-xl shadow-xl hover:scale-110 transition-transform"><Library size={24} /></button>
                              <button type="button" onClick={() => setCourseForm({...courseForm, capaUrl: ''})} className="p-3 bg-white text-red-600 rounded-xl shadow-xl hover:scale-110 transition-transform"><X size={24} /></button>
                            </div>
                          </>
                        ) : (
                          <div className="flex flex-col items-center text-center p-8 space-y-5">
                            <div className="p-4 bg-slate-900 rounded-3xl text-slate-600"><FileUp size={40} /></div>
                            <div className="flex flex-col gap-2">
                              <button type="button" onClick={() => handleOpenMaterialPicker('image', (url) => setCourseForm({...courseForm, capaUrl: url}))} className="px-8 py-3 bg-indigo-600 text-white rounded-2xl text-[10px] font-black uppercase shadow-xl hover:bg-indigo-500 transition-all">Usar da Biblioteca</button>
                              <label className="px-8 py-3 bg-slate-900 text-slate-300 rounded-2xl text-[10px] font-black uppercase cursor-pointer hover:bg-slate-700 transition-all">Fazer Upload<input type="file" className="hidden" onChange={handleFileUpload} accept="image/*" /></label>
                            </div>
                          </div>
                        )}
                      </div>
                    </div>
                  </div>
                </div>
              )}

              {/* Footer de Ações */}
              <div className="pt-10 flex gap-4 border-t border-slate-800">
                <button type="button" onClick={handleCloseCourseModal} className="flex-1 py-5 border border-slate-700 text-slate-400 rounded-[1.5rem] font-bold uppercase text-xs tracking-widest hover:bg-slate-800 transition-all">Descartar</button>
                <button type="submit" disabled={loading} className="flex-[2] py-5 bg-indigo-600 text-white rounded-[1.5rem] font-black uppercase text-xs tracking-[0.2em] shadow-2xl shadow-indigo-600/20 active:scale-95 transition-all">
                  {loading ? 'Salvando no Firestore...' : isEditingCourse ? 'Atualizar Grade Curricular' : 'Finalizar Cadastro de Curso'}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default ProfessorView;
